EXIT_OK, EXIT_NOT_FOUND, EXIT_INFRA = 0, 1, 2
#: Сколько строк таблицы релизов показываем: ниже начинаются раздачи без сидов.
TABLE_LIMIT = 12
#: Сколько ПРИГОВОРОВ терпим заведомо, прежде чем начать считать деньги: подмены не
#: молчат. Приговор - это когда ffprobe раздачу прочитал и она не годится (av1, vc1,
#: тяжёлая). Осечка роя приговором не считается и попытку не жжёт (:meth:`_Bench.resolve`).
#:
#: 🔴 TC-188. Это ПОЛ, а не потолок: меньше трёх приговоров отбор не сдаётся никогда, а
#: сверху его держит уже не счётчик, а :data:`VERDICT_BUDGET` - секунды.
MAX_TRIES = 3
#: **Во что приговоры вправе обойтись ЧЕЛОВЕКУ, секунды** (:meth:`_Bench.resolve`).
#:
#: 🔴 TC-188. Счётчик приговоров мерил не то, чем платят. В замере каталога из 92 живых
#: 1080p, прошедших мимо показа, 44 просто СТОЯЛИ В ОЧЕРЕДИ: до них не дошли, потому что
#: три места :data:`MAX_TRIES` сгорали выше по списку - на именах, которые ffprobe читает
#: за секунду и тут же отбраковывает (SD-рип на 1.5 ГБ, vp9, av1). Такой приговор
#: человеку не стоит почти ничего, а место в очереди съедает ровно так же, как приговор
#: тяжёлому ремуксу, который поднимался полминуты.
#:
#: Поэтому потолок переведён в то, чем платят: в секунды ОЖИДАНИЯ. Считается не работа
#: фонового потока (он греет запасного параллельно, и часть его времени человеку ничего
#: не стоила), а ровно то, сколько отбор простоял на этой раздаче, прежде чем её осудить.
#: Раздача, прогретая ещё под меню (:data:`PREWARM_SPARE`), отвечает мгновенно - её
#: приговор и стоит почти нуля, и отнимать место у следующей ему не за что.
#:
#: Пятнадцать - это цена прежних трёх приговоров по верхней замеренной их цене (2-5 с на
#: приговор), то есть послаблением число не является: строже прежнего отбор не станет
#: (ниже :data:`MAX_TRIES` он не опускается), а мягче - только там, где приговоры
#: оказались дешёвыми. Потолок всей фазы (:data:`PICK_BUDGET`) стоит где стоял.
VERDICT_BUDGET = 15.0
#: ``--voice`` без номера: показать меню озвучек. Ноль тут свободен - дорожки для
#: человека нумеруются с единицы.
VOICE_MENU = 0
#: ``--tv`` без адреса: найти приёмники в сети и показать список. Адресом такое значение
#: не бывает никогда, поэтому путь «адрес назвали руками» остаётся ровно прежним.
TV_MENU = "?"
#: Сколько картин франшизы греем под меню: топ-2-3 релиза уходят в TorrServer фоном,
#: пока человек отвечает на вопросы.
PREWARM = 3
#: Сколько ЗАПАСНЫХ релизов греется под меню сверх картин - у той картины, в которую
#: попадёт Enter (:func:`warm_order`). Прогрев под меню тратится на РАЗНЫЕ картины: человек
#: может ответить не дефолтом, и меню обязано вести в живое. Но внутри выбранной картины
#: до сих пор грелся ровно один релиз, а запасной поднимался только тогда, когда верх уже
#: забракован (:meth:`_Bench.resolve`) - то есть на бракованном верхе человек платил полную
#: цену подъёма второй раздачи: 6-7 с чистого ожидания DHT и ffprobe в фазе отбора.
#: Единица тут не «побольше параллели», а перенос по времени: этот же запасной всё равно
#: поднимался секундой позже, в resolve, - меняется только то, когда он начинает греться.
#: Пик одновременных раздач от этого не растёт (в отборе он и был PREWARM + 1), а вот пауза
#: под меню, которая иначе простаивает, уходит в дело.
PREWARM_SPARE = 1
#: Сколько раздач с ОБЕЩАННОЙ русской дорожкой греется под меню сверх запасного - одна,
#: ближайшая по очереди (:meth:`_Bench.spare`). 🔴 TC-309. Стоит такая раздача в очереди
#: где угодно - на 4-9 месте, - и подъём её с нуля это метаданные роя (3-6 с) плюс чтение
#: дорожек, то есть ровно те секунды, которых в отборе и не хватает.
#:
#: 🔴 TC-492. Спрашивают её теперь не отдельной проверкой, а самой очередью: гейт бракует
#: и прямое «нет», и молчание паспорта (:func:`voice_unproven`), поэтому отбор идёт дальше
#: и до обещавшей русскую раздачи доходит сам. Тёплой она нужна тем более: греется она
#: ровно тогда, когда очередь и правда может уйти дальше верха - молчаливое имя есть у
#: кого-то из первых :data:`MAX_TRIES` кандидатов, а обещавший русскую сосед в очереди
#: вообще есть.
PREWARM_DUB = 1
#: **Жёсткий потолок одновременных раздач, которые держим МЫ** (:meth:`_Bench._room`).
#:
#: Число не про вежливость к службе, а про её живучесть. Замер на стенде: TorrServer
#: падает по таймеру раз в 15 минут (паника в форке библиотеки), и срывается тем
#: вероятнее, чем больше раздач и чем активнее у них просят куски: с ОДНОЙ раздачей тик
#: проходит спокойно, со 120 раздачами и живым чтением - паника на первом же тике.
#: Прогрев по своей природе греет лишнее (:data:`PREWARM` картин плюс
#: :data:`PREWARM_SPARE`, а где верх промолчал про звук - ещё и :data:`PREWARM_DUB`), и
#: без потолка это лишнее копилось: очередь перебора поднимала
#: по раздаче за попытку, честная проверка (:meth:`_Bench._honest`) - ещё до
#: :data:`MAX_TRIES` сверху, а убиралось всё разом только перед стартом показа.
#:
#: Пять - это ровно пик прогрева под меню (:data:`PREWARM` + :data:`PREWARM_SPARE` +
#: :data:`PREWARM_DUB`), то есть замеренного выигрыша потолок не трогает: и топ-3
#: картины, и запасной релиз, и обещавший русскую сосед греются как грелись. Он режет то,
#: что живёт ПОСЛЕ того, как перестало быть нужным.
MAX_LIVE = PREWARM + PREWARM_SPARE + PREWARM_DUB
#: Бюджет одной раздачи на метаданные по DHT, секунды. Не уложилась - не «зависли
#: насмерть», а честная строка и следующий релиз.
META_BUDGET = 20.0
#: Бюджет на чтение дорожек (ffprobe) той же раздачи, секунды.
PROBE_BUDGET = 40.0
#: Сколько ffprobe ждёт первых байт потока, прежде чем счесть рой мёртвым, секунды.
#: Раздача с мёртвым роем метаданные отдаёт (они уже в TorrServer), а содержимого не
#: отдаёт вовсе - и раньше на ней сгорал весь :data:`PROBE_BUDGET` (сорок секунд на одном
#: молчащем релизе, когда рядом в очереди стояли живые). Отсрочка отделяет такой рой от
#: честно долгого заголовка («Моана 2» едет 17 с): ни байта за неё - пиров нет, обрываем
#: и берём запасного, он уже греется параллельно (:func:`torrcast.stream.swarm_pulse`).
SWARM_GRACE = 12.0
#: Сколько ждём ПЕРВОГО КОНТАКТА роя, прежде чем счесть раздачу пустой, секунды.
#:
#: Тот же приём, что :data:`SWARM_GRACE`, но фазой раньше - на метаданных
#: (:func:`torrcast.stream.swarm_alive`). До сих пор эта фаза стоила одинаково и медленному
#: рою, и пустому: полные :data:`META_BUDGET` на релиз. В замере каталога на 225 запросах
#: таких запросов 6 - там, где в каталоге правда 0-4 сида, - и человек получал честный
#: отказ, но по двадцать секунд молчания на каждый мёртвый релиз.
#:
#: 🔴 Отсрочка не про сиды из выдачи: те врут в обе стороны, и отказывать по их обещанию
#: нельзя. Спрашивается ФАКТ - насчитала ли служба хоть один контакт. Раздача, у которой
#: контакты есть, ждёт весь :data:`META_BUDGET` ровно как ждала: медленный рой - это рой,
#: а не пустота. Раздача, метаданные которой приехали за доли секунды, до проверки не
#: доходит вовсе.
#:
#: 🔴 Шесть секунд - это середина разброса, а не его край, и цена такого приговора
#: замерена: 140 раздач сохранённого каталога, поднятых по шесть раз каждая (840
#: подъёмов), отдают первый контакт за 4.3 с в половине случаев, за 6.0 с в трёх
#: четвертях и за 7.6 с в девяти десятых. Отсюда два следствия, и оба надо держать в
#: голове, читая приговор «рой пуст»: он неустойчив (29% соседних прогонов одной и той же
#: раздачи расходятся) и в 73% случаев ложен - метаданные приезжают в обычный
#: :data:`META_BUDGET`. Ошибка в эту сторону стоит одного места в очереди: следующий релиз
#: всё равно спрашивается, а осечка роя попытку не жжёт (:data:`MAX_TRIES`).
#:
#: 🔴 TC-300. Ровно поэтому отсрочка снимается там, где очереди больше нет: когда
#: промолчали все до одной, её ошибка стоит уже не места, а показа, и последний спрос
#: идёт по полному бюджету раздачи (:meth:`_Bench._recheck`).
#:
#: 🔴 TC-387. И по той же причине она длиннее там, где очередь ниже ступенью
#: (:data:`STEP_GRACE`).
PEER_GRACE = 6.0
#: Сколько ждём первого контакта у раздачи, чья осечка стоит СТУПЕНИ ЧЁТКОСТИ, секунды.
#:
#: 🔴 TC-387. Отсрочка назначается ценой ошибки (:func:`peer_grace`), и у релиза, под
#: которым в очереди стоит ступень ниже, эта цена - обещанные 1080p: человек видит 720p
#: там, где в выдаче был живой 1080p, и узнаёт об этом только глазами.
#:
#: Десять секунд - это край того же разброса, что описан у :data:`PEER_GRACE`, и цена
#: перехода замерена на той же ленте подъёмов: соседние прогоны одной раздачи расходятся
#: в 5% случаев вместо 29%, а ложным оказывается каждый пятый приговор вместо трёх из
#: четырёх (18 из 86 против 191 из 262). На запросах, где ступень решает ровно этот
#: приговор, качество скачет между прогонами у 11% картин вместо 74%.
#:
#: Платят за это раздачи, у которых роя правда нет: их в замере 5 из 140, и каждая стоит
#: четырёх лишних секунд. Идут они не в пустоту: запасной релиз эти секунды греется рядом
#: (:data:`PREWARM_SPARE`), поэтому спуск ступенью ниже после них стоит уже не подъёма
#: раздачи, а разницы между двумя ffprobe - в замере это 0.9 с медианой и 3.6 с в худшем
#: случае. Дальше десятой секунды разброс кончается: двенадцатая вернула бы ещё 12 ложных
#: приговоров из 262, двадцатая - ещё 5 поверх них, и обе секунды уже дороже цели старта.
STEP_GRACE = 10.0
#: **Бюджет всей фазы отбора, секунды**: столько CLI перебирает очередь, прежде чем
#: сдаться. Число не новое и не «с запасом»: это ровно прежний потолок фазы - три
#: попытки, каждая по полному бюджету раздачи (:data:`META_BUDGET` + :data:`PROBE_BUDGET`).
#: Потолок остался тем же, изменилось только, на что он тратится: раньше в него
#: укладывались строго три раздачи, теперь - сколько успеет, пока осечки идут молчанием
#: роя. Осечки эти дешёвые: запасной греется параллельно с текущим, поэтому мёртвая
#: раздача стоит не двадцати секунд, а разницы между двумя ожиданиями DHT.
PICK_BUDGET = MAX_TRIES * (META_BUDGET + PROBE_BUDGET)
#: Сколько ждём ответа от честного запасного, если верх оказался хуже, чем обещал. Запасной
#: к этой секунде уже греется (:meth:`_Bench.resolve` поднимает следующего сразу), так что
#: платим не за прогрев, а за разницу между двумя ffprobe. Не уложился - играем то, что
#: есть, и говорим об этом вслух: лишние секунды старта хуже, чем 574p.
HONEST_BUDGET = 12.0
#: Ниже этой высоты кадра HD уже не назовёшь. Имя раздачи о разрешении молчит чаще, чем
#: врёт (у «Моаны 2» - в 5 именах из 11), поэтому «имя молчало, а внутри SD» - такой же
#: повод посмотреть на соседа, как и прямое враньё в имени.
HD_HEIGHT = 720
#: Ступень, ради которой затеян отбор: честный 1080p. Имя, называющее её (или выше),
#: поднимается над названным 720p - но только если раздача жива (:func:`is_full_hd`).
FULL_HEIGHT = 1080
#: Насколько живым обязан быть названный 1080p, чтобы обойти 720p: доля от сидов
#: сильнейшего соседа, с которым он спорит за верх (:func:`rank_releases` считает
#: максимум среди равных по ступеням выше). Не абсолютное число, потому что живость
#: у картин разная: у новинки сосед набирает сотни сидов, у кино 1994 года - четыре
#: десятка, и «20 сидов» означало бы в этих двух пулах совершенно разное. Замер по
#: живой выдаче: у «Мастера и Маргариты» 1080p держит 0.40 от соперника (59 против 146)
#: и обязан выиграть, у «Зелёной мили» - 0.10 (4 против 38), у «Форреста Гампа» - 0.05
#: (2 против 41), и эти обязаны проиграть: 15 ГБ на двух сидах - это не 1080p, а подгрузы.
FULL_HD_LIVENESS = 0.25
#: Насколько живым обязан быть именной кандидат, чтобы ворота отбора остались закрытыми:
#: доля от сидов самой обсиженной раздачи картины. Доля, а не абсолютное число, ровно по
#: той же причине, что и у :data:`FULL_HD_LIVENESS`.
#:
#: Замер по живой выдаче «наруто»: у картины «Наруто» (2002) именных кандидатов два - на
#: 3 и на 1 сид, - а полный сериал «[E220 of 220]» с 91 сидом в кандидаты не проходил
#: вовсе. 3/91 = 0.03: живым такой кандидат не назовёшь, и выбор между ним и ничем - это
#: выбор между подгрузами и подгрузами. У фильмов с богатой выдачей доля лидера-кандидата
#: заметно выше порога, и ворота там не открываются никогда.
GATE_LIVENESS = 0.25
#: Насколько живым обязан быть релиз с обещанной русской дорожкой, чтобы обойти по звуку
#: более обсиженного соседа (:func:`sound_step`). Порог ниже, чем у HD (0.10 против 0.25),
#: и это не небрежность: «1080p вместо 720p» - оттенок, а «по-русски вместо по-японски» -
#: разница между «посмотрел» и «не посмотрел», и платить за неё сидами можно дороже.
#: Замер по живой выдаче: у «Врат Штейна» русский BDRip 1080p держит 86 сидов против 397
#: у самого живого «[Anime Time]» - 0.22, и обязан выиграть; у «Наруто: Ураганные
#: хроники» русская раздача имеет НОЛЬ сидов против трёх - 0.0, и обязана проиграть,
#: потому что мёртвый рой это не показ ни на каком языке.
SOUND_LIVENESS = 0.10
#: **Сколько сидов делают картину играбельной** - порог живости части франшизы
#: (:func:`alive_numbers`). Здесь, в отличие от трёх порогов выше, доля от лидера не
#: годится, и это не оттенок, а разные вопросы. Те три - про РАЗМЕН внутри одной картины
#: («1080p вместо 720p», «по-русски вместо по-японски»), и цена размена честно меряется
#: в сидах соседа по тому же пулу. А этот - про то, есть ли у картины чем играть вообще,
#: и ответ на него сосед не даёт: рой чужой части не качает и не тормозит эту.
#:
#: Доля тут стояла и обходилась дороже всего: свежая часть с сотнями сидов объявляла
#: мёртвой всю классику франшизы, и дефолт садился на картину, которую человек не звал
#: («мумия» - 2026 год вместо 1999, десять прогонов из десяти; то же у «хищника»,
#: «голодных игр», «дюны», «безумного макса», «джуманджи»).
#:
#: Пять - это нижняя граница между двумя замеренными случаями, а не число из воздуха:
#: у «Тачек 2» годным верхом остался HDRip «фильм о фильме» на 1 сид, и играть им
#: нельзя; у «Мальтийского сокола» 1931 года 16 сид - и он играет. Точнее порог поставит
#: только замер по доехавшим показам; пока он стоит там, где ошибка дешевле всего -
#: лишняя живая часть в дефолте видна человеку в меню, а лишняя мёртвая стоит вечера.
ALIVE_SEEDERS = 5
#: Насколько подтверждённая высота вправе отставать от заявленной. 0.9 - это про обрезку
#: чёрных полей: у 1080p-широкоформатника реальная высота 800-816, и релиз честен. А
#: 574 против 1080 - это уже другая ступень лестницы, а не кадрирование.
HONEST_RATIO = 0.9
#: Потолок ожидания метаданных раздачи **в юните**, секунды. Здесь это не «бюджет фазы
#: под меню» (:data:`META_BUDGET`), а последний рубеж: магнит юниту уже дали, и если
#: метаданные не приехали, показывать нечего.
WORKER_META = 60.0
#: Потолок ffprobe длительности в юните: своей длительности следующая серия не знает, и
#: читается она из потока (:func:`_duration`).
WORKER_DUR = 90.0
#: Прочее на пути юнита до картинки, у чего своего потолка нет: запуск transient-юнита,
#: чтение состояния, подъём раздачи. Секунды, но считать их нулём - врать себе.
START_SLACK = 10.0
#: **Бюджет старта показа: столько CLI ждёт картинку на экране** (:func:`_await_playing`).
#:
#: Число не выбирается на глаз и не «берётся с запасом»: это сумма потолков всех фаз,
#: которые юнит проходит от запуска до первого ``PLAYING``, - метаданные раздачи, ffprobe
#: длительности, ожидание чужой карты опорных кадров, пробный прогон упаковки и терпение
#: приёмника к молчаливому ``IDLE``. Пока CLI ждал меньше суммы (120 с против 60 + 90 +
#: 60), он гасил `stop_play_unit`'ом показ, который вот-вот начался бы.
#:
#: Ждать так долго не страшно и не молчаливо: :class:`~torrcast.console.Progress` всё это
#: время показывает живую фазу, а любая честная неудача убивает юнит раньше - CLI видит
#: это по :func:`unit_active` и печатает причину из журнала, не досиживая до конца.
START_BUDGET = (
    WORKER_META
    + WORKER_DUR
    + KEYS_WAIT
    + PILOT_TIMEOUT
    + START_SLACK
    + ChromecastReceiver.START_TIMEOUT
)
#: Как часто сторож кладёт позицию в state, секунды.
WATCH_SECONDS = 10.0
#: Доля фильма, с которой прогрев считается полным в статусе. Не единица: хвост сетки
#: короче шага, и последний кусок доезжает позже всех - а «интернет не нужен» верно уже
#: тогда, когда впереди лежит всё, что зритель успеет посмотреть.
WARMED_RATIO = 0.99
#: Как часто показ пишет в журнал, что видит приёмник: позиция и общее время -
#: единственное доказательство того, что на экране есть таймлайн.
SAY_SECONDS = 30.0
#: ``TORRCAST_TRACE=1`` - писать в журнал запас показа на каждом опросе (раз в 2 с):
#: позиция приёмника, край упаковки, разница между ними и вес tmpfs. Инструмент про
#: устойчивость: её провал видно только в динамике запаса, а раз в 30 с он теряется.
TRACE_ENV = "TORRCAST_TRACE"
#: ``TORRCAST_CTL=<файл>`` - диагностический пульт показа: строка в файле («``seek 1200``»,
#: «``pause``», «``play``») исполняется владеющим сендером на ближайшем опросе, файл
#: съедается. Нужен ровно затем, что кнопку на пульте может нажать только человек, а
#: вторым pychromecast команду не подать вовсе: приёмник считает второе соединение тем же
#: сендером и отвечает пустым MEDIA_STATUS (докстринг :class:`ChromecastReceiver`).
#: Приёмнику это приходит той же MEDIA-командой, что и с пульта, поэтому проверка честная.
#: На счастливом пути не участвует: переменной нет - кода нет.
CTL_ENV = "TORRCAST_CTL"
#: Сколько терпим паузу на пульте, прежде чем погасить упаковку: дальше
#: сегменты копились бы в tmpfs впустую - приёмник их не забирает.
PAUSE_SECONDS = 60.0
#: Пауза длиннее этого - показ считается оконченным: юнит гаснет и не держит раздачу.
PAUSE_LIMIT = 3600.0
#: Сколько раз юнит поднимает погасший показ на ОДИН обрыв (:class:`_Revival`).
#: Три - это не «побольше»: столько же попыток даётся упаковке (:attr:`Feed.limit`), и
#: столько же раз человек нажал бы `cast` руками, прежде чем решить, что чинить надо не
#: показ. Удачей счётчик не обнуляется - иначе показ, гаснущий сразу после подъёма, гонял
#: бы приёмник по кругу вечно; его обнуляет пережитый обрыв (:data:`REVIVE_LIVED`).
REVIVE_TRIES = 3
#: Выдержка между попытками воскрешения.
#:
#: ⚠️ Прежнее обоснование («приёмник, поймавший 404, не берёт LOAD ещё две-три минуты»)
#: замером 09-08-2026 опровергнуто: наказания за 404 нет, ноль секунд
#: (:attr:`torrcast.profile.Profile.sulk`). Число осталось прежним по другой причине:
#: приложение Samsung Q70D занимает экран 301 с после смерти медиасессии
#: (:attr:`torrcast.profile.Profile.app_patience`), и минута между попытками - это про то,
#: чтобы не жечь их быстрее, чем приёмник успевает освободить экран.
#:
#: ⚠️ До ПЕРВОЙ попытки в темноте, которую устроил сам приёмник, эта минута больше не
#: выжидается: там своя выдержка и свой замер (:data:`REVIVE_DROP`).
REVIVE_PAUSE = 60.0
#: Сколько ждём ПРИЁМНИК, прежде чем первый раз поднять брошенный им же показ, секунды.
#:
#: 🔴 Замер: приёмник, только что погасивший показ, готов взять LOAD через 3-4 с - PLAYING
#: приходит на 3.2-3.6 с, то есть БЫСТРЕЕ обычного тёплого LOAD (5.6 с), и так трижды.
#: Минута (:data:`REVIVE_PAUSE`) в этой темноте была минутой чёрного экрана впустую: ждать
#: было уже нечего, приёмник давно готов.
#:
#: Осторожность из этого не пропала, она сдвинулась на попытки со второй: если самая
#: быстрая попытка показ не вернула, значит замер к этой аварии не подходит, и дальше
#: выдержка снова минутная. Все три попытки при этом укладываются в окно, пока экран ещё
#: занят нашим же приложением (:attr:`torrcast.profile.Profile.app_patience`, 301 с): на
#: сухом прогоне LOAD уходят на 8-й, 68-й и 128-й секундах темноты, а было 60/120/180.
#:
#: ⚠️ Восемь, а не четыре, - и это не промах: прежде чем поверить, что виноват приёмник,
#: показ шесть секунд расспрашивает источник (:data:`SOURCE_TRIES`, :func:`_blamed`), и
#: только потом начинает считать эту выдержку. Меньше 3-4 с тут ставить нечего - раньше
#: приёмник LOAD всё равно не берёт.
REVIVE_DROP = 4.0
#: Сколько показ должен идти ЖИВЫМ, чтобы запас попыток снова считался полным
#: (:meth:`_Revival.alive`). Замерено на живом Q70D: за 13 минут показа два коротких обрыва
#: съели все три попытки на весь сеанс - хотя каждый из них показ пережил, и третий обрыв
#: гасить было уже нечем. Запас попыток отмеряется обрыву, а не сеансу.
#: Меньше :data:`REVIVE_PAUSE` брать нельзя: тогда мигающий показ (поднялся и тут же погас)
#: возвращал бы себе попытки быстрее, чем тратит, и LOAD в приёмник шёл бы вечно. С этим
#: порогом поток LOAD ограничен сверху даже в самом злом случае: :data:`REVIVE_TRIES` штук
#: на каждую полную минуту НАСТОЯЩЕЙ картинки на экране.
REVIVE_LIVED = REVIVE_PAUSE
#: Сколько всего ждём в темноте, прежде чем погаснуть честно. Вчетверо дольше терпения
#: самого приёмника (~4 минуты) и вчетверо короче терпения к паузе (:data:`PAUSE_LIMIT`):
#: обрыв длиннее четверти часа - это уже не «моргнул интернет», зритель за это время
#: встал и ушёл, а держать раздачу и tmpfs ради пустого экрана незачем. Позиция к этому
#: моменту давно в состоянии, и `cast` продолжит с неё.
REVIVE_LIMIT = 900.0
#: Сколько раз спрашиваем источник, прежде чем поверить, что он в порядке (:func:`_blamed`).
#: Четыре вопроса через :data:`SOURCE_PAUSE` перекрывают замеренное окно перезапуска службы
#: (3.0-3.1 с) и её же панику (5 с) - а внутри этого окна она отвечает как живая.
SOURCE_TRIES = 4
#: Выдержка между вопросами источнику. Показ к этому моменту уже кончился, поэтому цена
#: тут одна - задержка последней строки, и платится она только за правду в ней.
SOURCE_PAUSE = 2.0
#: Битрейт, ниже которого раздача без единого маркера качества в имени - это SD-рип
#: (MPEG-4 в .avi), а не скромный 1080p. Порог выбран по замеру, а не на глаз: из 264
#: раздач живой выдачи («моана», «тачки», «матрица», «интерстеллар», «аватар») удалось
#: достать .torrent и заглянуть внутрь у 36. Все восемь .avi в этой выборке не называют
#: ни разрешения, ни кодека, и у пяти полнометражных потолок вышел 3.5 Мбит/с; ближайший
#: снизу подтверждённый .mkv с такой же безымянной шапкой - 5.4 Мбит/с. Порог поставлен
#: посередине этого зазора.
SD_BITRATE = 4.0
#: Битрейт, ниже которого раздача с пометкой приложения (:attr:`~torrcast.parse.Release.extras`)
#: самой картиной быть уже не может: при длительности, которую назвала справка, столько
#: весит ролик, а не фильм. Порог взят по сохранённым выдачам, а не на глаз: у «Тачек 2»
#: (1 ч 46 мин) «фильм о фильме» весит 0.4 ГБ - это 0.5 Мбит/с, у «Кунг-фу Панды» трейлер
#: 0.12 ГБ, у «Робокопа» интервью 0.05 ГБ; самый скромный ЦЕЛЬНЫЙ рип тех же картин в тех
#: же пулах - 0.7-1.5 ГБ, то есть 0.8-1.7 Мбит/с. Порог стоит выше этого зазора нарочно:
#: имя уже сказало «это приложение», и цена ошибки тут несимметрична - лишний отсев стоит
#: одной раздачи из очереди, а пропуск стоит подменённой картины на экране.
EXTRAS_MBIT = 2.0
#: Сколько серий в сезоне считаем МИНИМУМОМ, когда имя пака называет сезоны, но не серии
#: (:func:`pack_mbit`). Число выбрано снизу нарочно: делим размер на заведомо МЕНЬШЕЕ
#: число серий, значит получаем ПОТОЛОК битрейта серии, а не выдуманную оценку. Сезон
#: короче шести серий бывает (британские мини-сериалы), и такому паку потолок достанется
#: завышенный - то есть в сторону «не трогать», а не в сторону ложного понижения.
SEASON_EPISODES = 6
#: Признаки образа диска в имени раздачи - внутри VOB/BDMV, а не один файл.
_DISC_RE = re.compile(
    r"\b(?:video_?ts|bdmv|dvd[- ]?video|dvd[59]|iso|blu-?ray\s*(?:disc|cee)|avc\+?\s*iso)\b",
    re.IGNORECASE,
)


@dataclass(slots=True)
class Args:
    query: list[str]
    #: ``--tv <ip>`` - запомнить адрес; ``--tv`` без адреса (:data:`TV_MENU`) - найти
    #: приёмники в сети и спросить, какой из них телевизор.
    tv: str | None = None
    release: int | None = None
    #: ``--pick N`` - картина N из меню, вопрос «Что смотрим?» не задаётся. Номер называет
    #: человек по списку на экране: молчаливой подмены тут не бывает, а без терминала это
    #: единственный способ назвать картину неинтерактивному запуску.
    pick: int | None = None
    file: int | None = None
    #: ``--voice N`` - играть дорожку N; ``--voice`` без номера (:data:`VOICE_MENU`) -
    #: показать меню озвучек и спросить. На счастливом пути обоих нет: озвучка
    #: выбирается сама.
    voice: int | None = None
    new: bool = False
    dry: bool = False
    #: ``cast log --since 2d|12h|30m|ГГГГ-ММ-ДД`` - с какого момента показывать след.
    since: str | None = None
    #: Внутреннее: показ внутри transient-юнита, руками не зовётся.
    play_key: str | None = None

    @property
    def command(self) -> str:
        """``stop`` / ``status`` / ``doctor`` / ``releases`` / ``voices`` / ``play`` /
        ``configure`` / ``worker``.
        """
        if self.play_key:
            return "worker"
        words = {"stop", "status", "doctor", "releases", "voices", "log"}
        if self.query and self.query[0] in words:
            return self.query[0]
        if not self.query:
            return "configure" if self.tv else "status"
        return "play"

    @property
    def episode(self) -> Episode | None:
        """Явно указанная серия: ``cast киберпанк s2e5``, ``2x5``, «2 сезон 5 серия»."""
        return split_episode(" ".join(self.query))[1]

    @property
    def title_query(self) -> str:
        """Запрос без указания серии: искать надо «киберпанк», а не «киберпанк 2x5»."""
        return split_episode(" ".join(self.query))[0]

    @property
    def pinned(self) -> bool:
        """Релиз или файл названы руками — отладочный путь, подмен в нём не бывает."""
        return self.release is not None or self.file is not None


def parse_args(argv: Sequence[str] | None = None) -> Args:
    """Разобрать argv по контракту CLI."""
    about = "torrcast - найти релиз и кастить его на ТВ без скачивания"
    parser = argparse.ArgumentParser(prog="cast", description=about, allow_abbrev=False)
    parser.add_argument("query", nargs="*", help="название, либо stop / status")
    parser.add_argument(
        "--tv",
        nargs="?",
        const=TV_MENU,
        metavar="IP",
        help="настройка ТВ: без адреса - найти приёмники в сети и выбрать из списка",
    )
    # Номер релиза имеет смысл только вместе с запросом и выбранной картиной: другой
    # запрос - другой список, а у каждой картины в нём - свои номера (TC-446).
    parser.add_argument(
        "--release",
        type=int,
        metavar="N",
        help="отладка: релиз N выбранной картины; номера - из cast releases с тем же запросом",
    )
    parser.add_argument("--pick", type=int, metavar="N", help="картина N из меню, без вопроса")
    parser.add_argument("--file", type=int, metavar="N", help="отладка: взять файл N раздачи")
    parser.add_argument(
        "--voice",
        type=int,
        nargs="?",
        const=VOICE_MENU,
        metavar="N",
        help="озвучка: N - взять дорожку N и запомнить, без номера - меню",
    )
    # Прежнее имя того же флага: ломать чужие пальцы и историю оболочки незачем.
    parser.add_argument(
        "--audio", type=int, nargs="?", const=VOICE_MENU, dest="voice", help=argparse.SUPPRESS
    )
    parser.add_argument("--new", action="store_true", help="забыть прогресс и выбрать заново")
    parser.add_argument("--dry", action="store_true", help="весь резолв без каста")
    parser.add_argument(
        "--since", metavar="СРОК", help="cast log: с какого момента (2d / 12h / 30m / ГГГГ-ММ-ДД)"
    )
    parser.add_argument("--play-key", metavar="KEY", help=argparse.SUPPRESS)
    parser.add_argument("--version", action="version", version=f"torrcast {__version__}")
    return Args(**vars(parser.parse_args(argv)))


def main(argv: Sequence[str] | None = None) -> int:
    """Точка входа console-script ``cast``."""
    # Прогресс идёт вперемешку с ошибками в stderr: без построчного сброса врёт порядок.
    if isinstance(sys.stdout, io.TextIOWrapper):
        sys.stdout.reconfigure(line_buffering=True)
    try:
        args = parse_args(argv)
        command = args.command
        # IUTF8 на stdin включаем на всё время команды и возвращаем режим как было:
        # без него ssh-сессия ломает кириллицу в вопросах.
        with terminal():
            if command == "configure":
                return _cmd_configure(args)
            if command == "stop":
                return _cmd_stop()
            if command == "status":
                return _cmd_status()
            if command == "doctor":
                return _cmd_doctor()
            if command == "log":
                return _cmd_log(args)
            if command == "releases":
                return _cmd_releases(args)
            if command == "voices":
                return _cmd_voices(args)
            if command == "worker":
                return _cmd_worker(str(args.play_key))
            return _cmd_play(args)
    except NotFoundError as exc:
        trace.emit("error", "error", text=str(exc)[:200])
        print(str(exc), file=sys.stderr)
        return EXIT_NOT_FOUND
    except TorrcastError as exc:  # InfraError и всё прочее наше
        trace.emit("error", "error", text=str(exc)[:200])
        print(str(exc), file=sys.stderr)
        return EXIT_INFRA
    except _Stopped:  # `cast stop` - штатный конец показа, а не отказ
        return EXIT_OK
    except KeyboardInterrupt:
        return EXIT_INFRA
    except BrokenPipeError:  # `cast status | head` - не повод показывать трейсбек
        with contextlib.suppress(OSError):
            sys.stdout.close()
        return EXIT_OK
    finally:
        # Дожать хвост следа: фоновый писатель - демон, штатный выход обязан его дождаться.
        trace.shutdown()


def _cmd_configure(args: Args) -> int:
    """``cast --tv`` - единственная настройка: адрес телевизора.

    Без адреса приёмники ищутся сами (:func:`found_tv`), с адресом - берётся сказанное:
    кто свой IP помнит, тому лишний поиск ни к чему. Пишется в конфиг в обоих случаях
    одинаково, разница ровно в том, откуда взялась строка.

    Отдельное значение ``mock`` включает headless-приёмник: так torrcast проверяется без
    телевизора, и адрес ТВ в конфиге при этом отсутствует физически.
    """
    device = found_tv() if args.tv == TV_MENU else Device(address=str(args.tv))
    config = load_config()
    config.tv = device.address
    config.receiver = "mock" if device.address == "mock" else "chromecast"
    save_config(config)
    note = " (headless-приёмник, каста наружу нет)" if device.address == "mock" else ""
    name = f"{device.name} - " if device.name else ""
    print(f"ТВ: {name}{config.tv}{note}")
    return EXIT_OK


def found_tv() -> Device:
    """``cast --tv`` без адреса: найти приёмники в сети и спросить, который из них ТВ.

    Это последний шаг установки, и человек на нём знает про свой дом ровно одно - как
    телевизор называется. Поэтому список из имён и адресов, ответ номером, а единственный
    найденный подтверждается пустым Enter.

    Никого не нашли - не «ошибка сети», а понятная причина: телевизор выключен или стоит
    в другой сети. Нашли несколько, а терминала нет - отказываемся вслух, ровно как в
    меню картин: выбрать вслепую тут значит записать в конфиг чужое устройство.
    """
    with Progress() as progress:
        progress.phase("ищу приёмники в сети")
        found = scan.find()
    for note in found.notes:
        print(note)
    if not found.devices:
        raise NotFoundError(
            "приёмников в сети не нашёл - телевизор включён и в той же сети? "
            "адрес можно задать и руками: cast --tv <ip>"
        )
    print(tv_lines(found.devices))
    if len(found.devices) > 1 and not console.stdin_is_tty():
        raise NotFoundError(
            f"нашёл приёмников: {len(found.devices)}, а терминала нет - вслепую не выбираю; "
            "назови адрес сам: cast --tv <ip>"
        )
    return found.devices[ask("Какой телевизор?", len(found.devices)) - 1]


def tv_lines(devices: list[Device]) -> str:
    """Список найденных приёмников: номер, имя, адрес - по строке на устройство.

    Формат тот же, что у меню картин: глаз уже знает, что отвечать надо номером слева.
    Адрес печатается всегда, даже когда имя есть: имён вида «Гостиная» в доме бывает
    два, а адрес различает их наверняка.
    """
    return "\n".join(
        f"  {number}. {device.title} - {device.address}"
        for number, device in enumerate(devices, start=1)
    )


#: Хэш раздачи внутри магнита: ровно сорок шестнадцатеричных знаков и ничего другого.
#: Base32-форма (32 знака) сюда намеренно не попадает: TorrServer знает раздачу по hex, и
#: снос «похожей строки» был бы сносом наугад - а сносим мы только по ТОЧНОМУ своему хэшу.
_BTIH: Final = re.compile(r"xt=urn:btih:([0-9a-fA-F]{40})")


def _torrent_hash(magnet: str) -> str:
    """Хэш раздачи прямо из магнита, без похода в TorrServer; не разобрали — пусто.

    Нужен там, где хозяин раздачи уже умер и спросить у него нечего (``cast stop`` после
    убитого юнита): хэш - это часть самого магнита, и знать его можно, не поднимая ничего.
    """
    found = _BTIH.search(magnet)
    return found.group(1).lower() if found else ""


def _release_torrents(config: Config, hashes: Sequence[str]) -> list[str]:
    """Убрать свои раздачи по ЯВНЫМ хэшам; возвращает те, которых в службе больше нет.

    🔴 Именно по хэшам, а не «всё, что видно в списке службы»: раздачи мы заводим с
    ``save_to_db:false``, и «снести всё из list» уже сносило ЧУЖОЕ. Здесь список не
    спрашивается ни разу.

    Срок службе даётся короткий (:data:`torrcast.stream.PROBE_TIMEOUT`), а молчание не
    считается бедой: уборка идёт на выходе, в том числе по SIGTERM от ``cast stop``, и
    задерживать выход из-за неотвечающей службы она права не имеет. Повторный снос
    несуществующей раздачи - не ошибка (:meth:`torrcast.stream.TorrServer.drop`).

    🔴 Но молчание - и не уборка, а разница между ними видна только отсюда. Зовущие по
    этому ответу решают, забывать ли хэш: забытый хэш нечем снести, а раздача переживает
    свой процесс и живёт в службе до её перезапуска.
    """
    gone: list[str] = []
    if not hashes:
        return gone
    torrserver = TorrServer(config.torrserver_url, timeout=PROBE_TIMEOUT)
    for torrent_hash in dict.fromkeys(h for h in hashes if h):
        with contextlib.suppress(TorrcastError):
            if torrserver.drop(torrent_hash):
                gone.append(torrent_hash)
    return gone


def _own_torrent(key: str, torrent_hash: str) -> None:
    """Отметить в состоянии хэш раздачи, которую держит показ; пусто - снять отметку.

    Записывается в тот же момент, когда юнит раздачу поднял, и снимается тогда, когда он
    её убрал: между этими двумя секундами запись и есть единственный след того, кому
    раздача принадлежит (:attr:`torrcast.state.Entry.torrent`).

    Состояние перечитывается: рядом мог писать сторож позиции.
    """
    state = State.load()
    entry = state.get(key)
    if entry is None or entry.torrent == torrent_hash:
        return
    entry.torrent = torrent_hash
    state.put(key, entry)
    state.save()


def _release_orphans(config: Config) -> None:
    """Убрать раздачу, чей хозяин умер не по-людски: SIGKILL по таймауту, паника, ребут.

    Юнит убирает своё сам на любом штатном выходе, но SIGKILL не спрашивает, и хэш умирал
    вместе с процессом: раздача оставалась в TorrServer навсегда - до его перезапуска, - а
    убрать её было нечем («снести всё из list» снесло бы чужое). Теперь хэш лежит в
    состоянии, и сирота живёт максимум до следующего запуска.

    🔴 Мёртвым хозяин считается по ЖИВОСТИ юнита, а не по наличию записи: идёт показ -
    раздача его, и трогать её нельзя. Убирается только то, что записано явным хэшем,
    повторный снос уже убранной - не ошибка (:meth:`torrcast.stream.TorrServer.drop`).

    🔴 Забывается хэш только вместе с раздачей. Служба, которая не ответила, ничего не
    убрала, а запись - единственное, чем эту раздачу вообще можно снести: стерев её за
    молчание, мы делали сироту вечной. Не убралось - не забываем, попробуем в другой раз.
    """
    state = State.load()
    orphans = {key: entry.torrent for key, entry in state if entry.torrent}
    if not orphans:  # обычный случай, и он не стоит ни одного вопроса systemd
        return
    if unit_active():  # показ идёт - раздача под ним живая, и она не сирота
        return
    gone = set(_release_torrents(config, list(orphans.values())))
    if not gone:  # службы нет - сироты остались сиротами, и запись о них тоже
        return
    for key, torrent_hash in orphans.items():
        if torrent_hash in gone:  # не через put: уборка мусора не делает запись «свежей»
            state.entries[key].torrent = ""
    state.save()


def _held_by_show(torrent_hash: str) -> bool:
    """Правда ли, что раздачу держит показ: её хэш записан в состоянии хозяином.

    Параллельный ``cast`` греет раздачи той же выдачи, что стоит на экране (досмотр
    сериала из той же раздачи, ``cast voices`` на играющий фильм), а ``add`` в TorrServer
    идемпотентен - и раздача живого показа оказывается среди прогретых. Снести её на
    уборке прогрева - выдернуть источник из-под экрана, поэтому каждый такой снос
    спрашивает состояние.

    Счётчика владения тут не нужно: двух держателей не бывает по устройству
    (:meth:`torrcast.state.State.held`). А systemd нарочно не спрашивается: так нет ни окна
    гонки на старте юнита (``is-active`` отвечает «active» не в первую же секунду), ни
    цены на счастливом пути - одно чтение файла на снос, а сносы не горячий путь.

    Цена консервативности: хэш, забытый убитым юнитом (SIGKILL), прогрев сносить не
    станет - за него уберёт :func:`_release_orphans` при следующем запуске показа.
    """
    return bool(torrent_hash) and torrent_hash in State.load().held()


def _cmd_stop() -> int:
    """``cast stop`` — снять каст и зафиксировать позицию. Позицию пишет сам
    юнит: ``systemctl stop`` шлёт ему SIGTERM и ждёт, сторож на выходе дописывает state.

    Раздачу за собой убирает сам юнит (:func:`_cmd_worker`), и к этой строке он уже мёртв:
    ``systemctl stop`` его дождался. Но умереть он мог и не по-людски - SIGKILL по
    таймауту, паника, перезагрузка, - а раздача переживает свой процесс: она живёт в
    TorrServer до его перезапуска. Поэтому тот же хэш сносится ещё раз, уже отсюда: он
    берётся из магнита остановленной записи (:func:`_torrent_hash`), снос идемпотентен, и
    ничего, кроме этого хэша, не трогается. Когда ничего не играло, не трогается и он:
    раздачу с тем же магнитом в этот момент может греть чужой ход.
    """
    played = unit_active()
    key = unit_key()  # спрашиваем, пока юнит жив: у мёртвого описания уже не узнать
    stop_play_unit()
    found = _shown(State.load(), key)
    if not played or found is None:
        print("ничего не играет")
        return EXIT_OK
    _, entry = found
    with contextlib.suppress(TorrcastError):  # уборка не вправе провалить саму остановку
        _release_torrents(load_config(), [_torrent_hash(entry.magnet)])
    print(f"остановлено: «{entry.title}» на {_hms(entry.pos)} / {_hms(entry.dur)}")
    return EXIT_OK


def _shown(state: State, key: str) -> tuple[str, Entry] | None:
    """Запись играющего показа: ключ берём из ``--description`` юнита, а не «самую свежую».
    Рядом мог писать другой ход — тогда свежайшая запись не та, что играет.
    """
    entry = state.get(key) if key else None
    return (key, entry) if entry is not None else state.latest()


def _cmd_status() -> int:
    """``cast status`` — что играет, позиция/длительность, источник. Живой юнит —
    источник правды о том, что показ ЗАВЕДЁН, позиция — из state, куда её кладёт сторож.

    🔴 Живой юнит не доказывает картинку на экране. Юнит переживает смерть источника
    нарочно - прогретое досматривается без сети, а вернувшийся источник поднимает показ
    сам (:class:`_Revival`), - и всё это время играть может быть нечем. Замер: с мёртвым
    источником юнит жил 902 с, `cast status` все эти минуты отвечал «играю», и человек
    смотрел в чёрный экран, которому инструмент выдавал справку о здоровье. Поэтому
    отдельный вопрос - не «жив ли юнит», а «есть ли кадр»: ответ на него показ кладёт в
    ту же запись (:attr:`torrcast.state.Entry.dark`).
    """
    config = load_config()
    playing = unit_active()
    found = _shown(State.load(), unit_key() if playing else "")
    if not playing or found is None:
        print("ничего не играет")
        if found is not None and found[1].resumable:
            print(f"последнее: «{found[1].title}» на {_hms(found[1].pos)} / {_hms(found[1].dur)}")
        return EXIT_OK
    key, entry = found
    what = f"«{entry.title}»" + (f" {entry.label}" if entry.label else "")
    # Разрешение - подтверждённое ffprobe у играющего файла, а не заявка имени.
    what += f" · {entry.quality}" if entry.quality else ""
    if entry.dark:
        print(f"показ погас: {what} - {_hms(entry.pos)} / {_hms(entry.dur)}")
        print(f"   {_darkness(entry)} ({entry.dark_why}) - жду возврата, подниму сам")
    else:
        print(f"играю {what} - {_hms(entry.pos)} / {_hms(entry.dur)}")
    if entry.warm > 0:
        # Прогрев - это и есть ответ на вопрос «переживёт ли показ обрыв связи», поэтому
        # он стоит в статусе, а не в отладочной ручке.
        whole = entry.dur > 0 and entry.warm >= entry.dur * WARMED_RATIO
        print(
            f"   прогрето {_hms(entry.warm)} из {_hms(entry.dur)}"
            + (" - весь фильм на диске, интернет не нужен" if whole else "")
        )
    reserve = _cache_reserve(config, entry)
    if reserve:
        print(f"   {reserve}")
    where = "адрес раздачи не определён"
    with contextlib.suppress(TorrcastError):  # адреса нет - статус показа это не отменяет
        where = hls_base(config)
    print(
        f"   {key} · файл #{entry.file_idx} · дорожка {entry.audio + 1} · "
        f"раздача {where}, приёмник {config.receiver}"
    )
    return EXIT_OK


def _cache_reserve(config: Config, entry: Entry) -> str:
    """Сколько минут показа лежит в кэше службы прямо сейчас, языком зрителя.

    Число считается из того, что уже есть: набитое в кэше спрашивает сама служба
    (:meth:`TorrServer.cache`), битрейт лежит в записи (:attr:`Entry.vbps`). Спросить
    - один запрос к местной службе, и только из ``cast status``: горячий путь показа
    сюда не ходит.

    Минуты - частное от битрейта ЭТОГО файла, а не константа: замер показал, что одни
    и те же гигабайты кэша - это 32 минуты тяжёлого релиза и вдвое больше лёгкого.
    Звук источника в записи не хранится и потому не учитывается - оценка чуть щедрая,
    и число читается как «примерно столько».

    Любое звено может умереть, и каждая смерть - честная строка, а не исключение и не
    молчание: нет хэша раздачи (запись прежней версии) - спросить нечего и строки нет,
    служба не отвечает или молчит про кэш - «неизвестно», битрейт не спрошен - минуты
    не перевести, кэш пуст - запаса нет.
    """
    if not entry.torrent:
        return ""
    try:
        payload = TorrServer(config.torrserver_url, timeout=PROBE_TIMEOUT).cache(entry.torrent)
    except InfraError:
        return "запас в кэше службы неизвестен - служба раздач не отвечает"
    filled = payload.get("Filled")
    if not isinstance(filled, int) or isinstance(filled, bool) or filled < 0:
        return "запас в кэше службы неизвестен - служба про него молчит"
    if filled == 0:
        return "кэш службы пуст, запаса показа в нём нет"
    if entry.vbps <= 0:
        return "запас в кэше службы есть, в минуты не перевести - битрейт файла неизвестен"
    minutes = filled * 8 / (entry.vbps * 1e6 * 60)
    if minutes < 1:
        return "в кэше службы запас меньше минуты показа"
    return f"в кэше службы запас ещё на {minutes:.0f} мин показа"


def _darkness(entry: Entry) -> str:
    """Сколько на экране темно, для человека.

    Отметку ставил показ, а читает её ``cast status`` - это два процесса и, вообще
    говоря, два взгляда на часы. Поэтому отрицательная разница тут не сбой измерения, а
    сдвинутые часы: про число тогда молчим, про саму темноту - нет.
    """
    dark = time.time() - entry.dark
    return f"темнота {_hms(dark)}" if dark > 0 else "темнота"


def _cmd_releases(args: Args) -> int:
    """``cast releases <запрос>`` — отладочная ручка: таблица и выход.

    На счастливом пути таблицы нет вовсе: релиз выбирается сам. Но посмотреть, из чего
    он выбирал, иногда надо — и тогда рядом лежит ``cast <запрос> --release N``.

    Таблица спрашивает настоящую длительность, чтобы битрейт (а значит, и порядок
    раздач, и номера ``N``) совпал с тем, что сыграет ``cast`` по этому номеру.

    🔴 TC-446. Номер релиза относится к КАРТИНЕ своей таблицы, а не к выдаче целиком:
    нумерация в каждой таблице своя. Картин несколько - одним номером релиза картину не
    назвать, и таблица обязана это говорить: картины нумеруются (тем же номером, что в
    меню ``cast <запрос>`` и у ``--pick``), а строка-подсказка зовёт оба флага.

    🔴 TC-241. Судит таблица по ОБНАРУЖЕННОМУ профилю приёмника - тому самому, на
    который поедет показ: по осторожному умолчанию пометка «перекодируем» врала,
    обещая перекод там, где приставка играет копией. Определение профиля - то же, что
    на пути показа (:func:`~torrcast.profile.detect`), и оно не молчаливое: строка про
    профиль печатается всегда, и приёмника может не быть вовсе - тогда строка честно
    говорит, по какому профилю судим.
    """
    config = load_config()
    inner = Args(query=list(args.query[1:]))
    if not inner.query:
        raise NotFoundError("что искать? cast releases <запрос>")
    chosen = detect_profile(config)
    config = tune_profile(config, chosen.profile)
    with Progress() as progress:
        plans = _search(config, inner, progress, chosen.profile)
    facts = Facts([(p.picture.title, p.picture.year) for p in plans])
    facts.start()
    try:
        print(f"профиль приёмника: {chosen.profile.title} - {chosen.how}")
        for number, plan in enumerate(plans, start=1):
            plan = _timed(plan, facts, inner, config, chosen.profile)
            print()
            head = f"{_named(plan.picture)} - раздач {len(plan.ranked)}"
            # Номер картины тот же, что у пункта меню в `cast <запрос>` и у --pick:
            # порядок таблиц - порядок меню (:func:`_search` в обеих командах).
            print(f"{number}. {head}" if len(plans) > 1 else head)
            print(
                render_table(
                    plan.ranked,
                    plan.runtime,
                    plan.warn_mbit,
                    recode_at=plan.recode_at,
                    hard_mbit=plan.hard_mbit,
                )
            )
        print()
        if len(plans) > 1:
            print(
                "играть конкретный: cast <запрос> --pick M --release N [--file N] - "
                "M это номер картины выше, N номер релиза в её таблице"
            )
        else:
            print("играть конкретный: cast <запрос> --release N [--file N]")
        return EXIT_OK
    finally:
        facts.finish()


def _cmd_voices(args: Args) -> int:
    """``cast voices <запрос>`` — какие озвучки есть у релиза, который поедет на ТВ.

    Отладочная ручка того же рода, что ``cast releases``: на счастливом пути озвучка
    выбирается сама, а посмотреть, из чего она выбрана, — сюда. Играть конкретную:
    ``cast <запрос> --voice N``.

    Показ отсюда не начинается и состояние не пишется; прогретые раздачи убираются из
    TorrServer, как и на всяком пути мимо показа (:meth:`_Bench.drop_all`).
    """
    config = load_config()
    inner = Args(query=list(args.query[1:]), release=args.release, file=args.file)
    if not inner.query:
        raise NotFoundError("что искать? cast voices <запрос>")
    with Progress() as progress:
        plans = _search(config, inner, progress)
        bench = _Bench(TorrServer(config.torrserver_url), choose=_file_picker(inner))
        try:
            plan = _pick_plan(plans, asked=inner.title_query)
            prep = bench.resolve(plan, inner, progress)
        finally:
            bench.drop_all()
    media = prep.found
    remembered = _remembered(State.load(), plan.picture.key, None)
    print()
    print(f"{_named(plan.picture)} - релиз {prep.number}: {_cut(prep.release.title, 60)}")
    print(voices_table(media, media.default_track(), remembered))
    print()
    print("играть конкретную: cast <запрос> --voice N   (выбор запомнится на эту картину)")
    return EXIT_OK


def _cmd_doctor() -> int:
    """``cast doctor`` — самопроверка окружения по-русски.

    Один вызов отвечает на все вопросы, которые иначе приходится проверять руками: терминал и
    локаль (кириллица в вопросах), Prowlarr и TorrServer (есть чем искать и чем
    раздавать), адрес ТВ и его порт 8009 (есть кому играть), ffmpeg с ``readrate``.
    """
    from torrcast.doctor import checkup

    bad = 0
    for line, ok in checkup(load_config()):
        print(line)
        bad += 0 if ok else 1
    print()
    print("всё в порядке" if not bad else f"проблем: {bad} - смотри строки «плохо» выше")
    return EXIT_OK if not bad else EXIT_INFRA


def _cmd_log(args: Args) -> int:
    """``cast log [--since]`` — выжимка недельного диагностического следа.

    По умолчанию - последние три сеанса; ``--since`` двигает границу (``2d``/``12h``/``30m``
    или дата ``ГГГГ-ММ-ДД``) и снимает потолок числа сеансов. Читает ту же ленту, что ведут
    поиск, отбор и показ, - никаких внешних систем, всё лежит рядом с состоянием.
    """
    since = _since_seconds(args.since)
    rows = trace.records(since)
    limit = 0 if args.since else 3
    print(trace.digest(rows, limit=limit))
    return EXIT_OK


def _since_seconds(since: str | None) -> float:
    """``--since`` в абсолютное время: ``2d``/``12h``/``30m`` от сейчас или дата ГГГГ-ММ-ДД."""
    if not since:
        return 0.0
    units = {"d": 86400.0, "h": 3600.0, "m": 60.0}
    tail = since[-1].lower()
    if tail in units and since[:-1].isdigit():
        return time.time() - int(since[:-1]) * units[tail]
    with contextlib.suppress(ValueError, OverflowError):
        return time.mktime(time.strptime(since, "%Y-%m-%d"))  # локальная дата, как и весь след
    return 0.0


def _cmd_worker(key: str) -> int:
    """Показ внутри transient-юнита: своей раздачей, своей упаковкой и своим сторожем.

    Руками не зовётся — это ``ExecStart`` юнита ``torrcast-play``. Всё, что нужно знать о
    показе, лежит в записи состояния: magnet, файл, дорожка и позиция.

    Сериал юнит доигрывает сам: серия дошла до порога 95 % — сторож записал в
    состояние следующую, и цикл берёт её же раздачу и следующий файл, не спрашивая CLI.
    Серия была последней — состояние отмечает конец, цикл выходит, юнит гаснет чисто.

    ⚠️ **Приёмник один на весь юнит, а не на серию.** Соединение с ТВ живёт здесь и
    достаётся каждой серии готовым. Иначе получалось два сендера сразу: на стыке серий
    приложение приёмника намеренно не закрывается (:func:`_handover`), поэтому и сокет
    прошлой серии оставался жив, а следующая поднимала себе новый. Для приёмника оба —
    один и тот же ``sender-0`` (докстринг :class:`torrcast.cast.ChromecastReceiver`), и он
    отвечает новому пустым статусом. Замер на живом Q70D, стык s1e5→s1e6: два
    соединения в ``ss``, «LOAD не взяли (IDLE/ERROR)», «приёмник залип — закрываю
    приложение и соединение», экран пустой **15.3 с**.

    ⚠️ **Раздача уезжает вместе с показом.** Юнит - единственный её хозяин: он её поднял,
    он один из неё читает, и кроме него о ней не знает никто (``save_to_db:false``, в
    списке службы её не видно). Пока уборки тут не было, каждый сеанс оставлял по раздаче
    навсегда - до перезапуска TorrServer, - и они копились ровно в той службе, которая
    падает по таймеру тем вероятнее, чем их больше (:data:`MAX_LIVE`). Убирается своё и
    только своё, по хэшам, которые юнит завёл сам, и на любом выходе: штатный конец,
    ошибка и SIGTERM от ``cast stop`` (он приходит как :class:`_Stopped` и раскручивает
    ``finally`` наравне с прочими). Прогрев следующей серии тут не жертва: он идёт по этой
    же раздаче и кончается вместе с юнитом.
    """
    mark("процесс показа")
    config = load_config()
    # Профиль приёмника юнит выбирает себе сам, а не получает от CLI: юнит переживает
    # смену серии и живёт своей жизнью, а опрос паспорта стоит одного HTTP к устройству.
    chosen = detect_profile(config)
    config = tune_profile(config, chosen.profile)
    print(f"профиль приёмника: {chosen.profile.title} - {chosen.how}", flush=True)
    # SIGTERM от `cast stop` обязан пройти через finally: иначе позиция не запишется.
    signal.signal(signal.SIGTERM, _on_term)
    torrserver = TorrServer(config.torrserver_url)
    receiver = make_receiver(
        config.receiver,
        config.tv or "",
        config.hls_cert if config.transport == "https" else "",
        profile=chosen.profile,
    )
    supply = Supply(TorrServer(config.torrserver_url, timeout=PROBE_TIMEOUT))
    #: Хэши, которые подняли МЫ, - по ним и только по ним пойдёт уборка на выходе.
    mine: list[str] = []
    try:
        return _worker_loop(config, key, torrserver, receiver, supply, mine, chosen.profile)
    finally:
        gone = _release_torrents(config, mine)
        # Раздачи больше нет - и записи о ней тоже: следующему запуску убирать нечего.
        # А вот если служба смолчала, раздача жива, и запись о ней - единственное, чем её
        # потом снести (:func:`_release_orphans`): такой хэш забывать нельзя.
        if not mine or mine[-1] in gone:
            with contextlib.suppress(TorrcastError):  # не вправе провалить сам выход
                _own_torrent(key, "")


def _worker_loop(
    config: Config,
    key: str,
    torrserver: TorrServer,
    receiver: Receiver,
    supply: Supply,
    mine: list[str],
    profile: Profile,
) -> int:
    """Сам цикл показа: серия за серией, пока сериал не кончится. Раздачи, которые он
    поднял, складываются в ``mine`` — их убирает :func:`_cmd_worker` на выходе.
    """
    magnet, torrent_hash = "", ""
    while True:
        entry = State.load().get(key)
        if entry is None:
            raise InfraError(f"в состоянии нет записи {key}")
        if entry.magnet != magnet:  # раздача та же - метаданные второй раз не ждём
            magnet = entry.magnet
            torrent_hash = torrserver.add(magnet)
            mine.append(torrent_hash)  # с этой секунды у раздачи есть хозяин - этот юнит
            # ...и с этой же секунды имя хозяина знает состояние: умри мы по SIGKILL,
            # хэш - единственное, чем раздачу потом убрать (:func:`_release_orphans`).
            # Поле правится и в своей копии записи: её кладёт на диск сторож позиции.
            entry.torrent = torrent_hash
            _own_torrent(key, torrent_hash)
            torrserver.wait_files(torrent_hash, timeout=WORKER_META)
            # Тот же магнит, но живёт он теперь и у сторожа: URL потока несёт только хэш,
            # и вернуть раздачу с трекерами после аварии источника может лишь он
            # (:class:`torrcast.stream.Supply`). За магнитом в индексеры мы не ходим - он
            # лежит в записи картины.
            supply.torrent_hash, supply.magnet, supply.lost = torrent_hash, magnet, ""
        source = torrserver.stream_url(torrent_hash, entry.file_idx)
        entry = _duration(key, entry, source)
        watch = Watch(key=key, entry=entry)
        title = " ".join(filter(None, (entry.title, entry.label)))
        sid = trace.start_session()
        journal = f"[сеанс {sid}]"
        # Профиль идёт в след каждой серией: по какому набору порогов играли - вопрос,
        # который иначе снова пришлось бы выяснять с гипервизора.
        trace.emit(
            "session",
            "session_start",
            title=title,
            pos=round(entry.pos, 1),
            profile=profile.key,
        )
        print(f"{journal} показ «{title}» с {_hms(entry.pos)}", flush=True)
        code = _play(
            config,
            source,
            entry.audio,
            title,
            _Clock(),
            watch,
            receiver=receiver,
            codec=entry.codec,
            # Кодек без глубины цвета - половина паспорта: Hi10P зовётся тем же h264.
            depth=entry.depth,
            # И кадр туда же: 2160p приёмник не берёт ни в каком кодеке, его ужимает
            # перекод (TC-221/TC-222). HDR - чем красить ужатое (TC-223).
            frame=entry.frame,
            hdr=entry.hdr,
            # Прогрев следующей серии впрок: собирается лениво, когда текущая уже на
            # диске (:meth:`torrcast.warm.Warmer._chain`). Раздача та же, файл - соседний.
            follow=partial(_next_warmer, config, torrserver, torrent_hash, entry, profile),
            supply=supply,
            profile=profile,
            journal=journal,
        )
        following = _following(key) if watch.done else None
        if following is None:
            return code
        print(f"следующая серия: {following.label}", flush=True)


def _following(key: str) -> Entry | None:
    """Серия, которую юнит доиграет следом за только что досмотренной.

    ``None`` — показ на этом кончается: фильм, последняя серия сезона или запись, которую
    сериалом и не считали. Отсюда же знают, закрывать ли приложение приёмника: между
    сериями оно живёт дальше, а на конце показа — гаснет (см. :func:`_play`).
    """
    entry = State.load().get(key)
    if entry is None or entry.done or not entry.label:
        return None
    return entry


def _duration(key: str, entry: Entry, source: str) -> Entry:
    """Длительность серии для порога 95 %: следующая серия своей ещё не знает —
    её длительность лежит в её же файле, и читается она из потока, как дорожки.

    Тем же ffprobe берётся и вес видеодорожки (:attr:`Entry.vbps`): у следующей серии
    он свой, а профиль тяжести показа считается по нему.

    ⚠️ Ради одного только веса дорожки ffprobe тут не зовётся. Записи прежних версий его
    не несут, и спрашивать за них при каждом запуске значило бы платить секундами старта
    (у «Моаны 2» ffprobe стоит до 17 с) за то, что показ и так доберёт по факту
    (:meth:`torrcast.recode.Weights.calibrate`). Своё число такая запись получит на первом
    же обычном запуске через выбор релиза.

    🔴 Ради глубины цвета (:attr:`Entry.depth`) ffprobe зовётся и у записи с известной
    длительностью - ровно один раз на запись. Записи прежних версий её не несут вовсе, а
    молчание тут читается как «восемь бит», то есть как «уезжай копией»: на десятибитном
    H.264 это вечная петля на экране (:func:`torrcast.stream.recodes_whole`). Один ffprobe
    против неиграющего показа - цена, которую платить стоит, и платится она однажды.

    🔴 TC-251. Тем же одним ffprobe добирается и кадр (:attr:`Entry.frame`) - ровно по
    той же причине. Запись прежней версии его не несёт, а молчание тут читается
    :func:`torrcast.recode.level_for` как «4.1»: на 4К это враньё в поток (у 2160p 32400
    макроблоков против потолка 8192), и окно у вранья ровно одно - первое продолжение
    старой записи. Лишнего запроса это не стоит: паспорт и так читается один раз на
    запись ради глубины, кадр лежит в нём же.
    """
    if entry.dur > 0 and entry.depth > 0 and entry.frame > 0:
        return entry
    media = probe(source, timeout=WORKER_DUR)
    entry.dur = media.duration or entry.dur
    # Ноль - «ещё не спрашивали», минус - «спросили, паспорт промолчал» (mp4 без тегов).
    entry.vbps = media.video_bps / 1e6 or -1.0
    # Кодек следующей серии тоже свой: в раздаче аниме нередко лежат и HEVC, и H.264,
    # а решение «перекодировать целиком» принимается по файлу, который играем сейчас.
    entry.codec = media.video or ""
    # Глубина цвета оттуда же и той же ценой: без неё Hi10P неотличим от обычного H.264.
    entry.depth = media.depth
    # И кадр тем же паспортом: без него 4К-запись прежней версии уезжала бы с уровнем
    # «4.1» в потоке - заведомым враньём (TC-251).
    entry.frame = media.frame
    state = State.load()
    state.put(key, entry)
    state.save()
    return entry


class _Stopped(KeyboardInterrupt):
    """``cast stop``: SIGTERM пришёл, показ окончен штатно — это не авария.

    Наследуемся от ``KeyboardInterrupt`` намеренно: раскрутка обязана пройти ровно так
    же, как проходила, — через ``finally`` в :func:`_play`, где пишется позиция, гаснет
    упаковка и снимается каст. Меняется только вывеска на выходе: ``cast stop`` — это
    успех, и юнит обязан умереть кодом 0, иначе systemd помечает его ``failed`` и после
    каждой штатной остановки в `systemctl` краснеет `● torrcast-play … failed`.
    """


def _on_term(_signal: int, _frame: object) -> None:
    raise _Stopped


@dataclass(slots=True)
class Watch:
    """Сторож: раз в :data:`WATCH_SECONDS` кладёт позицию приёмника в state.

    Позиция приходит абсолютной: манифест описывает весь фильм, а ``-copyts`` оставляет
    в сегментах исходные метки времени, поэтому приёмник считает время от начала фильма
    независимо от того, с какого места идёт упаковка. Пересчитывать смещение показу
    больше не нужно — раньше это была отдельная строчка возможной лжи.
    Порог 95 % — «досмотрено»: фильму сброс с пометкой, сериалу следующая серия.
    """

    key: str
    entry: Entry
    every: float = WATCH_SECONDS
    done: bool = False
    last: float = field(default_factory=time.monotonic)

    def see(self, pos: float) -> None:
        """Позиция от приёмника; на диск — не чаще раза в ``every`` секунд. Порог 95 %
        записывается сразу: на нём держится стык серий, ждать тика ещё 10 с незачем.
        """
        if pos <= 0:  # приёмник ещё не начал считать - нулём позицию не затираем
            return
        self.entry.pos = pos
        if self.entry.watched or time.monotonic() - self.last >= self.every:
            self.flush()

    def flush(self) -> None:
        """Записать состояние атомарно (tmp + rename в :mod:`torrcast.state`)."""
        if self.done:  # досмотренную запись повторными тиками не портим
            return
        self.last = time.monotonic()
        state = State.load()  # перечитываем: рядом мог писать другой ход
        self.done = self.entry.watched
        state.put(self.key, self.entry.advance() if self.done else self.entry)
        state.save()
        if self.done:
            what = f" {self.entry.label}" if self.entry.label else ""
            print(f"досмотрено{what}: {_hms(self.entry.pos)} из {_hms(self.entry.dur)}", flush=True)


@dataclass(slots=True)
class _Clock:
    """Фазы старта: холодный старт стоит 15–30 с, и цифры должны быть видны глазами."""

    start: float = field(default_factory=time.monotonic)
    last: float = field(default_factory=time.monotonic)

    def lap(self) -> str:
        now = time.monotonic()
        gap, self.last = now - self.last, now
        return f"{gap:.1f} с"

    @property
    def total(self) -> float:
        return time.monotonic() - self.start


def _cmd_play(args: Args) -> int:
    """Счастливый путь: запрос → «какой фильм?» → «какая озвучка?» → показ.

    Релиз и файл выбираются сами, таблиц и списков файлов на этом пути нет. Пока человек
    отвечает на вопрос про франшизу, топ-3 кандидата уже греются в TorrServer и читаются
    ffprobe: к моменту ответа критический путь чаще всего пуст.

    ``--new`` здесь ничего не стирает: сохранённая позиция уходит в расход только тогда,
    когда показ уже точно начинается (:func:`_forget_progress`). Почему так — там же.
    """
    mark("команда")
    clock = _Clock()
    config = load_config()
    # Раздача показа, убитого не по-людски, - первое, что убирается: она держит рой и
    # место в TorrServer, а хозяина у неё нет. Пустое состояние это не стоит ни секунды.
    _release_orphans(config)
    # Профиль приёмника - до всего остального: от него зависят и потолки отбора, и то,
    # какой кодек считается играбельным. Спрашивать о нём человека нечего: он выбирается
    # по паспорту устройства, а незнакомому приёмнику достаётся осторожный набор.
    chosen = detect_profile(config)
    config = tune_profile(config, chosen.profile)
    state = State.load()
    found_entry = state.find(args.title_query)
    # --new: прежний прогресс не продолжаем и выбираем заново, но запись пока цела.
    stale = found_entry[0] if found_entry is not None and args.new else None
    if found_entry is not None and not args.new:
        code = _continue(config, *found_entry, args=args, clock=clock)
        if code is not None:
            return code

    with Progress() as progress:
        plans = _search(config, args, progress, chosen.profile)
        # Справка к меню (рейтинг, хронометраж, о чём кино) едет фоном - ровно в те
        # секунды, что уходят на подъём прогрева. Меню её не ждёт: см. torrcast.facts.
        facts = Facts([(p.picture.title, p.picture.year) for p in plans])
        facts.start()
        # 🔴 TC-199/TC-200. Год картины, которая встанет дефолтом, сверяется со справкой -
        # так же, как добор сверяет свой (:func:`year_note`). Справку зовём вслепую и фоном,
        # ровно в те секунды, что уходят на меню и прогрев: путь до меню её не ждёт, а к
        # последней строке перед стартом паспорт уже приехал. Год выдачи ей НЕ сообщаем -
        # иначе подстроится под подмену и сверять станет нечего.
        passport = _passport(plans)
        torrserver = TorrServer(config.torrserver_url)
        bench = _Bench(torrserver, choose=_file_picker(args), profile=chosen.profile)
        # Прогрев под меню: пока идёт вопрос, раздачи уже качают метаданные. Греется
        # голова ОЧЕРЕДИ, а не верх ранжира: верх мог не пройти ворота (TC-432), и
        # греть то, что отбор не возьмёт, - тянуть чужой вес из роя зря.
        order = warm_order(plans)
        for plan in order[:PREWARM]:
            # Номер, названный руками, у каждой картины меню свой, и у части их столько
            # раздач не наберётся: спрос с той, которую человек выберет, - за отбором.
            if args.release is not None and not 1 <= args.release <= len(plan.ranked):
                continue
            if queue := plan.candidates(args):
                bench.start(plan, queue[0])
        # ...и запасной релиз той картины, в которую попадёт Enter: брак верха не должен
        # стоить человеку подъёма второй раздачи с нуля (:data:`PREWARM_SPARE`).
        bench.spare(order[0], args)
        mark("прогрев пущен")  # TC-108: замер
        try:
            try:
                plan = _pick_plan(plans, facts, pick=args.pick, asked=args.title_query)
                mark("картина выбрана")  # TC-108: замер
                # Опоздавший индексер: круг ушёл по кворуму, и его выдача доехала, пока
                # человек читал меню. Доливаем ЗДЕСЬ - список уже прочитан и отвечен,
                # менять под курсором нечего (:func:`_topup`). Ключи меню ему нужны,
                # чтобы отличить картину, которой в списке не было (о ней - честная
                # строка), от соседней по меню (о ней говорить «её не было» - соврать).
                plan = bench.reorder(
                    plan,
                    _topup(
                        plan,
                        args,
                        config,
                        chosen.profile,
                        progress,
                        menu=frozenset(p.picture.key for p in plans),
                    ),
                )
                # Справка уже дождана меню - её хронометраж встаёт в знаменатель
                # битрейта вместо прикидки (:func:`_timed`), и порядок отбора
                # пересобирается на настоящих числах. Прогретое при этом не пропадает:
                # номера релизов переезжают вместе с порядком (:meth:`_Bench.reorder`).
                plan = bench.reorder(plan, _timed(plan, facts, args, config, chosen.profile))
                # Прогретые кандидаты ДРУГИХ картин с этой секунды - мусор: они тянут
                # куски у той раздачи, которую сейчас будем показывать, и всё это время
                # стоят в TorrServer лишними (:meth:`_Bench.keep_plan`).
                bench.keep_plan(plan)
            finally:
                # Меню уже на экране, и ответ на него получен: пусть фоновый добор допишет
                # кэш - СЛЕДУЮЩЕЕ меню этой франшизы будет полным. Ко времени до меню это
                # отношения не имеет, а к моменту ответа поток обычно давно закончил.
                facts.finish()
            plan, prep = _played(bench, plans, plan, args, progress, facts, config, chosen.profile)
            mark("отбор релиза", релиз=prep.number)  # TC-108: замер
        except BaseException:  # Ctrl-C, «картин много, а терминала нет», «годного нет»
            bench.drop_all()  # прогретое без показа - мусор в рое и кэш в чужой RAM
            raise
        bench.keep_only(prep)  # прогрев греет лишнее - до показа лишнее убираем

    release, video, media = prep.release, prep.want, prep.found
    audio, voice = pick_voice(media, args, _remembered(state, plan.picture.key, found_entry))
    mark("ответы")  # ноль секундомера: Enter после последнего вопроса
    label = media.tracks[audio].label if audio < len(media.tracks) else "-"
    series = plan.series
    what = f"«{plan.picture.title}»" + (
        f" {series.want}" if series else f" ({plan.picture.year or '?'})"
    )
    about = f"{what} · {quality_text(release, media)} · {label}"
    trace.emit(
        "select",
        "select",
        release=prep.number,
        quality=quality_text(release, media),
        track=label,
        codec=media.video or "",
        mbit=round(bitrate_mbit(video.size, media.duration or plan.runtime), 1),
    )
    # Настоящий битрейт: размер файла серии/фильма на его же длительность, а не оценка.
    peak = bitrate_mbit(video.size, media.duration or plan.runtime)
    if peak > config.bitrate_warn_mbit:
        print(
            f"внимание: ~{peak:.0f} Мбит/с - тяжёлые куски перекодирую на ходу"
            if config.recode
            else f"внимание: ~{peak:.0f} Мбит/с - ресивер на таком битрейте может встать"
        )
    # Молчаливого японского не бывает: перевода в файле нет - человек слышит об этом
    # строкой, а не на слух через минуту показа.
    playable = [plan.ranked[number - 1] for number in plan.candidates(args)]
    if note := sound_note(
        media,
        audio,
        playable,
        release,
        prep.files,
        native=plan.picture.native,
    ):
        print(note)
    # Русских дорожек было несколько - говорим, сколько и что взяли: подпись дорожки
    # отвечает «что играет», а эта строка - «почему это, а не соседняя».
    if note := voice_note(media, audio):
        print(note)
    if args.pinned:  # отладочный путь: тут внутренности показывать и надо
        print(f"файл: {video.base} · {_gb(video.size)} · {_hms(media.duration)} · {media.video}")
    # 🔴 TC-198. Последняя строка перед стартом: взяли не то, что назвали вслух. Место
    # выбрано не для порядка - фазы поиска к этой секунде уехали вверх экрана, а решение
    # про КАРТИНУ человек должен унести с собой. Человек выбрал пункт меню сам - подмены
    # нет и строки нет (:func:`default_note`).
    if note := swap_note(plans, plan, args.title_query):
        print(note)
    # 🔴 TC-199/TC-200. Год дефолтной картины против независимого слова справки: имя
    # раздачи врёт («Оно» 2014, «Медведь» 2026), а год у дефолта не сверялся нигде.
    if _is_default(plans, plan) and (note := year_note(plan, passport.get(), args.title_query)):
        print(note)
    # 🔴 TC-371. Двусмысленность самих источников: под одним именем и годом картин две,
    # и развести их отбору нечем - значит человек читает об этом строкой.
    if note := namesake_note(plan, passport.get()):
        print(note)
    if args.dry:
        # Показа не будет: «сыгранная» раздача - такой же мусор, как прогретое лишнее.
        # Убирается по СВОИМ явным хэшам, как на любом выходе без показа.
        bench.drop_all()
        # Сухой прогон - главный замер отбора, поэтому он называет, ЧТО выбрал бы:
        # имя файла внутри раздачи, а не эхо запроса. Иначе дефект «сыграла не та
        # серия» (сквозная нумерация против сезонной) всухую не виден вовсе (TC-302).
        print(f"(--dry) {about} · файл «{video.base}» - каста нет")
        return EXIT_OK
    entry = Entry(
        title=plan.picture.title,
        magnet=release.magnet,
        kind="tv" if plan.picture.kind == "tv" else "movie",
        file_idx=video.index,
        audio=audio,
        voice=voice,
        dur=media.duration,
        # Вес видеодорожки из паспорта: по нему показ строит профиль тяжести с первой
        # секунды, не набирая поправку «контейнер → ТВ» вслепую.
        vbps=media.video_bps / 1e6 or -1.0,
        # Кодек оттуда же: по нему показ решает, играть копией или перекодировать файл
        # целиком, и решает это один раз - до первого сегмента (:func:`_encode_all`).
        codec=media.video or "",
        # И глубина цвета рядом: одного имени кодека для этого решения не хватает.
        depth=media.depth,
        # То, что уехало на ТВ: `cast status` покажет факт, а не заявку имени.
        quality=media.quality if media.height else "",
        # Тот же кадр числом: по нему показ решает, до чего ужать картинку перекодом.
        frame=media.frame,
        # И HDR оттуда же: ужатому кадру ещё решать, приводить ли цвет к SDR.
        hdr=media.hdr,
        query=slugify(args.title_query),
        season=series.want.season if series else None,
        episode=series.want.episode if series else None,
        episodes=series.table if series else [],
    )
    if stale is not None:  # точка невозврата пройдена - вот теперь --new вправе забывать
        _forget_progress(stale)
    return _launch(config, plan.picture.key, entry, about, clock)


def _forget_progress(key: str) -> None:
    """Забыть прежний прогресс по ``--new`` — в момент, когда показ уже точно начинается.

    Раньше запись стиралась первым же действием команды, до единого вопроса. Любой обрыв
    после этого — «ничего не разобралось», Ctrl-C, упавший ffprobe, а на прогоне без
    терминала ещё и выбор вслепую — оставлял пользователя без сохранённого места, и взять
    его было неоткуда: state уже перезаписан (ровно так и терялась запись фильма).

    Раннее стирание при этом ничего не давало: свежую запись с нулевой позицией всё равно
    кладёт :func:`_launch`. То есть у него была одна цена и ни одной пользы.
    """
    state = State.load()  # перечитываем: рядом мог писать другой ход
    state.drop(key)
    state.save()


def _relayout(
    client: Prowlarr, query: str, name: str, index: int | None, progress: Progress
) -> tuple[str, str, int | None, list[RawResult]]:
    """Второй заход той же строкой, прочитанной как забытая раскладка. Пусто - как было.

    `cast nfxrb` - это «тачки»: запрос, набранный не переключив раскладку. Отказ по
    такой строке правдив для ``nfxrb``, но не для картины, которая есть в каталоге.

    Зовётся ровно на пустой выдаче, и это принципиально: у латинской строки всегда есть
    кириллический двойник, и звать перевод раньше значило бы искать «сфкы» вместо
    «cars». Пустая выдача - единственный случай, когда терять нечего, и стоит он один
    заход к индексерам там, где иначе человек уже читал бы отказ.

    Номер части перечитывается заново (:func:`~torrcast.parse.split_franchise_index`):
    «nfxrb 2» - это «тачки 2», и цифра в новой строке обязана снова стать номером, а не
    остаться в имени. Подмена не молчаливая: строка про раскладку печатается до меню -
    человек видит, ЧТО именно за него прочитали.
    """
    from torrcast.parse import unswap_layout

    swapped = unswap_layout(query)
    if swapped == query.casefold():
        return query, name, index, []
    fixed, moved = split_franchise_index(swapped)
    progress.phase(f"поиск «{fixed}»")
    raw = _ask(client, fixed, progress)
    if not raw:
        return query, name, index, []
    progress.note(f"«{query}» - это «{swapped}» в русской раскладке")
    return swapped, fixed, moved, raw


def _titled_number(
    client: Prowlarr, query: str, name: str, raw: list[RawResult], progress: Progress
) -> tuple[list[RawResult], list[Picture], list[Picture]]:
    """Второй заход ВСЕЙ строкой: цифра оказалась частью названия. Не помогло - как было.

    🔴 TC-296. `cast «бен 10»` уезжал искать «Бен-Гур». Хвостовая цифра читается номером
    части франшизы (:func:`~torrcast.parse.split_franchise_index`), и в индексеры уходил
    обрубок «бен» - строка, по которой каталог отдаёт «Бена» 1972 года и три десятка
    однофамильцев, а семи картин «Бен 10» не отдаёт ВООБЩЕ НИ ОДНОЙ. Дальше всё честно
    работало по чужой выдаче: тощий пул звал добор, справка по «бену» приводила
    ``Ben-Hur``, и человек читал «картин во франшизе 1, номера 10 нет» при живом сериале,
    который лежит в том же каталоге. Замер той же строкой без обрезки: 88 строк, семь
    картин линейки «Бен 10».

    Отличить номер части от цифры в названии ДО первого круга нечем: «тачки 2» и «бен 10»
    - одна и та же строка с точностью до слов. Зато после круга каталог уже ответил, и
    ответ этот однозначный: картины с таким номером в найденной франшизе НЕТ (пустой
    ``found`` при названном номере) - значит либо номер лишний, либо франшиза не та.
    В обоих случаях впереди был отказ, и заход всей строкой стоит ровно столько же,
    сколько стоил бы он, - как и второй заход по забытой раскладке (:func:`_relayout`).

    На счастливом пути этого захода нет вовсе: «тачки 2», «форсаж 5», «шрек 2» находят
    свою картину первым же кругом, и сюда не заглядывают. Круг платится из остатка цели
    (:func:`_no_budget`), как и все прочие доборы.

    ⚠️ Не помогло - остаётся ПРЕЖНЯЯ выдача, а не расширенная. Лишние строки сдвинули бы
    нумерацию франшизы (о том же :func:`_second_language`), и честное «номера N нет»
    стало бы неправдой про другую линейку.
    """
    from torrcast.parse import cluster, pick_franchise

    if _no_budget(client, f"поиск «{query}» целиком", progress) is None:
        return raw, cluster(to_releases(raw)), []
    progress.phase(f"поиск «{query}»")
    merged = merge(raw, _ask(client, query, progress))
    progress.phase("")
    if len(merged) == len(raw):
        return raw, cluster(to_releases(raw)), []
    pictures = cluster(to_releases(merged))
    found = pick_franchise(query, pictures)
    if not found:
        return raw, cluster(to_releases(raw)), []
    progress.note(f"по «{name}» картины не нашлось - искал «{query}» целиком")
    return merged, pictures, found


def _season_asked(found: list[Picture], name: str, pictures: list[Picture]) -> bool:
    """Номер запроса просит СЕЗОН сериала, а не часть франшизы (TC-363).

    Спрашивается ровно то же, что решил разбор (:func:`~torrcast.parse.reads_season`), и
    сверяется его ответом: номер отдан сериалам франшизы, а не картине по счёту. Двух
    правил тут нет - есть одно, и cli лишь читает, чем оно кончилось: номер должен
    доехать до сезонной машинерии, а знает про сезоны она, а не разбор.
    """
    from torrcast.parse import pick_franchise, reads_season

    if not found or any(picture.kind != "tv" for picture in found):
        return False
    return reads_season(pick_franchise(name, pictures))


def _search(
    config: Config, args: Args, progress: Progress, profile: Profile = CAUTIOUS
) -> list[_Plan]:
    """Поиск и разбор выдачи: запрос → картины франшизы, каждая со своим пулом релизов.

    ``profile`` - чей декодер судит релизы (:mod:`torrcast.profile`). Пороги битрейта до
    отбора доезжают сами - профиль накладывается на настройки ещё в ``_cmd_play``
    (:func:`torrcast.profile.tune`), - а вот НАБОР КОДЕКОВ в настройках ключа не имеет, и
    спросить о нём можно только сам профиль (:func:`last_hope`). Умолчание осторожное, и
    пользуются им только ручки вроде ``cast voices``: ``cast releases`` передаёт
    обнаруженный профиль явно - таблица обязана судить про тот приёмник, на который
    поедет показ (TC-241).
    """
    from torrcast.parse import cluster, pick_franchise

    if not config.prowlarr_apikey:  # без Prowlarr искать нечем - это инфра-ошибка
        raise InfraError("не настроен Prowlarr: apikey пуст, перезапусти ./install.sh")
    query = args.title_query
    name, index = split_franchise_index(query)
    client = Prowlarr(config.prowlarr_url, config.prowlarr_apikey)
    progress.phase(f"поиск «{name}»")
    raw = _ask(client, name, progress)
    if not raw:
        # Ни одной строки - повод заподозрить забытую раскладку (:func:`unswap_layout`).
        # Проверка стоит один заход к индексерам и только там, где иначе был бы отказ.
        query, name, index, raw = _relayout(client, query, name, index, progress)
    mark("индексеры ответили", строк=len(raw))  # TC-108: замер
    pictures = cluster(to_releases(raw))
    # Номер в запросе - позиция во франшизе, а не в общей выдаче.
    found = pick_franchise(query, pictures)
    titled = False
    if index is not None and _season_asked(found, name, pictures):
        # 🔴 TC-363. У сериала номер это сезон, а не часть франшизы
        # (:func:`~torrcast.parse.reads_season`), и дальше по строке он идёт ровно тем же
        # путём, что и явное `sNeM`: своей сезонной машинерией, вплоть до честного
        # «раздач с сезоном N нет». Молчать о таком прочтении нельзя - номер человек
        # написал сам, и он вправе знать, чем мы его сочли.
        progress.note(f"«{name}» - это сериал: номер {index} читаю сезоном, а не частью")
        args = replace(args, query=[*name.split(), f"s{index}e1"])
        query, index = name, None
    if index is not None and not found:
        # Цифра оказалась частью названия, и обрубок увёз поиск не туда
        # (:func:`_titled_number`). Заход платится только вместо отказа.
        raw, pictures, found = _titled_number(client, query, name, raw, progress)
        # Каталог ответил: цифра - часть имени. Дальше по строке идут справка и добор, и
        # обрубок им не годится ровно так же, как не годился индексерам.
        titled = bool(found)
        if titled:
            name, index = query, None
    if worth_asking_original(found, args, config, profile):
        raw, pictures, found = _second_language(client, query, args, raw, found, progress, titled)
    elif index is None and not titled and _ceiling_hides_name(client, name, pictures, found):
        # Номер части и «цифра - часть названия» уточнению не подчиняются: запрос «имя +
        # год» строится по голому имени, и смысл номера в нём теряется.
        raw, pictures, found = _ceiling_reinforce(
            client, name, args, raw, pictures, found, progress
        )
    # Сериал есть, а раздач нужного сезона в нём нет - добрать сезонной строкой по
    # оригиналу, прежде чем честно отказать (:func:`_season_reinforce`).
    if _lacks_season(found, args):
        raw, pictures, found = _season_reinforce(client, query, args, raw, found, progress, titled)
    # Картина есть, а русской дорожки не обещает ни одна её играбельная раздача - добрать
    # точной строкой «оригинал + год» (:func:`_voice_reinforce`).
    if (voiceless := voiceless_pool(found, args, config, profile)) is not None:
        raw, pictures, found = _voice_reinforce(
            client, query, voiceless, raw, found, progress, titled
        )
    mark("поиск", найдено=len(raw))
    trace.emit("search", "query", query=query, raw=len(raw), pictures=len(pictures))
    if not raw:
        raise NotFoundError(f"по запросу «{name}» ничего не нашлось")
    if not pictures:
        raise NotFoundError(f"по запросу «{name}» ничего не разобралось")
    if not found:
        raise NotFoundError(_nothing(name, index, pictures))
    lead = _leading(found)
    if other := other_words(name, lead):
        progress.note(f"«{name}» - в каталоге это «{other}»")
    if lead is not None and lead.also:
        # Склейка картин (:func:`~torrcast.parse.glue`) - решение автоматическое, и молчать
        # о нём нельзя: человек спросил одно имя, а в меню и в отборе теперь оба.
        progress.note(f"«{lead.also}» и «{lead.title}» - одна картина, раздач {len(lead.releases)}")
    progress.phase("")
    # Номер пункта меню человек читает как номер части и им же отвечает: «Тачки 2» обязаны
    # стоять вторыми, а безномерные - после линейки (:func:`~torrcast.parse.menu_order`).
    found = menu_order(found)
    plans = [plan for plan in (_plan_for(p, args, config, profile) for p in found) if plan.ranked]
    for line in season_gaps(found, {plan.picture.key for plan in plans}, args.episode):
        progress.note(line)
    # Соседи по франшизе, до меню не доехавшие: понадобятся, если у выбранной картины
    # годного релиза не окажется вовсе (:func:`kin_line`).
    kin = _kin(_leading(found), pictures, {plan.picture.key for plan in plans})
    for plan in plans:
        plan.kin = kin
        # Опоздавший индексер (круг ушёл по кворуму, TC-118) доедет уже после меню -
        # ручку долива несёт план, а зовут её один раз и после ответа (:func:`_topup`).
        plan.late = client.late
    if not plans:  # картина есть, а раздач нужного сезона в ней нет
        want = args.episode or Episode(1, 1)
        raise NotFoundError(f"«{found[0].title}»: раздач с сезоном {want.season} нет")
    return plans


def worth_asking_original(
    found: list[Picture], args: Args, config: Config, profile: Profile = CAUTIOUS
) -> bool:
    """Стоит ли переспросить оригинальным названием (:func:`_second_language`).

    Поводов два, и оба про одно: русской выдачи не хватило.

    1. Пул ТОЩИЙ - строк выдачи меньше :data:`~torrcast.parse.THIN_POOL`. Мера считается
       строками (:attr:`~torrcast.parse.Picture.rows`), а не склеенными раздачами:
       зеркалящие индексеры несут один торрент по разу каждый, и по склеенному пулу
       порог срабатывал бы тем чаще, чем больше зеркал в круге.
    2. 🔴 TC-245. Пул НЕГОДЕН - раздач много, а играть нечем (:func:`unfit_pool`).
       Тощесть тут ничего не ловит, а беда та же самая: «Оранжевый хит сезона» приезжал
       57 русскими строками без единого HD, отбор перебирал мертвецов и сдавался, тогда
       как под ``Orange Is the New Black`` лежат 93 HD. То же у «Звёздного пути:
       Следующее поколение» (24 строки без HD против 116 со ста живыми HD). Толщина пула
       про его годность не говорит ровно ничего, и мерить надо годность.

    Второй повод считается по УЖЕ вынесенным приговорам отбора, а не заранее: пул
    прогоняется через тот же :func:`_plan_for`, что построит меню, и вопрос к нему один -
    осталось ли после отбора хоть что-нибудь, чем стоит играть. Лишнего круга на здоровой
    выдаче отсюда не берётся: годная раздача есть - второго захода нет.

    🔴 TC-262. **Цена второго повода замерена, и она мала.** Тысяча запросов в один поток:
    ОДИН ЛИШЬ второй повод (пул не тощий, но негоден) срабатывает в 16 запросах из 1000, и
    сквозной поиск на них дорожает на 1.84 с по медиане (p90 2.07 с, максимум 2.45 с) -
    пятая часть цели в :data:`~torrcast.search.GOAL` секунд. Мерено двумя способами: тем же
    поиском со старым поводом (только тощесть) в чередующихся арках и отдельным
    секундомером вокруг самого добора (медиана 2.18 с, из них справка до 1.5 с, круг по
    индексерам 0.5-1.8 с).

    Круг этот вдобавок не всегда лишний: в 7 запросах из 16 он ЗАМЕНЯЕТ собой тот, что
    иначе заплатил бы добор голоса (:func:`_voice_reinforce`) - там дельта нулевая. И
    платит он за дело: в 12 запросах из 16 после круга у картины впервые появился годный
    релиз, впустую круг ушёл ровно в одном.

    ⚠️ Сузить повод до «негоден И мёртв» (то есть требовать, чтобы живого не было даже
    среди старья) - соблазн, но замер против: одну лишнюю трату в 2.3 с это сняло бы
    вместе с ПЯТЬЮ спасёнными вечерами, где живым в пуле было только старьё («Конклав»,
    «Реальная любовь», «Крёстный отец 2», «Шёпот сердца», «Иван Васильевич меняет
    профессию»). Старьё играется, когда другого нет вовсе, - но это не повод не искать
    другого.

    Цель второй повод не роняет: единственный запрос замера, перевалив 10 с, простоял их
    на ПЕРВОМ круге. Тогда остаток цели отменял второй заход вовсе - и ровно это стоило
    картины (TC-386): с тех пор добор по второму имени бюджетом не отменяется, а идёт с
    полом в целую цель (:func:`_second_language`).

    Рядом, тем же решением «идти ли на второй круг», стоит третий повод: пул упёрся в
    потолок индексера, а картины с именем запроса в ней нет вовсе
    (:func:`_ceiling_hides_name`). Он срабатывает лишь когда эти два молчат: тощий или
    негодный пул важнее обрезанного хвоста.
    """
    from torrcast.parse import THIN_POOL

    if max((p.rows for p in found), default=0) < THIN_POOL:
        return True
    return unfit_pool(found, args, config, profile)


def unfit_pool(
    found: list[Picture], args: Args, config: Config, profile: Profile = CAUTIOUS
) -> bool:
    """Пул негоден: ни у одной картины нет раздачи, которой стоило бы играть.

    «Стоило бы» - это :func:`fitness`, то есть уже собранные факты отбора: раздача годна
    по :func:`is_candidate`, жива по :data:`ALIVE_SEEDERS` и не старьё по
    :func:`is_dated`. Ни одного такого релиза во всём пуле - и вечер по этой выдаче не
    состоится, сколько бы строк в ней ни было.
    """
    return not any(fitness(_plan_for(p, args, config, profile)) for p in found)


#: Сколько соседей по франшизе называем в строке отказа. Больше не помещается в строку, да
#: и незачем: это подсказка, а не второй список - список человек уже получит по `cast`.
KIN_SHOWN: Final = 3


def season_gaps(found: list[Picture], shown: set[str], want: Episode | None) -> list[str]:
    """Честные строки о сериалах, выпавших из меню целиком: сезона нет, а раздачи есть.

    🔴 Молчаливых отказов у нас не бывает, а тут был самый глухой из возможных: картина
    доезжает до меню живой, план по ней не строится (ни одна раздача не назвала нужный
    сезон - :meth:`~torrcast.parse.Release.covers`), и она просто исчезает из списка.
    Человек видит меню без неё и дефолт, вставший на соседа, - и ни одного слова о том,
    что произошло. Замер на «Гинтама»: картина 2018 года переживает привязку с 41
    раздачей и 33 живыми, на `s1e1` даёт ноль кандидатов, а дефолтом встаёт спин-офф
    «Gintama: 3-nen Z-gumi Ginpachi-sensei» - восьмым пунктом из восьми.

    Строка говорит ровно то, что мы знаем, и ни словом больше: сколько раздач у картины
    и какие сезоны они назвали. Обещать, что нужный сезон где-то есть, нельзя - его в
    этой выдаче действительно нет, и второй заход за ним уже сделан там, где он
    применим (:func:`_season_reinforce`).

    Молчат ли раздачи о сезонах вовсе (:func:`~torrcast.parse.seasons_named` пуста) -
    строки нет: сказать «сезона 1 нет» про имена, которые о сезонах не говорили,
    значило бы соврать. Такая картина в план и так попадает: молчание имени -
    «может быть», а не «нет».
    """
    from torrcast.parse import seasons_named

    asked = (want or Episode(1, 1)).season
    lines = []
    for picture in found:
        if picture.kind != "tv" or picture.key in shown or not picture.releases:
            continue
        if not (named := seasons_named(picture)):
            continue
        have = ", ".join(str(s) for s in named)
        lines.append(
            f"«{picture.title}» ({picture.year or '?'}): раздач {len(picture.releases)},"
            f" но сезона {asked} среди них нет - названы {have}"
        )
    return lines


def _kin(picture: Picture | None, pictures: list[Picture], shown: set[str]) -> list[Picture]:
    """Части франшизы, до меню не доехавшие, но в каталоге живые.

    Не доехать часть могла по-разному: запрос попал в свою половину двуязычной франшизы,
    или у картины не осталось ни одного релиза, прошедшего отбор. Обещать за них ничего
    нельзя - поэтому строка отказа говорит ровно «в каталоге есть», а не «возьми это».
    """
    from torrcast.parse import franchise_name, pick_franchise

    if picture is None:
        return []
    whole = pick_franchise(franchise_name(picture.title), pictures)
    return [p for p in whole if p.key not in shown and p.key != picture.key and p.releases]


def kin_line(kin: list[Picture]) -> str:
    """«в каталоге есть Тачки 2 (2011), Тачки 3 (2017) - cast тачки 2». Пусто - молчим.

    Строка-подсказка, и только: сама другую часть не запускает. Человек просил «cast
    cars», у этой картины годного релиза не нашлось - и подменить её соседкой по франшизе
    значило бы показать не то, что просили. А вот промолчать о живых соседях, отправив
    человека разбираться руками, - это скрыть то, что мы уже знаем.
    """
    if not kin:
        return ""
    names = ", ".join(f"{p.title} ({p.year or '?'})" for p in kin[:KIN_SHOWN])
    return f"в каталоге есть {names} - cast {kin[0].title.casefold()}"


def silent_swarm(
    plan: _Plan, queue: list[int], touched: int, shown: str, *, picked: int | None = None
) -> str:
    """Отказ, когда ни одна тронутая раздача не отозвалась ни метаданными, ни потоком.

    Прежде это была одна строка на все случаи - «рой у них мёртв, пиров нет». С виду
    честная, она врала чаще прежней: в замере каталога такой вердикт получили 18
    запросов из 225, и у девяти из них рой был ЖИВОЙ - просто очередь отбора кончилась
    на трёх раздачах из пятнадцати, а «пиров нет» было сказано про всю выдачу.

    Очередь отбора (:meth:`_Plan.candidates`) - это не вся выдача: мимо неё проходят
    раздачи с чужой серией, образы дисков, слишком тяжёлые. Молчание тех, кого
    потрогали, не говорит ни слова о тех, кого не трогали. Поэтому строк пять, и
    различает их не догадка, а счётчики:

    * сидов не числится ни у одной раздачи картины - пиров правда нет, и сказать так
      можно честно;
    * обход не дошёл до конца очереди: его остановил потолок фазы
      (:data:`PICK_BUDGET`), и сколько именно раздач осталось неспрошенными, строка
      называет числом (TC-435);
    * потрогали всю выдачу до последней - молчат все, кого вообще можно было спросить,
      но сиды у них числились: это молчание роя, а не пустой каталог;
    * нетронутое осталось, но всё оно непригодно по уже ИЗВЕСТНЫМ признакам - нужной
      серии нет по имени раздачи или она тяжелее потолка (TC-375): играть в нём
      нечего, и строка говорит об этом прямо, ручного выбора не предлагая. Замер по
      сохранённым прогонам: у таких отказов 132 нетронутые раздачи из 195 не
      содержали запрошенной серии вовсе;
    * нетронутое осталось, и пригодное в нём есть - про него мы не знаем ничего, и
      врать за него нельзя. Человеку остаётся ручной выбор, и строка говорит, чем
      именно он располагает.

    Числа в строке - всегда два: сколько раздач было в выдаче и сколько потрогали.
    Сиды называются как обещание индексера («числится»), а не как факт: раздача,
    которая молчит поток, показывает в выдаче сотню сидов ровно так же бодро. И
    числится максимум по ОЧЕРЕДИ, а не по всей выдаче (TC-376): иначе число ложилось
    на раздачу, которую ворота в очередь не пустили вовсе, и выглядело уликой против
    роя («числится 25, а молчат»), уликой не будучи. Исключение - первая строка: её
    «пиров нет ни у одной» сказано про всю выдачу и считается по всей выдаче.

    🔴 Ход человеку предлагает КАЖДАЯ из строк, и ходы эти разные, потому что разное
    осталось непроверенным. Там, где отбор до пригодной части выдачи не дошёл, ход -
    ручной выбор: непроверенные раздачи есть, и они рядом. Там, где потрогали всё или
    где нетронутое заведомо непригодно, ручной выбор врал бы надеждой - выбирать не
    из чего, и честный ход другой: назвать картину иначе (другой запрос собирает
    другую выдачу) или вернуться позже, когда рой проснётся. Отказ без хода - это
    тупик, в котором человек остаётся один; раньше таким был отказ по
    :data:`PEER_GRACE`, а он теперь и самый частый.

    Обход, срезанный часами, ход получает тот же - «иначе или позже», а не ручной
    выбор. Про неспрошенный хвост очереди неизвестно ничего, кроме одного: весь бюджет
    фазы ушёл на раздачи, которые стояли ВЫШЕ него и не отозвались ни одна. Указать на
    хвост номером значило бы выдать за подсказку то, чего мы не проверяли; сказать, что
    рой молчит и сколько раздач он молчит, - это факт.
    """
    total = len(plan.ranked)
    peers = max((plan.ranked[n - 1].seeders for n in queue), default=0)
    all_peers = max((release.seeders for release in plan.ranked), default=0)
    counts = f"раздач в выдаче {total}, потрогали {touched}"
    later = (
        "назови картину иначе или зайди позже - другой запрос соберёт другую выдачу, "
        "а рой может ожить"
    )
    if all_peers <= 0:
        return f"{counts} - пиров нет ни у одной, показывать нечего: {later} ({shown})"
    if touched < len(queue):
        # 🔴 TC-435. Обход кончился не очередью, а часами (:data:`PICK_BUDGET`): дальше
        # головы дело не дошло, и приписывать молчание хвосту нельзя - его не спрашивали.
        # Числа тут два, и оба свои: сколько раздач отбор взял и сколько успел потрогать.
        return (
            f"{counts} из очереди {len(queue)} - эти молчат, на остальных не хватило "
            f"времени (у потроганных числилось до {peers} сид), показывать нечего: "
            f"{later} ({shown})"
        )
    queued = set(queue)
    untouched = [r for n, r in enumerate(plan.ranked, start=1) if n not in queued]
    # Причины - в порядке суда отбора (:func:`drop_reason`): у выкинутой их бывает
    # несколько сразу, а называется та, на которой её и выкинули.
    no_episode = [r for r in untouched if misses_episode(r, plan.want)]
    heavy = [
        r
        for r in untouched
        if not misses_episode(r, plan.want)
        and over_ceiling(r, plan.runtime, plan.warn_mbit, plan.hard_mbit)
    ]
    if len(untouched) > len(no_episode) + len(heavy):
        seed = (
            f" (у потроганных числилось до {peers} сид)"
            if peers
            else " (сидов у потроганных не числилось)"
        )
        move = "выбери другой релиз" if picked is not None else "выбери руками"
        return (
            f"{counts} - эти молчат, до остальных отбор не дошёл{seed}: {move} - "
            f"cast releases <запрос>, потом cast <запрос> --release N ({shown})"
        )
    if not untouched:
        return (
            f"{counts} (все) - ни одна не отозвалась, хотя сиды у них числятся "
            f"(до {peers}), показывать нечего: {later} ({shown})"
        )
    why = [f"нужной серии нет - {len(no_episode)}"] if no_episode else []
    why += [f"тяжелее потолка - {len(heavy)}"] if heavy else []
    return (
        f"{counts} - эти молчат, а остальным играть нечего ({', '.join(why)}), "
        f"показывать нечего: {later} ({shown})"
    )


def unfit_line(plan: _Plan, drops: dict[str, int], kin: list[Picture]) -> str:
    """Отказ, когда ворота отбора не пропустили НИ ОДНОГО релиза картины (TC-432).

    Пустая очередь - это картина, в выдаче которой одни игры, книги, образы дисков или
    раздачи тяжелее потолка. Сыграть такую вместо спрошенной картины было бы подменой,
    худшим видом брака, и отказ тут честнее показа.

    Замер по корпусу-100 (515 планов, 100 запросов) говорит, чего этот отказ стоит:
    очередь пустеет у 51 плана, и у каждого из них она состояла ровно из одной раздачи
    - той самой, что проходила мимо ворот. Ни разу пустая очередь не досталась картине
    по умолчанию, ни разу не осталось без очереди всё меню запроса: человек видит
    отказ, только сам назвав пункт списка, и список у него перед глазами.

    Ход у отказа обязан быть всегда. Живых соседей по франшизе строка предлагает
    (:func:`kin_line`), а «выбери руками» не предлагает: раздачи отвергнуты по уже
    ИЗВЕСТНЫМ признакам, и номер этого не меняет. Названный человеком релиз при этом
    играет как играл: ворота на него не смотрят вовсе (:meth:`_Plan.candidates`).

    🔴 TC-447. Соседей нет - и ход всё равно есть, той же строкой. Честное «ничего не
    нашлось» тут врало бы: картина в каталоге есть, негодны её раздачи, - так и
    говорится, и следующий шаг тот же, что у молчащего роя (:func:`silent_swarm`):
    назвать картину иначе (другой запрос собирает другую выдачу) или зайти позже.

    Строка называет выдачу и причины: счёт отсева (:func:`queue_drops`) гарантирует,
    что сумма причин сходится с пулом, - ни одна раздача не пропадает молча.
    """
    why = ", ".join(f"{reason} - {count}" for reason, count in drops.items())
    line = (
        f"годного релиза нет: раздач в выдаче {len(plan.picture.releases)}, "
        f"и все до одной отсеял отбор ({why})"
    )
    if offer := kin_line(kin):
        return f"{line}\n{offer}"
    return (
        f"{line} - картина есть, а раздачи её негодны: назови её иначе или зайди позже - "
        "другой запрос соберёт другую выдачу, а годный рип может появиться"
    )


def _nothing(name: str, index: int | None, pictures: list[Picture]) -> str:
    """Почему ответа нет. Причины две, и человеку с ними делать разное.

    Прежде обе накрывались одной строкой - «такой картины во франшизе нет». Она честна
    ровно в одном случае из двух: когда франшизу нашли, а нужной части в ней не оказалось.
    В остальных выдача не содержала вообще ничего похожего на запрос («дети мужчин» - это
    ``Children of Men``, в каталоге такого имени нет вовсе), и строка про франшизу
    отправляла человека проверять номер части там, где не нашлось и самого фильма.

    Разводим по факту: спрашивали ли номер и стоит ли за ним живая франшиза.

    * франшиза есть, номера в ней нет → сколько в ней картин и что номера столько нет,
      плюс перечень того, что в ней есть, - молчаливого отказа быть не должно (TC-373);
    * во всём остальном → честное «ничего не нашлось», то есть «назови другими словами».
    """
    from torrcast.parse import pick_franchise

    whole = pick_franchise(name, pictures) if index is not None else []
    if whole:
        have = ", ".join(f"{p.title} ({p.year or '?'})" for p in whole[:5])
        more = " и другие" if len(whole) > 5 else ""
        return f"«{name}»: картин во франшизе {len(whole)}, номера {index} нет - есть: {have}{more}"
    return f"по запросу «{name}» ничего не нашлось"


def _ask(client: Prowlarr, query: str, progress: Progress) -> list[RawResult]:
    """Один запрос к индексерам; пусто - это не ошибка, а повод переспросить иначе."""
    try:
        rows = client.search(query)
    except NotFoundError:
        rows = []
    # Через getattr, а не полем: в тестах на месте клиента стоят подделки, которые
    # обещают только `search`, и требовать от них весь договор Prowlarr незачем.
    lost: tuple[str, ...] = getattr(client, "silent", ())
    reported: set[str] = getattr(client, "reported_silent", set())
    silent = [name for name in lost if name not in reported]
    reported.update(silent)
    if len(silent) == 1:
        progress.note(f"индексер {silent[0]} не ответил - выдача может быть хуже")
    elif silent:
        progress.note(f"индексеры не ответили: {', '.join(silent)} - выдача может быть хуже")
    return rows


def _no_budget(client: Prowlarr, what: str, progress: Progress) -> float | None:
    """Хватит ли остатка цели на второй заход; ``None`` - не хватит, и это сказано вслух.

    🔴 TC-228. Второй круг зовётся в 18 запросах из 100 и удваивает цену поиска: сквозной
    замер 1.93-2.39 с там, где он есть, против 0.01-0.09 с там, где его нет. Своего
    бюджета у него не было вовсе - он платил хвост первого круга плюс свой полный, и на
    хвосте Knaben (502 плюс ретрай, 10-20 с) это давало 30 с при цели в 10.

    Теперь у него есть остаток цели (:meth:`~torrcast.search.Prowlarr.spare`), и остаток
    этот честный: часы идут от начала поиска, поэтому справка на пути добора
    (:func:`~torrcast.facts.origin`) считается наравне со всем прочим, а не «бесплатно».
    Возвращается она же как потолок справки - чтобы та не съела то, на что рассчитывает
    сам круг (:data:`~torrcast.search.CIRCLE_SHARE`).

    Отказ не молчаливый: человек ждал дольше обещанного и вправе знать, что второго
    захода за него не сделали. Обещать «нашлось бы» тут нельзя - неизвестно.

    ⚠️ Охранник это заходов, у которых есть честный отступ: уточнение по потолку
    индексера, сезонная и голосовая строки, переспрос всей строкой - без них отвечает
    то, что уже найдено. Добор по второму ИМЕНИ картины сюда не приходит: у него свой
    счёт бюджета, и отмены в нём нет вовсе (:func:`_second_language`, TC-386).
    """
    spare = client.spare()
    if spare >= SECOND_LEAST:
        return min(FACTS_BUDGET, spare - CIRCLE_SHARE)
    progress.phase("")
    progress.note(f"{what} не делаю: поиск уже съел цель в {GOAL:.0f} с")
    return None


def _second_language(
    client: Prowlarr,
    query: str,
    args: Args,
    raw: list[RawResult],
    found: list[Picture],
    progress: Progress,
    titled: bool = False,
) -> tuple[list[RawResult], list[Picture], list[Picture]]:
    """Русский запрос дал пусто или тощий пул - переспросить тем же названием на латинице.

    Индексер ищет по имени раздачи, поэтому «Психо» приносит десяток русских имён, а
    сорок раздач ``Psycho.1960.*`` остаются за бортом - и человек либо смотрит 576p, либо
    (как на «Птицах») не получает ни одного годного релиза. Догадываться, что надо
    набрать латиницей, он не обязан: название на латинице лежит в первой же выдаче,
    :func:`~torrcast.parse.alt_query` его оттуда и достаёт.

    Второй заход стоит ещё одного круга по индексерам, поэтому он не всегда, а только на
    тощем пуле: на полной выдаче (порог :data:`~torrcast.parse.THIN_POOL`) поиск остаётся
    ровно таким, каким был. Цена круга - обычно 0.5-1.5 с, но ровно та же, что у первого:
    если индексер молчит, круг стоит его личного бюджета
    (:data:`~torrcast.search._QUORUM_TIMEOUT`), и тогда добор виден человеку секундами
    ожидания. Обещать «1-3 с» тут нельзя: замеры на живом стенде давали и 101.6-102.1 с -
    столько круг стоил, пока молчание одного индексера ждали общим запросом.

    🔴 TC-386. **Отмены по бюджету у добора нет.** Остаток цели (:meth:`Prowlarr.spare`)
    задавал ему потолок, а ниже :data:`~torrcast.search.SECOND_LEAST` отменял вовсе - и
    отмена стоила картины: при медленном первом круге (живой замер - Knaben 7.0 с вместо
    0.5) пул «тачек» падал с 28 раздач до 4-5, и поиск кончался отказом при живом
    каталоге. По лестнице целей «не включилось» сильнее «дольше 10 секунд», поэтому цель
    тут подчинена поиску: пол бюджета круга добора - целая цель
    (:attr:`~torrcast.search.Prowlarr.cap_floor`), а съеденный остаток не отменяет заход,
    а объявляется строкой. Остальные вторые заходы (уточнение, сезон, голос) бюджетом
    по-прежнему охраняются (:func:`_no_budget`) - у них есть честный отступ, тут его нет.

    Запросы идут последовательно, а не парой: второе имя достаётся из ПЕРВОЙ выдачи, до
    неё его просто нет. И уж точно не тем же именем: на латинском запросе оригинал из
    выдачи совпадает с самим запросом, и круг уходил целиком впустую - на живом стенде
    это стоило 102 секунды до меню.

    Строка вердикта печатается ПОСЛЕ строки того круга, о котором она говорит: ``note``
    выходит сразу, а строка фазы - только когда фазу закрыли, и в прежнем порядке «не
    беру» стояло перед «поиск… 102.1 с». Читалось это как противоречие: сначала отказ,
    а следом будто бы удавшийся второй поиск, из которого и выросло меню.

    Выдачи склеиваются, а не заменяются: русские имена несут озвучки и оригинал, по
    которому кластер и сшивает оба языка в одну картину. Если добор ничего не дал или
    картину после него не нашли, остаётся прежний результат - хуже стать не может.

    🔴 **Гейт: добор не вправе подменить картину.** Русское имя картину не определяет.
    «Восхождение» - это и фильм Шепитько 1977 года, и китайский 2019-го, подписанный
    тем же словом; оригинал ``The Climbers`` лежал прямо в русской выдаче, добор
    переспрашивал им и приносил два десятка раздач чужого кино с дорожкой ``und``.
    Раздач становилось больше, прежней проверке этого хватало, и человек молча получал
    не тот фильм. Поэтому мало «стало больше» - сверяется САМА КАРТИНА:

    * год у справки (:func:`~torrcast.facts.origin`) - она отвечает про ту картину, что
      спросили, и её слово сильнее выдачи;
    * год картины, за которой шли ДО добора, - если справки нет, годится и он;
    * франшиза - когда года не назвал никто.

    ⚠️ Год справки не в счёт, когда в запросе назван номер части: справку зовут по имени
    франшизы, и год она называет первой картины, а спрашивали другую.

    Расхождение или сомнение - добора не было. Честное «не нашлось» лучше чужого фильма,
    и это не перестраховка: подмену видно только по году, потому что кластер сшивает
    одноимённые картины в одну франшизу и «стало больше» у неё выходит честным.

    ⚠️ Право у гейта ровно одно - НЕ ДОБАВИТЬ своё. Выбросить то, что нашёл первый,
    русский запрос, он не вправе: отказ от добора возвращает прежнюю выдачу целиком
    (:func:`_as_is`), а не пустоту.

    🔴 **Привязка к картине - вторая половина того же вопроса.** Латинская раздача
    («Blue Exorcist - 01 [1080p]») не несёт ни русского имени, ни оригинала, поэтому
    кластеру нечем сшить её с русской картиной, а :func:`~torrcast.parse.pick_franchise`
    по русскому запросу до неё не достаёт. Привезённое добором уезжало в мусор ровно
    здесь: 105 раздач на 33 сида при трёх русских с нулём живых. Поэтому берутся ОБЕ
    половины - и найденная по русскому имени, и подписанная самим именем добора, - но
    вторая лишь тогда, когда за это имя ручается справка (:func:`_vouched`).

    🔴 TC-253. **Пустая русская выдача - гейт остаётся без опоры.** Сверять добор не с
    чем: картины до него не было, и :func:`same_picture` вырождается в вопрос о
    ПРОИСХОЖДЕНИИ имени, а про картину происхождение не говорит ничего. Справка же тут
    ошибается уверенно: статьи «Все мы незнакомцы» в Википедии нет, и по сходству имён
    находится «Все мы убийцы» - французская картина 1952 года, то есть ровно молчаливая
    подмена картины. Поэтому имя, лишь ПРИЗНАННОЕ похожим
    (:attr:`~torrcast.facts.Origin.guessed`), проверенным не считается. Требование одно и
    то же, есть вожак или нет (TC-359): с вожаком гейт сверяет добор со справкой, а оба
    они на этом пути про одну и ту же чужую картину, и сверка сходится на подмене:

    * справка назвала ту же картину тем же именем (:func:`~torrcast.facts.same_name`,
      «Сальтберн» и «Солтберн») - второй признак есть, идём как шли;
    * назвала другим («Все мы незнакомцы» против «Все мы убийцы») - это другая картина, и
      второго захода за ней не делаем вовсе: круг по индексерам тут не нужен, а честное
      «ничего не нашлось» не хуже чужого фильма под знакомым именем;
    * своего русского имени у статьи нет (аниме подписано латиницей) - сверить было не с
      чем, и добор берётся со строкой ровно об этом. Молча выдать его за проверенный
      нельзя: имя человек назвал сам, а картину под ним выбрала справка.

    ⚠️ Имени, за которым стоит САМА Википедия, это не касается: перенаправление «Мальчик
    и цапля» → «Мальчик и птица» - её собственное утверждение о том, что это одна вещь,
    и отметки ``guessed`` у такого паспорта нет.

    ⚠️ ``titled`` - каталог уже сказал, что хвостовая цифра это часть НАЗВАНИЯ, а не номер
    части (:func:`_titled_number`). Тогда обрубок «бен» не годится ни справке, ни строке
    добора: по нему справка отвечает про «Бен-Гур», и второй заход уходит за чужой
    картиной. Спрашиваем всей строкой - справка знает «Бен 10» и отдаёт ``Ben 10``.
    """
    from torrcast.parse import alt_query, cluster, pick_franchise, slugify

    name, index = (query, None) if titled else split_franchise_index(query)
    spare = client.spare()
    if spare >= SECOND_LEAST:
        # 🔴 TC-243. Картины не нашлось вовсе - без второго имени тут отказ, и справка
        # становится единственной опорой: ей отдаётся весь остаток цели за вычетом доли
        # круга, а не обычный потолок. Полутора секунд ей не хватает: прямая выборка
        # промолчала, а поиск Википедии и разбор описки - это ещё два-три запроса, и они
        # физически не успевают («Секреты Лос-Анджелеса» и «Реинкарнация (фильм, 2018)»
        # лежат первыми строками поиска, но приезжают уже никому не нужными).
        budget = spare - CIRCLE_SHARE if not found else min(FACTS_BUDGET, spare - CIRCLE_SHARE)
    else:
        # 🔴 TC-386. Остатка цели на добор не хватает - а добор всё равно делается. Отмена
        # тут стоила картины: на живом стенде «тачки» при медленном Knaben (7.0 с вместо
        # 0.5) теряли пул с 28 раздач до 4-5 и кончались отказом. По лестнице целей
        # «не включилось» сильнее «дольше 10 секунд», поэтому цель тут подчиняется:
        # справке - её обычный потолок, кругу добора - пол в целую цель
        # (:attr:`~torrcast.search.Prowlarr.cap_floor`), и человек читает про это строку.
        progress.phase("")
        progress.note(
            f"поиск уже съел цель в {GOAL:.0f} с - добор по «{name}» всё равно делаю: "
            "картину ищут оба её имени"
        )
        budget = FACTS_BUDGET
    pool = [r for p in found for r in p.releases] or to_releases(raw)
    lead = _leading(found)
    # Справку спрашиваем вслепую: год выдачи ей не сообщаем, иначе она подстроится под него
    # и сверять станет нечего. Тип картины - другое дело, у сериала и фильма разные статьи.
    # Сети нет - паспорт пуст, и всё дальше работает ровно так, как работало.
    kind = _asked_kind(lead, args)
    about = origin(name, series=kind, budget=budget)
    if not about and kind is not None:
        # 🔴 TC-399. Тип подсказал вожак тощего пула, и под ним справка промолчала.
        # Подсказка эта слабая: единственная строка тощего пула бывает не картиной
        # вовсе - по запросу «lain» приехал самиздатовский журнал «lainzine 1-5», он
        # назвал тип «фильм», и справка честно молчала: статьи о фильме «Lain» нет,
        # есть статья о сериале «Serial Experiments Lain». Переспрос без типа
        # (:func:`~torrcast.facts.origin_either`) спрашивает обе статьи разом и верит
        # лишь согласию - подмену он не родит, а молчание разводит.
        about = origin(name, series=None, budget=budget)
    if index is not None:
        # 🔴 Спросили номер части - год справки к делу не относится. Справку зовут по имени
        # франшизы, и отвечает она про её ПЕРВУЮ картину: у «тачек» это 2006 год, а человек
        # просил «тачки 2» - картину 2011-го. Гейт читал это расхождение как подмену и
        # выбрасывал честную выдачу; на живом стенде «тачки 2» так и не находились вовсе.
        # Название латиницей остаётся: номер части у него всё равно отрезан, и оно верное.
        about = Origin(title=about.title, name=about.name, guessed=about.guessed)
    alt = alt_query(name, pool, about.title, about.name)
    # 🔴 TC-253, TC-359. Имя добора - догадка справки, и гейт (:func:`same_picture`)
    # против неё безоружен в обоих случаях: на пустой выдаче сверять добор не с чем, а
    # с вожаком гейт сверяет добор со СПРАВКОЙ - но оба они тут про одну и ту же чужую
    # картину, и сверка сходится. Справка на этом пути ошибается уверенно: статьи «Все
    # мы незнакомцы» в Википедии нет, и по сходству имён находится «Все мы убийцы» -
    # французская картина 1952 года. Раньше эту ложь чаще прятал потолок в полторы
    # секунды; теперь справке тут отдают весь остаток цели, и доезжать она будет ЧАЩЕ.
    # Поэтому имя, лишь признанное похожим, само себя не доказывает - ему нужен второй
    # признак, и требование одно и то же, есть вожак или нет.
    hearsay = about.guessed and slugify(alt) == slugify(about.title)
    if hearsay and about.name:
        # Второй признак у справки есть, и он её же: она называет имя, под которым нашла
        # картину. То же самое имя (пусть и другой транскрипцией - «Сальтберн» и
        # «Солтберн») - подтверждение; другое слово в имени - другая картина, и второго
        # захода за ней не бывает. Отказ тут не хуже: честное «ничего не нашлось» лучше
        # чужого фильма под знакомым именем.
        if not same_name(name, about.name):
            progress.phase("")
            progress.note(
                f"по «{name}» справка нашла лишь похожее имя «{about.name}» - "
                "за чужой картиной не иду"
            )
            return _as_is(raw, found, about, progress)
        hearsay = False
    # Полное имя уже приехавшей картины может лежать только в паспорте. Короткий запрос
    # ``lain`` сам по себе выбирает журнал ``lainzine``, хотя в том же первом пуле есть
    # ``Serial Experiments Lain``. Второй круг тут ничего не находит - он лишь повторяет
    # уже имеющуюся картину другим именем. Паспортное имя применяем прямо к первому пулу,
    # но только когда оно однозначно указывает на одну картину и её год не спорит со
    # справкой. Сам короткий запрос права голоса не получает.
    first_pictures = cluster(to_releases(raw))
    passport_hits: dict[str, Picture] = {}
    for passport_name in (about.title, about.name):
        for picture in pick_franchise(passport_name, first_pictures):
            passport_hits[picture.key] = picture
    found_keys = {picture.key for picture in found}
    if len(passport_hits) == 1 and set(passport_hits) != found_keys:
        passport_found = list(passport_hits.values())
        if _vouched(passport_found, about, proven=True):
            return raw, first_pictures, passport_found
    said = _query_note(name, alt, pool, about)
    # Тем же именем второй раз ходить незачем: на «cast cars» оригинал из выдачи - «Cars»,
    # и это ещё один полный круг по всем индексерам (на живом стенде - до 102 секунд, если
    # в круге кто-то молчит) ради той же самой выдачи. Регистр и разделители имя не меняют,
    # поэтому сверяем по слагу.
    if not alt or slugify(alt) == slugify(name):
        return _as_is(raw, found, about, progress)
    # Несколько картин под одним коротким именем заполняют широкий латинский поиск
    # свежими тёзками. Если независимый паспорт назвал отсутствующий в первом круге год,
    # уточняем исходное имя им: это всё тот же один добор, но русская строка сохраняет
    # релизы с озвучкой, ради которых человек и назвал картину по-русски.
    exact_year = (
        about.year
        if index is None
        and about.year is not None
        and len(found) > 1
        and all(picture.year is None or abs(picture.year - about.year) > 1 for picture in found)
        else None
    )
    asked = f"{name} {exact_year}" if exact_year is not None else alt
    progress.phase(f"поиск «{asked}»")
    # 🔴 TC-386. Круг добора спрашивается с полом в целую цель: медленный, но живой
    # индексер (на живом стенде Knaben отвечал 7.0 с вместо 0.5) в остаток цели не
    # укладывается, и добор проходил формально, не привезя ничего, - картина пропадала
    # из каталога так же, как при отмене. На здоровом круге пол ничего не стоит:
    # кворум закрывает круг за его обычные 0.5-1.5 с.
    client.cap_floor = GOAL
    try:
        second = _ask(client, asked, progress)
        # Пока шёл второй круг, один из запросов мог завершиться уже после кворума.
        # Список картин человеку ещё не показан, поэтому готовый хвост можно включить в
        # тот же отбор без ожидания и без подмены уже прочитанного меню. Особенно важен
        # хвост первого круга: картина без латинской подписи по имени добора не найдётся.
        merged = merge(raw, second, client.late())
    finally:
        client.cap_floor = CIRCLE_SHARE
    # Круг кончился - закрываем его строку прямо здесь. Всё, что скажем дальше, это его
    # итог, а `note` печатается сразу, тогда как строка фазы ждёт закрытия фазы: без этого
    # вердикт «не беру» выходил ПЕРЕД строкой «поиск «Cars»... 102.1 с», и человек читал два
    # несвязанных сообщения как противоречие - отказ, а следом будто бы удавшийся поиск.
    progress.phase("")
    if len(merged) == len(raw):
        outcome = f"добор по «{alt}» ничего не дал"
        progress.note(f"{said}; {outcome}" if said else outcome)
        return _as_is(raw, found, about, progress)
    pictures = cluster(to_releases(merged))
    # Транслит - это сами слова запроса, чужого фильма он принести не может; оригинал из
    # справки отвечает про ту самую картину. А вот оригинал из выдачи ничем не подтверждён.
    proven = bool(about.title) or alt == about.name or alt == transliterate(name)
    # Спрашивали по-русски - им и выбираем; кластер сшил оба языка по оригиналу.
    mine = pick_franchise(query, pictures)
    # 🔴 Но сшивать бывает нечем: латинская раздача «Blue Exorcist - 01 [1080p]» не несёт
    # ни русского имени, ни поля «оригинал», и кластер оставляет её отдельной картиной, до
    # которой русский запрос не достаёт. Привезённое добором уезжало в мусор ровно на этой
    # привязке: 105 раздач на 33 сида при трёх русских с нулём живых. Поэтому картины,
    # подписанные САМИМ именем добора, берутся вдобавок к русским, а не вместо них.
    theirs = pick_franchise(f"{alt} {index}" if index else alt, pictures)
    vouched = _vouched(theirs, about, proven)
    if not (vouched or not mine):  # за это имя никто не ручается - берём лишь своё
        theirs = []
    wider = mine + [p for p in theirs if p.key not in {q.key for q in mine}]
    was = sum(len(p.releases) for p in found)
    now = sum(len(p.releases) for p in wider)
    if now <= was:
        # Прибавка не в раздачах картины, а в чужих строках выдачи: широкий пул сдвинул бы
        # нумерацию франшизы («дилижанс 1» уехал бы с 1939 года на 1936) и ничего не дал
        # взамен. Тогда второго захода как будто и не было.
        outcome = f"добор по «{alt}» новых раздач картины не дал"
        progress.note(f"{said}; {outcome}" if said else outcome)
        return _as_is(raw, found, about, progress)
    # Имя добора от справки - она отвечает про ТУ САМУЮ картину, и спор идёт лишь о том,
    # доехала ли картина нужного года. Имя из выдачи ничем не подтверждено - там гейт строг
    # и сверяет вожака: именно он станет ответом.
    after = _twin(wider, about, lead) if proven else _leading(wider)
    if not vouched and not same_picture(lead, after, about, proven):
        outcome = f"по «{alt}» приехала другая картина - остаюсь на выдаче по «{name}»"
        progress.note(f"{said}; {outcome}" if said else outcome)
        return _as_is(raw, found, about, progress)
    details = []
    if hearsay:
        # Своего русского имени у статьи нет вовсе (аниме русская Википедия подписывает
        # латиницей), и подтвердить догадку справки было нечем. Выдать её за проверенное
        # молча нельзя: человек вправе знать, на чьём слове стоит эта выдача.
        details.append(f"имя «{alt}» взято со справки, сверить было не с чем")
    details.append(f"по-русски раздач {was} - добрал по «{alt}»: стало {now}")
    progress.note("; ".join(([said] if said else []) + details))
    return merged, pictures, wider


def _asked_kind(lead: Picture | None, args: Args) -> bool | None:
    """Сериал это или фильм - для справки; ``None`` - неизвестно, и она спросит оба.

    Тип разводит статьи Википедии по разным страницам, и наугад его подсказывать нельзя:
    с ``True`` «Восхождение» уводит в чужой сериал 2024 года вместо фильма Шепитько, с
    ``False`` «Дедвуд» даёт фильм 2006 вместо сериала 2004. Поэтому источников ровно два,
    и оба говорят о картине прямо:

    * выдача первого круга - у найденной картины тип уже разобран;
    * сам запрос - серию называет человек, и «клиника s1e1» это утверждение о сериале,
      а не догадка (:attr:`Args.episode`).

    🔴 TC-243. Второй источник нужен там, где первого нет: русская выдача пуста, тип брать
    было неоткуда, и справка шла в самом слабом своём режиме - «спросить оба и поверить
    лишь согласию» (:func:`~torrcast.facts.origin_either`). Согласия у сериала с фильмом
    не бывает ровно тогда, когда одноимённый фильм существует: «Дедвуд» и «Клиника» на
    живой пробе так и теряют имя (``Deadwood``, ``Scrubs``) - а без имени второй заход
    уходит транслитом в никуда. Молчание о серии по-прежнему НЕ значит «фильм»: сериал
    зовут и без номера, поэтому там остаётся прежний осторожный режим.
    """
    if lead is not None:
        return lead.kind == "tv"
    return True if args.episode else None


def _query_note(name: str, alt: str, pool: list[Release], about: Origin) -> str:
    """Строка о том, что запрос второго захода выбрала справка, а не транслит с выдачей.

    Молчаливых подмен у нас нет, и смена ЗАПРОСА - такая же подмена, как смена картины:
    в индексер уходит не то, что человек набрал. Пока справка молчала, второй заход шёл
    транслитом («Крики и шёпот» → ``kriki i shepot``), и по одной строке фазы «поиск
    «Viskningar och rop»» не понять, откуда взялось шведское имя и почему ему верить.

    Печатается только там, где справка ДЕЙСТВИТЕЛЬНО изменила запрос: без неё второй заход
    ушёл бы другим именем (транслитом или оригиналом из выдачи). Совпали - говорить не о
    чем, и строки нет: справка тут ничего не решила.
    """
    from torrcast.parse import alt_query, slugify

    if not alt or not about.title:
        return ""
    blind = alt_query(name, pool)  # чем бы искали, не будь справки
    if not blind:
        return f"оригинал «{alt}» - по справке; без неё второго запроса не было бы"
    if slugify(blind) == slugify(alt):
        return ""
    return f"оригинал «{alt}» - по справке; без неё искал бы «{blind}»"


def _vouched(theirs: list[Picture], about: Origin, proven: bool) -> bool:
    """Ручается ли за приехавшее само имя добора: каталог подписал им эту картину.

    Гейт узнаёт «ту же вещь» по ОРИГИНАЛУ: ремейк «Корзинки фруктов» 2019 года несёт тот
    же ``Fruits Basket``, что и справка, - и это добор, а не подмена. Но у половины
    каталога поля «оригинал» нет вовсе: латинская раздача подписана одним именем, и оно
    стоит НАЗВАНИЕМ картины. Доказательство от этого не слабеет - меняется лишь место,
    где оно записано, и картина «Blue Exorcist» под именем из справки ровно так же не
    может быть однофамильцем, как и картина с таким оригиналом.

    Отсюда два условия, и оба обязательны:

    * имя добора ``proven`` - от справки или транслит запроса, а не вычитано у чужой
      раздачи (``The Climbers`` из выдачи «Восхождения» не ручается ни за что);
    * год не спорит: справка знает год, картина под этим именем называет СВОЙ, и они
      врозь - это однофамилец, и ручаться за него нельзя. Года у латинских раздач обычно
      нет вовсе (``Blue Exorcist - 01 [1080p]``), и тогда спорить не о чем.

    ⚠️ Ручательство не отменяет гейт, а даёт ему второй ключ: вожака он сверяет как
    сверял, и добор, приехавший под ИМЕНЕМ ИЗ ВЫДАЧИ, отбраковывается ровно как прежде.
    """
    lead = _leading(theirs)
    if not proven or lead is None:
        return False
    return about.year is None or lead.year is None or abs(lead.year - about.year) <= 1


def _as_is(
    raw: list[RawResult], found: list[Picture], about: Origin, progress: Progress
) -> tuple[list[RawResult], list[Picture], list[Picture]]:
    """Добора не было - остаётся то, что нашёл русский запрос. И сказать, если год спорит.

    🔴 **Право у гейта года ровно одно - не ДОБАВИТЬ своё. ОТНЯТЬ найденное русским
    запросом он не вправе.** Раньше отнимал: справка знает «Крестьян» 1935 года, в
    каталоге под этим именем лежит картина 2023-го, и живой BDRip 1080p выбрасывался
    целиком - человек читал «ничего не нашлось» при существующей картине. Честный отказ
    там, где кино есть, это не осторожность, а брак: спорить о годе можно, только пока
    есть о чём спорить, а после отказа человеку не остаётся вообще ничего.

    Расхождение при этом не замалчивается - оно печатается строкой. Слово справки против
    слова каталога решает человек: имя он назвал сам, картину под этим именем видит в
    меню вместе с её годом, а мы говорим ровно то, что знаем, и ничего за него не решаем.

    ⚠️ Спорный год - это ещё не подмена. Настоящие подмены («Восхождение» Шепитько против
    китайского ``The Climbers``) ловит гейт ДОБОРА: там чужая картина именно ДОБАВЛЯЕТСЯ
    к найденному, и вот её-то брать нельзя (:func:`_second_language`, :func:`_vouched`).
    Здесь же добавлять нечего - добора не было вовсе.

    ⚠️ Условия узкие нарочно. Строка говорится про ОДНУ картину - ту, что нашлась под этим
    именем в единственном числе. Во франшизе справка отвечает про первую часть, а в
    каталоге может лежать вторая: на «моане 2» широкий вариант этой сверки ругался бы на
    честную выдачу. Не знает года справка, картин несколько, годы сходятся - молчим.
    """
    from torrcast.parse import cluster

    if about.name and not about.title:
        for picture in found:
            if same_name(picture.title, about.name):
                picture.native = True
    stays = (raw, cluster(to_releases(raw)), found)
    if about.year is None or len(found) != 1 or found[0].year is None:
        return stays
    if abs(found[0].year - about.year) <= 1:
        return stays
    # Тот же оригинал - ремейк, а не другая картина: справка знает «Fruits Basket» 2006, в
    # каталоге ремейк 2019, и это одна и та же вещь. Чужой оригинал год по-прежнему разводит.
    if found[0].original and slugify(found[0].original) == slugify(about.title):
        return stays
    progress.phase("")  # вердикт - итог уже законченного круга, и печатается после него
    progress.note(
        f"под этим именем в каталоге лежит картина {found[0].year} года, "
        f"а не {about.year} - другой там нет"
    )
    return stays


def _ceiling_hides_name(
    client: Prowlarr, name: str, pictures: list[Picture], found: list[Picture]
) -> bool:
    """Выдача упёрлась в потолок индексера, а картины с именем запроса в ней нет.

    Третий повод второго круга рядом с тощим и негодным пулом
    (:func:`worth_asking_original`): пул густой и годный, но обрезан СВЕРХУ. Замер по
    сохранённым выдачам: 46 запросов из 100 хотя бы один индексер закрыл ровно сотней
    строк (у RuTor это его собственный потолок - с ``limit=400`` он отдаёт те же 100).
    Пока имя запроса в выдаче есть, обрезан хвост - досадно, но жить можно. А вот когда
    имени нет вовсе, потолок прячет САМУ картину: по запросу «девять» 21 раздача картины
    «Девять» (2009) лежит за сотней, каталог её не видит, и в меню человек получает
    «Девять ярдов» - при том что пул тощим не считается и ни один добор не запускается.

    Пустой ``found`` сюда не доходит: там пул тощий по определению, и первым отвечает
    добор вторым языком (:func:`_second_language`).
    """
    return (
        bool(found) and bool(getattr(client, "capped", ())) and not catalog_has_name(name, pictures)
    )


def _ceiling_reinforce(
    client: Prowlarr,
    name: str,
    args: Args,
    raw: list[RawResult],
    pictures: list[Picture],
    found: list[Picture],
    progress: Progress,
) -> tuple[list[RawResult], list[Picture], list[Picture]]:
    """Второй круг с УТОЧНЁННЫМ запросом «имя + год из справки». Не помогло - как было.

    Голое имя индексер закрыл потолком, поэтому спрашиваем точнее: год сужает выдачу
    так, что нужная картина влезает под потолок (по «девять» - сотня чужих строк, по
    «девять 2009» - 22 строки, и «Девять» (2009) среди них). Год берётся только из
    справки: выдача года не знает, а выдумывать его нечем.

    Ограждения - те же, что у добора вторым языком (:func:`_second_language`):

    * круг платится из остатка цели (:func:`_no_budget`);
    * имя, за которое справка не ручается (:attr:`~torrcast.facts.Origin.guessed`),
      ничего не решает - уточнения не бывает (гейт TC-253);
    * берутся только картины, подписанные ТОЧНО спрошенным именем
      (:func:`~torrcast.parse.catalog_has_name`), и только тех, чей год не спорит со
      справкой. Ничего такого не приехало - остаётся прежняя выдача, хуже не бывает.

    ⚠️ Тип картины справке подсказывает вожак пула - ровно как в доборе вторым языком
    (:func:`_asked_kind`). Он сосед по подстроке, а не сама картина, и без подсказки
    справка уходит в режим «оба типа, верить согласию»: по «девять» путь сериала
    притаскивает лишь похожее имя («Девять совсем незнакомых людей»), согласия с
    фильмом нет - и паспорт пуст при живой статье «Девять (фильм)». Подмену тут держит
    не тип, а гейт ниже: берутся только картины, подписанные ТОЧНО спрошенным именем,
    и только тех лет, что назвала справка.

    Строка итога - после строки самого круга (о порядке - :func:`_second_language`), и
    картины с именем запроса встают ВПЕРЕДИ соседей по подстроке: спрошенное имя точнее
    вхождения. Подмена при этом не молчаливая - она и есть содержание строки.
    """
    from torrcast.parse import cluster

    if (spare := _no_budget(client, f"уточнение по «{name}»", progress)) is None:
        return raw, pictures, found
    about = origin(name, series=_asked_kind(_leading(found), args), budget=spare)
    if about.guessed or about.year is None:
        return raw, pictures, found
    refined = f"{name} {about.year}"
    progress.phase(f"поиск «{refined}»")
    merged = merge(raw, _ask(client, refined, progress))
    progress.phase("")
    if len(merged) == len(raw):
        return raw, pictures, found
    wider = cluster(to_releases(merged))
    vouched = [
        p
        for p in wider
        if catalog_has_name(name, [p]) and (p.year is None or abs(p.year - about.year) <= 1)
    ]
    if not vouched:
        return raw, pictures, found
    kept = [p for p in found if p.key not in {q.key for q in vouched}]
    first = vouched[0]
    progress.note(
        f"по «{name}» выдача упёрлась в потолок каталога, а самой картины в ней нет - "
        f"добрал по «{refined}»: «{first.title}» ({first.year or 'год не назван'})"
    )
    return merged, wider, vouched + kept


def _lacks_season(found: list[Picture], args: Args) -> bool:
    """Сериал найден, а раздач нужного сезона в нём нет ни по одному имени.

    Ровно тот случай, где отбор упирался в «раздач с сезоном N нет»: TC-6 берёт сезон-пак,
    КОГДА он есть в выдаче, но у части западных сериалов («Ангел») русский запрос не
    приносит ни одной раздачи с нужным сезоном - пак лежит под оригинальным именем со
    строкой сезона (``Angel S01``), до которой русское слово не достаёт. Проверяем по
    именам (:meth:`Release.covers`), без похода в рой: имя пака сезон называет само.
    """
    tv = [p for p in found if p.kind == "tv"]
    if not tv:
        return False
    want = args.episode or Episode(1, 1)
    return not any(r.covers(want.season) for p in tv for r in p.releases)


def _season_reinforce(
    client: Prowlarr,
    query: str,
    args: Args,
    raw: list[RawResult],
    found: list[Picture],
    progress: Progress,
    titled: bool = False,
) -> tuple[list[RawResult], list[Picture], list[Picture]]:
    """Добрать сезон-пак сезонной строкой по оригиналу, прежде чем честно отказать.

    Родня транслит-добору (:func:`_second_language`), но повод другой: там пул тощий и
    добираем ЛЮБЫЕ раздачи, здесь пул может быть и полным, а не хватает раздач ровно
    нужного СЕЗОНА. Индексер ищет по имени раздачи, поэтому сезон-пак «Angel [S01-05]»
    русское «ангел» не приносит - его находит строка ``Angel S01`` по оригиналу.

    🔴 **Гейт против подмены.** Добор не пересобирает выдачу как попало: из ответа сезонной
    строки берутся ТОЛЬКО раздачи, у которых оригинал совпадает с оригиналом найденного
    сериала И имя которых называет нужный сезон. Без этого «Angel S01» натащил бы десяток
    чужих аниме («The Angel Next Door ... S01»): у них другой оригинал, и фильтр их
    отсекает. Сама картина после этого выбирается прежним :func:`~torrcast.parse.pick_franchise`.

    Один лишний круг по индексерам, и только когда сезона в выдаче не было вовсе
    (:func:`_lacks_season`): на счастливом пути добора нет. Ничего не подошло - остаётся
    прежний результат, дальше честное «раздач с сезоном N нет».

    🔴 Оригинала у вожака нет - опора только справка, и её ДОГАДКА
    (:attr:`~torrcast.facts.Origin.guessed`) ключом фильтра быть не вправе: имя, лишь
    признанное похожим, бывает чужой картиной под тем же русским словом, и тогда её
    раздачи сшиваются с вожаком по русскому имени - подмена мимо гейта TC-253. Догадка
    берётся ровно с тем же вторым признаком, что и в доборе вторым языком: справка сама
    называет найденную картину тем же словом, что спросили.

    ⚠️ ``titled`` - каталог уже сказал, что хвостовая цифра это часть НАЗВАНИЯ, а не номер
    части (:func:`_titled_number`). Тогда строку делить повторно нельзя: обрубок «бен»
    уводит и справку, и сезонную строку за чужой картиной, как и в доборе вторым языком
    (:func:`_second_language`).
    """
    from torrcast.parse import cluster, pick_franchise, slugify, transliterate

    name, _index = (query, None) if titled else split_franchise_index(query)
    want = args.episode or Episode(1, 1)
    lead = max((p for p in found if p.kind == "tv"), key=lambda p: len(p.releases), default=None)
    if lead is None:
        return raw, cluster(to_releases(raw)), found
    # Сезонная строка - такой же второй круг, как и добор вторым языком, и цель тратит
    # так же (TC-228). Остатка нет - честнее отказать сразу, чем платить полный круг.
    if (spare := _no_budget(client, f"добор сезона {want.season}", progress)) is None:
        return raw, cluster(to_releases(raw)), found
    # 🔴 Оригинала у вожака нет - опора только справка, и её догадка (Origin.guessed)
    # ключом фильтра быть не вправе: имя, лишь признанное похожим, бывает чужой
    # картиной под тем же русским словом. Второй признак тот же, что у гейта добора
    # (:func:`_second_language`): справка сама зовёт найденную картину тем же словом,
    # что спросили, - тогда это описка, а не чужая статья. Нет признака - остаётся
    # транслит: свои слова запроса чужой картины не принесут.
    hint = ""
    if not lead.original:
        about = origin(name, series=True, budget=spare)
        if about.title and (not about.guessed or (about.name and same_name(name, about.name))):
            hint = about.title
    base = (lead.original or hint or transliterate(name)).strip()
    season_query = f"{base} S{want.season:02d}" if base else ""
    # Тем же именем второй раз ходить незачем: если оригинала нет и транслит совпал с
    # запросом, сезонная строка это тот же круг по индексерам ради той же выдачи.
    if not base or slugify(season_query) == slugify(name):
        return raw, cluster(to_releases(raw)), found
    progress.phase(f"поиск «{season_query}»")
    extra = _ask(client, season_query, progress)
    progress.phase("")
    want_orig = slugify(lead.original or base)
    # Берём лишь раздачи ТОГО ЖЕ оригинала и ровно нужного сезона: чужое одноимённое
    # (аниме «The Angel Next Door») по оригиналу не проходит.
    keep = [
        row
        for row, rel in zip(extra, to_releases(extra), strict=True)
        if rel.original and slugify(rel.original) == want_orig and rel.covers(want.season)
    ]
    merged = merge(raw, keep) if keep else raw
    if len(merged) == len(raw):
        return raw, cluster(to_releases(raw)), found
    pictures = cluster(to_releases(merged))
    wider = pick_franchise(query, pictures)
    progress.note(f"сезона {want.season} в выдаче не было - добрал по «{season_query}»")
    return merged, pictures, wider


def voiceless_pool(
    found: list[Picture], args: Args, config: Config, profile: Profile = CAUTIOUS
) -> Picture | None:
    """Картина, у которой русская дорожка обещана только в неиграбельных раздачах.

    🔴 Русская дорожка - часть «включилось», а не предпочтение (TC-178): релиз без неё
    показу не годится, и очередь на нём не кончается, а идёт дальше. Значит картина,
    у которой дубляж лежит ровно там, куда отбор не ходит, - это не «выбор победнее»,
    а вечер, которого не будет, и повод переспросить он ровно такой же, как негодный пул
    (:func:`unfit_pool`). Живые случаи - обе «Тачки»: у первой части русские раздачи
    оказались образами DVD, у второй дубляж обещан 38-гигабайтным 4К-ремуксом и
    56-гигабайтным двухдисковым изданием, и то и другое отбор не берёт по делу.

    Условия ДВА, и второе не менее важно первого:

    * ни одна играбельная раздача русского не обещает. «Играбельная» - то же самое слово,
      что и в :func:`fitness`: годна воротами, жива и не старьё;
    * а НЕИГРАБЕЛЬНАЯ - обещает. Без этого условия круг платили бы за любую выдачу,
      чьи имена о звуке просто МОЛЧАТ, - а молчание вполне может скрывать дубляж, его
      рассудит ffprobe (:func:`sound_step` о том же). Здесь же каталог сказал прямо:
      русская дорожка у картины есть, и лежит она не там, где мы ищем.

    Спрашивается по имени раздачи (:attr:`~torrcast.parse.Release.dubbed`), то есть до
    всякого ffprobe и без единого похода в рой.

    Картина берётся не любая из найденных, а ТА, ЧТО СЫГРАЕТ (:func:`first_alive`): на
    франшизе «тачки» это первая часть, а не самая обсиженная третья, и добирать надо
    именно ей. Без оригинала или года точной строки не собрать - тогда ``None``.

    ⚠️ Сериал сюда не заходит, и это не забывчивость. «Оригинал + год» - приём КАТАЛОГА
    ПОЛНОМЕТРАЖНОГО КИНО: у фильма год стоит в имени каждой раздачи и разводит выдачу, а
    сезон-пак подписан годом первого сезона или вилкой лет, и точной строкой его не
    вытащить - его вытаскивает своя, сезонная (:func:`_season_reinforce`).

    Замер по ста сохранённым выдачам говорит и про цену: круг сработал бы в 13 из 99, а
    без сериалов - в 5 из 99. Это один лишний круг по индексерам там, где иначе показа
    нет, и платится он из остатка цели (:func:`_no_budget`), как и оба соседних добора.
    """
    plans = [
        plan
        for plan in (_plan_for(p, args, config, profile) for p in menu_order(found))
        if plan.ranked
    ]
    if not plans:
        return None
    plan = plans[first_alive(plans) - 1]
    if plan.picture.kind == "tv" or not plan.picture.original or not plan.picture.year:
        return None
    if fitness(plan, dubbed=True) or not any(r.dubbed for r in plan.ranked):
        return None
    return plan.picture


def _voice_reinforce(
    client: Prowlarr,
    query: str,
    lead: Picture,
    raw: list[RawResult],
    found: list[Picture],
    progress: Progress,
    titled: bool = False,
) -> tuple[list[RawResult], list[Picture], list[Picture]]:
    """Добрать точной строкой «оригинал + год», когда русской дорожки нет ни у кого.

    🔴 Третий добор, и повод у него свой. Тощий пул добирают вторым языком
    (:func:`_second_language`), нехватку сезона - сезонной строкой
    (:func:`_season_reinforce`), а здесь раздач может быть сколько угодно, и все они
    негодны по одной причине: играть картину не на чем по-русски.

    Живые случаи, ради которых написано, - обе «Тачки»:

    * «тачки» - все русские раздачи первой части оказались образами DVD (играть в них
      нечего), и единственным кандидатом остался англоязычный ``Cars 2006 BluRay 1080p``
      на 66 сид. Добор вторым языком сюда уже сходил и принёс ровно его;
    * «тачки 2» - кандидатами стоят 0.4-гигабайтный HDRip «фильм о фильме» и ремукс на
      27 ГБ, о звуке молчащий, а дубляж лежит в 38-гигабайтном 4К-ремуксе, который
      потолок битрейта не пускает по делу.

    Обычный запрос обеих не спасает, и вот почему: индексер отдаёт первую сотню строк
    на слово, и по слову ``Cars`` в неё попадают «Тачки 3», «Cars on the Road», гоночные
    симуляторы и десяток англоязычных рипов, а русский ``BDRip 1080p | D`` - нет. ГОД в
    строке эту сотню и разводит: по ``Cars 2006`` приезжает «Тачки / Cars (2006) BDRip
    1080p | D» на 61 сид, по ``Cars 2 2011`` - «Тачки 2 / Cars 2 (2011) BDRip 1080p» на
    11 сид. Обе - честный 1080p с дубляжом, обе легче пяти гигабайт.

    🔴 **Однофамильца этот круг не приносит.** Из ответа берутся только раздачи, у
    которых ОРИГИНАЛ совпадает с оригиналом картины, за которой шли, и год сходится с её
    годом (±1 - разница проката и производства). Новых картин добор не открывает вовсе:
    он пополняет ту, что уже нашлась, и меню от него не растёт. Ничего не подошло -
    остаётся прежняя выдача целиком.

    Один лишний круг по индексерам, и только там, где иначе показа нет: пока у картины
    есть живая раздача с обещанным русским звуком, сюда не заходят (:func:`voiceless_pool`).
    Круг платит из остатка цели, как и оба соседних добора (:func:`_no_budget`).

    ⚠️ ``titled`` - каталог уже сказал, что хвостовая цифра это часть НАЗВАНИЯ, а не номер
    части (:func:`_titled_number`). Тогда строку делить повторно нельзя: обрубок «бен»
    уводит точную строку за чужой картиной, как и в доборе вторым языком
    (:func:`_second_language`).
    """
    from torrcast.parse import cluster, pick_franchise

    name, _index = (query, None) if titled else split_franchise_index(query)
    exact = f"{lead.original} {lead.year}"
    # Тем же именем второй раз ходить незачем: это тот же круг ради той же выдачи.
    if slugify(exact) == slugify(name):
        return raw, cluster(to_releases(raw)), found
    if _no_budget(client, f"добор по «{exact}»", progress) is None:
        return raw, cluster(to_releases(raw)), found
    progress.phase(f"поиск «{exact}»")
    extra = _ask(client, exact, progress)
    progress.phase("")
    want_orig = slugify(lead.original or "")
    keep = [
        row
        for row, rel in zip(extra, to_releases(extra), strict=True)
        if rel.original
        and slugify(rel.original) == want_orig
        and rel.year is not None
        and lead.year is not None
        and abs(rel.year - lead.year) <= 1
    ]
    merged = merge(raw, keep) if keep else raw
    if len(merged) == len(raw):
        return raw, cluster(to_releases(raw)), found
    pictures = cluster(to_releases(merged))
    wider = pick_franchise(query, pictures)
    was = sum(len(p.releases) for p in found)
    now = sum(len(p.releases) for p in wider)
    if now <= was:
        # Прибавка ушла мимо картины - тогда второго захода как будто и не было.
        return raw, cluster(to_releases(raw)), found
    progress.note(
        f"«{lead.title}» по-русски есть только там, где играть нечем - "
        f"добрал по «{exact}»: раздач стало {now}"
    )
    return merged, pictures, wider


def _leading(pictures: list[Picture]) -> Picture | None:
    """Картина, за которой идут: самая полная из найденных.

    Именно она - дефолт меню и она же играет, когда терминала нет. Гейт добора смотрит на
    неё, а не на список целиком: список одноимённых картин от добора и должен пополняться,
    а вот вожак меняться не должен.
    """
    return max(pictures, key=lambda p: len(p.releases), default=None)


def _twin(pictures: list[Picture], about: Origin, before: Picture | None) -> Picture | None:
    """Кого из приехавших после добора сверять с той картиной, за которой шли.

    Не самого многолюдного: добор по русскому имени приносит ФРАНШИЗУ целиком, и вожаком
    в ней становится самая раздаваемая часть. На «cars» это «Тачки 3» (14 раздач против
    четырёх у «Тачек» 2006 года), гейт читал 2017 против 2006 как подмену и выбрасывал
    ровно ту выдачу, за которой ходил: человек оставался с одной мёртвой англоязычной
    раздачей при живых русских.

    Поэтому сверяется картина ТОГО ЖЕ ГОДА - года справки, а её нет, так года той картины,
    за которой шли. Нет среди приехавших картины нужного года - сверять идёт вожак.

    🔴 Зовётся это только на ДОКАЗАННОМ имени добора (справка), и в этом вся его
    безопасность: справка отвечает про ту самую картину, поэтому вопрос к добору один -
    доехала ли она. Имя, подобранное из выдачи, не доказывает ничего: под ним приезжает
    однофамилец («Восхождение» - и фильм Шепитько, и китайский ``The Climbers``), и там
    сверяется вожак, то есть тот, кто станет ответом.
    """
    year = about.year if about.year is not None else (before.year if before else None)
    if year is not None:
        near = [p for p in pictures if p.year is not None and abs(p.year - year) <= 1]
        if near:
            return max(near, key=lambda p: len(p.releases))
    return _leading(pictures)


def same_picture(
    before: Picture | None, after: Picture | None, about: Origin, proven: bool
) -> bool:
    """Та же ли картина возглавляет выдачу после добора.

    Год из справки - последнее слово: она отвечает про картину, которую спросили, и если
    вожак после добора другого года, значит приехал однофамилец. Справки нет - сверяем с
    годом того, за кем шли. Годов не назвал никто (сериалы часто без года) - остаётся
    франшиза: подмену она не ловит, но и врать не будет, а без года подменять по сути
    нечего - раздачи неотличимы, и кластер всё равно свёл бы их в одну картину.

    Год ± 1 - это не послабление, а разница между годом производства и годом проката:
    её раздачи путают постоянно, и на ней гейт спотыкался бы о честный добор.

    Отдельный случай - ``before is None``: русский запрос не нашёл ни одной картины, и
    сверять добор не с чем. Тогда решает происхождение названия (``proven``): справка и
    транслит говорят о том, что спросили, а вот непроверенному оригиналу из выдачи в
    пустоту веры нет - «не нашлось» честнее наугад взятого однофамильца.

    ⚠️ TC-253. Слово справки на этом пути стоит ровно столько, сколько стоит само имя, а
    сюда оно приходит уже проверенным: догадку по сходству имён («Все мы незнакомцы» →
    «Все мы убийцы») отсеивает :func:`_second_language` ДО второго захода. Здесь её
    ловить нечем - сравнить не с чем, и в этом вся суть случая.
    """
    if after is None:
        return False
    # Ремейк или переиздание с тем же оригиналом - та же картина, хоть годы и врозь:
    # справка знает «Fruits Basket» 2006, а у индексеров ремейк 2019, и это добор, а не
    # подмена. Спорит с годом только совпадение самого ОРИГИНАЛА: русское имя картину не
    # определяет, а чужой оригинал («The Climbers» против «The Ascent») год по-прежнему
    # разводит - дыру для настоящих подмен это не открывает.
    if about.title and after.original and slugify(after.original) == slugify(about.title):
        return True
    if about.year is not None and after.year is not None:
        return abs(after.year - about.year) <= 1
    if before is None:
        return proven
    if before.year is not None and after.year is not None:
        return abs(after.year - before.year) <= 1
    return franchise_key(before.title) == franchise_key(after.title)


def _plan_for(
    picture: Picture,
    args: Args,
    config: Config,
    profile: Profile = CAUTIOUS,
    runtime: float = 0.0,
) -> _Plan:
    """План по одной картине: пул релизов в порядке отбора и цель для сериала.

    ``runtime`` — настоящая длительность картины, секунды (из справки, :func:`_timed`).
    Ноль — её не назвал никто, и в знаменатель битрейта идёт прикидка
    (:data:`torrcast.stream.RUNTIME_GUESS`).
    """
    from torrcast.stream import RUNTIME_GUESS

    series = _Series(want=args.episode or Episode(1, 1)) if picture.kind == "tv" else None
    known = runtime > 0
    runtime = runtime if known else RUNTIME_GUESS.get(picture.kind, 7200.0)
    pool = picture.releases
    if series is not None:
        pool = [r for r in pool if r.covers(series.want.season)]
    # Потолок отбора - уже не потолок декодера. Тяжёлые куски перекодируются
    # (:mod:`torrcast.recode`), поэтому честный тяжёлый 1080p теперь берётся, а отбраковывает
    # только то, что перекодированием не спасти, - ``bitrate_hard_mbit``. Перекодирование
    # выключено - потолком снова становится прежний ``bitrate_warn_mbit``.
    # Выше ``bitrate_hard_mbit`` перекодированием спасается не всё, а только то, что
    # перекодируется ЦЕЛИКОМ одним прогоном (``bitrate_recode_mbit``): аниме-BD-ремуксы
    # на 28-37 Мбит/с - ровно этот случай, и отказывать им незачем.
    ceiling = config.bitrate_hard_mbit if config.recode else config.bitrate_warn_mbit
    hard = ceiling
    if config.recode:
        ceiling = max(ceiling, config.bitrate_recode_mbit)
    want = series.want if series else None
    copy_hevc = profile.plays_copy("hevc", profile.copy_depth)
    loose = gate_open(pool, runtime, ceiling, want, hard_mbit=hard, copy_hevc=copy_hevc)
    # Ворота последней надежды открываются при двух условиях сразу, и оба - не про пул.
    # Первое: перекодирование включено. Играть HEVC умеет ровно сплошной перекод, и без
    # него пускать такой релиз в очередь значило бы обещать показ, которого не будет.
    # Второе: HEVC для ЭТОГО приёмника и правда тяжёлый путь - спрашивается там же, где
    # об этом спрашивают показ и прогрев (:func:`torrcast.stream.recodes_whole`), чтобы
    # отбор не судил по чужим числам. Приёмник, который берёт HEVC копией, в последней
    # надежде не нуждается вовсе: у него это обычный релиз, и место ему в воротах,
    # которым передан ответ профиля, а не здесь.
    heavy_hevc = recodes_whole("hevc", profile.copy_depth, profile)
    last = (
        config.recode
        and heavy_hevc
        and last_hope(pool, runtime, ceiling, want, loose, hard, copy_hevc=copy_hevc)
    )
    ranked = rank_releases(
        pool,
        runtime,
        ceiling,
        want=want,
        loose=loose,
        hard_mbit=hard,
        last=last,
        copy_hevc=copy_hevc,
    )
    return _Plan(
        picture=picture,
        ranked=ranked,
        runtime=runtime,
        runtime_known=known,
        off_season=len(picture.releases) - len(pool),
        warn_mbit=ceiling,
        series=series,
        recode_at=config.recode_at_mbit if config.recode else 0.0,
        loose=loose,
        last_resort=last,
        copy_hevc=copy_hevc,
        hard_mbit=hard,
        asked_series=args.episode is not None,
    )


def _timed(
    plan: _Plan, facts: Facts | None, args: Args, config: Config, profile: Profile = CAUTIOUS
) -> _Plan:
    """Пересобрать план на НАСТОЯЩЕЙ длительности картины, как только её назвала справка.

    🔴 TC-185. Битрейт релиза отбор считает делением размера раздачи на длительность
    (:func:`bitrate_of`), а длительности до ffprobe он не знает и берёт прикидку «фильм
    это два часа». Прикидка не нейтральна: у «Интерстеллара» (2 ч 49 мин) она завышает
    битрейт в 1.41 раза, у «Форреста Гампа» (2 ч 22 мин) — в 1.18, и честный 1080p,
    лежащий под потолком, отсекался потолком, которого он не переходил. Молча: отказ
    арифметики строки не печатает.

    Потолки при этом не двигаются ни на знак — чинится ЗНАМЕНАТЕЛЬ.

    Лишнего запроса тут нет ни одного: хронометраж уже приехал в справке к меню
    («2 ч 49 мин» печатается рядом с рейтингом), и спрашивается он у той же
    :class:`~torrcast.facts.Facts`, которую меню уже дождалось. Поэтому и зовётся это
    ПОСЛЕ меню: до меню справки ещё нет, а ждать её на пути старта нельзя.

    Справка молчит (нет статьи, нет сети, картины нет в выгрузке) — план остаётся на
    прикидке, и это решение не молчаливое: событие ``runtime`` уходит в недельный след
    (:func:`torrcast.trace.emit`) с тем же числом, которым считался битрейт.
    """
    fact = facts.get(plan.picture.title, plan.picture.year) if facts is not None else Fact()
    minutes = minutes_of(fact.runtime)
    if minutes <= 0:
        trace.emit(
            "select", "runtime", secs=round(plan.runtime), src="guess", title=plan.picture.title
        )
        return plan
    fresh = _plan_for(plan.picture, args, config, profile, runtime=minutes * 60.0)
    fresh.kin = plan.kin
    trace.emit(
        "select",
        "runtime",
        secs=round(fresh.runtime),
        src="facts",
        title=plan.picture.title,
        was=round(plan.runtime),
    )
    return fresh


def _topup(
    plan: _Plan,
    args: Args,
    config: Config,
    profile: Profile,
    progress: Progress,
    menu: frozenset[str] = frozenset(),
) -> _Plan:
    """Долить опоздавший индексер в пул УЖЕ выбранной картины (TC-118).

    🔴 Круг индексеров уходит по кворуму (:data:`~torrcast.search.QUORUM_INDEXERS`), и
    опоздавший доезжает, когда список картин человек уже прочитал. Место вызова выбрано
    ровно по одному правилу: **менять то, на что человек смотрит, нельзя**. Поэтому
    долив зовётся ПОСЛЕ ответа на меню, и права у него ровно одно - пополнить пул той
    картины, которую и выбрали:

    * список картин, их порядок и дефолт долив не трогает вовсе - меню уже напечатано,
      и подменить в нём номер или первую живую часть значило бы соврать задним числом;
    * картина, которой в меню не было, из долива в него не попадает - её и предложить
      уже некому. Но и молча она не пропадает (TC-238): её называет одна честная
      строка (:func:`_foreign_note`), как и всякое авто-решение;
    * а вот верх ОТБОРА долив поменять вправе - выбирали картину, а не раздачу, - но
      молча этого не делает: строка ниже называет и опоздавшего, и то, что верх другой.

    Пул при этом только растёт: старые раздачи остаются теми же объектами, и прогрев,
    пущенный под меню, переезжает на новые номера (:meth:`_Bench.reorder`), а не
    выбрасывается. Долив пустой или ничего не добавил - план возвращается прежним.
    """
    from torrcast.parse import cluster

    rows = plan.late()
    if not rows:
        return plan
    extra = to_releases(rows)
    have = {r.magnet for r in plan.picture.releases}
    # Кластер тут - судья принадлежности, а не сборщик: спрашиваем у него, какие из
    # приехавших раздач относятся к ТОЙ ЖЕ картине, и берём только их. Сам пул собираем
    # заменой поля, чтобы прежние релизы остались прежними объектами - по ним прогрев и
    # ищет своё новое место.
    grown = next(
        (p for p in cluster([*plan.picture.releases, *extra]) if p.key == plan.picture.key), None
    )
    mine = {r.magnet for r in grown.releases} if grown is not None else set()
    add = [r for r in extra if r.magnet in mine and r.magnet not in have]
    # Чужая картина (TC-238): в меню её внести нельзя, но и пропасть молча она не
    # должна - строка печатается независимо от того, был ли долив в свою картину.
    _foreign_note([r for r in extra if r.magnet not in mine], menu, progress)
    if not add:
        return plan
    fresh = _plan_for(
        replace(plan.picture, releases=[*plan.picture.releases, *add]), args, config, profile
    )
    if not fresh.ranked:  # отнимать уже показанное долив не вправе
        return plan
    fresh.kin = plan.kin
    who = ", ".join(sorted({r.indexer for r in add if r.indexer})) or "опоздавший индексер"
    changed = bool(plan.ranked) and fresh.ranked[0].magnet != plan.ranked[0].magnet
    progress.note(
        f"«{who}» доехал после списка: раздач {len(fresh.picture.releases)}"
        f" вместо {len(plan.picture.releases)}" + (", верх отбора другой" if changed else "")
    )
    return fresh


def _foreign_note(foreign: list[Release], menu: frozenset[str], progress: Progress) -> None:
    """Честная строка про картину опоздавшего индексера, которой в меню не было (TC-238).

    Меню напечатано и отвечено, поэтому внести туда новую картину долив не вправе
    никогда - но молчаливых пропаж у нас нет: человек узнаёт, что опоздавший источник
    привёз ещё одну картину, и что в отбор она не пойдёт. Раздачи картин, которые в
    меню ЕСТЬ (``menu`` - ключи показанного списка), строки не получают: сказать про
    них «в списке её не было» значило бы соврать.
    """
    from torrcast.parse import cluster

    guests = [p for p in cluster(foreign) if p.key not in menu]
    if not guests:
        return
    who = (
        ", ".join(sorted({r.indexer for p in guests for r in p.releases if r.indexer}))
        or "опоздавший индексер"
    )
    names = ", ".join(f"«{p.title}» ({p.year or '?'})" for p in guests[:KIN_SHOWN])
    if len(guests) > KIN_SHOWN:
        names += f" и ещё {len(guests) - KIN_SHOWN}"
    progress.note(
        f"«{who}» доехал после списка: привёз {names} - "
        + (
            "в списке её не было, в отбор она не пойдёт"
            if len(guests) == 1
            else "в списке их не было, в отбор они не пойдут"
        )
    )


def _nothing_late() -> list[RawResult]:
    """Долива нет: план собран не поиском (тесты, отладочные ручки) - доливать нечего."""
    return []


@dataclass(slots=True)
class _Plan:
    """Что покажем по одной картине: пул релизов и, для сериала, нужная серия.

    План строится на **все** картины франшизы ещё до вопроса — иначе прогрев под меню
    невозможен: греть надо то, что человек, скорее всего, выберет.
    """

    picture: Picture
    ranked: list[Release]
    runtime: float
    #: Потолок ОТБРАКОВКИ, Мбит/с: выше него релиз не берём вовсе (см. :func:`_plan_for`).
    warn_mbit: float
    series: _Series | None = None
    #: Порог ПЕРЕКОДИРОВАНИЯ, Мбит/с: выше него куски перекодируются, а релиз годен.
    #: Ноль - перекодирование выключено, и тогда отбраковка и порог это одно число.
    recode_at: float = 0.0
    #: Потолок для тех, кого сплошной перекод не спасает, Мбит/с: выше него релиз годен
    #: только при перекоде ЦЕЛИКОМ и только пока кадр не выше 1080p
    #: (:attr:`torrcast.state.Config.bitrate_hard_mbit`). Ноль - ступени нет.
    hard_mbit: float = 0.0
    #: Ворота отбора открыты: живых именных кандидатов у картины нет (:func:`gate_open`),
    #: и молчаливые имена идут в очередь наравне с именными.
    loose: bool = False
    #: Ворота последней надежды открыты: живого кандидата с нужной серией нет ВООБЩЕ
    #: (:func:`last_hope`), и в очередь пускается названный HEVC — играть его будет
    #: сплошной перекод. Перекодирование выключено — ворота закрыты всегда.
    last_resort: bool = False
    #: HEVC объявлен своим ресивером как играющий копией через наш HLS.
    copy_hevc: bool = False
    #: Другие части той же франшизы, до меню не доехавшие: их нет в списке картин, но в
    #: выдаче они есть и раздачи у них живые. Нужны одной строке отказа (:func:`kin_line`).
    kin: list[Picture] = field(default_factory=list)
    #: Запрос назвал СЕРИЮ (``s1e1``), а не просто имя. Тогда тип сказан вслух, и дефолт
    #: обязан считаться среди сериалов (:func:`asked_kind`), а не среди тёзок-полнометражек.
    asked_series: bool = False
    #: :attr:`runtime` — настоящая длительность из справки, а не прикидка (:func:`_timed`).
    runtime_known: bool = False
    #: Раздачи картины, не доехавшие даже до :attr:`ranked`: нужного сезона в них нет по
    #: их же именам. Нужны счёту отсева (:func:`queue_drops`), чтобы он сходился с пулом.
    off_season: int = 0
    #: Выдача опоздавших индексеров: круг ушёл по кворуму, а эти доехали позже (TC-118).
    #: Зовётся ОДИН раз и только после ответа на меню - :func:`_topup`.
    late: Callable[[], list[RawResult]] = _nothing_late

    def candidates(self, args: Args) -> list[int]:
        """Очередь релизов: прошедшие ворота, в порядке ранжира - **все, сколько есть**.

        Обрезать очередь тут больше нечем: сколько раздач успеет разобрать показ, решают
        не эти строки, а :meth:`_Bench.resolve` — по приговорам (:data:`MAX_TRIES`) и по
        часам (:data:`PICK_BUDGET`). Пока очередь резалась тремя номерами, отбор сдавался
        со словами «годного релиза нет» ровно тогда, когда рядом в ней стояли живые: в
        замере на тысяче запросов перепроверка в один поток оживляла шесть картин из
        восьми, у которых три раздачи подряд промолчали пирами.

        🔴 TC-432. Ворота проходят ВСЕ, включая верх ранжира. До сих пор он вставал в
        очередь безусловно, и мимо ворот проходил ровно он: «Ведьмак 3: Дикая Охота»
        (игра, ``kind=other``, 35.6 ГБ) стояла единственным кандидатом своей картины на
        запрос «ведьмак s2e4», а «Ван Пис - 923» с нулём сидов - на запрос s1e1. Это
        подмена картины, худший вид брака: человек просит серию сериала, а наверх
        очереди встаёт игра. Ворота при этом отсекают правильно (замер TC-377 по тому
        же корпусу: ложных отсевов ноль) - работать оставалось ровно одно место.

        Безусловной остаётся одна очередь - названная человеком (``--release N``): это
        его явное решение, а не подмена, и судить его воротами нечего.

        Огрызков в очереди нет вовсе (:func:`misses_episode`): тратить на них метаданные
        по DHT незачем — раздача уже своим именем сказала «нужной серии тут нет», и это
        5-40 с за заранее известный отказ. Отбраковка не молчаливая: кого выкинули,
        печатает :attr:`skipped`.

        При открытых воротах (:attr:`loose`) в очередь идут и молчаливые имена: у
        картины иначе нет ни одного живого кандидата, а судить молчание всё равно
        может только ffprobe — и он его тут же и судит.

        При открытых воротах последней надежды (:attr:`last_resort`) к ним добавляется
        названный HEVC до 1080p включительно (:func:`hevc_hope`): играть его будет
        сплошной перекод, и берётся он ровно тогда, когда живого кандидата с нужной
        серией нет вообще.

        Очередь может оказаться пустой - и это ответ, а не повод подставить отсеянное:
        отказ с перечнем причин печатает :meth:`_Bench.resolve` (:func:`unfit_line`).
        """
        if args.release is not None:
            if not 1 <= args.release <= len(self.ranked):
                # 🔴 TC-446. Номер относится к ЭТОЙ картине - той, что человек выбрал в
                # меню или назвал флагом --pick, - и отказ её называет. Безымянный счёт
                # читался как счёт всей выдачи, а считался по одной картине из неё.
                raise NotFoundError(
                    f"у «{self.picture.title}» релизов {len(self.ranked)}, "
                    f"номера {args.release} нет"
                )
            return [args.release]
        queue = [
            n
            for n, r in enumerate(self.ranked, start=1)
            if is_candidate(
                r,
                self.runtime,
                self.warn_mbit,
                self.loose,
                self.hard_mbit,
                self.last_resort,
                self.copy_hevc,
            )
            and not misses_episode(r, self.want)
        ]
        return queue + self._dubbed_tail(queue)

    def _dubbed_tail(self, queue: list[int]) -> list[int]:
        """Хвост очереди: русские раздачи, которых ворота отбора не пустили внутрь.

        🔴 TC-195. Ворота (:func:`is_candidate`) судят ИМЯ раздачи, и раздача, чьё имя
        молчит о качестве, кандидатом не становится, пока у картины есть живой ИМЕННОЙ
        кандидат (:attr:`loose`). Ровно на этом вечер владельца и кончился: у «Тачек»
        2006 года очередь состояла из ОДНОГО релиза - названного 1080p H.264 на 66 сид,
        - его рой промолчал, и показ отказал строкой «раздач в выдаче 5, потрогали 1 -
        до остальных отбор не дошёл». А среди четырёх нетронутых лежали две с дубляжом
        (4.4 ГБ на 3 и на 1 сид), которых никто не спрашивал.

        Отказ был честен про то, что потрогали, и бесполезен для человека: картина в
        каталоге есть, русская дорожка у неё есть, а на экране пусто.

        Хвост, а не послабление ворот, - и это главное. Порядок головы очереди не
        меняется ни на знак: дефолт тот же, запасные те же, и на картине, где голова
        играет, хвоста не видно вовсе - до него просто не доходят. Значит и время до
        картинки прежнее. Меняется ровно один случай: голова кончилась, а показывать
        нечего.

        В хвост идёт только то, у чего РУССКАЯ дорожка названа именем
        (:attr:`~torrcast.parse.Release.dubbed`): молчание про качество мы простить
        готовы - его рассудит ffprobe, - а молчание про язык прощать нечему, иначе
        хвост натащил бы англоязычных рипов туда, где человек ждёт перевод. Потолок
        битрейта и образы дисков хвост не двигает: там ресивер встаёт и играть нечего.
        """
        seen = set(queue)
        return [
            n
            for n, r in enumerate(self.ranked, start=1)
            if n not in seen
            and r.dubbed
            and not misses_episode(r, self.want)
            and is_candidate(
                r, self.runtime, self.warn_mbit, True, self.hard_mbit, True, self.copy_hevc
            )
        ]

    @property
    def want(self) -> Episode | None:
        """Нужная серия, если картина — сериал; у фильма серии нет."""
        return self.series.want if self.series else None

    @property
    def skipped(self) -> list[Release]:
        """Раздачи, отбракованные до каста: нужной серии в них нет по их же именам."""
        return [r for r in self.ranked if misses_episode(r, self.want)]


@dataclass(slots=True)
class _Series:
    """Серии выбранной раздачи: файлы → ``sNeM``, нужный файл и кэш для состояния.

    Пак это или один сезон — решают ФАЙЛЫ, а не имя раздачи: сколько сезонов нашлось в
    путях, столько и будет в списке, и прыжок `s2e5` внутри пака обойдётся без поиска.
    """

    want: Episode
    files: list[EpisodeFile] = field(default_factory=list)

    def choose(self, release: Release, files: list[TorrFile]) -> TorrFile:
        """Файл нужной серии; такой серии в раздаче нет — честная строка со списком."""
        self.files = map_episodes(files, release.season)
        found = next((f for f in self.files if f.at == self.want), None)
        if found is None:
            raise NotFoundError(self._miss_reason(release))
        return next(f for f in files if f.index == found.index)

    def _miss_reason(self, release: Release) -> str:
        """Текст отказа: серии правда нет — или раздача считает в ДРУГОЙ системе.

        🔴 TC-182. У одного сериала сосуществуют ДВЕ нумерации: у «Гинтамы» 38 раздач
        подписаны сезонами S05-S10 (нумерация стриминга), а куски RuTor — сквозным
        счётом через весь сериал (``[01-201]``, ``[202-252]``, ``[253-265]``). Это
        РАЗНЫЕ номера: s5e1 по-стриминговому живёт где-то внутри сквозного 202-252, а
        вычислить, где именно, нельзя честно — границ сезонов не назвало ни одно имя,
        и любой пересчёт был бы выдумкой.

        Признак системы — настоящий и лежит в имени раздачи: сезон она либо назвала
        (:attr:`~torrcast.parse.Release.season` / :attr:`~torrcast.parse.Release.seasons`),
        либо перечислила серии, не назвав сезона, — тот же признак, по которому
        сквозную линейку отличает :func:`torrcast.parse._run_span`. Раздача со сквозным
        счётом на просьбу о пятом сезоне не должна отвечать «серии нет»: серия там,
        скорее всего, ЕСТЬ — под сквозным номером, — и прежний ответ был неправдой
        дважды: и про наличие, и про причину. Поэтому здесь называются ОБЕ системы.
        """
        if (
            self.want.season > 1
            and release.episodes
            and release.season is None
            and not release.seasons
        ):
            span = f"{release.episodes[0]}-{release.episodes[-1]}"
            return (
                f"нумерации разные: {self.want} - это счёт по сезонам, а раздача считает "
                f"серии насквозь через весь сериал ({span}), не называя сезонов "
                f"({self.summary()}) - нужна раздача, подписанная сезоном: "
                "cast <запрос> --release N"
            )
        return (
            f"серии {self.want} в этой раздаче нет ({self.summary()}) - "
            "возьми другую раздачу: cast <запрос> --release N"
        )

    @property
    def table(self) -> list[list[int]]:
        """Список серий для состояния: по нему идут автопереход и прыжки."""
        return [[f.season, f.episode, f.index] for f in self.files]

    def summary(self) -> str:
        """«серий 10: s1e1…s1e10», для пака — ещё и диапазон сезонов."""
        if not self.files:
            return "серий не нашлось"
        seasons = {f.season for f in self.files}
        span = f"сезоны {min(seasons)}-{max(seasons)} · " if len(seasons) > 1 else ""
        return f"{span}серий {len(self.files)}: {self.files[0].at}...{self.files[-1].at}"


def _continue(config: Config, key: str, entry: Entry, args: Args, clock: _Clock) -> int | None:
    """Продолжение по сохранённому выбору. ``None`` — состоянием не обойтись,
    дальше идёт обычный путь с поиском и меню.

    Сериал вопросов не задаёт вовсе: релиз, дорожка и список серий уже выбраны, а
    какую серию и с какого места играть — записано. Фильм спрашивает ровно одно.

    ``--voice`` поднимает раздачу ещё до показа (:func:`_revoice` читает её дорожки), и
    хозяин у неё — этот вызов, пока показ её не принял. Принимает он её ровно в одном
    случае: юнит поднялся и играет ТОТ ЖЕ магнит (:attr:`_Voiced.handed`) — дальше её
    уберёт сам юнит. Все прочие исходы — сухой прогон, Ctrl-C на вопросе, «серии тут нет»,
    «смотреть сначала? нет», не поднявшийся юнит — оставляли раздачу навсегда, и убирает
    её теперь ``finally``, по её собственному хэшу.
    """
    own = _Voiced()
    try:
        if not entry.serial:  # фильм (в том числе ошибочно записанный сериалом) - вопрос один
            if not entry.resumable:
                return None  # продолжать нечего - озвучку выберет обычный путь, по дорожкам
            entry = _voiced(config, entry, args, own)
            code = _resume(config, key, entry, clock=clock, dry=args.dry)
            own.handed = not args.dry  # показ пошёл и раздача та же - дальше она его
            return code
        entry = _voiced(config, entry, args, own)
        if args.episode is not None:  # `cast киберпанк s2e5` - прыжок по кэшу раздачи
            jumped = entry.jump(args.episode.season, args.episode.episode)
            if jumped is None:
                return None  # серии в этой раздаче нет - честно идём искать релиз сезона
            code = _launch(config, key, jumped, _about(jumped), clock, args.dry)
            own.handed = not args.dry
            return code
        if entry.done:  # конец раздачи: сама собой следующая серия не появится
            print(f"«{entry.title}» - {entry.label} была последней в раздаче")
            if ask_line("Смотреть сначала? [Да/нет]")[:1] in {"н", "n"}:
                return EXIT_OK
            first = entry.episodes[0]
            entry = entry.jump(first[0], first[1]) or entry
        code = _launch(config, key, entry, _about(entry), clock, args.dry)
        own.handed = not args.dry
        return code
    finally:
        own.drop(config)


def _remembered(state: State, key: str, found: tuple[str, Entry] | None) -> str:
    """Озвучка, которую пользователь выбирал для этой картины.

    Смотрим по каноническому ключу картины — под ним показ и пишет запись. Запись,
    найденную по тексту запроса (:meth:`State.find`), берём запасным вариантом: у
    одной картины в состоянии могут лежать записи разных запросов («moana» и «моана»),
    и память озвучки не должна зависеть от того, как её позвали в прошлый раз.
    """
    entry = state.get(key) or (found[1] if found is not None else None)
    return entry.voice if entry is not None else ""


@dataclass(slots=True)
class _Voiced:
    """Раздача, поднятая ради ``--voice``: у неё есть хозяин, пока её не принял показ.

    Дорожки читаются из потока, а поток начинается с раздачи в TorrServer — и раздача
    эта переживает наш процесс: живёт она в чужой памяти до перезапуска службы. Пока
    хозяина у неё не было, каждый вызов с ``--voice`` оставлял по раздаче навсегда, в том
    числе ``--dry``, который заведён ровно затем, чтобы следов не оставлять.

    Хозяин один и меняется один раз: если показ поднялся на том же магните, раздача
    достаётся юниту (:attr:`handed`), и убирает её он (:func:`_cmd_worker`). Во всех
    остальных исходах её убирает :meth:`drop` — по СВОЕМУ хэшу, чужого не касаясь.
    """

    torrent_hash: str = ""
    #: Показ принял эту раздачу: юнит играет тот же магнит и уберёт её за собой сам.
    handed: bool = False

    def drop(self, config: Config) -> None:
        """Убрать, если так и не пригодилась. Повторный вызов и пустой хэш безвредны.

        Кроме одного случая: ту же раздачу держит живой показ - ``cast --voice`` на
        играющий фильм поднимает её же (``add`` идемпотентен), и снос выдернул бы её
        из-под экрана (:func:`_held_by_show`). Уберёт её хозяин показа сам.
        """
        if self.handed or not self.torrent_hash:
            return
        torrent_hash, self.torrent_hash = self.torrent_hash, ""
        if _held_by_show(torrent_hash):
            return
        with contextlib.suppress(TorrcastError):
            _release_torrents(config, [torrent_hash])


def _voiced(config: Config, entry: Entry, args: Args, own: _Voiced | None = None) -> Entry:
    """Запись с учётом ``--voice``; без флага — она же, не тронутая и без похода в рой.

    Флага нет — не читаем ничего: этот путь тем и хорош, что обходится состоянием.
    ⚠️ Звать только тогда, когда запись действительно пойдёт в показ. Живая грабля:
    вызов до проверки «есть ли что продолжать» лез в TorrServer за раздачей,
    которую никто играть не собирался, и падал на её магните.

    ``own`` — хозяин поднятой раздачи (:class:`_Voiced`): в списке службы её не видно, и
    убрать её можно только по хэшу, который знает он. Хозяина не назвали — раздача
    убирается тут же, на выходе: бесхозной она не остаётся ни в одном случае.
    """
    if args.voice is None:
        return entry
    if own is not None:
        return _revoice(config, entry, args, own)
    orphan = _Voiced()
    try:
        return _revoice(config, entry, args, orphan)
    finally:
        orphan.drop(config)


def _revoice(config: Config, entry: Entry, args: Args, own: _Voiced) -> Entry:
    """``--voice`` поверх сохранённого выбора: перечитать дорожки раздачи и взять нужную.

    Нужно ровно для сериала и продолжения: там показ идёт по записи состояния и потока
    никто не читает — ни номеров дорожек, ни подписей взять неоткуда. Платим за это
    метаданными раздачи и одним ffprobe (секунды, с живым прогрессом), и платим только
    когда флаг назван: счастливый путь этой цены не видит.

    Состояние отсюда не пишется: выбор уезжает в запись показа (:func:`_launch`) вместе
    с позицией и серией. Так у ``--dry`` не остаётся следов, а память не переписывается
    показом, который не начался.

    ⚠️ Следов не остаётся и в TorrServer: поднятая здесь раздача записывается хозяину
    (``own``) сразу же, той же строкой, что и поднимается. Раньше её не убирал никто -
    ни при сухом прогоне, ни когда показ до старта так и не доходил.
    """
    torrserver = TorrServer(config.torrserver_url)
    with Progress() as progress:
        progress.phase("дорожки")
        own.torrent_hash = torrent_hash = torrserver.add(entry.magnet)
        torrserver.wait_files(torrent_hash, timeout=META_BUDGET)
        media = probe(torrserver.stream_url(torrent_hash, entry.file_idx), timeout=PROBE_BUDGET)
        progress.phase("")
    entry.audio, entry.voice = pick_voice(media, args, entry.voice)
    return entry


def _about(entry: Entry) -> str:
    """Строка показа по записи состояния: «Киберпанк» · s1e2 · дорожка 1 · с 0:03:20."""
    voice = entry.voice or f"дорожка {entry.audio + 1}"
    parts = [f"«{entry.title}»", entry.label, entry.quality, voice]
    if entry.pos > 0:
        parts.append(f"с {_hms(entry.pos)}")
    return " · ".join(filter(None, parts))


@dataclass(slots=True)
class _Prep:
    """Подготовка одного релиза целиком в фоне: раздача, файл, дорожки.

    Это и есть прогрев под меню. Фазы идут своим ходом в отдельном потоке, а показ
    спрашивает только результат — поэтому 17 секунд ffprobe на «Моане 2» уходят из
    критического пути в паузу между вопросами.

    Каждая фаза имеет **бюджет**: не уложилась — это не «зависло насмерть» без единого
    слова, а :attr:`error` и следующий релиз в очереди.
    """

    number: int
    release: Release
    torrent_hash: str = ""
    #: Прогрев оказался ненужным: показ ушёл на другую картину или другой релиз. Такая
    #: раздача убирается из TorrServer сразу - иначе два лишних торрента тянули бы кэш
    #: и полосу у самого показа.
    dropped: bool = False
    video: TorrFile | None = None
    files: list[TorrFile] = field(default_factory=list)
    media: Media | None = None
    error: str = ""
    #: Отказ, которым кончилась подготовка (``error`` - его строка для человека).
    #: Нужен именно типом: «умерло собственное звено» опознаётся по классу
    #: исключения, а не по префиксу текста - текст пишется языком зрителя и правится.
    failure: TorrcastError | None = None
    #: Спрашивать рой по ПОЛНЫМ бюджетам фазы, без отсрочек на первый контакт
    #: (:data:`PEER_GRACE`, :data:`SWARM_GRACE`). Отсрочки существуют, чтобы не занимать
    #: место в очереди безнадёжной раздачей, и стоит их ошибка ровно этого места - пока
    #: в очереди есть кого спросить. Когда спрашивать больше некого, платить отсрочкам
    #: нечем: терпеливо спрашивается один-единственный релиз (:meth:`_Bench._recheck`).
    patient: bool = False
    contact_wait: ContactWait | None = None
    phase: str = "очередь"
    started: float = field(default_factory=time.monotonic)
    meta: float = 0.0
    read: float = 0.0
    ready: threading.Event = field(default_factory=threading.Event)

    @property
    def want(self) -> TorrFile:
        if self.video is None:
            raise InfraError("файл раздачи не выбран")
        return self.video

    @property
    def found(self) -> Media:
        if self.media is None:
            raise InfraError("поток не прочитан")
        return self.media

    @property
    def timing(self) -> str:
        return f"метаданные {self.meta:.1f} с, дорожки {self.read:.1f} с"


def _turned_down(judged: dict[int, str], number: int, why: str) -> None:
    """Релиз отвергнут: приговор запомнить и положить в след - ровно один раз на решение.

    🔴 TC-194. Единственное место, где рождается запись ``select/drop``, и заведено оно
    затем, чтобы отказ не мог напечататься мимо следа. Так и было: очередь отбора
    (:meth:`_Bench.resolve`) писала запись, а проверка честности (:meth:`_Bench._honest`)
    печатала свои отказы молча - «Наруто» кончился одной строкой на экране и нулём
    событий в недельной ленте, то есть след говорил, что отбор прошёл без единой осечки.

    ``judged`` - те же приговоры по номерам, которыми потом объясняется снижение ступени
    (:func:`stepdown_note`): релиз, которого мы коснулись, обязан числиться отбракованным,
    а не «не дошли».
    """
    judged[number] = why
    trace.emit("select", "drop", release=number, why=why)


def _did_not_answer(number: int, why: str) -> None:
    """Записать осечку роя, не превращая наше ожидание в приговор раздаче."""
    trace.emit("select", "drop", release=number, why=why)


def _waiting_note(prep: _Prep, why: str) -> str:
    """Назвать окончившееся терпение, а не объявлять неизвестный рой пустым."""
    if not _silenced(prep):
        return why
    matched = re.search(r"за (\d+) с", why)
    return f"не дождались за {matched.group(1)} с" if matched else "не дождались"


def _silenced(prep: _Prep | None) -> bool:
    """Осечка ли это РОЯ: про сам релиз мы так ничего и не узнали.

    Отличается тем же, чем отличаются две осечки отбора (:meth:`_Bench.resolve`): ffprobe
    паспорт прочитал - про релиз известно всё, и второй раз спрашивать нечего; рой
    промолчал - неизвестно ничего, кроме того, что раздача не отозвалась. Опознаётся
    ТИПОМ отказа, а не текстом: текст пишется языком зрителя и правится (TC-281).

    «Нужной серии в раздаче нет» и «отдельного видеофайла нет» - это
    :class:`~torrcast.NotFoundError`: про раздачу узнали всё, что хотели, и терпение ей
    ничего не добавит. Молчание роя приезжает :class:`~torrcast.SwarmError`, а не
    уложившаяся в бюджет фаза - вовсе без отказа, одной строкой :attr:`_Prep.error`.
    """
    if prep is None or prep.media is not None:
        return False
    return prep.failure is None or isinstance(prep.failure, SwarmError)


class _Bench:
    """Прогрев релизов: несколько раздач готовятся разом, показ берёт первую годную.

    Держит по потоку на релиз и умеет ждать нужный с живым прогрессом. Любая осечка
    (нет пиров, не читается поток, оказался HEVC) стоит одной строки и перехода к
    следующему кандидату — молчаливых подмен и молчаливых зависаний не бывает.
    """

    def __init__(
        self,
        torrserver: TorrServer,
        choose: Callable[[_Plan, Release, list[TorrFile]], TorrFile] | None = None,
        meta_budget: float = META_BUDGET,
        probe_budget: float = PROBE_BUDGET,
        profile: Profile = CAUTIOUS,
    ) -> None:
        self.torrserver = torrserver
        self.choose = choose or _default_file
        #: Чей декодер судит релизы: что играется копией, а что не играется вовсе.
        self.profile = profile
        self.meta_budget = meta_budget
        self.probe_budget = probe_budget
        self.preps: dict[tuple[str, int], _Prep] = {}
        #: Прогревы, которые прямо сейчас кому-то нужны и потолком не убираются: тот, чьего
        #: ответа ждут, и тот, который греется ему на смену. Пусто под меню - там нужны все.
        self.needed: set[tuple[str, int]] = set()

    def start(self, plan: _Plan, number: int, patient: bool = False) -> _Prep:
        """Начать (или вернуть уже начатую) подготовку релиза ``number`` этого плана.

        ``patient`` - спрашивать рой без отсрочек, по полным бюджетам фазы
        (:attr:`_Prep.patient`). Обычный прогрев начинает работу сразу, но часы
        отсрочки запускаются только когда релиз действительно дошёл до вопроса.
        """
        key = (plan.picture.key, number)
        found = self.preps.get(key)
        if found is not None:
            return found
        self._room()
        prep = _Prep(
            number=number,
            release=plan.ranked[number - 1],
            patient=patient,
            contact_wait=None if patient else ContactWait(PEER_GRACE),
        )
        self.preps[key] = prep
        threading.Thread(target=self._work, args=(plan, prep), daemon=True).start()
        return prep

    @staticmethod
    def _ask(plan: _Plan, prep: _Prep, queue: list[int]) -> None:
        """Запустить часы первого контакта, когда релиз дошёл до вопроса."""
        if prep.contact_wait is not None:
            prep.contact_wait.activate(peer_grace(plan, prep.number, queue))

    def live(self) -> list[_Prep]:
        """Прогревы, за которыми в TorrServer стоит (или вот-вот встанет) наша раздача."""
        return [prep for prep in self.preps.values() if not prep.dropped]

    def _room(self) -> None:
        """Освободить место под новую раздачу: одновременно держим не больше :data:`MAX_LIVE`.

        Убирается САМЫЙ СТАРЫЙ из ненужных - тот, чей прогрев начался раньше всех и кого
        никто не ждёт (:attr:`needed`). Порядок именно такой, а не «последний заведённый»:
        свежий прогрев - это работа, которая ещё идёт и вот-вот пригодится, а старый под
        меню уже отдал всё, что мог.

        🔴 Убирается по ЯВНОМУ ХЭШУ прогрева (:meth:`_forget`), а не «всё, что видно в
        списке службы»: в списке лежат и чужие раздачи, и своё мы там не всегда видим -
        заводим с ``save_to_db:false``. «Снести всё из list» уже сносило чужое.
        """
        while len(self.live()) >= MAX_LIVE:
            spare = [
                prep
                for key, prep in self.preps.items()
                if not prep.dropped and key not in self.needed
            ]
            if not spare:  # все живые нужны - потолок не повод убивать работу под ответом
                return
            self._forget(min(spare, key=lambda prep: prep.started))

    def reorder(self, before: _Plan, after: _Plan) -> _Plan:
        """Переставить уже начатые прогревы под НОВЫЙ порядок отбора; вернуть новый план.

        Прогрев под меню заводится по номеру релиза в плане (:meth:`start`), а номер —
        это место в :attr:`_Plan.ranked`. Пересборка плана на настоящей длительности
        (:func:`_timed`) порядок вправе поменять, и без переезда ключей прогрев верха
        отдался бы уже другой раздаче: та же цифра, другой магнит.

        Переезд считается по самой раздаче, а не по цифре: у прогрева она уже лежит
        (:attr:`_Prep.release`), и ищется её новое место. Раздачи, которой в новом
        порядке нет вовсе, быть не может — пул тот же, — но если она пропадёт, прогрев
        отпускается, а не переносится наугад.
        """
        if after is before:
            return before
        places = {id(release): number for number, release in enumerate(after.ranked, start=1)}
        moved: dict[tuple[str, int], _Prep] = {}
        for key, prep in self.preps.items():
            if key[0] != after.picture.key:
                moved[key] = prep
                continue
            number = places.get(id(prep.release))
            if number is None:  # раздача выпала из порядка - её прогрев больше не нужен
                self._forget(prep)
                continue
            prep.number = number
            moved[(key[0], number)] = prep
        self.preps = moved
        self.needed = {
            (key, places.get(id(before.ranked[number - 1]), number))
            if key == after.picture.key and 1 <= number <= len(before.ranked)
            else (key, number)
            for key, number in self.needed
        }
        return after

    def keep_plan(self, plan: _Plan) -> None:
        """Картина выбрана - прогревы ОСТАЛЬНЫХ картин больше не нужны, и они убираются.

        До сих пор они доживали до :meth:`keep_only`, то есть до конца отбора, - а отбор
        это до :data:`PICK_BUDGET` секунд (180). Всё это время две-три чужие раздачи
        тянули куски у той единственной, которую мы вот-вот покажем, и подставляли
        TorrServer под его же таймер (:data:`MAX_LIVE`).

        Внутри выбранной картины не трогается ничего: запасной релиз греется параллельно
        верху НАМЕРЕННО (:meth:`spare`, замеренный выигрыш - 5 с), и убрать его вправе
        только сам отбор, когда выбор уже сделан.
        """
        for key, prep in self.preps.items():
            if key[0] != plan.picture.key:
                self._forget(prep)

    def spare(self, plan: _Plan, args: Args) -> list[_Prep]:
        """Поднять запасной релиз этого плана - тот, к которому уйдёт отбор, если верх забракуют.

        Отличие от :meth:`start` только во времени. Очередь релизов та же самая, что
        спросит :meth:`resolve` (:meth:`_Plan.candidates`), и следующий номер в ней -
        ровно тот, который resolve поднимает первым же движением. Здесь он поднимается
        раньше: пока на экране висит меню, а не после того, как верх уже осуждён.

        Логику ОТБОРА это не трогает ни на знак: кто годен, решает по-прежнему
        :meth:`_trouble`, порядок очереди прежний, и печатается всё то же самое. Меняется
        только то, какая раздача к моменту отбора уже прогрета.

        Названный руками релиз (``--release N``) запасного не имеет по определению: очередь
        из одного номера, подменять человека нечем - и лишней раздачи в TorrServer не будет.

        🔴 TC-309. Второй запасной - по ЗВУКУ. Релиз, чьё имя русской дорожки не обещает,
        может оказаться «дорожкой без тега», а гейт такой релиз бракует и уводит очередь
        дальше (:func:`voice_unproven`, TC-492) - к той самой раздаче, которая русскую
        обещает. Стоит она в очереди где угодно - на 4-9 месте, - и подъём её с нуля это
        метаданные роя 3-6 с плюс чтение дорожек, то есть половина всего срока отбора.
        Здесь она греется заодно с обычным запасным, и очереди достаётся уже готовый ответ.

        Греется ровно тогда, когда очередь и правда может уйти дальше верха. Спрашивается
        не верх, а тот, кого отбор реально возьмёт, поэтому молчаливое имя ищется среди
        первых :data:`MAX_TRIES` кандидатов - верх и два ближайших запасных; а картина, у
        которой русскую обещали все трое, лишней раздачи в рое не получает вовсе.
        """
        if args.release is not None:
            return []
        queue = plan.candidates(args)
        preps = [self.start(plan, number) for number in queue[1 : 1 + PREWARM_SPARE]]
        front = queue[:MAX_TRIES]
        if any(not plan.ranked[n - 1].dubbed for n in front):
            dub = next((n for n in queue[1:] if plan.ranked[n - 1].dubbed), None)
            if dub is not None:  # совпал с обычным запасным - тот уже греется (:meth:`start`)
                preps.append(self.start(plan, dub))
        return preps

    def resolve(self, plan: _Plan, args: Args, progress: Progress) -> _Prep:
        """Годный релиз плана: ждём подготовку с прогрессом, негодный — следующий.

        Осечки бывают двух разных сортов, и до сих пор они стоили одинаково — попытки из
        трёх:

        * **приговор** — ffprobe раздачу прочитал и она не годится (av1, vc1, тяжёлая),
          либо сам осмотр раздачи ответил за неё («нужной серии нет», «отдельного
          видеофайла нет»). Про релиз узнали всё, второй раз спрашивать нечего;
        * **молчание роя** — метаданные не приехали, поток не прочитался, фаза не
          уложилась в бюджет. Про КАЧЕСТВО релиза при этом не узнали ничего: раздача
          просто не отозвалась.

        Считать их одинаково — это и есть главная причина 🟡 в замере на тысяче запросов:
        три подряд «нет пиров за 20 с» заканчивали отбор словами «годного релиза нет»,
        хотя ниже в очереди стояли живые. Перепроверка тех же картин в один поток
        оживляла шесть из восьми («Кавказская пленница», «Зона интересов», «Бесконечная
        история»).

        Поэтому попытку жжёт только приговор (:data:`MAX_TRIES`), а молчание роя — часы
        (:data:`PICK_BUDGET`). Бесконечно это не длится и молчаливым не бывает: потолок
        фазы прежний, каждая осечка стоит строки, а очередь конечна.

        🔴 TC-300. А кончившаяся очередь, в которой промолчали ВСЕ, кончается не отказом:
        лучший из промолчавших спрашивается ещё раз - один и без отсрочек, в остаток того
        же бюджета фазы (:meth:`_recheck`). Замер: такие отказы не упирались ни в
        приговоры, ни в часы ни разу из 98, то есть терпения им не хватало нашего, а не
        бюджетного.

        🔴 TC-188. Сами приговоры тоже считаются не поштучно, а СЕКУНДАМИ ожидания
        (:data:`VERDICT_BUDGET`): три места счётчика сгорали на именах, которые ffprobe
        читает за секунду, - SD-рип на 1.5 ГБ, vp9, av1, - и до живого 1080p ниже по
        очереди дело не доходило (44 случая в замере каталога). Дешёвый приговор больше
        не отнимает место у следующей раздачи, дорогой отнимает как отнимал.

        🔴 TC-178. Третья осечка - **звук**: «включилось» значит «включилось С РУССКОЙ
        ОЗВУЧКОЙ», и релиз, у которого русской дорожки не оказалось, годным не считается.
        Судит паспорт, а не имя (:func:`voice_unproven`): имя врёт и молчит, а до ffprobe
        язык звука не знает никто. Считается такая осечка как приговор - про релиз узнали
        всё, - и поэтому упирается в те же :data:`MAX_TRIES` и :data:`VERDICT_BUDGET`, что
        и остальные: гейт не имеет права стать бесконечным перебором выдачи, цель пути
        прежняя - десять секунд до картинки.

        🔴 TC-492. Годен только ПОДТВЕРЖДЁННЫЙ русский звук, и это не придирка к формулировке.
        Паспорт отвечает тремя ответами, а гейт до сих пор пропускал два: и «русская есть»,
        и «язык не назван». Второй ответ - незнание, а не согласие, и по замеру паспортов
        он приходит у 11% сыгранных релизов: ровно на них очередь и вставала, не дойдя до
        нетронутых соседей. Ни одного лишнего ffprobe правка не стоит - меняется только то,
        как читается уже прочитанный ответ, - а перебор остаётся под теми же двумя
        потолками.

        Лишнего времени гейт не стоит вовсе: спрашивается уже прочитанный паспорт, второго
        ffprobe и второго похода в рой на релиз не появляется. Дороже становится ровно
        один случай - когда верх отбора оказался без подтверждённой русской, и это ровно
        тот случай, ради которого всё и затевалось.

        И гейт не слепой: первый безрусский, но во всём остальном годный кандидат
        откладывается в сторону, а не выбрасывается, и если русской не найдётся ни у кого,
        играет он (:meth:`_mute_fallback`). Человек без картины не остаётся.
        """
        queue = plan.candidates(args)
        # Пул, очередь и весь отсев с причинами - одним событием на запрос (TC-186).
        # Сумма очереди и причин сходится с пулом картины: раздача, не доехавшая до
        # каста, больше не исчезает молча (:func:`queue_drops`).
        drops = queue_drops(plan, queue, pinned=args.release is not None)
        trace.emit(
            "select",
            "queue",
            pool=len(plan.picture.releases),
            queued=len(queue),
            dropped=drops,
        )
        if not queue:
            # 🔴 TC-432. Ворота не пропустил НИКТО, включая верх ранжира. Подставить
            # отсеянное значило бы сыграть игру или репак на запрос сериала - подмена
            # картины, худший вид брака. Отказ честный: сколько раздач было, почему
            # каждая не годится и какой у человека ход - всё это :func:`unfit_line`.
            raise NotFoundError(unfit_line(plan, drops, plan.kin))
        if args.release is None and (skipped := plan.skipped):
            # Молчать тут нельзя: человек попросил серию, а половину выдачи мы не взяли.
            print(
                f"серии {plan.want} нет в раздачах: {len(skipped)} "
                f"(«{_cut(skipped[0].raw_name, 60)}»...) - беру ту, где она есть"
            )
        tried: list[str] = []
        #: Приговоры по номерам релизов: нужны строке о снижении ступени (TC-187), чтобы
        #: она называла причину, а не просто «лучшее было».
        judged: dict[int, str] = {}
        verdicts = 0
        #: Сколько тронутых раздач промолчали роем (:func:`_silenced`): без этого счёта
        #: приговор осмотра («отдельного видеофайла нет») числился молчанием роя, и отказ
        #: советовал «зайти позже» там, где рой ни при чём - в раздаче просто не картина.
        silents = 0
        #: Во что приговоры уже обошлись человеку, секунды (:data:`VERDICT_BUDGET`).
        priced = 0.0
        exhausted = False
        #: Первый годный кандидат, у которого не оказалось русской дорожки: он не играет,
        #: пока в очереди есть кого спросить, но и не выбрасывается - это запасной ход на
        #: случай, когда русской не найдётся ни у кого (:meth:`_mute_fallback`).
        mute: _Prep | None = None
        #: Докуда дошла очередь - для строки о снижении ступени на запасном ходу.
        reached = 0
        deadline = time.monotonic() + PICK_BUDGET
        for attempt, number in enumerate(queue, start=1):
            reached = attempt
            following = queue[attempt] if attempt < len(queue) else None
            # Нужны ровно двое: тот, чьего ответа ждём, и тот, кто греется ему на смену.
            # Всё прочее прогретое потолок вправе убрать прямо здесь (:meth:`_room`).
            # Третий - отложенный безрусский: его раздача ещё может понадобиться показу.
            keep = (number, following, mute.number if mute is not None else None)
            self.needed = {(plan.picture.key, n) for n in keep if n is not None}
            prep = self.start(plan, number)
            self._ask(plan, prep, queue)
            if following is not None:  # запасной греется, пока ждём этот
                self.start(plan, following)
            # Секундомер стоит вокруг ОЖИДАНИЯ, а не вокруг работы потока: прогретая под
            # меню раздача отвечает мгновенно, и её приговор человеку ничего не стоил.
            entered = time.monotonic()
            voice_search = (
                "" if args.pinned else f"ищу русскую озвучку: релиз {attempt} из {len(queue)} - "
            )
            self._wait(prep, progress, prefix=voice_search)
            # Ошибка самой службы раздачи относится ко всей очереди, а не к одному
            # рою. Перебирать остальные релизы бессмысленно: они пойдут через тот же
            # мёртвый порт и лишь размножат одну строку, после чего итог ещё и свалит
            # вину на раздачи. Опознаётся такой отказ ТИПОМ исключения, а не текстом:
            # строка печатается языком зрителя и правится, тип - нет (TC-281).
            if isinstance(prep.failure, ServerDownError):
                raise InfraError(prep.error)
            trouble = self._trouble(
                prep,
                pinned=args.pinned,
                warn_mbit=plan.warn_mbit,
                recode=plan.recode_at > 0,
                hard_mbit=plan.hard_mbit,
            )
            # 🔴 TC-178. Русская дорожка - часть «включилось», а не предпочтение: релиз,
            # у которого её нет, годным не считается, и очередь идёт дальше. Спрашивается
            # уже прочитанный паспорт (:func:`voice_unproven`) - ни одного лишнего ffprobe
            # и ни одного лишнего похода в рой это не стоит. Названный руками релиз не
            # судим: там человек выбрал сам.
            #
            # 🔴 TC-492. Годен только ПОДТВЕРЖДЁННЫЙ русский звук. Дорожка без тега языка
            # раньше проходила гейт наравне с русской, и это была не поблажка, а подмена
            # правила незнанием: очередь вставала на первом же безымянном релизе.
            voiceless = (
                not trouble
                and not args.pinned
                and voice_unproven(prep.found, native=plan.picture.native)
            )
            if not trouble and not voiceless:
                progress.phase("")
                prep = self._honest(plan, prep, queue, args, progress, judged)
                self._announce(plan, prep, queue, judged, attempt)
                return prep
            why = _waiting_note(prep, trouble) if trouble else "без русской озвучки"
            tried.append(f"{number} - {why}")
            if _silenced(prep):
                _did_not_answer(number, why)
            else:
                _turned_down(judged, number, why)
            silents += 1 if _silenced(prep) else 0
            if not prep.error and prep.media is not None:  # ffprobe прочитал и осудил
                verdicts += 1
                priced += time.monotonic() - entered
            # Запасной ход держит ОДНОГО отложенного, и это лучший из безрусских. Лучший
            # тут - тот, про кого меньше известно плохого: паспорт, промолчавший про язык,
            # ещё может оказаться русским, а названный японским русским уже не станет
            # никогда (TC-492). Поэтому незнание вытесняет знание «нет», а между равными
            # выигрывает первый - он выше в ранжире.
            if voiceless and (mute is None or (mute.found.foreign and not prep.found.foreign)):
                if mute is not None:
                    self._forget(mute)
                mute = prep  # запасной ход: русской может не оказаться ни у кого
            else:
                self._forget(prep)
            progress.phase("")
            # Три приговора - пол, дальше решают секунды: дешёвые приговоры (SD-рип,
            # vp9) места следующей раздаче больше не занимают, дорогие занимают.
            affordable = verdicts < MAX_TRIES or priced < VERDICT_BUDGET
            goes_on = following is not None and affordable and time.monotonic() < deadline
            tail = f" - беру {following}" if goes_on else ""
            head = (
                f"релиз {number} без русской озвучки ({heard(prep.found)})"
                if voiceless
                else f"релиз {number} не годится ({why})"
            )
            print(head + tail)
            if not goes_on:
                # Дошли до конца очереди, а не встали по бюджету/попыткам: следующего нет.
                exhausted = following is None
                break
        if mute is not None:
            return self._mute_fallback(plan, mute, queue, judged, reached, len(tried))
        if verdicts == 0 and exhausted and tried:
            revived = self._recheck(plan, queue, args, progress, judged, deadline)
            if revived is not None:
                return revived
            # Повторный полный спрос может не промолчать, а вынести приговор: например,
            # метаданные приехали, но нужной серии в раздаче нет. Тогда итог обязан
            # говорить о приговоре, а не обещать, что молчавший рой позже оживёт.
            retried = next((number for number in queue if number in judged), None)
            if retried is not None:
                tried = [
                    f"{retried} - {judged[retried]}" if row.startswith(f"{retried} - ") else row
                    for row in tried
                ]
                silents -= 1
        shown = "; ".join(tried[:MAX_TRIES])
        more = f" и ещё {len(tried) - MAX_TRIES}" if len(tried) > MAX_TRIES else ""
        offer = kin_line(plan.kin)
        tail = f"\n{offer}" if offer else ""
        if silents == len(tried) and tried:
            # «Не нашли» и «рой промолчал» - разные отказы. Ни один тронутый релиз не
            # дошёл до приговора: ffprobe не прочитал ни одного, потому что не приехали
            # ни метаданные по DHT, ни поток. Раздачи есть и по именам годны - молчит
            # рой, а не выбор. Врать «годного релиза нет» тут нельзя. Но и «рой мёртв»
            # на всю выдачу - враньё ровно так же: очередь отбора это НЕ вся выдача, и
            # сколько из неё потрогали, знают только счётчики - они и печатаются
            # (:func:`silent_swarm`).
            # 🔴 TC-435. Исчерпания очереди ветка больше не ждёт. Обход 60 молчащих
            # роёв «Дюны», вставший по часам (:data:`PICK_BUDGET`), кончался словами
            # «годного релиза нет» - а негодных не нашли ни одного: их не прочитали.
            # Молчание роя названо молчанием роя независимо от того, кончилась очередь
            # или кончилось время; какое из двух - :func:`silent_swarm` знает по своим
            # счётчикам и говорит числом.
            # 🔴 TC-399. Ветка - только когда промолчали ВСЕ тронутые. Приговор осмотра
            # («отдельного видеофайла нет», «нужной серии нет») молчанием роя не является:
            # про такую раздачу известно всё, и «зайди позже - рой оживёт» было бы ложью.
            raise NotFoundError(
                silent_swarm(plan, queue, len(tried), f"{shown}{more}", picked=args.release) + tail
            )
        move = "выбери другой релиз" if args.release is not None else "выбери руками"
        raise NotFoundError(
            f"годного релиза нет ({shown}{more}): {move} - "
            "cast releases <запрос>, потом cast <запрос> --release N" + tail
        )

    def _recheck(
        self,
        plan: _Plan,
        queue: list[int],
        args: Args,
        progress: Progress,
        judged: dict[int, str],
        deadline: float,
    ) -> _Prep | None:
        """Второй спрос очереди, промолчавшей целиком: одному релизу и без отсрочек.

        🔴 TC-300. Отказ «до остальных отбор не дошёл» звучал так, будто обход упёрся в
        потолок, и потолки же в нём и подозревали. Замер по двум сохранённым прогонам
        (1131 запрос, 98 таких отказов) говорит обратное: НИ ОДИН из них не встал ни по
        приговорам (:data:`MAX_TRIES` - их там ноль по определению ветки), ни по часам
        (самый долгий занял 91 с из 180 :data:`PICK_BUDGET`). Очередь всякий раз доходила
        до собственного конца, и кончалась она тем, что каждый её релиз промолчал роем; в
        56 отказах из 98 при этом потрогали ВСЮ выдачу до последней раздачи. Поднимать
        потолки тут нечего - поднимать надо терпение.

        Молчание это часто ложное. Тот же корпус запросов, прогнанный дважды тем же кодом
        в один день: из 17 картин, отказанных молчанием роя в первом прогоне, во втором
        сыграли 8, и наоборот - из 13 отказанных во втором в первом сыграли 5. Живой рой,
        которого не дождались, выглядит точно так же, как мёртвый.

        Не дождались его МЫ, и ровно на столько, на сколько сами назначили: отсрочки
        (:data:`PEER_GRACE`, :data:`SWARM_GRACE`) обрывают раздачу втрое-вчетверо раньше
        её собственного бюджета. Заведены они по честному расчёту - «ошибка стоит одного
        места в очереди, следующий релиз всё равно спрашивается», - и расчёт этот верен
        ровно до тех пор, пока в очереди есть кого спрашивать. Когда промолчали все,
        ошибка отсрочки стоит уже не места, а всего показа, а бюджет фазы при этом не
        потрачен и наполовину (медиана такого отказа - 23 с из 180).

        Поэтому перед отказом лучший из промолчавших спрашивается ещё раз: один (соседей
        рядом не греется), по полным бюджетам метаданных и дорожек, без единой отсрочки.
        Потолок фазы стоит где стоял - второго спроса не будет вовсе, если остаток бюджета
        не покрывает его худшую цену, - и стоит он строки в обе стороны: и когда идёт, и
        когда рой промолчал повторно.

        Спрашивается тот, про кого мы правда ничего не знаем (:func:`_silenced`): раздачу
        без нужной серии терпение не изменит.
        """
        key = plan.picture.key
        number = next((n for n in queue if _silenced(self.preps.get((key, n)))), None)
        if number is None:  # молчал не рой, а сами раздачи - им терпение не поможет
            return None
        if time.monotonic() + self.meta_budget + self.probe_budget > deadline:
            return None  # честный второй спрос в остаток бюджета фазы уже не влезает
        print(
            f"промолчала вся очередь ({len(queue)}) - спрашиваю релиз {number} "
            "ещё раз, одного и без отсрочек"
        )
        # Прогрев, оборванный отсрочкой, уже забыт вместе с раздачей: спрашиваем заново.
        self.preps.pop((key, number), None)
        self.needed = {(key, number)}
        prep = self.start(plan, number, patient=True)
        self._wait(
            prep,
            progress,
            prefix=f"ищу русскую озвучку: релиз {queue.index(number) + 1} из {len(queue)} - ",
        )
        progress.phase("")
        if isinstance(prep.failure, ServerDownError):
            raise InfraError(prep.error)
        trouble = self._trouble(
            prep,
            pinned=args.pinned,
            warn_mbit=plan.warn_mbit,
            recode=plan.recode_at > 0,
            hard_mbit=plan.hard_mbit,
        )
        if trouble:
            silent = _silenced(prep)
            if silent:
                _did_not_answer(number, trouble)
            else:
                _turned_down(judged, number, trouble)
            result = "молчит и в одиночку" if silent else "ответил в одиночку, но не годится"
            print(f"релиз {number} {result} ({trouble})")
            self._forget(prep)
            return None
        if not args.pinned and voice_unproven(prep.found, native=plan.picture.native):
            # Ожил безрусский: русской не нашлось ни у кого, кого вообще удалось спросить.
            return self._mute_fallback(plan, prep, queue, judged, len(queue), len(queue))
        # Проверки честности (:meth:`_honest`) тут нет по той же причине, что и на запасном
        # ходу: сравнивать не с кем - все соседи уже ответили молчанием, и второй круг
        # ffprobe спрашивал бы ровно тех, кто только что промолчал.
        self._announce(plan, prep, queue, judged, len(queue))
        return prep

    def _announce(
        self,
        plan: _Plan,
        prep: _Prep,
        queue: list[int],
        judged: dict[int, str],
        reached: int,
    ) -> None:
        """Строки перед стартом: чем играем и чего это стоило. Молчаливых подмен нет.

        Собраны в одном месте, потому что путей к показу теперь два - обычный и запасной
        ход без русской озвучки (:meth:`_mute_fallback`), - а строки на них обязаны быть
        одни и те же: и «перекодирую целиком», и «ступень ниже доступной» относятся к
        файлу, а не к тому, как отбор до него добрался.
        """
        # Молчаливых подмен нет ни в одну сторону: и «ресивер может не взять», и
        # «перекодирую целиком» - это решение показа, и человек его слышит. Вес
        # тут такой же повод, как кодек: тяжёлый ремукс уезжает перекодированным
        # целиком, и сказано об этом ровно теми же словами и тем же числом.
        weight = prep.found.weight_mbit(prep.want.size)
        heavy = plan.hard_mbit > 0 and weight > plan.hard_mbit
        if hope := last_hope_note(plan, prep.release):
            print(hope)
        if plan.recode_at > 0 and (prep.found.recoded_whole or heavy):
            # Причина - кодек (с глубиной, если она и есть причина) либо вес.
            silent = prep.found.recoded_whole
            print(recode_note(prep.found.video_name, 0.0 if silent else weight))
        elif warning := prep.found.video_warning:
            print(warning)
        # Ступень ниже доступной - тоже авто-решение, и оно не молчит (TC-187).
        if step := stepdown_note(plan, prep.number, prep.media, queue, judged, reached):
            print(step)

    def _mute_fallback(
        self,
        plan: _Plan,
        mute: _Prep,
        queue: list[int],
        judged: dict[int, str],
        reached: int,
        tried: int,
    ) -> _Prep:
        """Запасной ход: русской дорожки не нашлось ни у кого - играем то, что есть.

        🔴 TC-178. Гейт русской озвучки нельзя делать слепым. Русская дорожка - условие
        годности релиза, но у картины её может не быть НИ У КОГО: японский тайтл, который
        никто не озвучивал, старое кино, чужой сериал. Отказать в такой картине значило бы
        отобрать у человека и то, что есть, - а он про неё ничего плохого не спрашивал.

        Поэтому ступеней две. Пока в очереди есть кого спросить, безрусский релиз ждёт в
        стороне (его раздача при этом не убирается - иначе запасной ход стоил бы второго
        подъёма с нуля). Кончилась очередь - он играет, и решение это громкое: строка на
        экране, запись в недельном следе (по ней замер и считает дыры каталога) и честная
        строка про язык звука перед стартом (:func:`sound_note`).

        🔴 TC-492. Сюда же приходит и третий ответ паспорта - «язык не назван»
        (:func:`voice_unproven`). Раньше такой релиз играл молча, как будто русская в нём
        нашлась; теперь он идёт тем же ходом и той же строкой, а язык в ней называется
        честно - «не назван» (:func:`heard`), а не выдуманным «оригинальным». Отдельной
        строки под этот случай не заводится намеренно: зрителю важно одно - русскую
        озвучку не нашли, - а чем именно кончился паспорт, ему договаривает
        :func:`sound_note` перед стартом.

        Проверки честности (:meth:`_honest`) тут нет намеренно: она меняет релиз ради
        разрешения, а на этом пути мы уже знаем, что русской дорожки нет ни у одного из
        проверенных, и второй круг ffprobe стоил бы секунд ровно за то же самое.
        """
        lang = heard(mute.found)
        trace.emit("select", "mute", release=mute.number, lang=lang, checked=tried)
        print(
            f"русской озвучки нет ни в одной из проверенных раздач ({tried}) - "
            f"включаю релиз {mute.number}, звук {lang}"
        )
        self._announce(plan, mute, queue, judged, reached)
        return mute

    def _wait(self, prep: _Prep, progress: Progress, prefix: str = "") -> None:
        """Дождаться подготовки, показывая фазу и бегущее время."""
        asked = prep.contact_wait.activated_at if prep.contact_wait is not None else None
        deadline = (asked or prep.started) + self.meta_budget + self.probe_budget + 5.0
        while not prep.ready.wait(0.2):
            progress.phase(f"{prefix}{prep.phase}")
            if time.monotonic() > deadline:  # поток сам не уложился - не ждём вечно
                prep.error = prep.error or f"фаза «{prep.phase}» не уложилась в бюджет"
                return

    def _peek(self, prep: _Prep, progress: Progress, deadline: float, phase: str) -> bool:
        """Заглянуть в подготовку с коротким сроком: успела — ``True``, нет — ``False``.

        Отличие от :meth:`_wait` не в сроке, а в последствиях: этот срок наш, а не
        релиза, и просроченному прогреву :attr:`_Prep.error` не ставится. Иначе
        подглядывание за соседом молча делало бы его негодным.
        """
        while not prep.ready.wait(0.2):
            progress.phase(phase)
            if time.monotonic() > deadline:
                return False
        return True

    def _honest(
        self,
        plan: _Plan,
        chosen: _Prep,
        queue: list[int],
        args: Args,
        progress: Progress,
        judged: dict[int, str] | None = None,
    ) -> _Prep:
        """Подтверждённое разрешение против обещанного: 574p вместо 1080p — не мелочь.

        Верх отбора — самый обсиженный годный кандидат, и это правило остаётся.
        Но обсиженность считается **среди честных**: если ffprobe уже прочитан и говорит,
        что внутри верха не HD, а рядом в очереди стоит живой релиз, который обещает
        1080p, — стоит спросить у ffprobe и его. Живой случай, ради которого это
        написано: «Моана 2», верх ``WEB-DL-AVC`` 3.14 ГБ / 140 сидов оказался 1150×574,
        а вторым лежит настоящий 1080p 13.3 ГБ со 121 сидом.

        Платим за проверку немного: запасной греется с той же секунды, что и верх
        (:meth:`resolve` поднимает следующего сразу), поэтому ждём не прогрев, а разницу
        двух ffprobe, и не дольше :data:`HONEST_BUDGET`.

        Молчаливых подмен нет в обе стороны: и подмена, и отказ от неё печатают строку.
        ``--release N`` и ``--file N`` не трогаем вовсе — там человек выбрал сам.

        🔴 TC-194. ``judged`` - приговоры, уже вынесенные очередью отбора (:meth:`resolve`).
        Без него проверка переспрашивала тех, кого сама же только что забраковала: их
        подготовка лежит в :attr:`preps` готовой, ``ffprobe`` прочитан, и тот же
        :meth:`_trouble` с теми же порогами возвращал тот же приговор - вторая одинаковая
        строка на экране («Сталкер»: два решения, четыре строки) и ни одной новой записи в
        следе. Заодно этим съедались места в :data:`MAX_TRIES`, и до по-настоящему
        непроверенных соседей проверка не доходила.

        🔴 TC-492. Второго повода - «язык звука не назван» (TC-301) - тут больше нет, и
        убран он не отказом от него, а тем, что повод перестал существовать: сюда доходит
        только релиз с ПОДТВЕРЖДЁННОЙ русской дорожкой (:func:`voice_unproven`), а
        безымянный паспорт теперь бракуется гейтом и очередь идёт дальше сама. Спросить
        соседа, обещавшего русскую именем, отдельной машинкой больше незачем: он и так
        стоит в очереди, и ранжир поднимает его над молчаливыми (:func:`sound_step`).
        """
        if args.release is not None or args.pinned:
            return chosen
        judged = judged or {}
        short = understated(chosen.release, chosen.found)
        if not short:
            return chosen
        why_look = short
        # Очередь целиком тут не спрашивается: каждый вопрос - это ещё одна раздача в
        # TorrServer, то есть кэш и полоса роя у того, кого мы и так вот-вот покажем.
        rest = [
            n
            for n in queue
            if n != chosen.number
            and n not in judged
            and promises_more(plan.ranked[n - 1], chosen.found)
        ][:MAX_TRIES]
        deadline = time.monotonic() + HONEST_BUDGET
        for number in rest:
            # Нужны двое: тот, кого играем, если проверка ничего не найдёт, и тот, кого
            # спрашиваем сейчас. Проверенные и отвергнутые убираются тут же, ниже.
            self.needed = {(plan.picture.key, chosen.number), (plan.picture.key, number)}
            alt = self.start(plan, number)
            self._ask(plan, alt, [number])
            phase = f"релиз {chosen.number} {why_look} - смотрю {number}"
            if not self._peek(alt, progress, deadline, phase):
                progress.phase("")
                _turned_down(judged, number, "не успел ответить")
                print(f"релиз {number} не успел ответить - играю {chosen.number} ({why_look})")
                # Спросили и ждать перестали - значит, ответ больше не нужен, а раздача
                # соседа осталась бы висеть до общей уборки, доедая полосу у того, кого мы
                # сейчас играем. Отпускаем сразу и по своему хэшу; подъём, который ещё
                # идёт в его потоке, уберёт себя сам (:meth:`_work`, ветка ``dropped``).
                self._forget(alt)
                return chosen
            progress.phase("")
            why = self._trouble(
                alt,
                pinned=False,
                warn_mbit=plan.warn_mbit,
                recode=plan.recode_at > 0,
                hard_mbit=plan.hard_mbit,
            )
            if why:
                _turned_down(judged, number, why)
                print(f"релиз {number} не годится ({why})")
                self._forget(alt)  # спросили и получили ответ - держать его больше незачем
                continue
            # 🔴 TC-178. Честный 1080p без русской дорожки - это не «лучше»: разрешение
            # выиграно, а картина осталась несмотренной. Взятый сюда доходит только с
            # ПОДТВЕРЖДЁННОЙ русской дорожкой, и менять её на кадр нельзя - в том числе на
            # кадр релиза, чей паспорт про язык промолчал (TC-492): это тот же размен
            # знания на незнание, только в профиль.
            if voice_unproven(alt.found, native=plan.picture.native):
                _turned_down(judged, number, "без русской озвучки")
                print(f"релиз {number} не лучше (без русской озвучки)")
                self._forget(alt)
                continue
            if not honest_shot(alt.release, alt.found) or alt.found.frame <= chosen.found.frame:
                _turned_down(judged, number, f"не лучше ({quality_text(alt.release, alt.found)})")
                print(f"релиз {number} не лучше ({quality_text(alt.release, alt.found)})")
                self._forget(alt)
                continue
            print(f"релиз {chosen.number} {short} - беру {number} (настоящий {alt.found.quality})")
            self._forget(chosen)  # верх больше не нужен: полосу роя доедать ему незачем
            return alt
        print(f"релиз {chosen.number} {short} - честнее рядом нет, играю его")
        return chosen

    def _trouble(
        self,
        prep: _Prep,
        pinned: bool,
        warn_mbit: float = 0.0,
        recode: bool = False,
        hard_mbit: float = 0.0,
    ) -> str:
        """Почему релиз не годится; пусто — годится. Названный руками не подменяется.

        Битрейт здесь считается **по прочитанному файлу**, а не по размеру раздачи, и это
        разные числа: у «Моаны 2» прикидка (:func:`bitrate_of`) делит 13.3 ГБ на типовые
        два часа и даёт 14.8 Мбит/с, а внутри — фильм на 1:39:37, то есть честные
        17.8 Мбит/с, на которых Q70D встаёт в ребуфер раз в 30–60 с.
        Прикидка потолка при выборе дефолта такой релиз пропускала и пропускать будет:
        до ffprobe длительности картины не знает никто. Поэтому потолок проверяется ещё
        раз — тем же числом, которое показ печатает пользователю.

        ⚠️ ``warn_mbit`` здесь — это ``bitrate_hard_mbit``, а не потолок декодера:
        тяжёлые куски перекодируются, и «Моана 2» на 19 Мбит/с теперь годится.
        Отбраковывается только то, что перекодированием не спасти.

        ⚠️ Само число берётся из **паспорта** — веса видеодорожки, — а не из размера
        файла (:meth:`torrcast.stream.Media.weight_mbit`). Отбраковка спрашивает
        «сколько придётся перекодировать», а десять озвучек и двенадцать субтитров
        перекодировать не придётся: они на ТВ не уезжают вовсе.

        ⚠️ **HEVC больше не отказ** (``recode``): такой файл перекодируется целиком
        (:data:`torrcast.stream.RECODE_CODECS`), и аниме — жанр, где HEVC бывает вообще
        всем, что нашлось, — теперь играет. Предпочтение H.264 при прочих равных живёт
        не здесь, а в ранжире (:func:`rank_releases` топит hevc ниже всех), то есть
        сплошной перекод достаётся ровно тем релизам, у которых альтернативы нет.

        🔴 TC-221/TC-222. Кадр выше того, что берёт приёмник, здесь больше НЕ отказ:
        сплошной перекод ужимает его вниз (:attr:`torrcast.profile.Profile.recode_frame`),
        и 2160p играется в 1080p. Прежний отказ стоял на объяснении «перекод 4К не
        успевает», а замер TC-157 его перевернул: со скейлом до 1080p тот же перекод идёт
        1.53x реального времени против 1.03x без скейла. Отказ остаётся ровно там, где
        ужать нечем, - при выключенном перекодировании.

        ⚠️ ``hard_mbit`` - потолок для тех, кого сплошной перекод не вытягивает
        (:attr:`torrcast.state.Config.bitrate_hard_mbit`), и кадру выше 1080p он достаётся
        по-прежнему. Причина теперь не в скорости, а в запасе: у ужатого 4К она 1.34-1.41x
        (замер 09-08-2026 на тяжёлом месте) против 3.4x у 1080p, и тянуть из роя при этом
        надо ровно столько, сколько весит исходник. Рост кадра тут знает ffprobe, а не имя
        раздачи, поэтому 4K-ремукс с молчаливым именем ловится именно на этой ступени.
        """
        if prep.error:
            return prep.error
        if prep.media is None or prep.video is None:
            return "поток не прочитан"
        if not pinned and warn_mbit > 0:
            peak = prep.media.weight_mbit(prep.video.size)
            ceiling = warn_mbit
            # Причину отказа называем по ситуации. Обычный потолок - свойство
            # приёмника. А потолок, опущенный по высоте кадра (RECODE_HEIGHT), -
            # это скорость перекода НАШЕЙ машины: кадр выше 1080p в реальное время
            # не укладывается, и винить тут приёмник - нечестно.
            reason = "слишком тяжёлый для приёмника"
            if hard_mbit > 0 and prep.media.height > RECODE_HEIGHT:
                ceiling = min(warn_mbit, hard_mbit)
                reason = "перекод такого кадра этой машине не по силам"
            if peak > ceiling:
                return f"{reason}, ~{peak:.0f} Мбит/с"
        # ⚠️ Имя кодека тут не последнее слово: Hi10P зовётся ``h264``, а приёмник его не
        # берёт (:meth:`torrcast.profile.Profile.verdict`). При выключенном перекодировании
        # такой релиз - честный отказ отбора наравне с HEVC, и назван он своим именем:
        # «h264» в строке «не подошёл» человека бы только запутало.
        codec = prep.media.video_name or "h264"
        # 🔴 Судьба картинки решается ОДНИМ вызовом и в одном месте на весь код: копия,
        # сплошной перекод или честный отказ (:meth:`torrcast.profile.Profile.verdict`).
        # Белый список кодеков и глубина цвета - свойство ПРИЁМНИКА, а не показа: они
        # приходят из его профиля (:mod:`torrcast.profile`).
        call = self.profile.verdict(prep.media.video or "", prep.media.depth, prep.media.frame)
        if pinned or call == COPY:
            return ""
        if call == REFUSE:
            # vp9, av1, vc1, mpeg2video: копией их приёмник не играет, а цена сплошного
            # перекода для них не мерена. Честный отказ и следующий релиз - это не
            # «мы не осилили», а «есть кандидат, про которого мы знаем всё».
            return codec
        if recode:
            return ""
        # 🔴 TC-221. Перекодирование выключено, а копией это не уедет - и причина у отказа
        # бывает двух разных сортов. Кодек с глубиной («hevc», «h264 10 бит») человеку всё
        # объясняет сам, а вот 2160p H.264 8 бит - это обычный кодек, и слово «h264» в
        # строке «не подошёл» только запутало бы: не подошёл кадр. Ужать его вниз мог бы
        # перекод (:attr:`Profile.recode_frame`), но его-то и выключили.
        if prep.media.frame > self.profile.recode_frame and self.profile.plays_copy(
            prep.media.video or "", prep.media.depth
        ):
            return f"{prep.media.quality} - такой кадр приёмнику только через перекод"
        return codec

    def _forget(self, prep: _Prep) -> None:
        """Убрать раздачу из TorrServer: она либо не подошла, либо больше не нужна.

        Кроме одного случая: её держит живой показ - параллельный ``cast`` греет ту же
        выдачу, и снос чужой раздачи выдернул бы источник из-под экрана
        (:func:`_held_by_show`).
        """
        prep.dropped = True
        if prep.torrent_hash and not _held_by_show(prep.torrent_hash):
            self.torrserver.drop(prep.torrent_hash)

    def drop_all(self) -> None:
        """Показа не будет: всё прогретое убирается из TorrServer.

        Выходов мимо :meth:`keep_only` хватает — Ctrl-C на вопросе «Что смотрим?», запуск
        без терминала, «годного релиза нет», ``--dry`` (ему сносится и ВЫБРАННАЯ раздача:
        :meth:`keep_only` к тому месту уже прошёл, и живой остаётся ровно она). Раздачи
        при этом уже добавлены и тянут кэш в RAM до перезапуска TorrServer: ``save_to_db``
        у них выключен, но живут они не в нашем процессе, и умирают не вместе с ним.
        """
        for prep in self.preps.values():
            if not prep.dropped:  # убранное потолком или keep_only второй раз не трогаем
                self._forget(prep)

    def keep_only(self, chosen: _Prep) -> None:
        """Оставить в TorrServer одну раздачу — ту, которую показываем.

        Прогрев по определению греет лишнее: топ-3 картины франшизы и запасной релиз.
        Всё лишнее обязано исчезнуть до старта показа, иначе оно доедает и кэш в RAM,
        и полосу роя, а показ идёт ровно на них (и tmpfs не должен расти без предела).
        """
        for prep in self.preps.values():
            if prep is not chosen:
                self._forget(prep)

    def _work(self, plan: _Plan, prep: _Prep) -> None:
        """Фоновая подготовка: раздача в TorrServer, метаданные по DHT, ffprobe."""
        try:
            prep.phase = "метаданные (DHT)"
            prep.torrent_hash = self.torrserver.add(prep.release.magnet)
            files = self.torrserver.wait_files(
                prep.torrent_hash,
                timeout=self.meta_budget,
                grace=prep.contact_wait or 0.0,
            )
            prep.files = files
            prep.meta = time.monotonic() - prep.started
            mark("метаданные", релиз=prep.number, картина=plan.picture.key)
            prep.video = self.choose(plan, prep.release, files)
            prep.phase = "дорожки"
            began = time.monotonic()
            source = self.torrserver.stream_url(prep.torrent_hash, prep.want.index)
            # Всё, что показ прочитает из роя первым, читается здесь и сейчас: карта
            # опорных кадров (без неё нет сетки) и начало файла (его читает ffmpeg). Это
            # самая ранняя секунда, когда известен файл, - то есть параллельно и ffprobe,
            # и вопросам человека. Показ потом либо берёт готовое, либо
            # дожидается этого же чтения, а не начинает своё вторым потоком.
            warm_file(source, alive=lambda: not prep.dropped, name=prep.want.name)
            prep.media = probe(
                source,
                timeout=self.probe_budget,
                alive=(
                    None
                    if prep.patient
                    else swarm_pulse(source, SWARM_GRACE, wait=prep.contact_wait)
                ),
            )
            prep.read = time.monotonic() - began
            mark("ffprobe", релиз=prep.number, картина=plan.picture.key)
            prep.phase = "готово"
        except TorrcastError as exc:
            prep.error = str(exc)
            prep.failure = exc
            prep.phase = "сбой"
        finally:
            prep.ready.set()
            if prep.dropped:  # пока грелись, показ ушёл к другому релизу
                self._forget(prep)


def _default_file(plan: _Plan, release: Release, files: list[TorrFile]) -> TorrFile:
    """Фильму — самый крупный видеофайл, сериалу — файл нужной серии."""
    return plan.series.choose(release, files) if plan.series else pick_video_file(files)


def _file_picker(args: Args) -> Callable[[_Plan, Release, list[TorrFile]], TorrFile]:
    """``--file N`` — отладочная ручка: взять N-й видеофайл раздачи."""
    if args.file is None:
        return _default_file

    def chosen(plan: _Plan, release: Release, files: list[TorrFile]) -> TorrFile:
        ordered = sorted(files, key=lambda f: f.index)
        videos = [f for f in ordered if f.name.lower().endswith(VIDEO_EXT)]
        if not 1 <= (args.file or 0) <= len(videos):
            raise NotFoundError(f"видеофайлов в раздаче {len(videos)}, номера {args.file} нет")
        return videos[(args.file or 1) - 1]

    return chosen


@dataclass(slots=True)
class _Resume:
    """Прогрев под вопросом «Продолжить?» — то же, что прогрев под меню, но для позиции.

    Продолжение с середины упирается не в поиск (его тут нет вовсе), а в рой: показу
    нужны заголовок файла и то место, где лежит сохранённая позиция, а холодная раздача
    отдаёт новое место секундами. Единственная свободная секунда на этом пути — та, пока
    человек читает вопрос, и она тут и тратится.

    Смещение позиции в байтах берётся из карты опорных кадров
    (:meth:`torrcast.stream.FilmKeys.byte_at`) — той же самой, по которой строится сетка.
    Пропорция «доля фильма от размера файла» сюда не годится: битрейт по фильму гуляет
    вдвое, и промах в проценте — это десятки мегабайт, то есть прогрев не того места.
    """

    torrserver: TorrServer
    entry: Entry
    source: str = ""
    cancelled: bool = False
    #: Хэш поднятой раздачи. Нужен ровно затем, чтобы её было чем убрать: раздачи с
    #: ``save_to_db: false`` в списке TorrServer не видны, и «снести всё из list» снесло бы
    #: чужое (:meth:`_Bench.drop_all` убирает своё по тем же явным хэшам).
    torrent_hash: str = ""
    #: Показа не будет: поднятое надо убрать, даже если подъём ещё в пути.
    discarded: bool = False

    def start(self) -> None:
        threading.Thread(target=self._work, daemon=True).start()

    def _work(self) -> None:
        with contextlib.suppress(TorrcastError):
            self.torrent_hash = torrent_hash = self.torrserver.add(self.entry.magnet)
            if self.discarded:  # отказались, пока раздача поднималась - убираем её сами
                if not _held_by_show(torrent_hash):  # ...но не из-под живого показа
                    self.torrserver.drop(torrent_hash)
                return
            files = self.torrserver.wait_files(torrent_hash)
            self.source = self.torrserver.stream_url(torrent_hash, self.entry.file_idx)
            # Имя файла - подсказка о контейнере для грелки головы: карта, снятая прошлой
            # версией, лежит в кэше без него (:func:`torrcast.stream.container_of`).
            name = next((f.name for f in files if f.index == self.entry.file_idx), "")
            warm_file(self.source, at=self.entry.pos, alive=lambda: not self.cancelled, name=name)

    def enough(self) -> None:
        """Ответ получен — прогрев прекращается, дальше те же байты читает сам показ.

        ⚠️ Это не мелочь и не гигиена, а замер. Прогрев, доигрывающий после Enter'а, —
        это **второй** читатель того же места через TorrServer, и он отбирает у показа
        ровно то, ради чего затевался: в замере пробный прогон вырос с 0.56
        до 1.92 с, а готовность LOAD — с 3.5 до 4.8 с. Смысл прогрева весь в секундах
        ДО ответа; после ответа лучший потребитель полосы — ffmpeg.

        «Сначала» отменяет прогрев по той же причине, только резче: середина фильма
        больше не нужна вовсе.
        """
        self.cancelled = True

    def discard(self) -> None:
        """Показа не будет вовсе — поднятую раздачу убрать по ЕЁ хэшу.

        Ровно два таких выхода: Ctrl-C на вопросе и ``--dry`` (он и заведён затем, чтобы
        ничего не начиналось и следов не оставалось). Раздача при этом уже поднята, а
        живёт она не в нашем процессе: наш умрёт, а она останется качать метаданные в
        чужой RAM до перезапуска TorrServer — та же беда, что у прогрева под меню
        (:meth:`_Bench.drop_all`).

        ⚠️ Ответ «сначала» сюда не относится: раздача та же самая, меняется только место,
        с которого играем, — убрать её значило бы сломать показ.

        И ту же раздачу, что держит параллельный живой показ (та же выдача, тот же
        infohash), тоже не трогаем: снос выдернул бы источник из-под экрана
        (:func:`_held_by_show`). Гонку с ещё не завершённым ``add`` ловит :meth:`_work`.
        """
        self.cancelled = True
        self.discarded = True
        if self.torrent_hash and not _held_by_show(self.torrent_hash):
            self.torrserver.drop(self.torrent_hash)


def _resume(config: Config, key: str, entry: Entry, clock: _Clock, dry: bool = False) -> int:
    """Возобновление: один вопрос и сразу показ. Релиз, файл и дорожка берутся из
    состояния — ни поиска, ни меню, поэтому старт укладывается в 5–15 с.

    Пока задаётся вопрос, раздача уже поднята в TorrServer, а рой прогрет по месту
    сохранённой позиции (:class:`_Resume`): к Enter'у критический путь чаще всего пуст.
    """
    warm = _Resume(TorrServer(config.torrserver_url), entry)
    warm.start()
    question = f"«{entry.title}» остановились на {_hms(entry.pos)}. Продолжить? [Да/сначала]"
    try:
        answer = ask_line(question)
    except BaseException:  # Ctrl-C на вопросе - показа не будет, а раздача уже поднята
        warm.discard()
        raise
    warm.enough()
    mark("рой прогрет")  # TC-108: замер
    if answer[:1] in {"с", "s", "н", "n"}:  # «сначала» / «с начала» / «нет»
        entry.pos = 0.0
    if dry:  # показа не будет: своё поднятое убираем сами, чужого не трогаем
        warm.discard()
    mark("ответы")  # ноль секундомера: Enter после последнего вопроса
    return _launch(config, key, entry, _about(entry), clock, dry)


def _launch(
    config: Config, key: str, entry: Entry, about: str, clock: _Clock, dry: bool = False
) -> int:
    """Показ уезжает в transient-юнит: ``cast`` завершился — показ продолжается."""
    if dry:
        print(f"(--dry) {about} - каста нет")
        return EXIT_OK
    _refuse_hopeless(config, entry)
    # Сначала гасим прошлый показ и только потом пишем свою запись: умирающий юнит по
    # SIGTERM дописывает СВОЮ позицию, и записанный раньше прыжок на s1e5 он бы затёр.
    stop_play_unit()
    state = State.load()
    # Темнота прошлого показа новому не наследуется. Снимает отметку тот же сторож, что
    # её ставит (:attr:`torrcast.state.Entry.dark`), но у убитого по SIGKILL юнита сторожа
    # не было вовсе, а у нового она снимается только с первого опроса приёмника - и до
    # него `cast status` звал бы погасшим показ, который прямо сейчас поднимается.
    entry.dark, entry.dark_why = 0.0, ""
    state.put(key, entry)
    state.save()
    forget_playing(Path(config.hls_dir))  # флажок прошлого показа нам не доказательство
    start_play_unit(key)
    mark("юнит")
    with Progress() as progress:
        _await_playing(config, progress)
    print(f"играю {about} - на ТВ   (старт {clock.total:.0f} с)")
    return EXIT_OK


def _refuse_hopeless(config: Config, entry: Entry) -> None:
    """Отказать ДО юнита, если этой записи на этом приёмнике картинки не видать.

    🔴 Случай ровно один, и он живой (TC-157): кадр 4К приёмник не берёт вовсе - ни в
    чужом кодеке, ни в своём. Замер 09-08-2026 на Q70D: пять заходов LOAD, каждый —
    ``IDLE/ERROR`` сразу после первого сегмента, картинки нет ни разу
    (:attr:`torrcast.profile.Profile.recode_frame`).

    ⚠️ TC-222 сузил проверку до одного условия, и это не ослабление. Ужать кадр вниз
    умеет сплошной перекод - значит отказывать надо не «большому кадру», а большому кадру
    БЕЗ перекода: ``recode: false`` в настройках. С включённым перекодированием ровно та
    же запись теперь играется - 2160p уезжает на приёмник как 1080p.

    Отбор такие релизы отбраковывает сам (:meth:`_Bench._trouble`), но мимо отбора ведут
    две двери: ``--release N`` / ``--file N`` (там человек выбрал сам, и подмен не бывает)
    и продолжение записи, попавшей в состояние через них же. Без этой проверки обе
    кончались одинаково: 86 с «жду телевизор», код 2 и ни слова о причине. Теперь
    причина печатается за доли секунды, а ffmpeg и раздача не поднимаются вовсе.

    Молчим там, где не знаем: кадр ноль — это записи прежних версий, они играются
    как раньше.
    """
    profile = detect_profile(config).profile
    if not entry.frame or entry.frame <= profile.recode_frame:
        return
    if config.recode:
        return
    raise NotFoundError(
        f"{entry.quality or f'{entry.frame}p'} - такой кадр приёмник берёт только ужатым, "
        f"а перекодирование выключено: нужен релиз {profile.recode_frame}p или ниже"
    )


def _await_playing(config: Config, progress: Progress, timeout: float = START_BUDGET) -> None:
    """Дождаться **картинки на экране**, а не «упаковка пошла».

    Две разные вещи, которые легко счесть одной: первый сегмент в tmpfs — это упаковка, а
    картинка — это приёмник, ответивший ``PLAYING``. Спросить приёмник отсюда нельзя:
    сендер к нему должен быть ровно один, и он живёт в юните (см. :mod:`torrcast.cast`).
    Поэтому юнит кладёт флажок (:func:`mark_playing`), а CLI его ждёт — и печатает
    «старт NN с» ровно в тот момент, когда на экране появилось изображение.
    """
    out = Path(config.hls_dir)
    flag = playing_flag(out)
    deadline = time.monotonic() + timeout
    packed = False
    while time.monotonic() < deadline:
        if flag.exists():
            mark("картинка")
            progress.phase("")
            return
        if not packed:
            with contextlib.suppress(OSError):
                packed = any(out.glob("v*.ts"))
            if packed:
                mark("первый сегмент")
        progress.phase("жду телевизор" if packed else "упаковка")
        if not unit_active():
            progress.phase("")
            raise InfraError(f"показ не запустился: {unit_why()}")
        time.sleep(0.2)
    progress.phase("")
    stop_play_unit()
    raise InfraError(f"показ не начался за {timeout:.0f} с - {unit_why()}")


def _recoder(
    source: str,
    audio: int,
    grid: Grid,
    spare: Path,
    config: Config,
    video_mbit: float = 0.0,
) -> Recoder | None:
    """Кодировщик тяжёлых кусков или ``None``, если он не нужен и не может помочь.

    Профиль тяжести считается из уже снятой карты опорных кадров: байты и секунды каждого
    сегмента известны до упаковки, и это ноль запросов к рою. Отказ бывает честный —
    выключено настройкой, сетка не по кадрам (тогда границы не совпадут с картой), карта
    снята прошлой версией и смещений не несёт, — и о нём говорится вслух.
    """
    from torrcast.recode import Encode, Recoder, Weights
    from torrcast.stream import AUDIO_MBIT, TS_OVERHEAD, film_keys

    if not config.recode:
        return None
    if not grid.on_keys:
        print("сетка не по опорным кадрам - тяжёлые куски перекодировать не берусь", flush=True)
        return None
    try:
        keys = film_keys(source)
    except InfraError as exc:
        print(f"профиль тяжести не снят ({why(exc)}) - играю как есть", flush=True)
        return None
    # Сколько уедет на ТВ: видеодорожка идёт копией, звук всегда AAC, сверху оверхед
    # mpegts. Паспорт молчит (mp4 без тегов) - поправка наберётся по факту, как раньше.
    delivered = (video_mbit + AUDIO_MBIT) * TS_OVERHEAD if video_mbit > 0 else 0.0
    weights = Weights.of(keys, grid, delivered=delivered)
    if weights is None:
        print("карта без смещений - профиль тяжести не построить, играю как есть", flush=True)
        return None
    print(
        f"профиль тяжести: контейнер {weights.container:.1f} Мбит/с, "
        + (
            f"на ТВ уедет {delivered:.1f} (видео {video_mbit:.1f} по паспорту)"
            if delivered > 0
            else "веса видеодорожки в паспорте нет - поправку наберу по факту"
        ),
        flush=True,
    )
    return Recoder(
        source=source,
        audio=audio,
        grid=grid,
        spare=spare,
        weights=weights,
        threshold=config.recode_at_mbit,
        encode=Encode(preset=config.recode_preset, mbit=config.recode_mbit),
        ahead=config.recode_ahead,
        cache_mb=config.recode_cache_mb,
        head_wait=config.recode_head_wait,
        log=lambda text: print(text, flush=True),
    )


def _encode_all(
    config: Config,
    codec: str,
    video_mbit: float = 0.0,
    depth: int = 0,
    profile: Profile = CAUTIOUS,
    frame: int = 0,
    hdr: bool = False,
) -> Encode | None:
    """Чем перекодировать ВЕСЬ файл или ``None`` — если видео уезжает копией, как всегда.

    Решение файл-уровневое и принимается один раз, по паспорту ffprobe: приёмник либо
    декодирует поток, либо нет (:func:`torrcast.stream.recodes_whole`), и середины тут не
    бывает. Посегментное решение по весу и битрейту на таком файле давало **смешанный**
    поток H.264 и HEVC — на живом Q70D это 24 с картинки и вечная петля «залип →
    перезагрузка»: ровно на границе первого не перекодированного куска.

    🔴 Вопрос задаётся белым списком: копия достаётся ТОЛЬКО тому, что в нём названо
    (:meth:`torrcast.profile.Profile.verdict`). Пока список был чёрным, VP9 и AV1 уезжали
    в mpegts копией всюду, куда отбор не дотянулся, — на релизе, названном руками
    (``--release N``), и на записи возобновления. Приёмник такой поток не начинает вовсе:
    ``LOAD`` не взят, ``IDLE/ERROR``. Кодек, которого мы не мерили, — честный отказ
    ОТБОРА, но если файл всё же играем, он идёт сплошным перекодом, а не копией.

    ``depth`` - глубина цвета из того же паспорта (:attr:`torrcast.state.Entry.depth`).
    🔴 Спрашивается она наравне с кодеком, потому что имени кодека не хватает: Hi10P
    зовётся тем же ``h264``, а приёмник его не декодирует (:data:`COPY_DEPTH`). Ноль -
    глубину не спрашивали (запись прежней версии), решаем по одному кодеку.

    ``frame`` - ступень кадра из того же паспорта (:attr:`torrcast.stream.Media.frame`).
    🔴 TC-222. Спрашивается она наравне с кодеком и глубиной по той же причине: 2160p
    приёмник не берёт и в посильном кодеке (TC-157), а ужать кадр может только перекод.
    Поэтому кадр выше потолка приёмника - это не отказ, а сплошной перекод со скейлом
    вниз, и потолок едет в :attr:`torrcast.recode.Encode.ceiling` вместе с самим кадром:
    решение «во что ужимать» принимается здесь, один раз, до первого сегмента.

    ``hdr`` - картинка в HDR (:attr:`torrcast.stream.Media.hdr`). Тонемап включается
    только вместе с настройкой (:attr:`torrcast.state.Config.recode_tonemap`), и по
    умолчанию он выключен: замер его цены лежит там же.

    Битрейт — не потолок, а **цель**, и она считается от источника. ``recode_mbit``
    остаётся потолком, но брать его всегда нельзя: 🔴 замер на живом Q70D (TC-29,
    «Bocchi the Rock» — 1.3 Мбит/с HEVC) показал, что перекод «в 9 Мбит/с» раздувает
    лёгкое аниме в семь раз, кладёт в сегменты 18.3 и 21.4 МБ при потолке 16 и тратит
    процессор на биты, которых в источнике нет. Отсюда :data:`FULL_GAIN` — во сколько
    раз H.264 тем же ``ultrafast`` (без CABAC и почти без анализа) дороже HEVC при
    сравнимой картинке, — и :data:`FULL_FLOOR`, ниже которого 1080p разваливается.

    Второй повод для сплошного перекода — не кодек, а вес: выше
    :attr:`torrcast.state.Config.bitrate_hard_mbit` тяжёл КАЖДЫЙ кусок, и посегментный
    кодировщик выродился бы в сотню коротких ffmpeg вместо одного длинного. Живой класс,
    ради которого написано, — аниме-BD-ремуксы 1080p на 28–37 Мбит/с; замер на 4 vCPU:
    ``h264`` 37.8 Мбит/с → 9 Мбит/с идёт 3.4× реального времени, синтетический ``hevc``
    29.9 Мбит/с → 2.35×. Потолок отбора для них — ``bitrate_recode_mbit``.
    """
    if not config.recode:
        return None
    heavy = video_mbit > config.bitrate_hard_mbit
    if not recodes_whole(codec or "", depth, profile, frame) and not heavy:
        return None
    return whole_encode(
        config.recode_mbit,
        video_mbit=video_mbit,
        frame=frame,
        ceiling=profile.recode_frame,
        hdr=hdr and config.recode_tonemap,
    )


def _layout(
    config: Config,
    source: str,
    length: float,
    codec: str,
    video_mbit: float,
    say: Any = None,
    depth: int = 0,
    profile: Profile = CAUTIOUS,
    frame: int = 0,
    hdr: bool = False,
) -> tuple[Grid, Encode | None]:
    """Сетка сегментов и решение «перекодировать файл целиком» - одной парой.

    Отдельной функцией потому, что считать это приходится дважды и обязательно
    одинаково: один раз показу (:func:`_play`), другой - прогреву следующей серии впрок
    (:func:`_next_warmer`). Разойдись они хоть в одном знаке после запятой - прогретое
    легло бы под другим ключом (:func:`torrcast.warm.warm_key`), и показ, ради которого
    всё грелось, своего же прогретого не нашёл бы.

    🔴 Ровно поэтому паспорт сюда приходит целиком - кодек, глубина цвета, кадр и HDR:
    пока глубину знал один прогрев, а показ решал по имени кодека, десятибитный H.264
    уезжал на ТВ копией и вставал намертво (:func:`torrcast.stream.recodes_whole`).

    Порядок внутри тоже не случаен: сплошной перекод решается ДО сетки, потому что от
    битрейта перекода зависит вес каждого куска, а значит и то, где сетка ставит границы.
    🔴 TC-222. На ужатом 4К это перестаёт быть тонкостью и становится условием показа: под
    сплошным перекодом вес куска задаём МЫ, и считать его по карте исходника нельзя. У
    4К-исходника на 21 Мбит/с карта обещает сегменты вдвое легче наших девяти - сетка
    нарезала бы по 20 с, а наши же 9 Мбит/с положили бы в такой кусок 22 МБ при потолке
    приёмника 16 (:attr:`torrcast.profile.Profile.max_segment_bytes`). Поэтому в сетку
    едет ``fixed_mbit`` - наш битрейт, а не исходника.
    """
    from torrcast.stream import AUDIO_MBIT, TS_OVERHEAD, grid_for

    whole = _encode_all(config, codec, video_mbit, depth, profile, frame, hdr)
    grid = grid_for(
        source,
        length,
        config.hls_segment,
        config.hls_keyframes,
        say=say,
        delivered_mbit=(video_mbit + AUDIO_MBIT) * TS_OVERHEAD if video_mbit > 0 else 0.0,
        ceiling_mbit=config.recode_mbit if config.recode else 0.0,
        # Сплошной перекод: вес куска задаём мы сами, карта источника тут не судья.
        fixed_mbit=(whole.mbit + AUDIO_MBIT) * TS_OVERHEAD if whole is not None else 0.0,
        # Потолок веса куска - у каждого приёмника свой (:mod:`torrcast.profile`).
        cap=profile.max_segment_bytes,
    )
    return grid, whole


def _next_warmer(
    config: Config,
    torrserver: Any,
    torrent_hash: str,
    entry: Entry,
    profile: Profile = CAUTIOUS,
) -> Warmer | None:
    """Прогрев СЛЕДУЮЩЕЙ серии - тем же механизмом, каким грелась текущая.

    Зовётся лениво и ровно один раз: когда текущая серия уже лежит на диске целиком и
    больше не нуждается ни в одном байте раздачи (:meth:`torrcast.warm.Warmer._chain`).
    Раньше этого момента следующая серия не имеет права ни на полосу, ни на процессор.

    ⚠️ Побочный смысл этой сборки не меньше самого прогрева. Автопереход на следующую
    серию (:func:`_cmd_worker`) начинается с двух вопросов к раздаче: паспорт файла
    (:func:`probe` - длительность для порога 95 %) и карта опорных кадров
    (:func:`torrcast.stream.film_keys` - сетка и манифест). Посреди обрыва связи спросить
    их не у кого, и показ, у которого следующая серия ЛЕЖИТ на диске, всё равно уткнулся
    бы в мёртвую раздачу. Здесь оба вопроса задаются заранее и оба ложатся в кэш на диск.

    ``None`` - греть нечего: фильм, последняя серия раздачи или запись без списка серий.
    """
    from torrcast.recode import RECODE_DIR
    from torrcast.stream import hls_dir, probe

    following = entry.advance()
    if following.done or not following.label:
        return None
    source = torrserver.stream_url(torrent_hash, following.file_idx)
    media = probe(source, timeout=WORKER_DUR)
    video_mbit = max(0.0, media.video_bps / 1e6)
    # 🔴 Профиль тот же, что у показа: разойдись они - прогретое ляжет под другим ключом
    # (:func:`torrcast.warm.warm_key`), и показ своего же прогретого не найдёт.
    grid, whole = _layout(
        config,
        source,
        media.duration,
        media.video or "",
        video_mbit,
        depth=media.depth,
        profile=profile,
        frame=media.frame,
        hdr=media.hdr,
    )
    recoder = (
        None
        if whole is not None
        else _recoder(
            source,
            following.audio,
            grid,
            hls_dir(config.hls_dir) / RECODE_DIR,
            config,
            video_mbit=video_mbit,
        )
    )
    title = " ".join(filter(None, (following.title, following.label)))
    return _warmer(
        config,
        source,
        following.audio,
        grid,
        0.0,
        title,
        whole=whole,
        recoder=recoder,
        profile=profile,
    )


def _warmer(
    config: Config,
    source: str,
    audio: int,
    grid: Grid,
    start: float,
    title: str,
    whole: Any = None,
    recoder: Any = None,
    follow: Any = None,
    profile: Profile = CAUTIOUS,
) -> Warmer | None:
    """Фоновый прогрев всего фильма на диск или ``None``, если он выключен.

    🔴 **Прогрев кодирует кусок ровно тем же решением, что и живая упаковка.** Куски
    одного показа приходят приёмнику из двух мест — из окна упаковки и с диска
    (:meth:`torrcast.stream.Feed.segment`), — и для приёмника это одна лента. Разойдись
    решение о кодировании, и на стыке двух источников меняется SPS: другой профиль, другая
    энтропийная кодировка, другая глубина буфера кадров — то есть декодер обязан
    переинициализироваться посреди фильма. Поэтому решение здесь ОДНО на обоих:

    * кодек, который приёмник не декодирует, — сплошной перекод (``whole``), и у показа,
      и у прогрева;
    * тяжёлые куски — точечный перекод тем же :class:`Encode`, которым их берёт живой
      кодировщик (``recoder``), и ровно на тех же слотах;
    * всё остальное — копия.

    ⚠️ Прежде тут стояло «есть хоть один тяжёлый кусок — греть весь фильм перекодом».
    Замер на лёгком материале («Тачки 3»: 5 тяжёлых кусков из 525): живая упаковка отдавала
    копию релиза, а прогрев клал на диск сплошной ``ultrafast``, и SPS этих двух не
    совпадали ни одним байтом. Стык был не редкостью, а нормой работы — прогрев обгоняет
    показ и отдаёт ему свои куски.
    """
    if not config.warm:
        return None
    encode = whole
    spots = () if whole is not None or recoder is None else tuple(recoder.targets)
    vault = Vault(
        root=warm_root(config.warm_dir),
        key=warm_key(source, audio, grid, encode, spots),
        budget=int(config.warm_budget_gb * 1e9),
        title=title,
    )
    spot_encode = getattr(recoder, "encode", None) if spots else None
    trace.plan(
        pack="recode" if encode is not None else "copy",
        warm="recode" if encode is not None else "copy",
        spots=len(spots),
        preset=str(getattr(spot_encode or encode, "preset", "")),
        mbit=float(getattr(spot_encode or encode, "mbit", 0.0)),
    )
    return Warmer(
        source=source,
        audio=audio,
        grid=grid,
        vault=vault,
        encode=encode,
        spots=spots,
        spot_encode=spot_encode,
        began_at=grid.slot_at(start),
        # Потолок веса куска - свойство приёмника, и прогреву он нужен ровно затем, чтобы
        # «прогрето NN» называло то, что показ и правда возьмёт с диска
        # (:attr:`torrcast.warm.Warmer.warmed`, :meth:`torrcast.stream.Feed._warm`).
        cap=profile.max_segment_bytes,
        rate=config.warm_rate,
        follow=follow,
        rival=recoder,
        log=lambda text: print(text, flush=True),
    )


def _play(
    config: Config,
    source: str,
    audio: int,
    about: str,
    clock: _Clock,
    watch: Watch | None = None,
    duration: float = 0.0,
    receiver: Receiver | None = None,
    codec: str = "",
    depth: int = 0,
    follow: Any = None,
    supply: Supply | None = None,
    profile: Profile = CAUTIOUS,
    frame: int = 0,
    hdr: bool = False,
    journal: str = "",
) -> int:
    """Упаковка → раздача по http на голом IP → приёмник. Своих демонов нет: и ffmpeg,
    и раздача живут ровно на время показа и гасятся вместе с ним, что бы ни случилось.

    Упаковка за показ перезапускается столько раз, сколько человек перемотал: манифест
    обещает приёмнику весь фильм, а :class:`Feed` пакует то место, которое он попросил.
    Раздача, приёмник и LOAD при этом одни на весь показ.

    ``follow`` - чем прогреву заняться, когда эта серия ляжет на диск целиком
    (:attr:`torrcast.warm.Warmer.follow`); у фильма его нет и быть не может.

    ``supply`` - источник показа (:class:`torrcast.stream.Supply`): служба раздач и наша
    раздача в ней. Спрашивают его только на краю показа, зато прежде, чем объявить показ
    погасшим, - иначе за аварию источника отвечает приёмник, который ни при чём.

    ``profile`` - пороги ПРИЁМНИКА (:mod:`torrcast.profile`): вес куска, терпение, сторож
    нуджей, удержание запроса вместо 404. Умолчание осторожное - тот же Q70D, что и был.
    """
    from torrcast.recode import RECODE_DIR
    from torrcast.stream import hls_base, hls_dir

    out = hls_dir(config.hls_dir)
    start = watch.entry.pos if watch else 0.0
    length = watch.entry.dur if watch else duration
    tls = config.transport == "https"
    video_mbit = max(0.0, watch.entry.vbps) if watch else 0.0
    journal = journal or f"[сеанс {trace.session_id()}]"
    # Сетка сегментов снимается с самого файла и дальше не меняется: она же в манифесте,
    # она же в команде ffmpeg. Всё, что показ говорит о времени, считается по ней.
    #
    # Сетке нужен не только шаг, но и вес. Сегмент тяжелее ~19 МБ приёмник не
    # доигрывает, а выбрасывает буфер и качает его заново, поэтому граница ставится с
    # оглядкой на предсказанный вес куска - а он зависит и от паспорта (что уедет на ТВ),
    # и от того, перекодируем ли мы тяжёлое (тогда кусок не тяжелее ``recode_mbit``).
    # Кодек, который приёмник не декодирует, - это решение на весь показ, а не на кусок:
    # перекодирует сама упаковка, одним прогоном, и кодировщик тяжёлых кусков не нужен -
    # перекодировать поверх перекода нечего. Решается это ДО сетки: от битрейта перекода
    # зависит вес каждого куска, а значит и то, где сетка поставит границы.
    grid, whole = _layout(
        config,
        source,
        length,
        codec,
        video_mbit,
        say=lambda text: print(text, flush=True),
        depth=depth,
        profile=profile,
        frame=frame,
        hdr=hdr,
    )
    mark("сетка", сегментов=grid.count, покадрам=grid.on_keys)
    if whole is not None:
        # Причина перекода называется вслух: кодек с глубиной - или вес, и тогда с числом.
        # А вместе с ней и ужатый кадр: 2160p наружу уезжает как 1080p (TC-222).
        name = codec_name(codec, depth)
        print(
            recode_note(
                name,
                0.0 if recodes_whole(codec, depth, profile, frame) else video_mbit,
                frame,
                whole.out_frame,
            ),
            flush=True,
        )
        mark(
            "сплошной перекод",
            кодек=name,
            пресет=whole.preset,
            мбит=round(whole.mbit, 2),
            кадр=whole.out_frame,
            тонемап=whole.hdr,
        )
    # Профиль тяжести всего фильма известен со старта - он считается из уже снятой
    # карты опорных кадров и не стоит ни одного запроса к рою. Тяжёлые куски кодировщик
    # начнёт перекодировать сразу, пока играет остальное.
    recoder = (
        None
        if whole is not None
        else _recoder(
            source,
            audio,
            grid,
            out / RECODE_DIR,
            config,
            video_mbit=video_mbit,
        )
    )
    # Прогрев поднимается ПОСЛЕ старта показа (ниже), а собирается здесь: ему нужны и
    # сетка, и решение о перекодировании - те же, что у живой упаковки.
    warmer = _warmer(
        config,
        source,
        audio,
        grid,
        start,
        about,
        whole=whole,
        recoder=recoder,
        follow=follow,
        profile=profile,
    )
    feed = Feed(
        source=source,
        audio=audio,
        out=out,
        grid=grid,
        readrate=config.hls_readrate,
        burst=config.hls_burst,
        keep=config.hls_keep,
        # Сколько держать запрос вместо 404 - свойство приёмника: Q70D после 404 молчит
        # минутами, а приставка Android TV берёт следующий LOAD через девять секунд.
        wait=profile.hold_seconds,
        # Потолок веса куска нужен раздаче отдельно от сетки: прогретое на диске уезжает
        # на ТВ мимо упаковки, и взвесить его больше негде (:meth:`Feed._warm`).
        cap=profile.max_segment_bytes,
        log=lambda text: print(text, flush=True),
        recoder=recoder,
        encode=whole,
        vault=None if warmer is None else warmer.vault,
    )
    server = HlsServer(
        out, config.hls_cert, config.hls_key, port=config.hls_port, tls=tls, feed=feed
    )
    # Серт приёмнику нужен только затем, чтобы проверить нашу раздачу: по http проверять
    # нечего, и mock не должен делать вид, что что-то проверил. Готовый приёмник приходит
    # с сериалом: он один на весь юнит (см. :func:`_cmd_worker`).
    if receiver is None:
        receiver = make_receiver(
            config.receiver, config.tv or "", config.hls_cert if tls else "", profile=profile
        )
    # Сетку знает показ, а спотыкается о неё приёмник: и прыжок сторожа, и подъём после
    # отказа обязаны мерить кусками, а не секундами
    # (:meth:`torrcast.cast.ChromecastReceiver._nudge`). Приёмник живёт весь юнит и
    # достаётся следующей серии - сетка у неё своя, и назвать её надо каждой.
    if isinstance(receiver, ChromecastReceiver):
        receiver.next_cut = grid.after
    url = f"{hls_base(config)}/index.m3u8"
    try:
        server.start()
        mark("раздача")
        # Упаковку начинаем сами, не дожидаясь первого запроса: ресиверу нужен готовый
        # кусок сразу, иначе LOAD упирается в ожидание ffmpeg и старт растёт на глазах.
        if recoder is not None:
            recoder.played = start
            recoder.start()
        feed.restart(grid.slot_at(start))
        mark("упаковка пошла")
        receiver.play(url, about, at=start)
        mark("LOAD взят")
        print(f"{journal} играю {about} - на ТВ   (старт {clock.total:.0f} с)", flush=True)
        # ⚠️ Прогрев стартует ровно ЗДЕСЬ и ни строкой выше: путь до картинки он не
        # удлиняет ни на секунду - ни своим ffmpeg, ни чтением каталога. Всё, что он
        # делает, происходит уже при играющем показе и на остатке процессора.
        if warmer is not None:
            warmer.start()
        expected_end = _hold(receiver, feed, watch, warmer, supply, profile, journal=journal)
    finally:
        # Позиция фиксируется при любом исходе, включая SIGTERM, и делается это ПЕРВЫМ
        # делом: показ, доигранный до конца файла, отмечает «досмотрено» ровно здесь, а
        # приёмнику ниже нужно уже готовое состояние - по нему он и узнаёт, конец это
        # показа или стык серий.
        if watch is not None:
            watch.flush()
            trace.emit(
                "session",
                "session_end",
                pos=round(watch.entry.pos, 1),
                dur=round(watch.entry.dur, 1),
                watched=bool(watch.done),
            )
        if warmer is not None:
            warmer.stop()
            # Досмотрено (порог 95 %) - прогретое стирается: держать на диске фильм,
            # который уже посмотрели, незачем. Прерванный показ прогретое сохраняет:
            # `cast` завтра продолжит с диска и без сети.
            if watch is not None and watch.done:
                warmer.vault.clear()
                print("досмотрено - прогретое с диска убрал", flush=True)
        # ⚠️ suppress(Exception), а не TorrcastError: pychromecast на полуживом соединении
        # роняет что угодно, а ffmpeg и раздача обязаны погаснуть в любом случае - иначе
        # процесс уходит, а они остаются.
        with contextlib.suppress(Exception):
            # Показ кончился - приложение приёмника закрываем, чтобы ТВ вернулся в
            # исходное состояние: иконка Default Media Receiver иначе висит до своего
            # таймаута простоя и оттягивает автовыключение.
            # Исключение ровно одно - стык серий: следующая серия грузится в то же
            # приложение, и гасить его между ними значит моргать экраном на каждой.
            receiver.stop(quit_app=not _handover(watch))
        feed.stop()
        server.stop()

    report = getattr(receiver, "report", None)
    if report is None:
        return EXIT_OK
    print(f"{journal} {report.line()}")
    # Серию обрывают намеренно на пороге 95 % - хвост упаковки декодеру и не отдавали.
    if not report.ok and not expected_end and not (watch is not None and watch.done):
        _blame_the_end(supply)
    return EXIT_OK


def _handover(watch: Watch | None) -> bool:
    """Правда ли показ передают следующей серии, а не заканчивают.

    Порог 95 % уже записал в состояние следующую серию (:meth:`Watch.flush`), поэтому
    ответ лежит там же, где его читает :func:`_cmd_worker`, — двух разных мнений о конце
    показа быть не должно.
    """
    return watch is not None and watch.done and _following(watch.key) is not None


def _blame_the_end(supply: Supply | None) -> NoReturn:
    """Показ кончился недосмотренным - назвать виноватого, и назвать верно. Всегда бросает.

    🔴 Последняя строка показа - последняя возможность сказать правду. Досюда доходит и
    показ, который не успел сдвинуться с нуля: поднимать его некому и неоткуда
    (:class:`_Revival` без позиции не работает), - и раньше он кончался обвинением
    «приёмник не досмотрел поток» при живом приёмнике и мёртвой службе раздач. Замерено на
    стенде: перезапуск службы под показом давал ровно эту строку, и про источник в ней не
    было ни слова.

    Спросить источник тут можно спокойно: показ уже кончился, горячего пути нет, а
    человеку и следу уходит одна и та же причина.
    """
    why_source = _blamed(supply)
    if why_source:
        trace.offline(why=why_source, asked=True)
        raise InfraError(f"источник не читается ({why_source}) - показ оборван, цифры выше")
    raise InfraError("приёмник не досмотрел поток - цифры выше")


def _blamed(supply: Supply | None, clock: Clock = CLOCK) -> str:
    """Причина аварии ИСТОЧНИКА для строки человеку; пусто - источник тут ни при чём.

    ⚠️ Отличается от :func:`_asked` двумя вещами, и обе - из замеров на живой службе.

    Первая: служба, которую перезапустили, поднимается за три секунды, и к тому мгновению,
    когда показ признан погасшим, она уже отвечает. Спросить её «сейчас всё хорошо?» мало -
    хорошо стало потому, что мы сами вернули ей раздачу магнитом, а это и есть
    доказательство того, что источник падал. Такую темноту вешать на приёмник нельзя.

    Вторая: спрашивать надо не один раз. Замер (05:37:48.3 - 05:37:51.5): все три секунды
    своей остановки старая служба продолжала отвечать на ``/echo`` и отдавать список
    раздач - «мёртвой» она не выглядит НИ РАЗУ, а показ умирает как раз внутри этого окна.
    Один вопрос в момент смерти застаёт источник здоровым и врёт. Поэтому вопросов
    несколько (:data:`SOURCE_TRIES`) и растянуты они на пару выдержек: показ к этому
    моменту уже кончился, и шесть секунд на правду - куда меньшая цена, чем ложь.
    """
    for left in range(SOURCE_TRIES, 0, -1):
        why_source = _asked(supply)
        if why_source:
            return why_source
        if supply is not None and supply.restored:
            return "TorrServer перезапускался - раздачу вернул магнитом"
        if left > 1 and supply is not None:
            clock.sleep(SOURCE_PAUSE)
    return ""


def _asked(supply: Supply | None) -> str:
    """Спросить ИСТОЧНИК: что с ним не так; пусто - он в порядке (и раздача при трекерах).

    Единственное место, где показ обращается к источнику, и зовут его только с края
    показа: упаковка объявила себя мёртвой либо приёмник погасил экран. В горячем пути
    этих вопросов нет и быть не может - раздача сегментов не ждёт ни журнал, ни лишний
    запрос.

    Возврат раздачи магнитом говорится вслух ровно здесь, одной строкой и одним событием
    следа: два разных мнения о том, что сделано с источником, - это то же самое, что
    молчание.
    """
    if supply is None:
        return ""
    why_source = supply.check()
    if supply.restored:
        trace.resupply(torrent=supply.torrent_hash, ok=True)
        print("источник вернулся - раздачу добавил магнитом заново", flush=True)
    return why_source


@dataclass(slots=True)
class _Revival:
    """Показ погас - ждём факта возврата сети и поднимаем LOAD с сохранённого места.

    🔴 Терпение приёмника меньше нашего и кончается молча. Замер 09-08-2026 на живом
    Samsung Q70D: медиасессия умирает через 23.5 с стоящей картинки, а приложение висит на
    экране ещё 301 с после этого (прежние «примерно четыре минуты» были склейкой этих
    двух сроков и не равны ни одному из них). Куски, пока сессия жива, приёмник
    перезабирает сам - по HTTP, а не повторами LOAD. Строка при этом честная и позиция
    сохранена, но экран чёрный до тех пор, пока человек не сходит к консоли. Продукт
    обещает другое: «что ни запросил - оно взяло и включилось», и показ обязан пережить
    обрыв интернета сам.

    Отсюда порядок: пока приёмник тёмный, LOAD в него не летит вовсе (у него своё
    терпение, и жечь его впустую нельзя) - ждём **факта**, а не таймера:

    * фильм лёг на диск целиком - сети не нужно вовсе, поднимаем сразу;
    * прогрев принёс новые куски - источник ожил, значит и сеть вернулась;
    * раздача снова читается (:attr:`Feed.offline` пуст) - то же самое;
    * источник, которого мы СПРОСИЛИ (:class:`torrcast.stream.Supply`), снова отвечает и
      снова знает нашу раздачу - её мы к этому моменту уже вернули магнитом.

    🔴 Все эти факты - про ИСТОЧНИК, и годятся они только для темноты, в которой источник
    виноват. Когда показ бросил сам приёмник (:attr:`dropped`), они выполнены с самого
    начала - прогрев растёт, пока жив TorrServer, - и первая попытка выстреливала в
    темноту нулевой длины, то есть сгорала впустую. В такой темноте ждут приёмник, а не
    куски, - и ровно столько, сколько ему нужно на самом деле: :data:`REVIVE_DROP` до
    первого LOAD (секунды, замер) и :data:`REVIVE_PAUSE` между остальными.

    🔴 Причина темноты берётся не из воздуха и не из пустого :attr:`Feed.offline`: прежде
    чем сказать «приёмник бросил показ», показ спрашивает источник. Трёхсекундный обрыв
    службы раздач не взводил в показе ровно ничего (ни счёт оборванных прогонов, ни часы
    молчания), и обвинение доставалось приёмнику - при живом, ни в чём не виноватом
    приёмнике и мёртвом источнике.

    Всё остальное - ограждения, и каждое кончается фолбэком «гаснем честно, а `cast`
    продолжит с места»: чужой показ на приёмнике не перебивается (:meth:`Receiver._free`),
    попыток не больше :data:`REVIVE_TRIES` на обрыв с выдержкой :data:`REVIVE_PAUSE`, а
    каждая темнота - не дольше :data:`REVIVE_LIMIT`. Запас попыток отмерян обрыву, а не
    сеансу, и возвращается только вместе с минутой живой картинки (:data:`REVIVE_LIVED`):
    иначе два коротких обрыва в начале фильма оставляли бы весь остаток вечера без защиты.

    🔴 Молча это ожидание не идёт. Оно - решение показа, а не пауза в работе: пока оно
    длится, на экране чёрное, и сказано об этом числом - в журнал каждые
    :data:`SAY_SECONDS` (сколько уже темно, из-за чего и через сколько показ сдастся) и
    отметкой в состоянии, откуда ту же правду берёт ``cast status``
    (:attr:`torrcast.state.Entry.dark`). Замер, из которого это выросло: с мёртвым
    источником юнит прожил 902 с, и всё это время «играю» отвечали и статус, и живой юнит.
    """

    #: С какого монотонного момента длится темнота; ``0.0`` - показ идёт.
    since: float = 0.0
    #: То же начало темноты, но стенным временем - метка для ЧУЖОГО процесса
    #: (:attr:`torrcast.state.Entry.dark`): монотонные часы за пределами своего процесса
    #: не значат ничего (:mod:`torrcast.timing`). Внутри показа по ней не ждут ни секунды,
    #: все выдержки по-прежнему меряет :attr:`clock`.
    began: float = 0.0
    #: Из-за чего погас показ (:meth:`_why`): та же строка, что ушла человеку и в след.
    #: Пусто - темноты нет. Хранится затем, чтобы правду говорил не только тот, кто был у
    #: консоли в секунду аварии: её повторяет и журнал показа, и ``cast status``.
    why: str = ""
    #: Сколько попыток подъёма потрачено на ТЕКУЩИЙ обрыв. Пережитый обрыв запас
    #: возвращает, но только вместе с доказательством - минутой живой картинки
    #: (:data:`REVIVE_LIVED`, :meth:`alive`).
    tries: int = 0
    #: Монотонное время последней попытки - от него отсчитывается :data:`REVIVE_PAUSE`.
    last: float = 0.0
    #: Сколько было прогрето, когда погасли: рост этого числа и есть «куски пошли».
    warmed: float = 0.0
    #: Источник показа или ``None`` (показ не из раздачи либо старый вызов). Спрашивается
    #: только отсюда и только в темноте: пока картинка идёт, вопросов источнику нет.
    supply: Supply | None = None
    #: Правда ли темнота случилась из-за ИСТОЧНИКА, а не приёмника: тогда и возврата ждём
    #: от источника, а не от :attr:`Feed.offline`, который в этом случае может быть пуст.
    blamed: bool = False
    #: Обратное: источника в этой темноте не винят вовсе - показ бросил сам приёмник
    #: (:meth:`_why`). Тогда ждать «куски пошли» бессмысленно, ждём ЕГО (:meth:`resurrect`).
    dropped: bool = False
    #: С какого монотонного момента показ снова идёт после темноты; ``0.0`` - либо темноты
    #: не было вовсе, либо запас попыток уже возвращён.
    back: float = 0.0
    #: Выдержка между попытками подъёма, секунды: мера молчания приёмника после 404
    #: (:attr:`torrcast.profile.Profile.revive_pause`). Умолчание - осторожный профиль.
    pause: float = REVIVE_PAUSE
    #: Выдержка до ПЕРВОЙ попытки в темноте, которую устроил сам приёмник, секунды: сколько
    #: ему нужно, чтобы снова взять LOAD (:attr:`torrcast.profile.Profile.revive_drop`).
    #: У разных приёмников она разная, поэтому приходит из профиля, а не из общей константы.
    #:
    #: ⚠️ Отсчёт - ОТ НАЧАЛА ТЕМНОТЫ, а не от приговора: прежде чем назвать виноватым
    #: приёмник, показ секунд шесть опрашивает источник (:data:`SOURCE_TRIES` вопросов с
    #: :data:`SOURCE_PAUSE`), и раньше конца этого опроса попытки быть не может вовсе -
    #: виновник ещё не назван. Значения меньше этих секунд потому сходятся в одно
    #: поведение - «сразу, как стало ясно, кто виноват» (живой замер: первая попытка
    #: вышла на 8.1 с, а не на 4.0). Это не сломанная ручка: собственный срок приёмника
    #: (3-4 с, замер) тоже идёт от начала темноты, и к концу опроса он уже истёк, а
    #: перенос отсчёта на момент приговора добавлял бы эти секунды чёрного экрана
    #: сверху - впустую, готовый приёмник ждал бы нас, а не мы его.
    drop: float = REVIVE_DROP
    #: Попытки закончились штатным фолбэком: позиция сохранена, показ можно продолжить.
    ended: bool = False
    #: Сколько показ должен идти живым, чтобы запас попыток снова считался полным.
    #: Меньше :attr:`pause` брать нельзя - см. :data:`REVIVE_LIVED`.
    lived: float = REVIVE_LIVED
    #: Чем меряется темнота и выдержка между попытками. Умолчание - настоящее время;
    #: сухой прогон подаёт свои часы (:class:`torrcast.timing.Clock`).
    clock: Clock = CLOCK

    def alive(self, shown: bool = True) -> None:
        """Показ идёт - темноте конец, а пережитый обрыв возвращает потраченный запас.

        Возвращает запас не сам факт подъёма, а прожитое после него время
        (:data:`REVIVE_LIVED`): «поднялся» говорит приёмник, а «обрыв позади» - только
        картинка, которая идёт и не гаснет. Замер, из которого это выросло: два коротких
        обрыва за 13 минут показа выбрали все три попытки, отмерянные на весь сеанс, -
        притом что каждый обрыв показ пережил и человек не заметил ничего.

        ``shown`` - на экране КАДР, а не ожидание его. ``BUFFERING`` темнотой не считается
        (показ жив, приёмник ждёт кусок), но и доказательством пережитого обрыва быть не
        может: картинки в нём нет ни секунды, а сторож подвиса в это время гонит указатель
        вперёд. Встала картинка - минуту живого показа считаем заново.
        """
        now = self.clock.monotonic()
        if self.since:
            self.since, self.blamed, self.dropped = 0.0, False, False
            self.began, self.why = 0.0, ""  # темноты нет - и отметки о ней тоже
            self.back = now  # темнота кончилась - засекаем прожитое
        if not self.back:
            return  # обрыва не было вовсе - и возвращать нечего
        if not shown:
            self.back = now
        elif now - self.back >= self.lived:
            self.back, self.tries = 0.0, 0

    def darkness(self) -> float:
        """Сколько длится темнота, секунды; ``0.0`` - на экране картинка.

        Отсюда правду о чёрном экране узнают оба, кто обязан её сказать: журнал показа
        (строка вместо «экран: … · IDLE») и через состояние - ``cast status``.
        """
        return self.clock.monotonic() - self.since if self.since else 0.0

    def resurrect(self, receiver: Receiver, feed: Feed, warmer: Warmer | None, pos: float) -> bool:
        """``True`` - показ ещё держим (ждём сеть или только что подняли), ``False`` - гаснем.

        ``pos`` - место, откуда поднимать: последняя позиция, которую приёмник успел
        назвать живой. Из мёртвой сессии её не взять - там ноль.
        """
        now = self.clock.monotonic()
        if not isinstance(receiver, _Revivable) or pos <= 0:
            return False  # поднимать нечем или неоткуда - это обычный конец показа
        if feed.duration > 0 and pos >= feed.duration * WATCHED_RATIO:
            return False  # фильм досмотрен: гаснущий экран тут и есть титры, а не авария
        if not self.since:
            self.since, self.warmed = now, warmer.warmed if warmer is not None else 0.0
            why = self._why(feed)
            self.began, self.why = time.time(), why
            trace.dark(pos=pos, why=why)
            print(
                f"показ погас на {_hms(pos)} ({why}) - подниму сам, как вернётся сеть",
                flush=True,
            )
        dark = now - self.since
        if self.tries >= REVIVE_TRIES or dark > REVIVE_LIMIT:
            print(
                f"показ поднять не удалось ({self.tries} попыт., темнота {dark:.0f} с) - "
                f"гашу; cast продолжит с {_hms(pos)}",
                flush=True,
            )
            self.ended = True
            return False
        if not self._may(feed, warmer, pos) or (self.last and now - self.last < self.pause):
            return True  # сети всё ещё нет либо выдержка между попытками не вышла
        if self.dropped and dark < self.drop:
            # 🔴 Показ бросил сам приёмник, источник цел - и признаки «сеть вернулась»
            # про приёмник не говорят ровно ничего. Прогрев в этот момент растёт всегда
            # (служба раздач жива, куски идут), :attr:`Feed.offline` пуст всегда - поэтому
            # первая попытка выстреливала в темноту нулевой длины и сгорала впустую.
            # Ждать тут можно одно - самого приёмника, а мера его молчания - время.
            #
            # ⚠️ Времени этого - секунды, а не минута: приёмник, бросивший показ, берёт
            # LOAD через 3-4 с (:data:`REVIVE_DROP`), и минута ожидания была минутой
            # чёрного экрана впустую. Осторожность живёт дальше по коду - в выдержке между
            # попытками со второй (:attr:`pause`), где она и заработана замером.
            return True
        self.tries, self.last = self.tries + 1, now
        came = "приёмник отмолчался" if self.dropped else "сеть вернулась"
        print(f"{came} - поднимаю показ с {_hms(pos)} (попытка {self.tries})", flush=True)
        ok = receiver.replay(pos)
        trace.revive(pos=pos, tries=self.tries, waited=dark, ok=ok)
        print(
            f"показ поднят с {_hms(pos)}"
            if ok
            else "приёмник показ не взял - жду ещё (или он занят чужим показом)",
            flush=True,
        )
        return True

    def _why(self, feed: Feed) -> str:
        """Из-за чего погас показ. Прежде чем винить приёмник, спрашиваем ИСТОЧНИК.

        Порядок именно такой. Приёмник гаснет молча и одинаково - и когда он сам исчерпал
        терпение, и когда ему нечего показывать, потому что источника не стало. Свои
        признаки показа тут не помощники: обрыв службы раздач на три секунды не взводит ни
        счёт оборванных прогонов, ни часы молчания (:data:`torrcast.stream.MUTE_SECONDS`), и
        :attr:`Feed.offline` остаётся пустым. Вопрос источнику стоит двух запросов и
        задаётся ровно один раз - в тот момент, когда показ уже признан погасшим.

        Причина возвращается одной строкой, и она же уезжает и в след, и человеку на
        экран: двух разных мнений о том, что случилось, быть не должно.
        """
        why_source = _blamed(self.supply, self.clock)
        if why_source:
            self.blamed = True
            if why_source != str(feed.offline):  # об одной аварии след пишет один раз
                trace.offline(why=why_source, asked=True)
            # Показ узнаёт причину от нас: дальше по ней живёт и упаковка (пробовать
            # реже, не умирать), и сам :class:`_Revival` (:meth:`_may`).
            feed.offline = why_source
            return why_source
        if feed.offline:
            return str(feed.offline)
        # Источник спрошен и здоров, упаковка на обрыв не жаловалась - винить некого,
        # кроме приёмника. Возврата в такой темноте ждут от него же (:meth:`resurrect`).
        self.dropped = True
        return "приёмник бросил показ"

    def _may(self, feed: Feed, warmer: Warmer | None, pos: float) -> bool:
        """Вернулась ли сеть - по факту, а не по часам.

        Прогретое сильнее любого признака сети: лежащий на диске фильм смотрится и без
        интернета вовсе, и ждать его возврата было бы враньём.

        Когда погасли из-за источника, спрашиваем ровно его же: :attr:`Feed.offline` в
        этом случае снимает только выложенный кусок, а выкладывать некому - упаковка ждёт
        запроса приёмника, а приёмник тёмен. Заодно это единственное место, где раздача
        возвращается магнитом: служба ответила - значит, самое время вернуть ей трекеры,
        и сделать это надо ДО того, как приёмник попросит поток по голому хэшу.
        """
        if warmer is not None:
            if warmer.done:
                return True
            if warmer.warmed > self.warmed:
                return True
        if self.blamed and self.supply is not None:
            if _asked(self.supply):
                return False  # источник всё ещё лежит - жечь терпение приёмника незачем
            feed.offline = ""
            self.why = "источник вернулся - жду готовности потока"
            # Ответ службы доказывает возврат источника, но не готовность потока. После
            # повторного добавления раздача ещё собирает метаданные и пиров; LOAD имеет
            # смысл лишь тогда, когда упаковка уже отдала кусок у сохранённой позиции.
            return feed.front(pos) > pos
        return not feed.offline


def _hold(
    receiver: Receiver,
    feed: Feed,
    watch: Watch | None = None,
    warmer: Warmer | None = None,
    supply: Supply | None = None,
    profile: Profile = CAUTIOUS,
    clock: Clock = CLOCK,
    journal: str = "",
) -> bool:
    """Держим показ: опрос приёмника раз в 2 с, упаковка должна быть жива, из RAM уходит
    только пройденное, сторож раз в 10 с пишет позицию.

    Перемотку здесь ловить больше нечем и незачем: приёмник видит весь фильм и на seek
    просто просит сегмент нужного места, а :class:`Feed` пакует оттуда.
    Показу остаётся то, о чём раздача не знает: пауза на пульте и конец показа.

    Придерживать ffmpeg сигналом (SIGSTOP) здесь больше нечем и незачем: темп держит
    сам ffmpeg (``-readrate`` + ``-readrate_initial_burst``), а под паузой процесс
    именно завершается — под SIGSTOP'ом приёмник намертво вис в BUFFERING.

    ``clock`` - чем меряются все выдержки показа (:class:`torrcast.timing.Clock`). Боевой
    путь ходит по настоящему времени; сухому прогону нужны свои часы, иначе тест выжидал
    бы терпение приёмника и выдержки между попытками подъёма по-настоящему.
    """
    paused, said, seen = 0.0, 0.0, False
    journal = journal or f"[сеанс {trace.session_id()}]"
    #: Позиция приёмника с прошлого опроса - от неё считается запас показа. Прошлая, а не
    #: сегодняшняя, потому что запас нужен раньше, чем приходит ответ приёмника, и взять
    #: его больше неоткуда. На решение сторожа это не влияет: нудж срабатывает только
    #: после :attr:`STALL_SECONDS` неподвижности, то есть когда прошлая позиция и есть
    #: сегодняшняя. А сразу после перемотки, где число ещё старое, позиция изменилась -
    #: и счётчик подвиса обнулён.
    last = 0.0
    #: Последний кадр, который человек ДЕЙСТВИТЕЛЬНО видел. Ровно оттуда показ и
    #: поднимают (:class:`_Revival`), и ровно он уходит в закладку «Продолжить?»:
    #: у мёртвой сессии позиции нет вовсе, там ноль.
    #:
    #: 🔴 ``BUFFERING`` в закладку не идёт, и это не придирка к состоянию: картинки на
    #: экране в нём нет, а позиция при этом двигается. Сторож подвиса
    #: (:meth:`torrcast.cast.ChromecastReceiver._nudge`) прыгает вперёд по 8 с, вытаскивая
    #: приёмник из зависания, и туда же смотрит повтор LOAD посреди показа. Замерено на
    #: живом Q70D: пока экран стоял на 2:39, сторож сделал 12 прыжков и увёл позицию на
    #: 4:15 - и показ воскресал с места, которого зритель не видел, ровно на 1:36 впереди
    #: последнего кадра. Сторож при этом прав, а закладка - нет: место показа отмеряет
    #: глаз, а не указатель.
    #:
    #: ``IDLE`` не идёт по другой причине: у мёртвой сессии позиции нет вовсе, там ноль.
    #: Всё остальное - показанный кадр: и пауза (на экране стоит он же), и честно
    #: доигранный конец входа. Штатная перемотка человеком тоже: после неё приёмник
    #: возвращается в ``PLAYING``, и первый же показанный кадр двигает закладку за ним.
    held = 0.0
    #: Позиция, на которой приёмник ВПЕРВЫЕ сказал ``PLAYING``; ``-1`` - ещё не говорил.
    #:
    #: 🔴 Слово состояния приходит раньше картинки, и разница не мелочь. Замер на живом
    #: Q70D (заход в тяжёлое место, сплошной перекод): приёмник отвечает ``PLAYING`` на
    #: 8.2-й секунде, а указатель стоит на месте захода ещё 6.0 с и трогается только
    #: тогда, когда показ выложил ВТОРОЙ кусок. Тот же прогон на другой сетке: ``PLAYING``
    #: на 10.4-й секунде, первый кадр - на 15.4-й. То есть каждое наше «старт NN с» было
    #: занижено на 5-6 с, и занижено ровно там, где человеку хуже всего - на тяжёлом месте.
    #: Отсюда правило: картинку доказывает ДВИЖЕНИЕ указателя, а не слово приёмника.
    still_at = -1.0
    show_trace = bool(os.environ.get(TRACE_ENV))
    buffering = was_offline = False
    # Обе выдержки воскрешения - мера молчания ПРИЁМНИКА, поэтому приходят из его профиля,
    # а не из общей константы: приставка после отказа берёт LOAD не так, как телевизор.
    revival = _Revival(
        supply=supply,
        pause=profile.revive_pause,
        lived=profile.revive_pause,
        drop=profile.revive_drop,
        clock=clock,
    )
    while True:
        _ctl(receiver)
        # Выкладка кусков стоит на пути запроса сегмента, а запросов может не быть вовсе:
        # показ, который берёт прогретое с диска, к упаковке не обращается, и написанное
        # ею копится в памяти (:meth:`torrcast.stream.Feed.sweep`). Поэтому её зовут ещё и
        # по часам показа - здесь, до всякого разговора с приёмником.
        feed.sweep()
        if trouble := feed.trouble():
            # 🔴 Упаковка сдалась - и вот теперь спрашиваем ИСТОЧНИК. Оборванные подряд
            # прогоны значат «показывать нечего» только при живом источнике; служба
            # раздач, которую перезапустили, рвёт вход так же, а ждать её три секунды.
            # Вопрос задаётся здесь, на краю показа, а не в горячем пути: раздача
            # сегментов не ждёт ни журнал, ни лишний запрос.
            why_source = _asked(supply)
            if why_source:
                feed.stall(why_source)  # показ не умирает, а ждёт возврата источника
                if not was_offline:  # говорим об аварии один раз, а не каждые две секунды
                    was_offline = True
                    trace.offline(why=why_source, asked=True)
                    print(
                        f"источник не читается ({why_source}) - жду его возврата, "
                        "показ подниму сам",
                        flush=True,
                    )
                clock.sleep(2.0)
                continue
            if supply is not None and supply.restored:
                # Источник вернулся ровно сейчас, и раздача у него снова с трекерами:
                # хоронить показ на этом месте было бы враньём - упаковка попробует ещё.
                feed.stall("")
                clock.sleep(2.0)
                continue
            # Убитый сигналом ffmpeg ничего сказать не успевает - не выдумываем за него.
            raise InfraError(f"упаковка оборвалась: {trouble}")
        try:
            # Запас упаковки идёт приёмнику: неподвижный BUFFERING при готовых сегментах
            # впереди - это зависание, а при пустых - законное ожидание нас.
            position = receiver.position(feed.front(last))
        except InfraError:  # приёмник позицию не отдаёт - показу остаётся только ждать
            clock.sleep(2.0)
            continue
        last = position.pos
        if position.pos > 0 and position.state not in {"BUFFERING", "IDLE"}:
            held = position.pos
        if not seen and position.state == "PLAYING":
            # Картинка на экране - теперь CLI имеет право сказать «старт NN с». Право это
            # даёт СДВИНУВШИЙСЯ указатель, а не слово ``PLAYING`` (см. :data:`still_at`):
            # приёмник объявляет себя играющим, ещё не набрав кадров, и на тяжёлом заходе
            # держит указатель на месте старта секунд шесть. Цена честности - один опрос
            # (2 с) запаса в худшую сторону; цена прежней доверчивости была 5-6 с в лучшую.
            if still_at < 0:
                still_at = position.pos
            elif position.pos > still_at:
                seen = True
                mark_playing(feed.out)
        # Ребуфер - только вход в BUFFERING, а не каждый опрос: иначе счётчик считал бы
        # секунды подвиса, а не сами подвисы. Сеть - на переходе в offline и обратно.
        if position.state == "BUFFERING" and not buffering:
            trace.emit("play", "buffering", pos=round(position.pos, 1))
        buffering = position.state == "BUFFERING"
        if bool(feed.offline) != was_offline:
            was_offline = bool(feed.offline)
            if was_offline:
                # Догадка, а не ответ источника: сюда приходят обрывы, замеченные самой
                # упаковкой (:meth:`torrcast.stream.Feed._survive`, :meth:`_mute`).
                trace.offline(why=str(feed.offline), asked=False)
        if show_trace:
            front = feed.front(position.pos)
            print(
                f"{journal} запас: показ {position.pos:.0f} · упаковано {front:.0f} · "
                f"впереди {front - position.pos:.0f} с · {feed.weight() / 1e6:.0f} МБ · "
                f"расхождение с манифестом {feed.drift():.3f} с · {position.state}",
                flush=True,
            )
        if warmer is not None:
            # Приоритет живого окна держится ровно здесь: прогрев видит тот же запас, что
            # и сторож приёмника, и на просевшем замирает (:meth:`torrcast.warm.Warmer._throttle`).
            warmer.feed(feed.front(position.pos) - position.pos)
            if warmer.done and feed.rest():
                print("прогрето целиком - живую упаковку гашу, показ идёт с диска", flush=True)
        if clock.monotonic() - said >= SAY_SECONDS:
            said = clock.monotonic()
            if dark := revival.darkness():
                # 🔴 Темнота - не «показ с неподвижным указателем». Отчитываться в ней
                # позицией и запасом («экран: 0:01:12 · IDLE», «показ обеспечен до
                # 0:01:12») значит называть чёрный экран показом: кадра на нём нет ни
                # одного, а числа те же, что и у живой картинки. Поэтому строка тут своя,
                # и в ней сказано ровно то, что показ решил сам: сколько уже темно, из-за
                # чего и когда он сдастся, если источник не вернётся.
                # ⚠️ Ноль попыток в темноте - это не сломанный счётчик, а решение: пока
                # источник лежит, LOAD в приёмник не летит вовсе (:meth:`_Revival._may`).
                # Молча это выглядело как бездействие, и на потолке человек получал
                # «0 попыт.» без единого объяснения, откуда он взялся.
                spent = (
                    f"поднимал {revival.tries} из {REVIVE_TRIES}"
                    if revival.tries
                    else "источник не вернулся - приёмник не трогаю"
                )
                print(
                    f"{journal} темнота {_hms(dark)} ({revival.why}) - картинки нет; "
                    f"{spent}, погашу через {_hms(REVIVE_LIMIT - dark)}",
                    flush=True,
                )
            else:
                # Что видит приёмник, тем и отчитываемся: длительность и позиция - это
                # ровно ``duration`` и ``current_time`` из MEDIA_STATUS, снятые владеющим
                # сендером. Другого доказательства «на ТВ есть таймлайн» у нас нет.
                print(
                    f"{journal} экран: {_hms(position.pos)} из {_hms(position.dur)} · "
                    f"{position.state}",
                    flush=True,
                )
                if feed.offline:
                    # Обрыв длиннее прогретого не имеет права быть молчаливой смертью:
                    # показ говорит, докуда он обеспечен, и продолжает пробовать сеть. В
                    # темноте эта строка не печатается: обеспечивать там уже нечего.
                    print(
                        f"сети нет ({feed.offline}) - показ обеспечен до "
                        f"{_hms(feed.front(position.pos))}",
                        flush=True,
                    )
            if warmer is not None:
                print(warmer.line(), flush=True)
        if watch is not None:
            # Прогрев виден снаружи только через состояние: живой показ из другого
            # процесса не спросишь (:attr:`torrcast.state.Entry.warm`).
            if warmer is not None:
                watch.entry.warm = warmer.warmed
            # В закладку уходит показанный кадр, а не указатель приёмника: пока экран
            # стоит, сторож подвиса гонит указатель вперёд, и «Продолжить?» звало бы
            # человека туда, где он не был (см. ``held``).
            watch.see(held)
            # Тем же каналом наружу уходит и правда о чёрном экране: живой юнит показа не
            # доказывает (:attr:`torrcast.state.Entry.dark`). Пишется она не по тику
            # сторожа, а сразу на переходе - врать «играю» лишние десять секунд не за что.
            if (watch.entry.dark, watch.entry.dark_why) != (revival.began, revival.why):
                watch.entry.dark, watch.entry.dark_why = revival.began, revival.why
                watch.flush()
            if watch.done and watch.entry.serial:
                return False  # серия досмотрена - освобождаем показ под следующую
        if position.state == "PAUSED":
            paused = paused or clock.monotonic()
            if clock.monotonic() - paused > PAUSE_LIMIT:
                return False  # пауза длиной с вечер - показ окончен, юнит гасим
            if clock.monotonic() - paused > PAUSE_SECONDS and not feed.halted():
                print("пауза на пульте - упаковку гашу", flush=True)
                feed.halt()  # вернутся к показу - раздача сама начнёт паковать заново
        elif not position.playing:
            # Показ погас. Это конец только тогда, когда поднять его не удалось: обрыв
            # интернета длиннее приёмникова терпения гасит экран, а фильм и место, где
            # его смотрели, никуда не делись (:class:`_Revival`).
            if not revival.resurrect(receiver, feed, warmer, held):
                return revival.ended
            # Причину темноты добывает сам :class:`_Revival`, спрашивая источник, и в след
            # она уже легла (:meth:`_Revival._why`). Второй раз то же событие не пишем.
            was_offline = bool(feed.offline)
        else:
            # Кадр на экране или ожидание его - разница тут в том же, в чём и у ``held``:
            # запас попыток возвращает прожитая картинка, а не прожитый BUFFERING.
            revival.alive(position.state == "PLAYING")
            paused = 0.0
            if feed.recoder is not None:
                feed.recoder.played = position.pos
            feed.prune(position.pos)
        clock.sleep(2.0)


@runtime_checkable
class _Revivable(Protocol):
    """Приёмник, чей погасший показ можно поднять заново (:class:`_Revival`).

    Отдельно от :class:`Receiver` намеренно: воскрешать имеет смысл только тот приёмник,
    у которого есть собственное терпение и который его тратит. Терпение mock моделирует
    нарочно и по замерам живого ТВ (:attr:`torrcast.cast.MockReceiver.PATIENCE`) - иначе
    целый класс аварий «источник моргнул» уходил бы из-под сухих прогонов вовсе.
    """

    def replay(self, at: float) -> bool: ...


@runtime_checkable
class _Steerable(Protocol):
    """Приёмник, которым можно управлять как с пульта (:data:`CTL_ENV`)."""

    def seek(self, pos: float) -> None: ...

    def pause(self) -> None: ...

    def resume(self) -> None: ...


def _ctl(receiver: Receiver) -> None:
    """Исполнить команду диагностического пульта, если она положена (:data:`CTL_ENV`).

    Файл съедается до исполнения: команда одноразовая, и повторить её на следующем опросе
    нельзя даже при осечке приёмника — иначе одна опечатка мотала бы фильм вечно.
    """
    name = os.environ.get(CTL_ENV)
    if not name or not isinstance(receiver, _Steerable):
        return
    path = Path(name)
    try:
        line = path.read_text("utf-8").strip()
    except OSError:
        return
    path.unlink(missing_ok=True)
    if not line:
        return
    word, _, rest = line.partition(" ")
    print(f"пульт: {line}", flush=True)
    with contextlib.suppress(Exception):
        if word == "seek":
            receiver.seek(float(rest))
        elif word == "pause":
            receiver.pause()
        elif word == "play":
            receiver.resume()


def liveliness(plan: _Plan) -> int:
    """Насколько картина живая — сиды самой живой раздачи, которой картина **может играть**.

    Мерок было три, и две отброшены на живой выдаче:

    * сумма сидов по всем релизам — вытягивает картину числом раздач, а не их
      качеством: у «Матрицы» 1999 сорок релизов против одиннадцати у «Воскрешения»,
      и сумма выбрала бы первую даже с мёртвыми DVD-рипами в хвосте;
    * сиды :attr:`~torrcast.parse.Picture.best_release` — не знают ни про потолок
      битрейта, ни про образы дисков, ни про старьё, а это и есть отбор.

    Осталось честное: сиды лучшей раздачи из тех, что годны по :func:`is_candidate`.
    Негодные в счёт не идут вовсе — ни 41-гигабайтный 4K-ремукс «Тачек» 2006 на 49.9
    Мбит/с (выше потолка декодера), ни образы дисков, ни старьё, которое отсеет
    :func:`is_dated`: играть ими картина не может, и вес им не положен.

    Считалось это раньше по ОДНОМУ релизу — верху :func:`rank_releases`, — и мерка
    получалась случайной: очередь сортируется не только сидами, и наверху у картины
    стоит то, что лучше СМОТРЕТЬ, а не то, что живее. У «Мальтийского сокола» 1941
    года на верху очереди 5 сидов при 97 у годного соседа ниже, и картина с 22
    раздачами весила меньше однораздачной тёзки 1931 года на 16 сидов - дефолт
    садился на неё. Считать по одному верху было честно, пока очередь и обрывалась
    на трёх номерах; с тех пор как :meth:`_Plan.candidates` отдаёт все годные
    раздачи, показ дойдёт до любой из них, и «чем играть» — это они все.

    Ворота спрашиваются те же, что у самого плана (:attr:`_Plan.loose`), и это не
    мелочь: пока они спрашивались строго, аниме с молчаливыми именами весило ноль
    целиком — у «наруто» дефолтом меню вместо сериала на 91 сид вставал полнометражный
    «Ниндзя в стране снега» на два.

    🔴 Последняя надежда (:attr:`_Plan.last_resort`) сюда НЕ спрашивается, и это
    осознанно. Вес картины решает, какой пункт меню предложить человеку, а HEVC — не
    предпочтение, а единственный оставшийся носитель ВНУТРИ уже выбранной картины.
    Замер на кэше выдачи «синий экзорцист s1e1»: стоило дать HEVC вес, и дефолт меню
    переезжал с «Blue Exorcist» (1080p H.264, 5 сидов) на одноимённую картину с
    ``HEVC``, то есть ровно то предпочтение, которого быть не должно.
    """
    return max(
        (
            release.seeders
            for release in plan.ranked
            if is_candidate(
                release,
                plan.runtime,
                plan.warn_mbit,
                plan.loose,
                plan.hard_mbit,
                copy_hevc=plan.copy_hevc,
            )
        ),
        default=0,
    )


def fitness(plan: _Plan, dubbed: bool = False) -> int:
    """Сиды лучшей раздачи, которой картину и правда стоит смотреть; 0 - такой нет.

    От :func:`liveliness` отличается двумя условиями, и оба взяты у самого отбора, а не
    придуманы заново:

    * раздача ЖИВА - сидов не меньше :data:`ALIVE_SEEDERS`. Живость картины считается
      этим же порогом (:func:`alive_numbers`), и второго значения у слова тут нет;
    * раздача НЕ СТАРЬЁ - :func:`is_dated`. Это тот самый приговор, который отбор выносит
      каждой строке: XviD и DVDRip, названная ступень ниже :data:`HD_HEIGHT`, молчаливое
      имя при SD-битрейте.

    Нужна она там, где вопрос не «кто живее», а «состоится ли вечер вообще»: пул, в
    котором ни одной такой раздачи нет, годным не бывает (:func:`unfit_pool`), а картина
    без единой такой раздачи - тупик, и дефолт меню на неё не садится, когда рядом стоит
    живая тёзка (:func:`playable`).

    ⚠️ Порядок отбора это НЕ смягчает и не ужесточает: годность релиза по-прежнему решает
    :func:`is_candidate`, а старьё по-прежнему играется, когда другого нет вовсе. Здесь
    считается только вес картины в двух вопросах выше.

    ``dubbed`` - считать только раздачи, чьё ИМЯ обещает русскую дорожку
    (:attr:`~torrcast.parse.Release.dubbed`). Тем же словом «стоит смотреть» отвечают на
    третий вопрос - «состоится ли вечер ПО-РУССКИ» (:func:`voiceless_pool`): русская дорожка
    входит в «включилось» (TC-178), и пул без единой играбельной раздачи с нею - такой же
    тупик, как пул без единой играбельной вовсе.
    """
    return max(
        (
            release.seeders
            for release in plan.ranked
            if release.seeders >= ALIVE_SEEDERS
            and (release.dubbed or not dubbed)
            and is_candidate(
                release,
                plan.runtime,
                plan.warn_mbit,
                plan.loose,
                plan.hard_mbit,
                copy_hevc=plan.copy_hevc,
            )
            and not is_dated(release, plan.runtime)
        ),
        default=0,
    )


def liveliest(plans: list[_Plan]) -> int:
    """Номер (с единицы) самой живой картины — он же дефолт меню и первый на прогрев.

    Список остаётся хронологическим, меняется только цифра в скобках:
    «моана» печатает четыре картины и предлагает вторую, а не немую документалку
    1926 года. Равный вес — берём раннюю: при ничьей хронология и есть ответ.
    """
    return max(range(1, len(plans) + 1), key=lambda n: (liveliness(plans[n - 1]), -n))


def first_alive(plans: list[_Plan]) -> int:
    """Номер (с единицы) картины по умолчанию: **первая по хронологии, чей рой жив**.

    Смотреть франшизу начинают с начала, а не с самой обсиженной части: «тачки» — это
    просьба про «Тачки» 2006, даже когда сидов больше у «Тачек 3». Прежний дефолт
    (:func:`liveliest`) на этом и ошибался — печатал `[4]`.

    Мёртвые части при этом пропускаются, иначе Enter снова упирался бы в пустой рой:
    у «моаны» первой в хронологии стоит «Моана: романтика золотого века» 1926 года,
    немая документалка одним VHS-рипом на 5 сидов.

    Живость - **свой рой картины** (:data:`ALIVE_SEEDERS`), а не доля от самой живой
    части франшизы. Доля тут была прямой ошибкой, и стоила она классики: одна свежая
    часть с большим роем объявляла мёртвой всю остальную франшизу. Замер по живой
    выдаче: «мумия» - свежая часть 2026 года набирает сотни сидов, «Мумия» 1999 года
    при живых десятках не дотягивала до четверти от неё и пропускалась, и дефолтом
    десять прогонов из десяти вставала картина, которой человек не называл. То же
    у «хищника», «голодных игр», «дюны», «безумного макса» и «джуманджи».

    * «тачки» - 66 / 0 / 1 / 121 сид: первая часть жива своим роем и выигрывает,
      а мимо проходят «Мультачки» (одни DVD-образы, играть нечем) и «Тачки 2»,
      у которых годным верхом остался 0.4-гигабайтный HDRip «фильм о фильме» на 1 сид;
    * «моана» - 0 / 222 / 140: документалка 1926 года пропускается (годного нет вовсе),
      дефолтом становится «Моана» 2016.

    Тип, названный запросом, весит больше одноимённого соседа другого типа
    (:func:`asked_kind`): «хорошая жена s1e1» — это просьба про сериал, и дефолт
    считается среди сериалов, даже если полнометражная тёзка живее.

    Живого нет вовсе — отдаём самую живую из картин названного типа: выбирать всё
    равно не из чего, но цифра в скобках обязана на что-то указывать.
    """
    return _first_alive(plans, asked_kind(plans))


def _first_alive(plans: list[_Plan], numbers: list[int]) -> int:
    """:func:`first_alive` среди перечисленных номеров - остальные картины не в счёт."""
    if not numbers:
        return liveliest(plans)
    if alive := alive_numbers(plans, numbers):
        return backed(plans, playable(plans, alive))[0]
    return max(numbers, key=lambda n: (liveliness(plans[n - 1]), -n))


def alive_numbers(plans: list[_Plan], numbers: list[int]) -> list[int]:
    """Номера картин, у которых есть чем играть; пусто - живых нет вовсе.

    Порог - свой рой картины (:data:`ALIVE_SEEDERS`), см. :func:`first_alive`. Соседи по
    франшизе в этот вопрос не входят вовсе: «есть чем играть» - свойство самой картины,
    и чужой рой его ни подтвердить, ни отменить не может.
    """
    return [n for n in numbers if liveliness(plans[n - 1]) >= ALIVE_SEEDERS]


def playable(plans: list[_Plan], alive: list[int]) -> list[int]:
    """🔴 TC-246. Тупиковая картина уступает дефолт своей ТЁЗКЕ, которой есть чем играть.

    Тупик - это картина, у которой после отбора не осталось ни одной раздачи, годной,
    живой и не старья разом (:func:`fitness`). Порог живости она проходит честно, и
    :func:`backed` за неё тоже не берётся, когда тёзка другого типа: замер каталога -
    «Призраки» приезжают 190 строками, из них 58 HD, а дефолтом вставала одноимённая
    картина с одной SD-раздачей и без нужного сезона. То же у «Ангела» (194 строки, 68
    HD), «Убийства» (189 / 91) и «Родины» (128 / 24).

    🔴 Уступают друг другу только ТЁЗКИ - картины, которые каталог подписал ОДНИМ И ТЕМ
    ЖЕ именем. Это ограждение, а не оттенок. Соседей по франшизе правило не трогает
    вовсе: дефолт франшизы - первая живая часть, и «Тачки», у которых в каталоге одни
    DVD-образы, обязаны остаться первым пунктом, а не уступить третьей части за её
    1080p. Тёзки же - это одна и та же вещь под одним именем, хронология между ними
    ничего не значит, и человек, назвавший имя, просил ту из них, которую можно смотреть.

    ⚠️ Ранжир по качеству это не смягчает: старьё как игралось последним, так и играется,
    и картина, у которой ВСЕ тёзки тупиковые, дефолта не теряет - уступать некому.

    ⚠️ TC-192 не отменяется. «Нелюбовь» - фильм 2017 года одной живой 1080p-раздачей
    против сериала-тёзки: у фильма годная раздача есть, тупиком он не был и дефолт
    остаётся за ним.
    """
    fit = {n: fitness(plans[n - 1]) for n in alive}
    if not any(fit.values()):
        return alive
    return [
        n
        for n in alive
        if fit[n] or not any(m != n and fit[m] and _same_name(plans, m, n) for m in alive)
    ]


def _same_name(plans: list[_Plan], first: int, second: int) -> bool:
    """Одним ли именем каталог подписал две картины меню."""
    return plans[first - 1].picture.title.casefold() == plans[second - 1].picture.title.casefold()


def backed(plans: list[_Plan], alive: list[int]) -> list[int]:
    """Из живых - те, кому есть чем играть: за картиной больше одной раздачи.

    Порог живости считает сиды, и по сидам однораздачная картина обходит соседку с
    очередью на законных основаниях: у «Мальтийского сокола» 1931 года ровно одна
    раздача на 16 сид, а у «Мальтийского сокола» 1941 года лучшая ГОДНАЯ раздача из
    двадцати двух держит 28 - доля честная, порог пройден, дефолт садился на 1931 год.
    То же у «Люпена»: «Rupan sansei» 2014 года одной раздачей на 3 сида обходил «Замок
    Калиостро» с десятью раздачами.

    Но «прошла порог» и «есть чем играть» - разные вещи. Сиды в выдаче это обещание
    индексера, а не факт: раздача, которая не отдаёт ни метаданных, ни потока, числится
    в выдаче ровно так же бодро (:func:`silent_swarm`). За картиной с очередью стоит
    двенадцать таких обещаний и показ переберёт их все; за однораздачной - одно, и
    осечка на нём заканчивает вечер. Ставить дефолт на монетку, когда рядом стоит
    очередь, - это и есть «формально живая».

    Ранжировать картины числом раздач эта ступень НЕ начинает, и это важно: на том уже
    обжигались - до-вожак по числу раздач выдавал сиквел вместо основной картины.
    Порядок остаётся хронологическим, а однораздачная картина уступает не всякой очереди,
    а только той, которая её же и живее. Первая часть на 100 сид одной раздачей остаётся
    дефолтом при сиквеле с двумя раздачами на 90 - она сама и есть самое живое, что
    нашлось, и уступать ей нечему. А «Мальтийский сокол» 1931 года на 16 сид уступает
    тёзке 1941 года, у которой и раздач двадцать две, и лучшая годная живее.

    Живых с очередью нет вовсе - список остаётся как был: выбирать не из чего, и
    молчаливо превращать «живую» картину в «мёртвую» не за что.

    🔴 TC-192. Уступают друг другу картины ОДНОГО типа, и это ограждение, а не оттенок.
    Глубина очереди у сериала говорит о сериале и ровно ничего - о полнометражной тёзке:
    у сериала раздача на каждый сезон, у фильма она одна на всё кино, и мерить их одной
    линейкой значит объявлять фильм «формально живым» за то, что он фильм. Замер:
    «Нелюбовь» - фильм Звягинцева 2017 года одной раздачей на 40 сид против сериала
    «НЕлюбовь [S01]» двумя раздачами на 120, и дефолтом молча вставал сериал. Тип запрос
    называет вслух ровно одним способом (:func:`asked_kind`), и там, где он промолчал,
    подменять кино сериалом за него нельзя.
    """
    deep = [n for n in alive if len(plans[n - 1].ranked) > 1]
    if not deep:
        return alive
    return [n for n in alive if n in deep or liveliness(plans[n - 1]) > _rival(plans, deep, n)]


def _rival(plans: list[_Plan], deep: list[int], number: int) -> int:
    """Самая живая очередь СВОЕГО типа - её и обязана перебить однораздачная картина.
    Очередей своего типа нет вовсе - уступать нечему, и порог равен нулю.
    """
    kind = plans[number - 1].picture.kind
    return max(
        (liveliness(plans[n - 1]) for n in deep if plans[n - 1].picture.kind == kind), default=0
    )


def asked_kind(plans: list[_Plan]) -> list[int]:
    """Номера (с единицы) картин того типа, который назвал сам запрос.

    Тип назван вслух ровно одним способом: запрос спросил СЕРИЮ (``s1e1``). Тогда
    одноимённая полнометражка — не «вариант поживее», а другое кино, и дефолт обязан
    считаться среди сериалов. Замер по живой выдаче:

    * «хорошая жена s1e1» — дефолтом вставал ФИЛЬМ 1987 года (3 раздачи, ни одной
      живой) при сериале 2015 года на 30 раздач и 18 сид;
    * «синий экзорцист s1e1» — дефолтом вставала полнометражка 2012 года;
    * «великий из бродячих псов s1e1» — дефолтом вставал чиби-спин-офф, приехавший
      отдельными сериями и потому опознанный как полный метр.

    Сериалов в выдаче нет вовсе — считаем как считали: гейт тут не судья тому, чего
    он не видел, и пустой ответ вместо картины был бы хуже неточного типа.

    Серии запрос не называл — тип не назван, и все картины равны: «мальтийский сокол»
    одинаково может оказаться и фильмом, и сериалом, и гадать за человека нечего.
    """
    if not any(plan.asked_series for plan in plans):
        return list(range(1, len(plans) + 1))
    series = [n for n, plan in enumerate(plans, start=1) if plan.picture.kind == "tv"]
    return series or list(range(1, len(plans) + 1))


def default_note(plans: list[_Plan], asked: str = "") -> str:
    """🔴 TC-198. Одна честная строка про смену картины: «спросили X - беру Y, потому что Z».

    Молчаливая подмена КАРТИНЫ - худший вид брака, а дефолт франшизы подменяет её
    буднично: пропускает мёртвую первую часть (:func:`alive_numbers`), уходит с
    однораздачной (:func:`backed`), считается среди сериалов (:func:`asked_kind`) - и
    всё это без единого слова. В замере каталога так молча прошли десять спорных
    запросов из четырнадцати: «мумия» показывала не ту «Мумию», «дюна» - не ту «Дюну»,
    «медведь s2e7» - не тот «Медведь». Ещё у четырёх строка была, но про другое: у
    «гарри поттера» человек читал про оригинальное имя и добор сезона, пока менялась
    ЧАСТЬ франшизы.

    Строка одна, и печатается она **последней перед стартом** (:func:`_cmd_play`), а не
    среди фаз поиска: фазы уезжают вверх экрана и читаются как ход работы, а это -
    решение, которое человек обязан унести с собой.

    Пусто - взято ровно то, что назвали, и говорить не о чем. Три случая молчания
    осознанные:

    * картина одна - выбора не было вовсе;
    * человек ответил на меню сам - подмены нет, есть его выбор (сравнение с
      :func:`first_alive` делает вызывающий);
    * дефолт сел на картину, чьё имя человек и назвал, а тёзок по году у неё нет:
      «голодные игры» → «Голодные игры» (2012) - это ровно запрошенное, и строка тут
      была бы шумом. Ровно это и чинит TC-196: после него три случая из четырнадцати
      перестают быть сменой вообще.

    ``asked`` - слова человека; без них строка та же, только без головы «спросили X».
    """
    numbers = asked_kind(plans)
    picked = _first_alive(plans, numbers)
    plain = _first_alive(plans, list(range(1, len(plans) + 1)))
    head = f"спросили «{asked}» - беру" if asked else "беру"
    mine = _named(plans[picked - 1].picture)
    if len(numbers) != len(plans) and picked != plain:
        other = _named(plans[plain - 1].picture)
        return f"{head} «{mine}», а не «{other}»: спросили серию, а это другой тип"
    if passed := [n for n in numbers if n < picked]:
        other = _named(plans[passed[0] - 1].picture)
        return f"{head} «{mine}», а не «{other}»: {_passed_why(plans, passed[0], numbers)}"
    if twins := [n for n in numbers if n != picked and _namesake(plans, n, picked)]:
        others = ", ".join(f"«{_named(plans[n - 1].picture)}»" for n in twins)
        return f"{head} «{mine}»: под этим именем есть ещё {others} - другая картина"
    return ""


def swap_note(plans: list[_Plan], picked: _Plan, asked: str = "") -> str:
    """Честная строка про смену картины для ТОГО, что реально пошло на показ.

    От :func:`default_note` отличается одним вопросом: а дефолт ли это. Человек, который
    ответил на меню номером, ничего не подменял - он выбрал, и говорить ему «беру не то,
    что вы назвали» было бы враньём. Поэтому строка живёт ровно там, где картину выбрали
    за него: выбранный пункт совпал с дефолтом (:func:`first_alive`).

    Картина одна - меню не задавалось вовсе, выбора не было, и строки нет.
    """
    if not _is_default(plans, picked):
        return ""
    return default_note(plans, asked)


def _is_default(plans: list[_Plan], picked: _Plan) -> bool:
    """Встал ли выбранный план дефолтом (:func:`first_alive`), а не выбором человека.

    Человек, ответивший на меню номером, ничего не подменял - он выбрал. Строки про
    подмену (:func:`swap_note`, :func:`year_note`) живут ровно там, где картину выбрали
    за него. Картина одна - меню не задавалось вовсе, выбора не было.

    План после меню пересобирается на настоящей длительности (:func:`_timed`) и это уже
    ДРУГОЙ объект - сверка идёт по картине, идентичность тут врёт.
    """
    if len(plans) < 2:
        return False
    number = next((n for n, plan in enumerate(plans, start=1) if plan.picture is picked.picture), 0)
    return number == first_alive(plans)


def year_note(picked: _Plan, about: Origin, asked: str = "") -> str:
    """🔴 TC-199/TC-200. Честная строка, когда год дефолтной картины расходится со справкой.

    Год картины склеивается из ИМЕНИ раздачи, а имя врёт: «Оно» уезжает раздачей 2014
    года, «Медведь» - 2026-го, «Брат 2» - «Брат 2025». Гейт подмены сверял этот год со
    справкой только ВОКРУГ ДОБОРА (:func:`_second_language`), а у картины, вставшей
    дефолтом, год не сверялся нигде - и человек молча получал не тот фильм.

    Сверка та же, что у добора: независимое слово справки (:func:`~torrcast.facts.origin`,
    год выдачи ей НЕ подсказан) против года картины, с тем же допуском ±1 год (год
    производства против года проката) и той же поблажкой ремейку - совпал оригинал, значит
    та же вещь, хоть годы и врозь.

    Право у строки ровно одно - сказать вслух; ни блокировать показ, ни менять год картины
    она не вправе (TC-199/TC-200 - про честность, а не про отказ). Молчим в трёх случаях,
    и все три - ограждения:

    * справка пуста или неуверенна (``about.year is None``) - латинописанное аниме, нет
      статьи, сеть легла, год в статье назван неоднозначно. Сверять нечем, и год из имени
      остаётся единственным источником: подменять его молчанием справки нельзя;
    * год картины неизвестен (``picture.year is None``) - опровергать нечего;
    * годы сошлись (±1) или это ремейк того же оригинала - решение верное, строка была бы
      шумом.
    """
    picture = picked.picture
    if about.year is None or picture.year is None:
        return ""
    if about.title and picture.original and slugify(picture.original) == slugify(about.title):
        return ""
    if abs(picture.year - about.year) <= 1:
        return ""
    head = f"спросили «{asked}» - " if asked else ""
    return (
        f"{head}беру «{picture.title}» {picture.year} года, "
        f"но справка знает эту картину как {about.year}"
    )


def namesake_note(picked: _Plan, about: Origin) -> str:
    """🔴 TC-371. Честная строка: под этим именем и годом картин ДВЕ, а играет одна.

    Двусмысленность тут не наша: именем «Девять» и годом 2009 в русском прокате подписаны
    мюзикл ``Nine`` и мультфильм ``9``. Отбор выбирает картину по имени и году - обоими
    признаками они совпадают, - и в одну кучку их сводит сам каталог: больше в раздачах не
    сказано ничего. Развести такую пару разбору нечем, и это ровно тот случай, когда
    молчать нельзя: человек просил имя, получил одну из двух, а какую - решил вес кучки.

    Сказать об этом может только независимый источник, и он уже отвечает: справка знает
    обе картины и приносит их одним ответом (:func:`~torrcast.facts.namesake`). Строка
    называет вторую картину так, как её подписала справка, - по этому имени человек
    отличит одну от другой и спросит точнее.

    Молчим, когда сверять нечего или не о чем:

    * тёзки того же года справка не нашла - строка была бы выдумкой;
    * год картины разошёлся со справкой (допуск ±1, как у :func:`year_note`): паспорт
      приехал про ДРУГУЮ картину, и её тёзка к выбранной отношения не имеет. Про сам
      разъезд годов человек читает своей строкой.
    """
    picture = picked.picture
    if not about.namesake or about.year is None or picture.year is None:
        return ""
    if abs(picture.year - about.year) > 1:
        return ""
    return (
        f"«{picture.title}» ({picture.year}): под этим именем и годом картин две - "
        f"справка знает ещё «{about.namesake}», развести их по имени и году нечем"
    )


class _Passport:
    """Фоновый паспорт дефолтной картины: :func:`_passport` пускает, :meth:`get` забирает.

    Справка (:func:`~torrcast.facts.origin`) - независимое слово для гейта года выбранной
    картины (:func:`year_note`). Нужна она лишь к последней строке перед стартом, поэтому
    едет фоном, ровно в те секунды, что уходят на меню и прогрев. :meth:`get` дожидается
    её сам добор бюджетом ограничил, так что путь до меню она не держит.
    """

    def __init__(self, picture: Picture | None) -> None:
        self._picture = picture
        self._box: list[Origin] = []
        self._thread: threading.Thread | None = None

    def start(self) -> None:
        if self._picture is None:  # меню не было - и сверять нечего
            return
        self._thread = threading.Thread(target=self._work, daemon=True)
        self._thread.start()

    def _work(self) -> None:
        # Тип картины известен из выдачи (:attr:`Picture.kind`), и его подсказать надо:
        # у сериала и фильма разные статьи. Год выдачи - нет: см. :func:`year_note`.
        with contextlib.suppress(Exception):
            self._box.append(origin(self._picture.title, series=self._picture.kind == "tv"))  # type: ignore[union-attr]

    def get(self) -> Origin:
        thread = self._thread
        if thread is not None:
            thread.join()
        return self._box[0] if self._box else Origin()


def _passport(plans: list[_Plan]) -> _Passport:
    """Пустить фоном добор паспорта верхней картины меню (:func:`year_note`).

    Только на меню из нескольких картин: одна картина - выбора не было, сверять нечего, и
    лишнего похода к справке на счастливом однокартинном пути не случается.
    """
    default = plans[0].picture if len(plans) >= 2 else None
    holder = _Passport(default)
    holder.start()
    return holder


def _passed_why(plans: list[_Plan], number: int, numbers: list[int]) -> str:
    """Почему картина, стоящая раньше по хронологии, дефолтом не стала.

    Причины ровно четыре, и человеку они разные: «играть нечем» (годной раздачи нет ни
    одной - образы дисков, 4K сверх потолка декодера, старьё), «рой мёртв» (годная
    раздача есть, но сидов у неё столько, что это подгрузы), «живого HD нет»
    (:func:`playable`: у тёзки того же имени он есть, а тут одно старьё) и «всего одна
    раздача» (:func:`backed`: одно обещание индексера против очереди у соседки).
    """
    life = liveliness(plans[number - 1])
    if life <= 0:
        return "играть у неё нечем - ни одной годной раздачи"
    if number not in alive_numbers(plans, numbers):
        return f"рой у неё мёртв - сидов {life}"
    if not fitness(plans[number - 1]):
        return "живого HD у неё нет - одно старьё"
    return f"у неё всего одна раздача, а тут их {len(plans[number - 1].ranked)}"


def part_one_swap(plans: list[_Plan], asked: str) -> str:
    """Честная строка вместо дефолта меню, когда дефолт подменил бы часть франшизы.

    🔴 TC-373. Запрос «тачки» - это просьба про «Тачки» 2006 года, и пока первая часть
    играет, дефолт стоит на ней. А вот когда её нет в выдаче или играть ей нечем, дефолт
    по правилу «первая живая часть» (:func:`first_alive`) перескакивал на «Тачки 2» - и
    Enter включал другое кино той же франшизы, которого не просили. Строка про это была
    (:func:`default_note`), но показ всё равно начинался сам.

    Теперь в этом случае дефолта нет вовсе: строка называет, что случилось с первой
    частью, список того, что есть, уже на экране над ней, и номер части называет сам
    человек. Пустой ответ - дефолт честен, и случаев тут три:

    * номер назван явно («тачки 2») - спрошенное уже отобрано до меню
      (:func:`~torrcast.parse.pick_franchise`), и дефолт - ровно оно;
    * франшиза без номерованных частей («Моана», «Мумия») - там первая ЖИВАЯ картина и
      есть ответ на запрос, решение «дефолт франшизы - первая живая часть» не тронуто;
    * дефолт встал на саму первую часть или на её ТЁЗКУ по году («Человек-невидимка» 2020
      вместо 1933): тёзка - та же вещь под тем же именем, послабление для неё остаётся.

    Запрос, назвавший франшизу оригинальным именем («cars»), читается так же, как русский:
    имя первой части сверяется в обоих языках.

    Линейкой считаются только картины: номерованная книжная серия («Homo Ludens 1» рядом
    со «Сталкером») франшизу не образует. И номер внутри одной картины («Дары Смерти:
    Часть I») - это глава, а не часть франшизы: если «первая часть» линейки младше другой
    картины меню, перед нами семья однофамильцев, и там дефолт честен.
    """
    from torrcast.parse import _numbered_line

    name, index = split_franchise_index(asked)
    if index is not None or len(plans) < 2:
        return ""
    key = slugify(name)
    pictures = [plan.picture for plan in plans]
    films = [p for p in pictures if p.kind != "other"]
    if not key or not any(p.part is not None for p in films):
        return ""
    line = _numbered_line(films)[0]
    first = line[0] if line and line[0].part in (None, 1) else None
    if first is not None and any(p.year and first.year and p.year < first.year for p in films):
        return ""
    names = {p.franchise for p in pictures}
    # Оригинальные имена зовут ту же франшизу («cars» - это «тачки»), а корень ключа
    # (:func:`franchise_key`) режет номер части: «Cars 2» подписано корнем «cars».
    names |= {franchise_key(p.original) for p in pictures if p.original}
    if key not in names:  # запрос назвал не франшизу, а картину - подменять тут нечего
        return ""
    if first is None:
        return (
            f"«{name}»: первой части в выдаче нет, и вместо неё другую часть сам не "
            f"включаю - вот что есть, назови номер"
        )
    default = plans[first_alive(plans) - 1].picture
    if default is first or default.title.casefold() == first.title.casefold():
        return ""
    number = next(n for n, plan in enumerate(plans, start=1) if plan.picture is first)
    why = _passed_why(plans, number, asked_kind(plans))
    return (
        f"«{_named(first)}» не играет: {why}; вместо неё другую часть сам не включаю - "
        f"вот что есть, назови номер"
    )


def understudy(plans: list[_Plan], failed: _Plan) -> _Plan | None:
    """🔴 TC-203. Живая ТЁЗКА выбранной картины - та, которой показ доиграет вместо неё.

    У выбранной картины кончились все раздачи, а рядом в меню стоит одноимённая живая -
    и человек читал отказ. Замер каталога: 6 отказов из 115, и самый наглядный -
    «Человек-невидимка»: дефолт садился на 1933 год (формально живой, играть нечем) при
    живой картине 2020 года в том же меню. Отказ там был честен про картину и неправдой
    про вечер: кино с этим именем в каталоге есть, и оно играет.

    Тёзка - это ровно ТО ЖЕ НАЗВАНИЕ (:func:`_namesake`), а не соседка по франшизе.
    Разница принципиальная: «Тачки 2» вместо «Тачек» - это другое кино, и уходить туда
    самому нельзя ни при каком отказе (о таких соседях говорит подсказка
    :func:`kin_line`, и она остаётся подсказкой). А «Человек-невидимка» 1933 и 2020 -
    это одна вещь, снятая дважды: имя человек назвал верно, промахнулись мы годом.

    Тип тоже обязан совпасть: полнометражка и одноимённый сериал - разные вещи, и
    подменять одно другим молча нельзя ровно по той же причине, по какой этого не делает
    дефолт (:func:`backed`).

    Круг ровно один: берём самую живую из тёзок. Лишний заход стоит человеку секунд, и
    платить их за перебор всего меню незачем - если и она не сыграет, честный отказ
    честнее долгого перебора.
    """
    number = next((n for n, plan in enumerate(plans, start=1) if plan.picture is failed.picture), 0)
    if number == 0:
        return None
    twins = [
        n
        for n in alive_numbers(plans, list(range(1, len(plans) + 1)))
        if n != number
        and _namesake(plans, n, number)
        and plans[n - 1].picture.kind == failed.picture.kind
    ]
    if not twins:
        return None
    return plans[max(twins, key=lambda n: liveliness(plans[n - 1])) - 1]


def _played(
    bench: _Bench,
    plans: list[_Plan],
    plan: _Plan,
    args: Args,
    progress: Progress,
    facts: Facts | None,
    config: Config,
    profile: Profile,
) -> tuple[_Plan, _Prep]:
    """Отбор релиза выбранной картины, а нечем играть - её живой тёзки (:func:`understudy`).

    🔴 TC-203. Отдельной функцией это стоит затем, что уход к тёзке - смена КАРТИНЫ, и
    смена эта обязана быть проверяемой отдельно от всего пути показа: печатается строка,
    пишется след, план подменяется целиком (вместе с длительностью из справки и порядком
    прогретого). Возвращается пара «чем в итоге играем» - вызывающему нужны обе половины.

    Кругов ровно два: выбранная картина и одна тёзка. Дальше - честный отказ: перебирать
    меню целиком дороже, чем сказать правду, а цель пути - десять секунд до картинки.
    """
    try:
        return plan, bench.resolve(plan, args, progress)
    except NotFoundError as refusal:
        spare = understudy(plans, plan)
        if spare is None:
            raise
        why = _why_refused(refusal)
        print(understudy_note(plan, spare, why))
        trace.emit(
            "select",
            "switch",
            **{"from": plan.picture.title, "to": spare.picture.title, "why": why},
        )
    # Тёзке достаётся ровно то же, что досталось бы ей после меню: своя длительность из
    # справки и свой порядок прогретого (:func:`_timed`, :meth:`_Bench.reorder`).
    spare = bench.reorder(spare, _timed(spare, facts, args, config, profile))
    bench.keep_plan(spare)
    return spare, bench.resolve(spare, args, progress)


def understudy_note(failed: _Plan, spare: _Plan, why: str) -> str:
    """Одна строка про уход к тёзке (:func:`understudy`) - печатается ВСЕГДА.

    Уход к тёзке - это смена картины, то есть ровно то, о чём молчать нельзя
    (:func:`default_note`). Строка называет обе стороны с годами и причину, по которой
    первая не сыграла: без причины это выглядело бы как каприз показа, а с ней человек
    видит, что выбор был сделан за него не от лени.
    """
    return (
        f"«{_named(failed.picture)}» - играть нечем ({why}); "
        f"ухожу к «{_named(spare.picture)}»: раздач {len(spare.ranked)}"
    )


def _why_refused(refusal: NotFoundError) -> str:
    """Голова отказа - без списка приговоров и без подсказки про соседей.

    В отказе есть всё: перечень осуждённых релизов, совет выбрать руками, строка
    :func:`kin_line`. В строке ухода к тёзке нужна ровно причина, потому что совет
    «выбери руками» после автоматического ухода уже неправда.
    """
    head = str(refusal).splitlines()[0]
    return _cut(head.split(":")[0].strip(), 60)


def _namesake(plans: list[_Plan], number: int, picked: int) -> bool:
    """Тёзка по году: то же название, другая картина.

    Одноимённые части - самая тихая из подмен: в меню они отличаются только годом в
    скобках, и человек, назвавший «мумия», получает «Мумию» - вопрос лишь, которую из
    трёх. Сказать вслух обязаны обе стороны выбора.
    """
    mine, other = plans[picked - 1].picture, plans[number - 1].picture
    return mine.title.casefold() == other.title.casefold() and mine.year != other.year


def warm_order(plans: list[_Plan]) -> list[_Plan]:
    """Кого греть под меню: сверху вниз, в том же порядке, который видит человек."""
    return plans


def _pick_plan(
    plans: list[_Plan], facts: Facts | None = None, pick: int | None = None, asked: str = ""
) -> _Plan:
    """Вопрос «какой фильм франшизы?»; один вариант — без вопроса.

    Дефолт — верхняя картина меню. Если играть её нечем, отбор называет причину и не
    подставляет соседнюю картину.

    🔴 TC-373. Ограждение того же дефолта: перескочив через спрошенную часть франшизы
    (её нет в выдаче или играть ей нечем), он вставал на ДРУГУЮ часть - и Enter включал
    «Тачки 2» вместо просимых «Тачек». Такому дефолту не бывать (:func:`part_one_swap`):
    строка говорит, что случилось с первой частью, список остаётся на экране, и номер
    называет сам человек.

    К каждой картине печатается справка (:mod:`torrcast.facts`) — рейтинг, хронометраж и
    фраза о том, что это за кино. Её тут не ждут: что успело приехать фоном, то и
    печатается, остальное просто не печатается.

    ``pick`` - номер пункта, названный флагом ``--pick N``: вопрос тогда не задаётся
    вовсе, и терминал не нужен. Это не молчаливая подмена, а названный человеком выбор -
    тот же номер, что стоит у пункта меню на экране. Номер вне списка - честная ошибка,
    а не тихий первый пункт.

    Без терминала (ssh без pty, cron, чужой скрипт) спрашивать некого, и общее правило —
    не висеть, а брать дефолт. Здесь мы по-прежнему отказываемся — и «дефолт стал умнее»
    ничего не меняет. У озвучки дефолт считается правилами, у «Продолжить?» это
    «продолжить», а тут любой дефолт означает **другой фильм**: разница между «Моаной»
    2016 и «Моаной 2» — это не оттенок, а не тот вечер. Цифра в скобках имеет смысл
    ровно потому, что рядом напечатан список и человек видит, от чего отказывается;
    без терминала видеть его некому. Поэтому отказываемся вслух и подсказываем, как
    назвать картину точно.
    """
    if pick is not None and not 1 <= pick <= len(plans):
        raise NotFoundError(f"подходит картин: {len(plans)}, номера {pick} нет")
    print(menu_lines(plans, facts))
    if pick is not None:  # номер назвал сам человек - ни вопроса, ни подмены
        return plans[pick - 1]
    if len(plans) == 1:
        return plans[0]
    default = 1
    if not console.stdin_is_tty():
        raise NotFoundError(
            f"подходит картин: {len(plans)}, а терминала нет - вслепую не выбираю; "
            f"назови картину точно (например «{plans[default - 1].picture.title}») "
            f"или её номер (--pick N), либо запусти cast в терминале"
        )
    if note := part_one_swap(plans, asked):
        # Дефолт подменил бы спрошенную часть другой - тогда его нет вовсе: строка
        # называет, что с первой частью, список на экране, номер зовёт человек.
        print(note)
        return plans[ask("Что смотрим?", len(plans), default=None) - 1]
    print(default_line(plans, default))
    return plans[ask("Что смотрим?", len(plans), default=default) - 1]


def default_line(plans: list[_Plan], default: int) -> str:
    """Что случится по Enter - словами, последней строкой перед вопросом.

    🔴 TC-204. Порядок меню хронологический, и это решение: франшизу читают так, как её
    снимали. А дефолт - первая ЖИВАЯ картина (:func:`first_alive`), и он с первой строкой
    не совпадает почти в половине меню: в замере 45 многокартинных меню из 82, в 13 из них
    дефолт стоял пятым и дальше, а у «ван пис s1e1» - строкой 33 из 35. Одной цифры в
    ``[33]`` человеку мало: он видит номер, а не название.

    Строка стоит именно ПЕРЕД вопросом, а не шапкой над списком. Терминал после длинного
    вывода показывает его ХВОСТ: шапка тридцатипятистрочного меню уезжает за экран вместе
    с ним, и «дефолт виден без прокрутки» она не даёт. Хвост же виден всегда - ровно
    там, где человек и держит глаза, отвечая на вопрос.

    Список при этом не переупорядочивается: показ дефолта - это показ, а не порядок.
    """
    return f"Enter - «{_named(plans[default - 1].picture)}», пункт {default} из {len(plans)}"


#: Отступ описания в меню: ровно под название, за номером с точкой.
_BLURB_INDENT = " " * 5


def _named(picture: Picture, aside: bool = False) -> str:
    """Название с годом; ``aside`` - картина стоит после нумерованной линейки франшизы.

    Подпись объясняет, почему пункт уехал вниз: номера части у неё нет, и в линейку по
    номерам ей вставать не с чем (:func:`~torrcast.parse.outside_numbering`).
    """
    marks = ", сериал" if picture.kind == "tv" else ""
    if aside:
        marks += ", без номера части"
    return f"{picture.title} ({picture.year or '?'}{marks})"


def menu_lines(plans: list[_Plan], facts: Facts | None = None, width: int = 0) -> str:
    """Список картин со справкой: номер, название с годом, рейтинг и хронометраж — в одну
    строку, описание — под ней, с отступом под номер.

    Формат такой, а не таблицей, ровно из-за узкого терминала: название бывает длинным
    («Тачки: Мультачки. Байки Мэтра»), а описание — тем более, и колонки разъехались бы
    на первой же франшизе. Отдельная строка вместо колонки ещё и читается сверху вниз:
    глаз идёт по номерам, а подробности — под ними.

    Описание переносится по словам и занимает столько строк, сколько нужно фразе (в
    восьмидесяти колонках это две-три). Раньше оно резалось по ширине терминала, и в
    меню оставался огрызок «американский компьютерно-анимационный…»: ни жанра, ни года,
    ни возможности дочитать. Место экономить тут не на чем — вопрос задаётся один раз.

    Справки нет (не приехала, сети нет, картины нет в Википедии) — печатается ровно та
    строка, что печаталась раньше, без пустых разделителей и без «не нашёл».
    """
    columns = width or shutil.get_terminal_size((80, 24)).columns
    aside = outside_numbering([plan.picture for plan in plans])
    rows: list[str] = []
    for number, plan in enumerate(plans, start=1):
        picture = plan.picture
        fact = facts.get(picture.title, picture.year) if facts else Fact()
        head = " · ".join(
            x for x in (_named(picture, picture.key in aside), fact.rating, fact.runtime) if x
        )
        rows.append(f"  {number}. {head}")
        if fact.about:
            rows += textwrap.wrap(
                shorten(fact.about),
                width=max(40, columns - 1),
                initial_indent=_BLURB_INDENT,
                subsequent_indent=_BLURB_INDENT,
                # Дефис - часть слова: «компьютерно-анимационный» рвать по нему незачем.
                break_on_hyphens=False,
            )
    return "\n".join(rows)


def warned(
    release: Release,
    runtime: float,
    warn_mbit: float,
    recode_at: float = 0.0,
    hard_mbit: float = 0.0,
) -> str:
    """Почему релиз не дефолт: HEVC ресивер может не потянуть, жирный битрейт — тоже.

    Словами, а не значками: ``⚠`` из вывода убран целиком — в терминале он не нёс
    смысла и разъезжался по ширине.

    ⚠️ «Не берём» про HEVC осталось правдой ровно там, где перекодирование выключено:
    иначе такой релиз играет, перекодированный целиком, и таблица обязана говорить то же,
    что и показ (:func:`_encode_all`).
    """
    peak = bitrate_of(release, runtime)
    marks: list[str] = []
    if release.is_hevc:
        marks += ["перекодирую целиком" if recode_at > 0 else "не берём"]
    if peak is None:  # вес неизвестен (TC-344) - пометок по весу нет, врать нечем
        return ", ".join(marks)
    if peak > warn_mbit:
        marks += ["тяжёлый"]
    elif hard_mbit > 0 and peak > hard_mbit:
        # Тяжелее прежнего потолка, но играбелен: уедет перекодированным целиком.
        if "перекодирую целиком" not in marks:
            marks += ["перекодирую целиком"]
    elif recode_at > 0 and peak > recode_at:
        # Не брак, а честное предупреждение - тяжёлые куски поедут перекодированными.
        marks += ["перекодируем"]
    return ", ".join(marks)


def last_hope_note(plan: _Plan, release: Release) -> str:
    """Та самая честная строка про последнюю надежду; пусто — путь обычный.

    Печатается ровно тогда, когда показ берёт релиз, попавший в очередь ТОЛЬКО потому,
    что живого кандидата с нужной серией нет вовсе (:func:`hevc_hope`). Человек обязан
    услышать не только «перекодирую целиком» (:func:`torrcast.stream.recode_note` скажет
    это следующей строкой), но и ПОЧЕМУ выбран дорогой путь: иначе «Гинтама» на HEVC и
    «Гинтама» на честном 1080p выглядят с экрана одинаково, а стоят разного.

    Строка одна, без числа: считать тут нечего — это не размен качества, а
    единственный оставшийся носитель серии.
    """
    if not (plan.last_resort and hevc_hope(release, plan.last_resort)):
        return ""
    what = f"серии {plan.want}" if plan.want else "картины"
    return f"живой раздачи {what} без HEVC нет - беру HEVC последней надеждой"


def quality_text(release: Release, media: Media) -> str:
    """Разрешение, которое реально поедет на ТВ. ffprobe уже прочитан — врать нечем.

    Порядок именно такой: сначала подтверждённая высота кадра, и только если ffprobe её
    не отдал (экзотика, битый заголовок) — заявка из имени. Раньше было наоборот, и
    «Моана 2» печаталась 1080p при 1150×574 внутри: заявка выигрывала у факта, то есть
    ровно та молчаливая подмена, которой быть не должно.

    Буква развёртки тоже из потока (:attr:`torrcast.stream.Media.quality`): названный
    «1080p» чересстрочник печатается «1080i» - гребёнку нельзя подписать прогрессивом.
    """
    return media.quality if media.height else (release.quality or "?")


def understated(release: Release, media: Media) -> str:
    """Чем подтверждённое разрешение хуже обещанного; пусто — релиз честен.

    Две половины, и обе взяты с живой выдачи «моаны 2»:

    1. имя называет разрешение, а внутри заметно меньше (:data:`HONEST_RATIO`);
    2. имя не называет ничего, а внутри не HD вовсе (:data:`HD_HEIGHT`) — это и есть
       верхний кандидат «Моаны 2»: ``WEB-DL-AVC`` без единой цифры в заголовке, 3.14 ГБ,
       140 сидов, а на деле 1150×574.

    И третья, про развёртку: имя обещает прогрессивный кадр, а поток чересстрочный
    (:attr:`~torrcast.stream.Media.interlaced`). Разрешение тут не врёт, поэтому
    высотой её не поймать - ловится только буквой.

    Возвращает кусок фразы, а не флаг: строка про подмену обязана назвать обе цифры,
    иначе она ничего не объясняет.
    """
    if not media.height:  # ffprobe высоту не отдал - сравнивать не с чем, молчим
        return ""
    if release.height:
        if media.frame < release.height * HONEST_RATIO:
            return f"назван {release.quality}, на деле {media.quality}"
        if media.interlaced and not release.interlaced:
            return f"назван {release.quality}, на деле {media.quality}"
        return ""
    return f"на деле {media.quality}" if media.frame < HD_HEIGHT else ""


def promises_more(release: Release, media: Media) -> bool:
    """Стоит ли вообще смотреть на этот запасной: обещает HD и больше, чем дал верх."""
    return release.height >= HD_HEIGHT and release.height > media.frame


def voice_unproven(media: Media, *, native: bool = False) -> bool:
    """Русская дорожка в этом файле НЕ ПОДТВЕРЖДЕНА: паспорт либо отрицает, либо молчит.

    🔴 TC-301. У паспорта три ответа, а не два. «Русская есть»
    (:attr:`~torrcast.stream.Media.russian`) - играем. «Русской нет»
    (:attr:`~torrcast.stream.Media.foreign`) - гейт бракует релиз и очередь идёт дальше
    (:meth:`_Bench.resolve`). А между ними лежит третий: дорожка БЕЗ ТЕГА ЯЗЫКА
    (:attr:`~torrcast.stream.AudioTrack.named`), и по замеру паспортов таких файлов 28%.

    🔴 TC-492. Третий ответ засчитывался за первый, и стоило это зрителю картины:
    «Эксперименты Лэйн» уехали с нерусской дорожкой ровно потому, что язык её никто не
    назвал, - а в очереди оставалось ещё четыре нетронутых релиза. Незнание - это не
    «сойдёт»: правило продукта требует русской озвучки, а не отсутствия доказательств
    обратного. Поэтому годным считается только первый ответ, а второй и третий отправляют
    релиз в один и тот же запасной ход (:meth:`_Bench._mute_fallback`): очередь идёт
    дальше, а когда спрашивать больше некого - играет лучшее из отложенного, и говорит об
    этом вслух.

    Имя раздачи тут не судья ни в одну сторону (TC-191): «[RUS(int)]» русской дорожки не
    гарантирует, и подменять им паспорт значит вернуть ту же ошибку с другого конца.

    ``native`` - справка подтвердила отечественное происхождение картины. Тогда безымянная
    дорожка не пробел, а паспорт происхождения: «Бригаду» никто не озвучивал, она так и
    снята. Та же развилка стоит в :func:`sound_note`.

    ⚠️ Граница проведена по ДОРОЖКЕ, а не по паспорту целиком: файл, у которого ffprobe не
    отдал ни одной звуковой дорожки, сюда не относится. Это не «язык не назван», а «звук
    не прочитан» - паспорт, дочитанный до половины, и бракует он не релиз, а нашу спешку
    (:attr:`~torrcast.stream.Media.foreign` о том же). В замере паспортов таких файлов нет
    ни одного из 92, а стоила бы такая строгость всей выдачи разом.
    """
    if media.russian or not media.tracks:
        return False
    return media.foreign or not native


def honest_shot(release: Release, media: Media) -> bool:
    """Запасной подтвердил своё имя: кадр из ffprobe не ниже заявленной ступени. Имя
    молчало — тогда достаточно, чтобы внутри оказался HD.
    """
    if not media.height:
        return False
    if release.height:
        return media.frame >= release.height * HONEST_RATIO
    return media.frame >= HD_HEIGHT


def is_disc(release: Release) -> bool:
    """Образ диска (DVD-Video, BDMV, ISO): цельного файла внутри нет — не дефолт."""
    return bool(_DISC_RE.search(release.raw_name))


def is_extra(release: Release, runtime: float) -> bool:
    """Раздача - приложение к картине, а не сама картина: так сказало имя, так вышло по весу.

    🔴 TC-290. Ворота отбора судили, КАК раздача снята - разрешение, битрейт, живость,
    звук, - и ни одна ступень не спрашивала, картина ли это вообще. Дополнительные
    материалы (фильм о фильме, интервью, вырезанные сцены, трейлер) проходили обычным
    кандидатом, а из-за малого веса выглядели по битрейту даже прилично. У «Тачек 2» из
    сохранённой выдачи «HDRip … фильм о фильме» на 0.4 ГБ стоял в очереди четырнадцатым,
    а в пуле, где у картины всего две раздачи, - ПЕРВЫМ, то есть дефолтом Enter. Человек
    просит кино и получает получасовой ролик о съёмках; молча.

    Признаков два, и по отдельности ни один не годится.

    Имя (:attr:`~torrcast.parse.Release.extras`) без веса отбраковало бы законную картину,
    у которой такое слово стоит в её же названии, и раздачу «картина + приложение».

    Вес без имени - это уже :func:`is_dated`, и он про другое: мизерный битрейт бывает у
    честного SD-рипа, и выкидывать такой нельзя, пока другого нет. Здесь же имя прямо
    говорит, что играть тут не картину, и вес это подтверждает: при длительности из
    справки (:func:`torrcast.facts.minutes_of`, она же знаменатель :func:`bitrate_of`)
    столько весит ролик, а не фильм.

    ⚠️ Короткометражке признак не грозит, и не по доброте: её длительность справка называет
    честно, а ролик от картины отличает не абсолютный размер файла, а вес НА МИНУТУ. Пока
    справка молчит, в знаменателе стоит прикидка «фильм это два часа»
    (:data:`torrcast.stream.RUNTIME_GUESS`), и она короткометражку занижает - но занизить
    раздачу без пометки приложения в имени всё равно некуда: ворота её и не смотрят.

    ⚠️ Признак отнимает и единственную раздачу картины (TC-432): показать трейлер на
    запрос сериала - это подмена картины, а не «лучше, чем ничего». Вернуть её может
    только сам человек, номером из таблицы (``--release N`` в ворота не ходит).

    🔴 TC-339. Весу есть предел измерения: «Титаник | Дополнительные материалы» на
    11.6 ГБ, «Довод» на 22.5 ГБ, «Хоббит: Приложения» на 19.2 ГБ по битрейту выглядят
    картиной и ворота проходили, а подменить её могут, стоит умереть всему выше них.
    Поэтому однозначная метка (:attr:`~torrcast.parse.Release.extras_sure`) судит БЕЗ
    веса: «дополнительные материалы» и «бонус-диск» не бывают картиной ни при каком
    битрейте. Прочие метки без веса не судятся по-прежнему: их носят и раздачи самой
    картины, и сохранённая выдача это подтверждает - отсев по любой метке оставил бы
    без живых кандидатов 10 картин корпуса из 107 пулов, по однозначной - ни одной.
    ⚠️ Замер тот считал верх ранжира неприкосновенным, а TC-432 повёл через ворота и
    его: там, где однозначная метка стоит на ЕДИНСТВЕННОЙ раздаче картины, очередь
    теперь пустеет, и человек получает честный отказ (:func:`unfit_line`), а не
    бонус-диск вместо картины.

    🔴 TC-344. Молчание веса - не «лёгкий»: у сериала, чьё имя серий не считает,
    :func:`bitrate_of` отдаёт ``None``, и приложение с таким весом ворота НЕ отсекают -
    выкидывать раздачу по весу, которого нет, значит карать за собственное незнание.
    Порядок её всё равно уводит под картину (:func:`rank_releases`), а судит содержимое
    ffprobe, как и всякую молчаливую раздачу.
    """
    if not release.extras:
        return False
    if release.extras_sure:
        return True
    mbit = bitrate_of(release, runtime)
    return mbit is not None and mbit < EXTRAS_MBIT


def is_candidate(
    release: Release,
    runtime: float,
    warn_mbit: float,
    loose: bool = False,
    hard_mbit: float = 0.0,
    last: bool = False,
    copy_hevc: bool = False,
) -> bool:
    """Кандидат в дефолт: первый сорт (:attr:`Release.prime`), не образ диска, не
    приложение к картине (:func:`is_extra`) и в пределах потолка декодера. Жирнее потолка —
    в таблице остаётся с пометкой, но Enter его не возьмёт: ресивер на таком битрейте встаёт.

    ``loose`` — ворота открыты (:func:`gate_open`): живых именных кандидатов у картины
    нет, и тогда кандидатом становится ещё и раздача, чьё имя о качестве просто МОЛЧИТ
    (:attr:`Release.quiet`). Судить её будет ffprobe после выбора — механизм отбраковки
    и перехода к следующему уже стоит на пути (:meth:`_Bench.resolve`), и стоит он
    ровно тех же секунд, что и на любом другом релизе.

    Имя, сказавшее о себе правду, послаблением ``loose`` не пользуется: названный HEVC,
    MPEG-4 и «480p» остаются снаружи, потому что про них известно, а не неизвестно.
    Образ диска и потолок битрейта тоже не двигаются: там играть нечего и там ресивер
    встаёт, а от открытых ворот это не меняется.

    ``last`` — последняя надежда (:func:`last_hope`): живого кандидата с нужной серией
    нет ВООБЩЕ, и тогда в очередь пускается названный HEVC (:func:`hevc_hope`). Это не
    смягчение ворот, а признание того, что тракт умеет: такой файл играется сплошным
    перекодом (:data:`torrcast.stream.RECODE_CODECS`) ровно как десятибитный H.264.
    Предпочтением это не становится ни на шаг — ворота открываются только когда живого
    обычного кандидата нет, а порядок держит HEVC ниже всех живых (:func:`rank_releases`).

    ``copy_hevc`` - ответ единственного судьи кодека (:meth:`Profile.verdict`): свой
    ресивер объявил HEVC играющим копией через наш HLS. Для него HEVC проходит обычные
    ворота; профиль не снимает ограничения образа диска, качества и битрейта.

    ⚠️ Не-видео (``kind == "other"``: игры, музыка, книги) послабление не пускает
    никогда, и это не перестраховка. Замер на живой выдаче «one piece»: репак игры
    «One Piece: Pirate Warriors 4 … PC | RePack» несёт 97 сидов и о качестве видео
    молчит по той простой причине, что видео там нет, — при открытых воротах он
    перевешивал настоящий сериал с русским дубляжом и вставал дефолтом меню.

    ``hard_mbit`` — потолок для тех, у кого запас сплошного перекода тонок: имя, обещающее
    кадр выше 1080p, судится им, а не поднятым ``warn_mbit``. Причина не в качестве и уже
    не в «4К не успевает» (замер TC-157 это снял: ужатый до 1080p перекод идёт 1.34-1.53×
    реального времени), а в том, сколько остаётся про запас. У 1080p-ремукса запас 3.4×,
    у ужатого 4К - полтора, и рою при этом всё равно надо отдавать вес ИСХОДНИКА.
    Ноль — ступени нет, всё судится одним потолком.
    """
    if (
        is_disc(release)
        or is_extra(release, runtime)
        or over_ceiling(release, runtime, warn_mbit, hard_mbit)
    ):
        return False
    if (
        release.prime
        or (copy_hevc and release.is_hevc)
        or (loose and release.quiet and release.kind != "other")
    ):
        return True
    return hevc_hope(release, last)


def over_ceiling(
    release: Release, runtime: float, warn_mbit: float, hard_mbit: float = 0.0
) -> bool:
    """Битрейт релиза выше потолка отбора: играть его нечем, и в очередь он не идёт.

    Потолок у кадра выше 1080p свой (``hard_mbit``): запас скорости у ужатого 4К вдвое
    тоньше, а из роя тянуть надо вес исходника — см. :func:`is_candidate`.

    Отдельной функцией это стоит затем, что решение «выкинуть по битрейту» обязано
    называться одним и тем же кодом и в воротах, и в счёте отсева (:func:`drop_reason`):
    иначе счёт объяснял бы отказ не тем, чем он случился.
    """
    ceiling = warn_mbit
    if hard_mbit > 0 and release.height > RECODE_HEIGHT:
        ceiling = min(warn_mbit, hard_mbit)
    mbit = bitrate_of(release, runtime)
    # Вес неизвестен (TC-344) - потолок молчит: выкидывать по весу, которого нет,
    # нельзя, а тяжесть файла рассудит ffprobe уже после выбора (:meth:`_Bench._trouble`).
    return mbit is not None and mbit > ceiling


#: Раздачи картины, отсеянные до очереди, по причинам (:func:`drop_reason`). Порядок
#: слов один на весь код: причина называется там, где считается, и печатается в
#: `cast log` теми же словами (:func:`torrcast.trace._event_line`).
OFF_SEASON: Final = "нужного сезона нет"
_NO_EPISODE: Final = "нужной серии нет по имени"
_DISC: Final = "образ диска"
_EXTRAS: Final = "дополнительные материалы, а не сама картина"
_HEAVY: Final = "тяжелее потолка"
_HEVC: Final = "hevc, а сплошного перекода нет"
_CODEC: Final = "кодек не тот"
_SMALL: Final = "кадр ниже 720p по имени"
_SOURCE: Final = "источник не HD"
_QUIET: Final = "имя молчит о качестве"
_PINNED: Final = "релиз назван руками"


def drop_reason(release: Release, plan: _Plan) -> str:
    """Почему раздача не доехала до очереди отбора; пусто — доехала.

    🔴 TC-186. Пул картины и очередь отбора — не одно и то же: между ними стоят ворота
    (:func:`is_candidate`), сезонный фильтр и потолок битрейта, и на замере тысячи
    запросов между ними терялось 895 раздач из 3164 — без строки на экране и без
    события в недельном следе. «В журнале нет строки» это не «события не было»:
    отказавшая арифметика выглядела в следе ровно как её отсутствие.

    Причины перечислены в том же порядке, в каком судит :meth:`_Plan.candidates`, и
    каждая раздача получает ПЕРВУЮ подошедшую: у выкинутой их бывает несколько сразу,
    а объяснять человеку надо ту, на которой её и выкинули.
    """
    if misses_episode(release, plan.want):
        return _NO_EPISODE
    if is_disc(release):
        return _DISC
    if is_extra(release, plan.runtime):
        return _EXTRAS
    if over_ceiling(release, plan.runtime, plan.warn_mbit, plan.hard_mbit):
        return _HEAVY
    if release.is_hevc and plan.copy_hevc:
        return ""
    if release.is_hevc and not (plan.last_resort or plan.copy_hevc):
        return _HEVC
    # Дальше раздача не прошла ворота (:attr:`~torrcast.parse.Release.prime`), и причина
    # у ворот ровно та, чем имя о себе сказало: назван чужой кодек, назван мелкий кадр,
    # назван не-HD-источник. Не сказало ничего - это молчание, и оно отдельная причина:
    # молчаливую раздачу судит ffprobe, когда ворота открыты (:attr:`_Plan.loose`).
    if release.codec:
        return _CODEC
    if release.height:
        return _SMALL
    if release.source:
        return _SOURCE
    return _QUIET


def queue_drops(plan: _Plan, queue: list[int], pinned: bool = False) -> dict[str, int]:
    """Сколько раздач картины выкинуто до очереди и по каким причинам.

    Считается ПО ПУЛУ КАРТИНЫ, а не по :attr:`_Plan.ranked`: раздачи, у которых нет
    нужного сезона, отсекаются ещё при сборке плана (:func:`_plan_for`) и до сих пор не
    попадали ни в одну строку вовсе. Поэтому сумма очереди и всех причин сходится с
    длиной ``plan.picture.releases`` — это и есть проверка того, что счёт полон.

    Свёрткой, а не событием на раздачу, — намеренно: 895 событий на один запрос это не
    диагностика, а способ переполнить очередь записи, из которой события теряются молча
    (:class:`torrcast.trace._Writer`).

    ``pinned`` — релиз назван руками (``--release N``), и остальные не «выкинуты», а не
    спрошены: причин отбора у них нет.
    """
    counts: dict[str, int] = {}
    if plan.off_season:
        counts[OFF_SEASON] = plan.off_season
    taken = set(queue)
    for number, release in enumerate(plan.ranked, start=1):
        if number in taken:
            continue
        why = _PINNED if pinned else drop_reason(release, plan)
        counts[why] = counts.get(why, 0) + 1
    return counts


def hevc_hope(release: Release, last: bool) -> bool:
    """Релиз проходит в очередь ТОЛЬКО последней надеждой: он названный HEVC.

    Ворота отбора держали HEVC снаружи с самого начала, и это было правдой ровно до тех
    пор, пока показ его не умел. Теперь умеет: сплошной перекод по файлу закрыл
    десятибитный H.264 (:func:`torrcast.stream.recodes_whole`), и HEVC идёт по тому же
    пути тем же кодом. Ворота при этом отбраковывали то, что тракт играет, — и на
    «Гинтаме» это стоило показа целиком: первая серия во всём каталоге лежит в двух
    раздачах, DVDRip-AVC с НУЛЁМ сидов и ``BDRip-HEVC 720p`` с четырьмя, то есть
    единственный живой носитель серии в очередь не попадал вовсе.

    ``last`` — ворота последней надежды открыты (:func:`_plan_for`). Закрыты — признак
    не срабатывает никогда, и ни отбор, ни порядок не меняются ни на знак: при живом
    обычном релизе HEVC по-прежнему не кандидат. Это не осторожность, а цена: сплошной
    перекод занимает процессор от первой секунды до титров и стартует медленнее
    (замер: 8 с против 5 с).

    🔴 Про ПРИЁМНИК здесь не спрашивается ничего, и это не забывчивость. Вопрос «а этот
    декодер вообще спотыкается о HEVC» — один на весь код
    (:func:`torrcast.stream.recodes_whole`), задаётся он профилю
    (:mod:`torrcast.profile`) и задан уже в воротах, при вычислении ``last``. Спросить
    его и тут значило бы развести решение о кодеке на два места, а именно от этого и
    ломался десятибитный H.264.

    🔴 TC-222. Кадр выше 1080p сюда ПРОХОДИТ, и это разворот прежнего правила. Прежнее
    стояло на арифметике «скорость сплошного перекода замерена на 1080p, у 2160p вчетверо
    больше пикселей, в бюджет старта не влезает», а замер TC-157 её перевернул: тот же
    перекод СО СКЕЙЛОМ до 1080p идёт 1.53× реального времени против 1.03× без скейла -
    вчетверо меньше пикселей достаётся кодировщику, и он от этого не тонет, а ускоряется.
    Отказывать тут значило бы отказывать в единственном носителе картины ради потолка,
    которого больше нет. Решение владельца ровно такое: нет 1080p - 2160p перекодируется
    вниз как последняя надежда, а не отбрасывается.

    ⚠️ Предпочтением 4К от этого не становится: под 1080p его топит ступень
    :func:`needs_whole_recode` (она стоит выше живости), а слишком тяжёлый 4К по-прежнему
    не проходит потолок :func:`over_ceiling`.

    Имя, о разрешении молчащее, проходит и здесь: судить его будет ffprobe после выбора
    (:meth:`_Bench._trouble`), у которого высота кадра не заявка, а факт.
    """
    return last and release.is_hevc


def needs_whole_recode(release: Release, runtime: float, hard_mbit: float) -> bool:
    """Релиз играбелен только сплошным перекодом: он тяжелее ``hard_mbit`` или крупнее кадром.

    Ступень отбора, а не отказ. Такой релиз берётся — но последним из годных: держать
    его показ дороже во всём сразу. Процессор занят с первой секунды и до титров
    (посегментному перекоду хватало тяжёлых мест), рою надо отдавать ~4.7 МБ/с
    непрерывно вместо ~1 МБ/с, и любая просадка роя, которую лёгкий релиз пережил бы за
    счёт запаса, тут сразу становится подгрузом. Поэтому ремукс на 36 Мбит/с обязан
    уступать честному релизу на 8, даже когда сидов у него больше.

    🔴 TC-221. Кадр выше :data:`torrcast.recode.RECODE_HEIGHT` стоит на этой ступени рядом
    с весом, и это ровно то место, где решение владельца «2160p отбраковывается в пользу
    ЖИВОГО 1080p» и превращается в порядок. 4К играется только сплошным перекодом со
    скейлом вниз - копией приёмник его не берёт (TC-157), - то есть по стоимости это тот
    же класс, что ремукс: процессор занят от первой секунды до титров, а из роя надо
    тянуть все 20 Мбит/с ради 9 на экране. Ступень стоит ВЫШЕ живости и выше
    :func:`is_full_hd`, поэтому 4К никогда не обгоняет живой 1080p, а берётся ровно
    тогда, когда 1080p нет.

    ``hard_mbit`` ноль — ступени по весу нет: перекодирование выключено, и тяжёлое
    отсеяно раньше, самим потолком отбора. Кадра это не касается: 2160p и без
    перекодирования не играется, и внизу списка ему самое место.
    """
    if release.height > RECODE_HEIGHT:
        return True
    mbit = bitrate_of(release, runtime)
    return hard_mbit > 0 and mbit is not None and mbit > hard_mbit


def gate_open(
    releases: list[Release],
    runtime: float,
    warn_mbit: float,
    want: Episode | None = None,
    hard_mbit: float = 0.0,
    copy_hevc: bool = False,
) -> bool:
    """Пора ли открыть ворота отбора: живого именного кандидата у картины нет.

    ``copy_hevc`` приходит из профиля и делает HEVC обычным именным кандидатом только
    для ресивера, который объявил его играющим копией через наш HLS.

    Ворота (:attr:`Release.prime`) защищают от мусора и делают это по делу — пока в
    выдаче есть из чего выбирать. У аниме выбирать нечасто есть из чего: имена раздач
    там сплошь без разрешения, кодека и HD-источника, и ворота оставляют картину вообще
    без живых кандидатов. Живой случай, ради которого написано: «Наруто» (2002) — полный
    сериал «[E220 of 220] [RUS(ext), ENG, JAP+Sub] … DVDRip», 157 ГБ, 91 сид, в
    кандидаты не проходит; проходят «[1-5 из 220]» на 3 сида и «[S01E01-08 of 220]» на
    один. Очередь из двух умирающих огрызков — это не защита от мусора, это отсутствие
    показа.

    «Живой» здесь — доля от лидера пула (:data:`GATE_LIVENESS`), как и у
    :func:`is_full_hd`: абсолютное число в пулах разной населённости значит разное.
    Раздачи, у которых нужной серии нет по их же имени, в счёт не идут — они и в
    очередь не попадают.

    Ворота остаются закрытыми и тогда, когда живых нет вовсе (лидер пула на нуле
    сидов): открывать их незачем, показывать всё равно нечего.
    """
    alive = max((r.seeders for r in releases), default=0)
    if alive <= 0:
        return False
    return not any(
        r.seeders >= alive * GATE_LIVENESS
        and is_candidate(r, runtime, warn_mbit, hard_mbit=hard_mbit, copy_hevc=copy_hevc)
        and not misses_episode(r, want)
        for r in releases
    )


def last_hope(
    releases: list[Release],
    runtime: float,
    warn_mbit: float,
    want: Episode | None = None,
    loose: bool = False,
    hard_mbit: float = 0.0,
    copy_hevc: bool = False,
) -> bool:
    """Пора ли пускать в очередь названный HEVC: живого кандидата нет ВООБЩЕ.

    Ступень за :func:`gate_open`, и порог у неё жёстче нарочно. Открытые ворота ещё
    ничего не гарантируют: они пускают молчаливые имена, а те могут все до одного лежать
    с нулём сидов. Ровно это и есть «Гинтама»: 162 раздачи в каталоге, первая серия — в
    двух, и та, что проходит ворота (``DVDRip-AVC``, 99 ГБ), раздаётся нулём пиров.
    Кандидат формально есть, показа нет.

    Поэтому здесь спрашивается не «есть ли кандидат», а «есть ли кандидат, которым
    МОЖНО СЫГРАТЬ»: годен по :func:`is_candidate`, несёт нужную серию и жив. Живость —
    строгий ноль, а не доля от лидера (:func:`is_dead`): доля это размен качества на
    рой, а тут разменивать нечего — либо рой есть, либо показа нет.

    ``loose`` — те же ворота, что у самого плана: молчаливое имя, если оно живое, —
    полноценный кандидат, и последнюю надежду оно закрывает наравне с именным.

    HEVC в выдаче может и не быть вовсе — тогда открытые ворота не меняют ничего:
    признак :func:`hevc_hope` не сработает ни на одной раздаче.

    ⚠️ Про приёмник тут не спрашивается: «тяжёлый ли для него HEVC» — вопрос профиля, и
    задаёт его :func:`_plan_for` перед этой ступенью, одним и тем же
    :func:`torrcast.stream.recodes_whole` на весь код.
    """
    return not any(
        release.seeders > 0
        and is_candidate(release, runtime, warn_mbit, loose, hard_mbit, copy_hevc=copy_hevc)
        and not misses_episode(release, want)
        for release in releases
    )


def sound_step(release: Release, alive: int = 0) -> int:
    """Ступень звука по имени раздачи: 0 — русская дорожка обещана, 1 — не обещана.

    Решение владельца по аниме: субтитров не делаем, а японскую дорожку без перевода
    смотреть нельзя — значит, при прочих равных релиз с русской озвучкой обязан
    обыграть чисто японский, даже если тот сидастее. У аниме дубляж часто лежит
    ОТДЕЛЬНОЙ раздачей (RuTor, Knaben), а не в релизе Nyaa, и по сидам эта раздача
    проигрывает вчистую: у «Боруто» русский «[RUS(int)]» держит 3 сида против 8 у
    «[JAP+Sub]», у «Врат Штейна» — 2 против 3.

    Ступеней ровно две, и это осознанно сжато с трёх. Промежуточная «имя прямо назвало
    чужой звук» (``[Dual Audio]``, ``[JAP+Sub]``) звучит разумно, но на живой выдаче
    покупается зря: у «Steins;Gate» она меняла верх с 397 сидов на 17, у «Chainsaw Man» —
    с 221 на 34, и русского звука ни там, ни там не появлялось. Менять живой рой на
    мёртвый, ничего не выигрывая, — прямая дорога к подгрузам, а гейт показа обратный.
    Поэтому ступень срабатывает ровно тогда, когда в выдаче ЕСТЬ что предпочесть.

    Молчание имени и чужой звук стоят в ней рядом по той же причине, по какой ворота
    отбора не судят молчание (:attr:`Release.quiet`): молчаливая раздача вполне может
    нести русскую дорожку, и узнать это можно только у ffprobe.

    ``alive`` — сиды лидера пула: мёртвый рой выигрышем не бывает ни на каком языке
    (:data:`SOUND_LIVENESS`). Без него ступень поднимала у «Наруто: Ураганные хроники»
    раздачу с НУЛЁМ сидов над играбельной — то есть меняла японский показ на никакой.
    Ноль (умолчание) читается как «пул не назван» и оставляет чистый сигнал имени: так
    ступень зовут таблица релизов и тесты.
    """
    if not release.dubbed:
        return 1
    return 0 if release.seeders >= alive * SOUND_LIVENESS else 1


def is_dated(release: Release, runtime: float) -> bool:
    """Раздача пахнет старьём — до всякого ffprobe, по имени и размеру.

    Три части признака, и они не взаимозаменяемы:

    1. :attr:`Release.dated` — имя признаётся само: XviD/DivX, ``.avi``, DVDRip/VHSRip/
       SATRip/TVRip/CAM.
    2. Имя называет ступень ниже :data:`HD_HEIGHT` — «480p», «576p». Тут спорить не с чем:
       раздача сама говорит, что она не HD, и место ей ниже любого HD. SD играется, только
       если HD в каталоге нет вовсе, — и тогда порядок внутри группы прежний.
    3. Имя не называет РАЗРЕШЕНИЯ, а размер даёт меньше :data:`SD_BITRATE` Мбит/с. Это и
       есть та раздача, ради которой всё затевалось: «Моана 2 … WEB-DL] Dub (MovieDalen)»,
       221 сид, 1.46 ГБ — в заголовке rutracker ни слова про кодек, а внутри
       ``Moana.2.2024.WEB-DLRip.ELEKTRI4KA.avi`` (проверено по самому .torrent). Ни один
       маркер из пункта 1 её не ловит.

       ⚠️ Названный кодек эту часть больше не отключает, и вот почему. Про РАЗРЕШЕНИЕ
       кодек не говорит ничего: ``BDRip-AVC`` — это и честный 1080p на 6 Мбит/с, и рип
       720×304 на 1.7. Пока «назван кодек» означало «имя не молчит», от эвристики
       ускользал целый пласт rutracker-раздач на 1.45–1.47 ГБ: у «Тёмного рыцаря:
       Возрождение легенды» такая стояла верхом с 58 сидами, у «Форреста Гампа» — со 105,
       у «Зелёной мили» — с 64, и рядом в каждой лежал названный 1080p. Ровно они и дали
       SD-фолбэк топа замера. Разрешение в имени эвристику по-прежнему отключает: там имя
       говорит по делу, и спорить с ним — работа ffprobe (:func:`understated`), а не
       прикидки по размеру.

    Почему это в cli, а не свойством релиза рядом с ``dated``: последней части нужна
    длительность картины, а её знает только план (:class:`_Plan`), не парсер. Ровно та
    же причина держит здесь :func:`bitrate_of` и :func:`is_candidate`.

    Сериалу вторая половина считается **на серию**, а не на раздачу: в ней лежит весь
    сезон, и «6 ГБ» это не битрейт фильма, а восемь серий. Делит их :func:`bitrate_of`
    по счёту серий из имени (``[S01E01-08 of 220]`` → восемь). Раньше здесь стоял
    отказ «сериалу не считаем вовсе», и подтверждённый .avi «Легенды об Аанге» 2024
    года эвристика не понижала — ловил его только ffprobe, то есть 2-5 секунд живого
    старта на раздачу, которую всё равно выбросят.

    ⚠️ Аниме (:attr:`~torrcast.parse.Release.anime`) вторая половина не судит вовсе, и это
    не поблажка жанру, а отказ от заведомо неверного счёта. Прикидка врёт там дважды:
    делит на типовые 45 минут сериала, тогда как серия аниме идёт 24, и сравнивает с
    порогом, который писан по полнометражному кино с живой съёмкой, — а рисованная
    картинка жмётся в разы лучше, и 1-1.5 Мбит/с на серию у честного 1080p там норма.
    Пока прикидка судила, получалась ровно та бессмыслица, ради которой признак и
    заведён: пак, чьё имя серии ПЕРЕСЧИТАЛО, получал метку «старьё» за свой законный
    битрейт и топился, а сосед, чьё имя серий не считает (битрейт не вычислить), метки
    не получал и стоял верхом. Судит такую раздачу ffprobe после выбора — как и всякую,
    про которую имя молчит.

    ⚠️ Имя, которое серий не считает («Локи [S01]»), по-прежнему судится только ffprobe:
    сколько внутри файлов, до метаданных не знает никто, а делить на выдуманное число
    хуже, чем промолчать. Отбраковку это не роняет — :meth:`_Bench._trouble` читает
    настоящий кодек и выбрасывает MPEG-4 в любом случае; цена молчания — те самые
    секунды, а не подмена.

    Признак меняет только ПОРЯДОК: годность решает ffprobe, а :func:`is_candidate` его
    не спрашивает — иначе у картины, где ни в одном имени нет маркера качества, не
    осталось бы ни одного кандидата.
    """
    if release.dated:
        return True
    if release.height:  # имя назвало ступень - верим ему, спорить с ним дело ffprobe
        return release.height < HD_HEIGHT
    if release.anime:  # жанровый битрейт: 1-1.5 Мбит/с на серию - это норма, а не SD
        return False
    mbit = bitrate_of(release, runtime)
    if mbit is not None and mbit < SD_BITRATE:
        return True
    return 0.0 < pack_mbit(release, runtime) < SD_BITRATE


def pack_mbit(release: Release, runtime: float) -> float:
    """Потолок битрейта серии у пака, чьё имя считает СЕЗОНЫ, но не серии; 0 — не считает.

    Дыра, которую это закрывает, и есть 🟡 «Чёрные паруса»: имена вида
    ``[S01-04] (2014-2017) HDTV-AlexFilm`` и ``HDRip, WEB-DL, HDTV … | КПК`` не называют
    ни разрешения, ни кодека, а серий не считают вовсе — :func:`bitrate_of` на них
    молчит, :func:`is_dated` промолчать обязана, и такая раздача с ОДНИМ сидом встаёт
    в очереди перебора ВЫШЕ живого сериала на 61 сид. А внутри у них SD: показ либо
    сожжёт на них :data:`MAX_TRIES` и 130 секунд, либо сыграет SD, не дойдя до живого
    720p, — и то и другое при живом каталоге.

    Считается это не выдумкой, а потолком. Сколько серий в сезоне, имя не сказало — но
    меньше :data:`SEASON_EPISODES` их почти не бывает, а делённый на МЕНЬШЕЕ число размер
    даёт БОЛЬШИЙ битрейт: если даже потолок ниже :data:`SD_BITRATE`, внутри SD наверняка.
    Числа того же случая: 10.24 ГБ на четыре сезона — потолок 1.3 Мбит/с, 27.24 ГБ —
    3.4 Мбит/с, а настоящий ``BDRip 720p`` на 114 ГБ — 14 Мбит/с, и его признак не
    трогает. Двухгигабайтный ``HDTV | BaibaKo-iPhone`` на один сезон — 1.3 Мбит/с.

    ⚠️ Это по-прежнему только ПОРЯДОК (:func:`is_dated`), и годность им не решается.
    Отдельно от :func:`bitrate_of` — нарочно: тот кормит ВОРОТА отбора
    (:func:`is_candidate`, :func:`needs_whole_recode`), а потолок в воротах означал бы
    «раздача слишком тяжёлая», то есть отказ показывать честный 114-гигабайтный пак.
    Ворота судят по подтверждённому счёту серий, как и судили; порядок — по потолку.
    """
    if release.kind != "tv" or release.episode_count or not release.seasons:
        return 0.0
    return bitrate_mbit(release.size // (len(release.seasons) * SEASON_EPISODES), runtime)


def misses_episode(release: Release, want: Episode | None) -> bool:
    """Раздача сама, своим именем, признаётся, что нужной серии в ней нет.

    Первая ступень порядка и единственная, которая стоит выше образов дисков: релиз без
    нужной серии не «хуже качеством», а бесполезен — играть в нём нечего. Молчаливое
    имя сюда не попадает никогда (:meth:`Release.covers_episode`), поэтому у сериала,
    где серии не перечисляет ни одно имя, порядок остаётся прежним.
    """
    return want is not None and not release.covers_episode(want)


def rank_releases(
    releases: list[Release],
    runtime: float,
    warn_mbit: float,
    want: Episode | None = None,
    loose: bool = False,
    hard_mbit: float = 0.0,
    last: bool = False,
    copy_hevc: bool = False,
) -> list[Release]:
    """Порядок меню: сверху самый обсиженный кандидат, потом всё остальное по
    сидам, образы дисков всегда внизу — цельного файла внутри нет, стримить нечего.

    Первой ступенью для сериала идёт :func:`misses_episode`: раздача, которая своим
    именем говорит «нужной серии тут нет», уходит под всех, кто может её содержать, —
    даже под мёртвые и под образы дисков. Живой случай, ради которого ступень
    появилась: у «Наруто» верхом стоял ``[S01E01-08 of 220]``, у «Локи» и
    «Сверхъестественного» — такие же огрызки, а полный сезон лежал строкой ниже, и
    авто-выбор упирался в «серии s1e1 в этой раздаче нет» уже после похода в рой.

    Сразу под годностью стоит :attr:`~torrcast.parse.Release.extras` — раздача, чьё имя
    называет её приложением к картине, а не картиной: фильм о фильме, дополнительные
    материалы, бонус-диск, трейлер. Ступень судит ОДНО имя, без веса, и права выкинуть
    раздачу у неё нет — она только уводит её под всё, что и правда картина. Выкидывает
    ворота (:func:`is_extra`), и им нужен ещё и вес. Разница видна ровно там, где и должна:
    бонус-диск на 11 ГБ ворота пропускают (столько ролик не весит, а ошибиться тут дорого),
    а порядок всё равно держит его последним из годных — у картины есть она сама.

    Там же сборник уступает одиночной раздаче картины. Внутри дилогии или коллекции
    выбор файла снова должен угадать часть, хотя индексер уже умеет отдать ровно
    спрошенный фильм. Сборник остаётся кандидатом, когда одиночного релиза нет.

    ⚠️ Ниже годности, а не выше, и это не мелочь. Выше она топила бы годную раздачу под
    негодную из-за одного слова в имени: у документального «Нечто: Ужас обретает форму»
    оба релиза подписаны «фильм о фильме», и BDRip на 2.2 ГБ уходил под DVDRip на 0.7,
    то есть меткой наказывалась сама картина, которую человек и звал.

    Сразу за годностью идёт ступень :func:`is_dead`: раздача с НУЛЁМ сидов уходит под
    всех, у кого рой хоть какой-то есть. Ступень стоит выше качества нарочно: качество
    это выбор между двумя показами, а ноль сидов — это отсутствие показа, и никакой
    1080p его не перевешивает. Живой случай: у «Наруто» верхом отбора стоял
    124-гигабайтный пак с нулём сидов, а сериал на 91 сид ждал ниже, потому что
    проигрывал ему по ступени старья; старт при этом упирался в двадцатисекундное
    молчание DHT ещё до первого кадра.

    Между «живостью» и «сидами» вклинена ступень :func:`is_dated`: обсиженное
    старьё уступает место годному даже при кратной разнице в сидах. Цена вопроса
    измерена: подъём такой раздачи стоит 2–5 секунд живого старта — метаданные по DHT
    плюс чтение дорожек, — и это ровно те секунды, которые незачем держать в
    критическом пути. На «Моане 2» так и было: первым
    кандидатом стоял 1.46-гигабайтный .avi с 221 сидом, а годный WEB-DL-AVC с 140
    сидами ждал своей очереди вторым.

    Следом за ней — ступень :func:`sound_step`: звук, которого не понять, — это не
    «качество похуже», а несмотренный тайтл. Поэтому она стоит ВЫШЕ :func:`is_full_hd`:
    обе ступени размениваются на сиды, и размен «1080p вместо 720p» дешевле размена
    «по-русски вместо по-японски». Ниже :func:`is_dated` она стоит по обратной причине:
    русский .avi вместо честного 1080p — это уже не размен, а откат по всему фронту.

    Следом — ступень :func:`is_full_hd`: живой 1080p обходит 720p, даже когда сидов
    у него меньше. Дальше внутри каждой группы всё как было — сиды, потом размер.

    Сразу под годностью стоит :func:`needs_whole_recode`: релиз, который играется только
    сплошным перекодом (BD-ремукс на 28-37 Мбит/с), годен, но идёт последним из годных.
    Ступень стоит выше живости нарочно: тяжёлое берётся, когда легче ничего нет, а не
    потому, что у ремукса больше сидов.

    Сразу под живостью стоит :func:`hevc_hope` — релиз, попавший в очередь последней
    надеждой. Ступень пустая, пока ворота ``last`` закрыты: ключ у всех одинаковый, и
    порядок обычного случая не меняется ни на строку. Открылись — HEVC уходит под всех
    прочих кандидатов, потому что стоит он дороже во всём: процессор занят сплошным
    перекодом от первой секунды до титров, а старт замерен на 3 с медленнее.

    Ниже живости, а не выше, она стоит по той же причине, по которой :func:`is_dead`
    поднялась над качеством: ворота последней надежды открываются только тогда, когда
    живого обычного кандидата нет вовсе, и единственный, кто остаётся против HEVC, —
    раздача с нулём сидов. Она не «обычный релиз», она отсутствие показа, и двадцать
    секунд молчания DHT перед живым HEVC — чистая потеря старта.

    ``loose`` — ворота отбора открыты (:func:`gate_open`), и молчаливые имена идут
    в кандидатах наравне с именными. ``last`` — открыты ворота последней надежды
    (:func:`last_hope`). ``copy_hevc`` - профиль разрешил HEVC копией, поэтому это
    обычный кандидат, а не последняя надежда.
    """
    alive = max((r.seeders for r in releases), default=0)
    steps = {
        id(r): (
            misses_episode(r, want),
            is_disc(r),
            not is_candidate(r, runtime, warn_mbit, loose, hard_mbit, last, copy_hevc),
            r.collection,
            r.extras,
            r.stereoscopic,
            needs_whole_recode(r, runtime, hard_mbit),
            is_dead(r, alive),
            hevc_hope(r, last),
            is_dated(r, runtime),
            sound_step(r, alive),
        )
        for r in releases
    }
    # Цена размена «1080p вместо 720p» меряется сидами сильнейшего из тех, кого этот
    # 1080p и правда потеснит, - равных по всем ступеням выше. Лидер пула тут не мерка:
    # он может сидеть на другой ступени (старьё, чужой звук, сплошной перекод) и в споре
    # за верх не участвовать вовсе, а его сиды всё равно раздували знаменатель.
    rivals: dict[tuple[object, ...], int] = {}
    for r in releases:
        key = steps[id(r)]
        rivals[key] = max(rivals.get(key, 0), r.seeders)
    return sorted(
        releases,
        key=lambda r: (
            *steps[id(r)],
            not is_full_hd(r, rivals[steps[id(r)]]),
            -r.seeders,
            -r.size,
            r.magnet,
        ),
    )


def is_dead(release: Release, alive: int) -> bool:
    """Ноль сидов при живых соседях: играть тут нечего ни на каком качестве.

    Живость участвовала в порядке и раньше, но только ВНУТРИ ступеней качества
    (:func:`is_full_hd`, :func:`sound_step`) — то есть мёртвая раздача имела полное
    право стоять верхом, если по имени она годнее живой. Так и было на живой выдаче
    «наруто»: 124-гигабайтный пак с нулём сидов обходил сериал на 91 сид, потому что у
    того в имени стоит ``DVDRip``. Enter в такой верх — это двадцать секунд молчания
    DHT и переход к следующему, то есть чистая потеря старта.

    Порог тут ровно ноль, и никакой доли от лидера: доля — это размен «поменьше сидов
    ради ступени качества», и её уже держат :data:`FULL_HD_LIVENESS` и
    :data:`SOUND_LIVENESS`, каждый со своей ценой. А ноль — не размен: раздача,
    которую никто не раздаёт, не играется вовсе.

    ``alive`` — сиды лидера пула. Пул, где на нуле ВСЕ (свежая раздача, индексер не
    отдал числа), ступень не трогает: понижать там некого и не в пользу кого.
    """
    return alive > 0 and release.seeders <= 0


def is_full_hd(release: Release, alive: int) -> bool:
    """Имя обещает 1080p (или выше), и раздача при этом жива.

    Ступень нужна затем, что до неё разрешение в порядке не участвовало вовсе: среди
    кандидатов правили одни сиды, и названный 1080p проигрывал названному 720p с
    троекратным перевесом сидов. На «Мастере и Маргарите» так и было — верхом стоял
    ``WEB-DL 720p`` со 146 сидами, а ``WEB-DL 1080p`` с 59 ждал вторым.

    Живость в условии не для красоты, и цена у неё замерена на той же выдаче: у «Зелёной
    мили» единственные названные 1080p имеют 4 и 1 сид против 38 у 720p, у «Форреста
    Гампа» — 2, 1, 0, 0 против 41. Поднять такой 1080p значило бы поменять ступень
    качества на подгрузы, а гейт показа прямо обратный: плавность выше пиковой чёткости.
    Порог :data:`FULL_HD_LIVENESS` разводит эти случаи с запасом — 0.40 против 0.10 и 0.05.

    ``alive`` — сиды сильнейшего из тех, кого 1080p потеснит этой ступенью, то есть
    равных ему по всем ступеням выше (:func:`rank_releases` считает максимум по группе).
    До этого знаменателем был лидер пула, и он топил живой 1080p под 720p всякий раз,
    когда лидер сидел на чужой ступени и в споре не участвовал: у «Истории игрушек 3»
    лидером числился 126-сидовый ``BDRip-AVC`` на 1.5 ГБ (старьё, утоплено своей
    ступенью), и названный 1080p с 30 сидами проигрывал 720p с 55 — 30 < 126 × 0.25,
    хотя против настоящего соперника у него 0.55.

    Второй пол условия — :data:`ALIVE_SEEDERS`: доля от соседа не оживляет рой, который
    не играет сам по себе. У «Сёгуна» верхом стоял 1080p на трёх сидах против 720p на
    пяти: доля 0.60 формально проходила, а двухсидовый рой — это подгрузы, и живой 720p
    честнее. Пол тот же, что у живости картины: один-два сида — не рой ни на какой
    ступени.

    Врущему имени ступень не помогает: подтверждает разрешение ffprobe, и «названный
    1080p, а внутри 574p» подменяется на честного соседа (:meth:`_Bench._honest`).

    2160p поднимается вместе с 1080p: это тоже честный HD, а его тяжесть снимает
    перекодирование на ходу — отбраковывает только ``bitrate_hard_mbit``.

    ⚠️ Живой 1080p от этого 4К не проигрывает: ступень «играется только сплошным
    перекодом» (:func:`needs_whole_recode`) стоит ВЫШЕ этой и топит 2160p под всех, у
    кого кадр по зубам приёмнику (TC-221). Здесь 2160p спорит уже только с 720p.
    """
    if release.interlaced or release.height < FULL_HEIGHT or release.seeders < ALIVE_SEEDERS:
        return False
    return release.seeders >= alive * FULL_HD_LIVENESS


def peer_grace(plan: _Plan, number: int, queue: list[int]) -> float:
    """Сколько этой раздаче даётся на ПЕРВЫЙ КОНТАКТ роя, секунды.

    🔴 TC-387. Отсрочка назначается ценой ошибки, а не свойствами раздачи. Обычная
    (:data:`PEER_GRACE`) стоит одного места в очереди: молчаливый релиз пропускается, а
    следующий спрашивается всё равно. Но когда следующий ступенью ниже, ошибка стоит
    обещанной чёткости - живой 1080p уступает 720p не своим роем, а нашим нетерпением, -
    и такой раздаче даётся :data:`STEP_GRACE`.

    Ступень тут решается ИМЕНАМИ соседей, а не сидами: живость раздачи в эту минуту как
    раз и есть то, чего мы ещё не знаем. Молчащее о разрешении имя стоит с низкими:
    подтвердить его нечем, пока раздачу не подняли, и ровно так же его судит
    :func:`is_full_hd`.

    Соседи берутся из фактического хвоста ``queue`` после этой раздачи. Поэтому ручной
    выбор, проверка по звуку и уже пройденный сосед отсрочку не удлиняют. Ворота и
    нужная серия учтены при построении самой очереди (:meth:`_Plan.candidates`).
    """
    release = plan.ranked[number - 1]
    if release.height < FULL_HEIGHT or number not in queue:
        return PEER_GRACE
    after = queue[queue.index(number) + 1 :]
    lower = any(plan.ranked[other - 1].height < FULL_HEIGHT for other in after)
    return STEP_GRACE if lower else PEER_GRACE


#: Насколько чужое обещание должно превышать наш кадр, чтобы считаться ступенью выше.
#: 1080 против 1078 — не ступень, а округление разных рипов одного и того же мастера.
STEP_RATIO: Final = 0.95


def stepdown_note(
    plan: _Plan,
    number: int,
    media: Media | None,
    queue: list[int],
    judged: dict[int, str] | None = None,
    reached: int = 0,
) -> str:
    """Одна строка о том, что показ едет ступенью НИЖЕ, чем в выдаче было доступно.

    🔴 TC-187. «Интерстеллар», «Форрест Гамп», «Зелёная миля», «Нелюбовь» доезжали в
    720p и SD при живых 1080p в той же выдаче — и ни одна строка об этом не говорила.
    Молчаливых подмен нет: снижение ступени — такое же авто-решение, как выбор релиза,
    и человек обязан услышать не только «что взяли», но и «почему не лучшее».

    Взятое меряется ПАСПОРТОМ, а не именем: ffprobe уже прочитан, и «названный 1080p, а
    внутри 574p» обязан считаться SD, иначе строка молчала бы ровно там, где подмена и
    случилась. Соседей мерить нечем, кроме имени, — их паспорта нет и не будет, пока их
    не подняли; поэтому у них берётся заявка, а порог :data:`STEP_RATIO` не даёт считать
    ступенью разницу в округлении.

    Причина — из того, чем кончилась их очередь:

    - ``отбраковали`` — раздачу трогали, и ffprobe (или рой) её осудил; приговор в строке;
    - ``не дошли`` — стояла в очереди, но до неё не добрались: годный нашёлся раньше;
    - ``в очередь не попал`` — выкинули воротами ещё до каста (:func:`drop_reason`);
    - ``рой мёртв`` — лучшее в выдаче есть, а сидов у него ноль: это не показ.

    Лучшего не было — строки нет вовсе: сообщать нечего, а лишняя строка на каждом
    показе обесценивает все остальные.
    """
    judged = judged or {}
    taken = plan.ranked[number - 1]
    frame = media.frame if media is not None and media.height else taken.height
    better = [
        (n, r)
        for n, r in enumerate(plan.ranked, start=1)
        if n != number
        and r.height * STEP_RATIO > frame
        and not misses_episode(r, plan.want)
        and not is_disc(r)
    ]
    if not better:
        return ""
    alive = [(n, r) for n, r in better if r.seeders > 0]
    best = max(alive or better, key=lambda pair: (pair[1].height, pair[1].seeders))
    at, rival = best
    if not alive:
        why = "рой мёртв"
    elif at in judged:
        why = f"отбраковали ({judged[at]})"
    elif at in queue:
        why = "не дошли" if queue.index(at) >= reached else "не ответил"
    else:
        why = f"в очередь не попал: {drop_reason(rival, plan)}"
    took = media.quality if media is not None and media.height else (taken.quality or "?")
    return f"взял {took}, рядом был {rival.quality} (релиз {at}, сидов {rival.seeders}) - {why}"


def bitrate_of(release: Release, duration: float) -> float | None:
    """Оценка битрейта по размеру раздачи. У одиночного фильма берётся вся раздача,
    у сборника - один фильм, у сериала - ОДНА СЕРИЯ: «9.7 ГБ» на восемь серий это
    3 Мбит/с, а не 30, и по оценке целиком самые обсиженные раздачи сезона улетали бы
    вниз с пометкой «тяжёлый».

    Сколько внутри серий, говорит имя раздачи (:attr:`Release.episode_count`):
    ``[S01E01-08 of 220]`` — восемь, ``[E220 of 220]`` — двести двадцать. Имя молчит —
    отдаём ``None``, и это 🔴 TC-344: «не знаю» и «мало» — разные ответы. Ноль здесь
    раньше значил «ниже любого порога», и ворота читали молчание имени как «лёгкий и
    безопасный»: весовая половина :func:`is_extra` у таких сериалов срабатывала всегда,
    а потолок :func:`over_ceiling` - никогда. Делить на выдуманный счёт значит врать
    себе, а настоящий битрейт серии всё равно померит ffprobe по её файлу - поэтому
    каждый, кто зовёт эту прикидку, обязан решить свой ``None`` сам: в отказ молчание
    не превращается нигде.
    """
    if release.kind != "tv":
        count = release.collection_count
        return bitrate_mbit(release.size // count, duration) if count else None
    count = release.episode_count
    return bitrate_mbit(release.size // count, duration) if count else None


def render_table(
    releases: list[Release],
    runtime: float,
    warn_mbit: float,
    limit: int = TABLE_LIMIT,
    recode_at: float = 0.0,
    hard_mbit: float = 0.0,
) -> str:
    """Таблица релизов: N · качество · размер · сиды · озвучка · кодек. Битрейт для
    пометки прикидывается по размеру и типовой длительности, пока настоящая не прочитана
    ffprobe; ниже ``limit`` — раздачи без сидов, выбирать там нечего.
    """
    shown = releases[:limit]
    rows = [
        (
            str(number),
            r.quality or "?",
            _gb(r.size),
            str(r.seeders),
            _cut(", ".join(r.voices) or "-", 34),
            ((r.codec or "?") + " " + warned(r, runtime, warn_mbit, recode_at, hard_mbit)).strip(),
        )
        for number, r in enumerate(shown, start=1)
    ]
    head = ("N", "Качество", "Размер", "Сиды", "Озвучка", "Кодек")
    width = [max(len(c[i]) for c in (head, *rows)) for i in range(len(head))]

    def line(cells: tuple[str, ...]) -> str:
        return "  " + "  ".join(_pad(c, w) for c, w in zip(cells, width, strict=True))

    out = ["Релизы:", line(head), *(line(row).rstrip() for row in rows)]
    if len(releases) > len(shown):
        out.append(f"  ... и ещё {len(releases) - len(shown)} с меньшим числом сидов")
    return "\n".join(out)


def pick_voice(media: Media, args: Args, remembered: str = "") -> tuple[int, str]:
    """Какую дорожку играем и что после этого лежит в памяти картины.

    **На счастливом пути вопроса про озвучку нет.** Дорожка выбирается сама
    (:meth:`Media.default_track`), и её подпись печатается в строке запуска —
    молчаливых подмен не бывает.

    Спросить можно только явно: ``--voice N`` берёт дорожку N, ``--voice`` без номера
    показывает меню. Оба — явный выбор, и только он пишется в память картины
    (:attr:`torrcast.state.Entry.voice`). Автовыбор память не трогает: иначе первый же
    запуск с другим релизом переписал бы то, что пользователь выбрал руками.

    Возвращает пару «номер дорожки в этом релизе, память картины».
    """
    if not media.tracks:
        raise InfraError("в файле нет звуковых дорожек")
    if args.voice is not None:
        index = _ask_voice(media) if args.voice == VOICE_MENU else _voice_number(media, args.voice)
        return index, media.tracks[index].label
    if remembered:
        found = media.find_voice(remembered)
        if found is not None:
            return found, remembered
        # Память живёт на картину, а релиз временный: озвучки в нём нет - говорим и
        # играем обычную, но выбор пользователя не забываем (:attr:`Entry.voice`).
        print(f"озвучки «{remembered}» в этом релизе нет - беру обычную")
    return media.default_track(), remembered


#: Языковые коды ffprobe → как язык зовут вслух. Список короткий и ровно про то, что
#: живёт в раздачах кино и аниме; чего в нём нет, называется «оригинальный».
_SPOKEN: dict[str, str] = {
    "jpn": "японский",
    "ja": "японский",
    "jap": "японский",
    "eng": "английский",
    "en": "английский",
    "kor": "корейский",
    "zho": "китайский",
    "chi": "китайский",
    "fra": "французский",
    "fre": "французский",
    "deu": "немецкий",
    "ger": "немецкий",
    "spa": "испанский",
    "ita": "итальянский",
}


def spoken(track: AudioTrack) -> str:
    """Как назвать язык дорожки вслух: «японский»; неизвестный — «оригинальный»."""
    return _SPOKEN.get((track.language or "").strip().casefold(), "оригинальный")


def heard(media: Media) -> str:
    """Каким языком заговорит этот файл: язык дорожки, которую взял бы показ.

    Нужен строкам отбора (:meth:`_Bench.resolve`): «релиз 1 без русской озвучки» само по
    себе не говорит человеку ничего о том, что он услышит, а «(японский)» говорит. Берётся
    та же дорожка, что и играла бы (:meth:`torrcast.stream.Media.default_track`), - иначе
    строка отбора и строка запуска называли бы разные языки одного файла.

    🔴 TC-492. Дорожка без тега языка называется «не назван», а не «оригинальный»: это
    ровно тот случай, ради которого гейт и бракует релиз (:func:`voice_unproven`), и
    придумывать ей язык в той же строке было бы второй такой же ошибкой.
    """
    if not media.tracks:
        return "не назван"
    index = media.default_track()
    track = media.tracks[index] if index < len(media.tracks) else media.tracks[0]
    return spoken(track) if track.named else "не назван"


def sound_note(
    media: Media,
    audio: int,
    pool: list[Release],
    release: Release | None = None,
    files: Sequence[TorrFile] = (),
    *,
    native: bool = False,
) -> str:
    """Честная строка про звук, когда русской дорожки в файле не оказалось; иначе пусто.

    Решение владельца по аниме: субтитров не делаем — значит японский тайтл без
    перевода останется японским, и показ обязан сказать это ДО картинки, а не оставить
    человека выяснять на слух. Показ при этом играет: решает он сам, наше дело —
    предупредить честно.

    Строки три, и разница между ними не косметическая:

    * перевод в каталоге есть, но в этом релизе его не оказалось — строка называет и
      запасной ход: выбрать раздачу руками;
    * 🔴 TC-191: перевод в каталоге есть, но только ОТДЕЛЬНЫМ ФАЙЛОМ
      (:attr:`~torrcast.parse.Release.external_dub`, «[RUS(ext)]») — тогда выбирать
      руками нечего: играть звук из соседнего файла показ не умеет, и честнее сказать
      это прямо, чем отправить человека по кругу за тем же японским;
    * перевода нет вообще ни у кого в выдаче — «только японский звук, перевода в
      каталоге нет», и делать тут больше нечего.

    Чей звук играет, читается из дорожки (:func:`spoken`), а не додумывается: у
    французского фильма без перевода японского звука взяться неоткуда.
    """
    if not media.tracks or any(t.is_russian for t in media.tracks):
        return ""
    track = media.tracks[audio] if audio < len(media.tracks) else media.tracks[0]
    if not track.named:
        if native:
            return ""
        # Раздача язык дорожки не назвала (тег ``und``). Единственная косвенная улика -
        # имя раздачи: русский маркер в нём (:attr:`Release.dubbed`) - повод СКАЗАТЬ про
        # русскую, назвав источник, а не молча подставить её (и не выдать за неё). Улики
        # нет - язык так и остаётся неизвестным, и об этом честная строка.
        if release is not None and release.dubbed:
            return "звук без метки языка - по имени релиза русская"
        return "язык дорожки неизвестен - раздача не назвала язык озвучки"
    lang = spoken(track)
    if any(r is not release and r.dubbed and r.seeders > 0 for r in pool):
        return f"только {lang} звук - в каталоге, возможно, есть перевод в другой раздаче"
    if _russian_audio_file(files) or any(r.external_dub and r.seeders > 0 for r in pool):
        return f"только {lang} звук - в каталоге перевод есть, но лежит отдельным файлом"
    return f"только {lang} звук, перевода в каталоге нет"


_AUDIO_FILE_EXT: Final = frozenset(
    {".aac", ".ac3", ".dts", ".eac3", ".flac", ".m4a", ".mka", ".mp3", ".ogg", ".opus", ".wav"}
)
_RU_FILE_RE: Final = re.compile(
    r"(?:^|[ ._\[(+-])(?:rus|russian|рус(?:ский|ская)?)(?:$|[ ._\])+-])", re.I
)


def _russian_audio_file(files: Sequence[TorrFile]) -> bool:
    """Есть ли в раздаче отдельный файл звука, прямо названный русским."""
    return any(
        Path(file.name).suffix.casefold() in _AUDIO_FILE_EXT and _RU_FILE_RE.search(file.base)
        for file in files
    )


def voice_note(media: Media, audio: int) -> str:
    """Одна строка про то, из чего выбиралась озвучка: «дорожек rus 4, беру дубляж
    (LostFilm)»; выбора не было — пусто.

    Подпись взятой дорожки печатается и так, но она отвечает на вопрос «что играет», а
    не «почему это». У «Барби» рядом лежат три русские дорожки, и человек, услышав не ту,
    до сих пор не знал ни что выбор был, ни что рядом было из чего выбрать.

    Молчим ровно там, где выбирать было не из чего: одна русская дорожка (или ни одной) -
    это не решение, а единственный вариант, и строка про него была бы шумом. Список
    студий целиком тут не печатается намеренно: он длинный, а нужен по запросу -
    ``cast voices <запрос>``.

    🔴 TC-242. Когда взятое расходится с лестницей по типу - двухголосый обошёл живой
    многоголосый - строка называет и ПРИЧИНУ, коротким хвостом: иначе человек читает её
    как противоречие лестнице. Причина одна: студию судят по её отборной ступени
    (:attr:`torrcast.stream.AudioTrack.rank_step`), а не по той, что произносится вслух.
    Нет расхождения - нет и хвоста: счастливый путь не засоряем.
    """
    russian = sum(1 for t in media.tracks if t.is_russian)
    if russian < 2 or not 0 <= audio < len(media.tracks):
        return ""
    track = media.tracks[audio]
    # Русских две, а играет нерусская - значит обе служебные; это тоже выбор, и назвать
    # его надо языком, а не видом перевода.
    what = (track.kind or "русскую") if track.is_russian else spoken(track)
    studio = track.studio
    tail = f" ({studio.name})" if studio and studio.name else ""
    why = ""
    if track.is_russian and studio and studio.ranks and track.rank_step < track.step:
        why = f" - эта студия у нас на уровне «{studio.ranks}»"
    return f"дорожек rus {russian}, беру {what}{tail}{why}"


def _voice_number(media: Media, number: int) -> int:
    """Номер дорожки от человека → индекс; чужого номера нет — честная строка."""
    if not 1 <= number <= len(media.tracks):
        raise NotFoundError(
            f"дорожек {len(media.tracks)}, номера {number} нет - посмотри: cast voices <запрос>"
        )
    return number - 1


def _ask_voice(media: Media) -> int:
    """Меню озвучек — только по ``--voice`` без номера. Дефолт тот же, что и без флага."""
    default = media.default_track()
    if len(media.tracks) == 1:  # выбора нет - вопроса тоже
        return default
    print(voices_table(media, default))
    return ask("Озвучка?", len(media.tracks), default=default + 1) - 1


def voices_table(media: Media, default: int, remembered: str = "") -> str:
    """Список озвучек с пометками «дефолт» и «запомнено» — для меню и ``cast voices``."""
    found = media.find_voice(remembered) if remembered else None
    rows = []
    for track in media.tracks:
        marks = (("дефолт", track.index == default), ("запомнено", track.index == found))
        note = [word for word, on in marks if on]
        tail = f"   [{', '.join(note)}]" if note else ""
        rows.append(f"  {track.index + 1}. {track.label}{tail}")
    return "\n".join(["Озвучка:", *rows])


def _gb(size: int) -> str:
    return f"{size / 1024**3:.1f} ГБ" if size else "-"


def _cut(text: str, limit: int) -> str:
    return text if len(text) <= limit else text[: limit - 3] + "..."


def _pad(text: str, width: int) -> str:
    return text + " " * (width - len(text))


def _hms(seconds: float) -> str:
    total = int(seconds)
    return f"{total // 3600}:{total % 3600 // 60:02d}:{total % 60:02d}"


if __name__ == "__main__":
    raise SystemExit(main())
